--
-- Name: crops_log_clear(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.crops_log_clear() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Fires on any is_active transition (for completeness).
    -- Only act when true→false (the "clear" direction).
    IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN
        -- Stamp cleared_at if not already set (caller may set it explicitly).
        IF NEW.cleared_at IS NULL THEN
            NEW.cleared_at := now();
        END IF;
        INSERT INTO crop_events (
            ts, crop_id, event_type, old_stage, new_stage,
            source, notes, greenhouse_id, position_id
        )
        VALUES (
            NEW.cleared_at,
            NEW.id,
            'removed',
            OLD.stage,
            NEW.stage,
            'trigger',
            'Auto-logged by crops_log_clear trigger (is_active: true → false)',
            NEW.greenhouse_id,
            NEW.position_id
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.crops_log_clear() OWNER TO verdify;

--
-- Name: crops_log_planted(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.crops_log_planted() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Only log on INSERT where the crop is born active. Backfilled
    -- historical rows (is_active=false on insert) don't get an auto-event.
    IF NEW.is_active THEN
        INSERT INTO crop_events (
            ts, crop_id, event_type, new_stage, source, notes,
            greenhouse_id, position_id
        )
        VALUES (
            COALESCE(NEW.created_at, now()),
            NEW.id,
            'planted',
            NEW.stage,
            'trigger',
            'Auto-logged by crops_log_planted trigger',
            NEW.greenhouse_id,
            NEW.position_id
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.crops_log_planted() OWNER TO verdify;

--
-- Name: crops_log_stage_change(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.crops_log_stage_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.stage IS DISTINCT FROM OLD.stage THEN
        INSERT INTO crop_events (
            ts, crop_id, event_type, old_stage, new_stage,
            source, notes, greenhouse_id, position_id
        )
        VALUES (
            now(),
            NEW.id,
            'stage_change',
            OLD.stage,
            NEW.stage,
            'trigger',
            'Auto-logged by crops_log_stage_change trigger',
            NEW.greenhouse_id,
            NEW.position_id
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.crops_log_stage_change() OWNER TO verdify;

--
-- Name: fn_achievable_envelope(text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_achievable_envelope(p_zone text, p_season text, p_ts timestamp with time zone, p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(env_temp_low_floor double precision, env_temp_hi_cap double precision, env_temp_achievable_p50 double precision, env_vpd_lo_floor double precision, env_vpd_hi_cap double precision, cap_source text)
    LANGUAGE plpgsql STABLE ROWS 1
    AS $$
DECLARE
    h0 int;
    h1 int;
    frac double precision;
    v_season text := p_season;
    r0 record;
    r1 record;
BEGIN
    h0 := EXTRACT(hour FROM p_ts AT TIME ZONE 'America/Denver')::int;
    frac := EXTRACT(minute FROM p_ts AT TIME ZONE 'America/Denver') / 60.0;
    h1 := (h0 + 1) % 24;

    -- nearest-season fallback if requested season absent
    IF NOT EXISTS (SELECT 1 FROM achievable_envelope
                    WHERE greenhouse_id = p_greenhouse_id AND zone = p_zone
                      AND season = v_season AND is_active) THEN
        v_season := 'spring';
    END IF;

    SELECT * INTO r0 FROM achievable_envelope
     WHERE greenhouse_id = p_greenhouse_id AND zone = p_zone
       AND season = v_season AND hour_of_day = h0 AND is_active;
    SELECT * INTO r1 FROM achievable_envelope
     WHERE greenhouse_id = p_greenhouse_id AND zone = p_zone
       AND season = v_season AND hour_of_day = h1 AND is_active;

    IF r0 IS NULL THEN
        -- never NULL: open-to-achievable conservative fallback
        env_temp_low_floor := 55.0;
        env_temp_hi_cap := 90.0;
        env_temp_achievable_p50 := 88.0;
        env_vpd_lo_floor := 0.30;
        env_vpd_hi_cap := 1.80;
        cap_source := 'fallback';
        RETURN NEXT;
        RETURN;
    END IF;

    IF r1 IS NULL THEN r1 := r0; END IF;

    env_temp_low_floor := r0.env_temp_lo_floor + frac * (r1.env_temp_lo_floor - r0.env_temp_lo_floor);
    env_temp_hi_cap := r0.env_temp_hi_cap + frac * (r1.env_temp_hi_cap - r0.env_temp_hi_cap);
    env_temp_achievable_p50 := COALESCE(r0.env_temp_achievable_p50, r0.env_temp_hi_cap)
        + frac * (COALESCE(r1.env_temp_achievable_p50, r1.env_temp_hi_cap)
                  - COALESCE(r0.env_temp_achievable_p50, r0.env_temp_hi_cap));
    env_vpd_lo_floor := COALESCE(r0.env_vpd_lo_floor, 0.30);
    env_vpd_hi_cap := COALESCE(r0.env_vpd_hi_cap, 1.80);
    cap_source := r0.cap_source;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_achievable_envelope(p_zone text, p_season text, p_ts timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: fn_active_noncenter_stress(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_active_noncenter_stress(target_ts timestamp with time zone) RETURNS TABLE(crop_type text, temp_stress_low double precision, temp_stress_high double precision, vpd_stress_low double precision, vpd_stress_high double precision)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_season text := fn_current_season();
    v_hour int := EXTRACT(hour FROM target_ts AT TIME ZONE 'America/Denver')::int;
BEGIN
    RETURN QUERY
    SELECT p.crop_type, p.temp_stress_low, p.temp_stress_high,
           p.vpd_stress_low, p.vpd_stress_high
      FROM crop_target_profiles p
      JOIN crops c ON c.crop_catalog_id = p.crop_catalog_id
                  AND c.is_active
                  AND c.greenhouse_id = p.greenhouse_id
     WHERE p.greenhouse_id = 'vallery'
       AND p.hour_of_day = v_hour
       AND p.season = COALESCE(
             (SELECT v_season WHERE EXISTS (
                 SELECT 1 FROM crop_target_profiles p2
                  WHERE p2.greenhouse_id = 'vallery' AND p2.season = v_season
                    AND p2.crop_catalog_id IS NOT NULL)),
             'spring')
       AND p.crop_catalog_id IS DISTINCT FROM 9   -- exclude center/orchid
       AND p.crop_catalog_id IS NOT NULL;         -- exclude _default
END;
$$;


ALTER FUNCTION public.fn_active_noncenter_stress(target_ts timestamp with time zone) OWNER TO verdify;

--
-- Name: fn_band_setpoint_provenance(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_band_setpoint_provenance(p_ts timestamp with time zone DEFAULT now(), p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(ts timestamp with time zone, greenhouse_id text, parameter text, axis text, edge text, crop_target_value double precision, dispatcher_value double precision, firmware_setpoint_value double precision, firmware_setpoint_ts timestamp with time zone, cfg_readback_value double precision, cfg_readback_ts timestamp with time zone, latest_plan_id text, latest_plan_created_at timestamp with time zone, latest_planner_instance text, automation_source text, source_chain text, displayed_on_operator_graph boolean)
    LANGUAGE sql STABLE ROWS 4
    AS $$
WITH crop AS (
    SELECT *
      FROM fn_band_setpoints(p_ts)
     LIMIT 1
),
house AS (
    SELECT *
      FROM fn_house_vpd_control_band(p_ts)
     LIMIT 1
),
latest_plan AS (
    SELECT pj.plan_id, pj.created_at, pj.planner_instance
      FROM plan_journal pj
     WHERE COALESCE(pj.greenhouse_id, 'vallery') = p_greenhouse_id
       AND pj.created_at <= p_ts
     ORDER BY pj.created_at DESC
     LIMIT 1
),
params AS (
    SELECT *
      FROM (
          VALUES
              ('temp_low'::text,  'temp'::text, 'low'::text,  (SELECT temp_low FROM crop),       (SELECT temp_low FROM crop),       'fn_band_setpoints crop temperature curve'::text),
              ('temp_high'::text, 'temp'::text, 'high'::text, (SELECT temp_high FROM crop),      (SELECT temp_high FROM crop),      'fn_band_setpoints crop temperature curve'::text),
              ('vpd_low'::text,   'vpd'::text,  'low'::text,  (SELECT crop_vpd_low FROM house),  (SELECT house_vpd_low FROM house), 'fn_house_vpd_control_band crop plus zone VPD curve'::text),
              ('vpd_high'::text,  'vpd'::text,  'high'::text, (SELECT crop_vpd_high FROM house), (SELECT house_vpd_high FROM house), 'fn_house_vpd_control_band crop plus zone VPD curve'::text)
      ) AS p(parameter, axis, edge, crop_target_value, dispatcher_value, automation_source)
)
SELECT
    p_ts AS ts,
    p_greenhouse_id AS greenhouse_id,
    p.parameter,
    p.axis,
    p.edge,
    p.crop_target_value,
    p.dispatcher_value,
    fw.value AS firmware_setpoint_value,
    fw.ts AS firmware_setpoint_ts,
    rb.value AS cfg_readback_value,
    rb.ts AS cfg_readback_ts,
    lp.plan_id AS latest_plan_id,
    lp.created_at AS latest_plan_created_at,
    lp.planner_instance AS latest_planner_instance,
    p.automation_source,
    CASE
        WHEN p.axis = 'temp' THEN
            'crop profiles -> fn_band_setpoints() -> setpoint_dispatcher/API fallback -> setpoint_changes -> ESP32 cfg_* readback'
        ELSE
            'crop profiles + zone VPD targets -> fn_house_vpd_control_band() -> setpoint_dispatcher/API fallback -> setpoint_changes -> ESP32 cfg_* readback'
    END AS source_chain,
    true AS displayed_on_operator_graph
FROM params p
LEFT JOIN LATERAL (
    SELECT sc.value, sc.ts
      FROM setpoint_changes sc
     WHERE sc.greenhouse_id = p_greenhouse_id
       AND sc.parameter = p.parameter
       AND sc.ts <= p_ts
       AND (sc.expired_at IS NULL OR sc.expired_at > p_ts)
     ORDER BY sc.ts DESC
     LIMIT 1
) fw ON true
LEFT JOIN LATERAL (
    SELECT ss.value, ss.ts
      FROM setpoint_snapshot ss
     WHERE ss.greenhouse_id = p_greenhouse_id
       AND ss.parameter = p.parameter
       AND ss.ts <= p_ts
     ORDER BY ss.ts DESC
     LIMIT 1
) rb ON true
LEFT JOIN latest_plan lp ON true
ORDER BY p.axis, p.edge;
$$;


ALTER FUNCTION public.fn_band_setpoint_provenance(p_ts timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

