-- Name: FUNCTION fn_band_setpoint_provenance(p_ts timestamp with time zone, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_band_setpoint_provenance(p_ts timestamp with time zone, p_greenhouse_id text) IS 'Current four-edge band provenance: crop target curve, dispatcher-derived value, latest pushed firmware setpoint, cfg_* readback, latest planner context, and source chain for operator table views.';


--
-- Name: fn_band_setpoints(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_band_setpoints(target_ts timestamp with time zone) RETURNS TABLE(temp_low double precision, temp_high double precision, vpd_low double precision, vpd_high double precision)
    LANGUAGE plpgsql STABLE ROWS 1
    AS $$
DECLARE
    c record;
    env record;
    v_floor double precision;
    v_ceil double precision;
    v_vlow double precision;
    v_vhigh double precision;
BEGIN
    SELECT * INTO c FROM fn_center_band_setpoints(target_ts);          -- orchid smooth band (145)
    SELECT * INTO env FROM fn_achievable_envelope('center', fn_current_season(), target_ts);

    -- decision #1 safety: never serve a ceiling above any active non-center
    -- crop's temp_stress_high, nor a floor below its temp_stress_low.
    SELECT MAX(s.temp_stress_low), MIN(s.temp_stress_high)
      INTO v_floor, v_ceil
      FROM fn_active_noncenter_stress(target_ts) s;

    -- temp_low  = max(center, non-center safety floor, envelope floor)
    -- temp_high = min(center, envelope cap, non-center safety ceiling)
    temp_low  := GREATEST(c.temp_low,
                          COALESCE(v_floor, c.temp_low),
                          COALESCE(env.env_temp_low_floor, c.temp_low));
    temp_high := LEAST(c.temp_high,
                       COALESCE(env.env_temp_hi_cap, c.temp_high),
                       COALESCE(v_ceil, c.temp_high));
    IF temp_low > temp_high THEN temp_low := temp_high; END IF;

    -- VPD served line = house control band (non-orchid), inversion-clamped.
    SELECT h.house_vpd_low, h.house_vpd_high
      INTO v_vlow, v_vhigh
      FROM fn_house_vpd_control_band(target_ts) h;
    IF v_vlow IS NULL OR v_vhigh IS NULL THEN
        v_vlow := c.vpd_low; v_vhigh := c.vpd_high;
    END IF;
    IF v_vlow > v_vhigh THEN v_vlow := v_vhigh; END IF;

    vpd_low := v_vlow;
    vpd_high := v_vhigh;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_band_setpoints(target_ts timestamp with time zone) OWNER TO verdify;

--
-- Name: fn_band_timeline(timestamp with time zone, timestamp with time zone, interval, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_band_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval DEFAULT '00:30:00'::interval, p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(ts timestamp with time zone, greenhouse_id text, timeline_phase text, crop_temp_low double precision, crop_temp_high double precision, crop_vpd_low double precision, crop_vpd_high double precision, projected_temp_low double precision, projected_temp_high double precision, projected_vpd_low double precision, projected_vpd_high double precision, actual_temp_low double precision, actual_temp_high double precision, actual_vpd_low double precision, actual_vpd_high double precision, firmware_temp_low double precision, firmware_temp_high double precision, firmware_vpd_low double precision, firmware_vpd_high double precision, temp_width_f double precision, vpd_width_kpa double precision, sw_fsm_controller_enabled boolean, indoor_temp_f double precision, indoor_vpd_kpa double precision, outdoor_temp_f double precision, outdoor_vpd_kpa double precision, solar_w_m2 double precision, outdoor_cold_for_vent boolean, temp_hysteresis_f double precision, heat_hysteresis_f double precision, d_heat_stage_2_f double precision, d_cool_stage_2_f double precision, bias_heat_f double precision, bias_cool_f double precision, vpd_hysteresis_kpa double precision, vpd_hysteresis_effective_kpa double precision, fog_escalation_kpa double precision, temp_heat_target_f double precision, temp_heat_on_below_f double precision, temp_heat2_on_below_f double precision, temp_heat2_clear_f double precision, temp_cool_on_above_f double precision, temp_cool_hold_until_f double precision, temp_cooling_entry_margin_f double precision, temp_cooling_exit_hysteresis_f double precision, solar_cooling_lead_f double precision, temp_cool_stage2_delta_f double precision, temp_cool_stage2_on_above_f double precision, vpd_humidify_on_above_kpa double precision, vpd_humidify_resolved_below_kpa double precision, vpd_dehum_on_below_kpa double precision, vpd_dehum_resolved_above_kpa double precision, vpd_low_eff_kpa double precision, vpd_high_eff_kpa double precision, vpd_vent_fog_on_above_kpa double precision, vpd_sealed_fog_on_above_kpa double precision)
    LANGUAGE sql STABLE ROWS 10000
    AS $$
WITH timeline AS (
    SELECT generate_series(p_start, p_end, p_step) AS ts
),
forecast_hourly AS (
    SELECT DISTINCT ON (date_trunc('hour', wf.ts))
        date_trunc('hour', wf.ts) AS forecast_hour,
        wf.temp_f AS outdoor_temp_f,
        wf.vpd_kpa AS outdoor_vpd_kpa,
        wf.solar_w_m2
      FROM weather_forecast wf
     WHERE wf.greenhouse_id = p_greenhouse_id
       AND wf.ts >= p_start - interval '1 hour'
       AND wf.ts <= p_end + interval '1 hour'
     ORDER BY date_trunc('hour', wf.ts), wf.fetched_at DESC
),
resolved AS (
SELECT
    t.ts,
    p_greenhouse_id AS greenhouse_id,
    CASE WHEN t.ts <= now() THEN 'actual' ELSE 'forecast' END AS timeline_phase,
    crop.temp_low AS crop_temp_low,
    crop.temp_high AS crop_temp_high,
    house.crop_vpd_low,
    house.crop_vpd_high,
    crop.temp_low AS projected_temp_low,
    crop.temp_high AS projected_temp_high,
    house.house_vpd_low AS projected_vpd_low,
    house.house_vpd_high AS projected_vpd_high,
    actual_temp_low.value AS actual_temp_low,
    actual_temp_high.value AS actual_temp_high,
    actual_vpd_low.value AS actual_vpd_low,
    actual_vpd_high.value AS actual_vpd_high,
    actual_climate.temp_avg AS indoor_temp_f,
    actual_climate.vpd_avg AS indoor_vpd_kpa,
    CASE
        WHEN t.ts <= now() THEN actual_climate.outdoor_temp_f
        ELSE forecast.outdoor_temp_f
    END AS outdoor_temp_f,
    CASE
        WHEN t.ts <= now() THEN actual_climate.outdoor_vpd_kpa
        ELSE forecast.outdoor_vpd_kpa
    END AS outdoor_vpd_kpa,
    CASE
        WHEN t.ts <= now() THEN actual_climate.solar_w_m2
        ELSE forecast.solar_w_m2
    END AS solar_w_m2,
    CASE
        WHEN t.ts <= now() THEN COALESCE(actual_temp_low.value, crop.temp_low)
        ELSE crop.temp_low
    END AS firmware_temp_low,
    CASE
        WHEN t.ts <= now() THEN COALESCE(actual_temp_high.value, crop.temp_high)
        ELSE crop.temp_high
    END AS firmware_temp_high,
    CASE
        WHEN t.ts <= now() THEN COALESCE(actual_vpd_low.value, house.house_vpd_low)
        ELSE house.house_vpd_low
    END AS firmware_vpd_low,
    CASE
        WHEN t.ts <= now() THEN COALESCE(actual_vpd_high.value, house.house_vpd_high)
        ELSE house.house_vpd_high
    END AS firmware_vpd_high
FROM timeline t
CROSS JOIN LATERAL fn_band_setpoints(t.ts) AS crop
CROSS JOIN LATERAL fn_house_vpd_control_band(t.ts) AS house
LEFT JOIN LATERAL (
    SELECT value
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_low'
       AND t.ts <= now()
       AND ts <= t.ts
       AND (expired_at IS NULL OR expired_at > t.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS actual_temp_low ON true
LEFT JOIN LATERAL (
    SELECT value
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_high'
       AND t.ts <= now()
       AND ts <= t.ts
       AND (expired_at IS NULL OR expired_at > t.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS actual_temp_high ON true
LEFT JOIN LATERAL (
    SELECT value
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_low'
       AND t.ts <= now()
       AND ts <= t.ts
       AND (expired_at IS NULL OR expired_at > t.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS actual_vpd_low ON true
LEFT JOIN LATERAL (
    SELECT value
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_high'
       AND t.ts <= now()
       AND ts <= t.ts
       AND (expired_at IS NULL OR expired_at > t.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS actual_vpd_high ON true
LEFT JOIN LATERAL (
    SELECT
        c.temp_avg,
        c.vpd_avg,
        c.outdoor_temp_f,
        CASE
            WHEN c.outdoor_temp_f IS NOT NULL AND c.outdoor_rh_pct IS NOT NULL THEN
                0.6108
                * exp(17.27 * ((c.outdoor_temp_f - 32.0) / 1.8)
                      / (((c.outdoor_temp_f - 32.0) / 1.8) + 237.3))
                * (1.0 - c.outdoor_rh_pct / 100.0)
            ELSE NULL
        END AS outdoor_vpd_kpa,
        c.solar_irradiance_w_m2 AS solar_w_m2
      FROM climate c
     WHERE c.greenhouse_id = p_greenhouse_id
       AND t.ts <= now()
       AND c.ts <= t.ts
       AND c.ts >= t.ts - interval '15 minutes'
     ORDER BY c.ts DESC
    LIMIT 1
) AS actual_climate ON true
LEFT JOIN forecast_hourly forecast
       ON t.ts > now()
      AND forecast.forecast_hour = date_trunc('hour', t.ts + interval '30 minutes')
),
with_tunables AS (
    SELECT
        r.*,
        greatest(2.0, r.firmware_temp_high - r.firmware_temp_low) AS temp_width_f,
        greatest(0.2, r.firmware_vpd_high - r.firmware_vpd_low) AS vpd_width_kpa,
        fn_timeline_setpoint_value(p_greenhouse_id, 'sw_fsm_controller_enabled', r.ts, 1.0) >= 0.5
            AS sw_fsm_controller_enabled,
        fn_timeline_setpoint_value(p_greenhouse_id, 'temp_hysteresis', r.ts, 1.5)
            AS temp_hysteresis_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'heat_hysteresis', r.ts, 1.0)
            AS heat_hysteresis_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'd_heat_stage_2', r.ts, 5.0)
            AS d_heat_stage_2_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'd_cool_stage_2', r.ts, 3.0)
            AS d_cool_stage_2_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'bias_heat', r.ts, 0.0)
            AS bias_heat_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'bias_cool', r.ts, 0.0)
            AS bias_cool_f,
        fn_timeline_setpoint_value(p_greenhouse_id, 'vpd_hysteresis', r.ts, 0.3)
            AS vpd_hysteresis_kpa,
        fn_timeline_setpoint_value(p_greenhouse_id, 'fog_escalation_kpa', r.ts, 0.4)
            AS fog_escalation_kpa
    FROM resolved r
),
derived_base AS (
    SELECT
        t.*,
        CASE
            WHEN t.sw_fsm_controller_enabled THEN
                least(greatest(0.05, t.vpd_hysteresis_kpa), greatest(0.05, t.vpd_width_kpa * 0.33))
            ELSE
                least(greatest(0.05, t.vpd_hysteresis_kpa), t.firmware_vpd_high * 0.5)
        END AS vpd_hysteresis_effective_kpa,
        CASE
            WHEN t.sw_fsm_controller_enabled THEN
                t.firmware_temp_low + t.temp_width_f * 0.25
            ELSE
                t.firmware_temp_low + t.temp_width_f * 0.25 + t.bias_heat_f
        END AS temp_heat_target_f,
        CASE
            WHEN t.sw_fsm_controller_enabled THEN
                least(t.d_cool_stage_2_f, greatest(1.0, t.temp_width_f * 0.25))
            ELSE
                t.d_cool_stage_2_f
        END AS temp_cool_stage2_delta_f,
        t.firmware_vpd_low + t.vpd_width_kpa * 0.25 AS vpd_low_eff_kpa,
        t.firmware_vpd_high - t.vpd_width_kpa * 0.25 AS vpd_high_eff_kpa
    FROM with_tunables t
),
derived AS (
    SELECT
        b.*,
        (
            b.outdoor_temp_f IS NOT NULL
            AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
        ) AS outdoor_cold_for_vent,
        CASE
            WHEN b.sw_fsm_controller_enabled
             AND b.outdoor_temp_f IS NOT NULL
             AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
                THEN b.temp_cool_stage2_delta_f
            ELSE 0.0
        END AS temp_cooling_entry_margin_f,
        CASE
            WHEN b.sw_fsm_controller_enabled
             AND b.outdoor_temp_f IS NOT NULL
             AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
                THEN greatest(b.temp_hysteresis_f, 3.0)
            ELSE b.temp_hysteresis_f
        END AS temp_cooling_exit_hysteresis_f,
        CASE
            WHEN b.sw_fsm_controller_enabled
             AND NOT (
                 b.outdoor_temp_f IS NOT NULL
                 AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
             )
             AND b.solar_w_m2 IS NOT NULL
             AND b.solar_w_m2 >= 500.0
             AND extract(hour FROM b.ts AT TIME ZONE 'America/Denver') BETWEEN 10 AND 17
             AND b.indoor_vpd_kpa IS NOT NULL
             AND b.indoor_vpd_kpa <= (b.firmware_vpd_high - b.vpd_hysteresis_effective_kpa)
                THEN 1.0
            ELSE 0.0
        END AS solar_cooling_lead_f,
        CASE
            WHEN b.sw_fsm_controller_enabled THEN
                greatest(
                    b.firmware_temp_low + 1.0,
                    b.firmware_temp_high
                    + CASE
                        WHEN b.outdoor_temp_f IS NOT NULL
                         AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
                            THEN b.temp_cool_stage2_delta_f
                        ELSE 0.0
                    END
                    - CASE
                        WHEN NOT (
                            b.outdoor_temp_f IS NOT NULL
                            AND b.outdoor_temp_f < (b.firmware_temp_low - 10.0)
                        )
                         AND b.solar_w_m2 IS NOT NULL
                         AND b.solar_w_m2 >= 500.0
                         AND extract(hour FROM b.ts AT TIME ZONE 'America/Denver') BETWEEN 10 AND 17
                         AND b.indoor_vpd_kpa IS NOT NULL
                         AND b.indoor_vpd_kpa <= (b.firmware_vpd_high - b.vpd_hysteresis_effective_kpa)
                            THEN 1.0
                        ELSE 0.0
                    END
                )
            ELSE
                b.firmware_temp_high - b.temp_width_f * 0.25 + b.bias_cool_f
        END AS temp_cool_on_above_f
    FROM derived_base b
)
SELECT
    d.ts,
    d.greenhouse_id,
    d.timeline_phase,
    d.crop_temp_low,
    d.crop_temp_high,
    d.crop_vpd_low,
    d.crop_vpd_high,
    d.projected_temp_low,
    d.projected_temp_high,
    d.projected_vpd_low,
    d.projected_vpd_high,
    d.actual_temp_low,
    d.actual_temp_high,
    d.actual_vpd_low,
    d.actual_vpd_high,
    d.firmware_temp_low,
    d.firmware_temp_high,
    d.firmware_vpd_low,
    d.firmware_vpd_high,
    d.temp_width_f,
    d.vpd_width_kpa,
    d.sw_fsm_controller_enabled,
    d.indoor_temp_f,
    d.indoor_vpd_kpa,
    d.outdoor_temp_f,
    d.outdoor_vpd_kpa,
    d.solar_w_m2,
    d.outdoor_cold_for_vent,
    d.temp_hysteresis_f,
    d.heat_hysteresis_f,
    d.d_heat_stage_2_f,
    d.d_cool_stage_2_f,
    d.bias_heat_f,
    d.bias_cool_f,
    d.vpd_hysteresis_kpa,
    d.vpd_hysteresis_effective_kpa,
    d.fog_escalation_kpa,
    d.temp_heat_target_f,
    d.temp_heat_target_f + d.heat_hysteresis_f AS temp_heat_on_below_f,
    CASE
        WHEN d.sw_fsm_controller_enabled THEN d.firmware_temp_low
        ELSE d.temp_heat_target_f - d.d_heat_stage_2_f
    END AS temp_heat2_on_below_f,
    CASE
        WHEN d.sw_fsm_controller_enabled THEN d.temp_heat_target_f
        ELSE d.temp_heat_target_f + d.heat_hysteresis_f
    END AS temp_heat2_clear_f,
    d.temp_cool_on_above_f,
    CASE
        WHEN d.sw_fsm_controller_enabled THEN
            least(
                d.firmware_temp_high - d.temp_cooling_exit_hysteresis_f,
                d.temp_cool_on_above_f - d.temp_cooling_exit_hysteresis_f
            )
        ELSE d.temp_cool_on_above_f - d.temp_hysteresis_f
    END AS temp_cool_hold_until_f,
    d.temp_cooling_entry_margin_f,
    d.temp_cooling_exit_hysteresis_f,
    d.solar_cooling_lead_f,
    d.temp_cool_stage2_delta_f,
    CASE
        WHEN d.sw_fsm_controller_enabled THEN d.firmware_temp_high + d.temp_cool_stage2_delta_f
        ELSE d.temp_cool_on_above_f + d.temp_cool_stage2_delta_f
    END AS temp_cool_stage2_on_above_f,
    d.firmware_vpd_high AS vpd_humidify_on_above_kpa,
    d.firmware_vpd_high - d.vpd_hysteresis_effective_kpa AS vpd_humidify_resolved_below_kpa,
    CASE
        WHEN d.sw_fsm_controller_enabled AND d.outdoor_cold_for_vent THEN
            d.firmware_vpd_low - d.vpd_hysteresis_effective_kpa
        ELSE d.firmware_vpd_low
    END AS vpd_dehum_on_below_kpa,
    d.firmware_vpd_low + d.vpd_hysteresis_effective_kpa AS vpd_dehum_resolved_above_kpa,
    d.vpd_low_eff_kpa,
    d.vpd_high_eff_kpa,
    d.vpd_high_eff_kpa + d.fog_escalation_kpa AS vpd_vent_fog_on_above_kpa,
    d.firmware_vpd_high + d.fog_escalation_kpa AS vpd_sealed_fog_on_above_kpa
FROM derived d
ORDER BY d.ts;
$$;


ALTER FUNCTION public.fn_band_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_band_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_band_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text) IS 'Actual-to-forecast band timeline for dashboards: historical firmware-pushed setpoints through now, dispatcher-projected band after now, crop provenance, and firmware-derived trigger/padding thresholds. Heat target mirrors firmware lower-quartile band-first policy.';


--
-- Name: fn_band_trace(timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_band_trace(p_start timestamp with time zone, p_end timestamp with time zone, p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(ts timestamp with time zone, greenhouse_id text, temp_avg double precision, vpd_avg double precision, rh_avg double precision, dew_point double precision, temp_avg_smooth_15m double precision, vpd_avg_smooth_30m double precision, crop_temp_low double precision, crop_temp_high double precision, crop_vpd_low double precision, crop_vpd_high double precision, vpd_target_south double precision, vpd_target_west double precision, vpd_target_east double precision, vpd_target_center double precision, house_vpd_low double precision, house_vpd_high double precision, fw_temp_low double precision, fw_temp_high double precision, fw_vpd_low double precision, fw_vpd_high double precision, fw_temp_low_ts timestamp with time zone, fw_temp_high_ts timestamp with time zone, fw_vpd_low_ts timestamp with time zone, fw_vpd_high_ts timestamp with time zone, rb_temp_low double precision, rb_temp_high double precision, rb_vpd_low double precision, rb_vpd_high double precision, rb_temp_low_ts timestamp with time zone, rb_temp_high_ts timestamp with time zone, rb_vpd_low_ts timestamp with time zone, rb_vpd_high_ts timestamp with time zone, crop_temp_in_band boolean, crop_vpd_in_band boolean, crop_both_in_band boolean, fw_temp_in_band boolean, fw_vpd_in_band boolean, fw_both_in_band boolean, readback_matches_fw_temp boolean, readback_matches_fw_vpd boolean, readback_matches_fw_band boolean, fw_minus_crop_temp_low_f double precision, fw_minus_crop_temp_high_f double precision, fw_minus_crop_vpd_low_kpa double precision, fw_minus_crop_vpd_high_kpa double precision, trace_quality_flag text)
    LANGUAGE sql STABLE ROWS 10000
    AS $$
WITH climate_window AS (
    SELECT
        c.ts,
        c.greenhouse_id,
        c.temp_avg,
        c.vpd_avg,
        c.rh_avg,
        c.dew_point,
        avg(c.temp_avg) OVER (
            PARTITION BY c.greenhouse_id
            ORDER BY c.ts
            RANGE BETWEEN interval '15 minutes' PRECEDING AND CURRENT ROW
        )::double precision AS temp_avg_smooth_15m,
        avg(c.vpd_avg) OVER (
            PARTITION BY c.greenhouse_id
            ORDER BY c.ts
            RANGE BETWEEN interval '30 minutes' PRECEDING AND CURRENT ROW
        )::double precision AS vpd_avg_smooth_30m
    FROM climate c
    WHERE c.greenhouse_id = p_greenhouse_id
      AND c.ts >= p_start
      AND c.ts <= p_end
      AND c.temp_avg IS NOT NULL
      AND c.vpd_avg IS NOT NULL
)
SELECT
    cw.ts,
    cw.greenhouse_id,
    cw.temp_avg,
    cw.vpd_avg,
    cw.rh_avg,
    cw.dew_point,
    cw.temp_avg_smooth_15m,
    cw.vpd_avg_smooth_30m,
    crop.temp_low AS crop_temp_low,
    crop.temp_high AS crop_temp_high,
    house.crop_vpd_low,
    house.crop_vpd_high,
    house.vpd_target_south,
    house.vpd_target_west,
    house.vpd_target_east,
    house.vpd_target_center,
    house.house_vpd_low,
    house.house_vpd_high,
    fw_temp_low.value AS fw_temp_low,
    fw_temp_high.value AS fw_temp_high,
    fw_vpd_low.value AS fw_vpd_low,
    fw_vpd_high.value AS fw_vpd_high,
    fw_temp_low.ts AS fw_temp_low_ts,
    fw_temp_high.ts AS fw_temp_high_ts,
    fw_vpd_low.ts AS fw_vpd_low_ts,
    fw_vpd_high.ts AS fw_vpd_high_ts,
    rb_temp_low.value AS rb_temp_low,
    rb_temp_high.value AS rb_temp_high,
    rb_vpd_low.value AS rb_vpd_low,
    rb_vpd_high.value AS rb_vpd_high,
    rb_temp_low.ts AS rb_temp_low_ts,
    rb_temp_high.ts AS rb_temp_high_ts,
    rb_vpd_low.ts AS rb_vpd_low_ts,
    rb_vpd_high.ts AS rb_vpd_high_ts,
    (cw.temp_avg BETWEEN crop.temp_low AND crop.temp_high) AS crop_temp_in_band,
    (cw.vpd_avg BETWEEN house.crop_vpd_low AND house.crop_vpd_high) AS crop_vpd_in_band,
    (
        cw.temp_avg BETWEEN crop.temp_low AND crop.temp_high
        AND cw.vpd_avg BETWEEN house.crop_vpd_low AND house.crop_vpd_high
    ) AS crop_both_in_band,
    (cw.temp_avg BETWEEN fw_temp_low.value AND fw_temp_high.value) AS fw_temp_in_band,
    (cw.vpd_avg BETWEEN fw_vpd_low.value AND fw_vpd_high.value) AS fw_vpd_in_band,
    (
        cw.temp_avg BETWEEN fw_temp_low.value AND fw_temp_high.value
        AND cw.vpd_avg BETWEEN fw_vpd_low.value AND fw_vpd_high.value
    ) AS fw_both_in_band,
    (
        rb_temp_low.value IS NOT NULL
        AND rb_temp_high.value IS NOT NULL
        AND fw_temp_low.value IS NOT NULL
        AND fw_temp_high.value IS NOT NULL
        AND abs(rb_temp_low.value - fw_temp_low.value) / greatest(abs(fw_temp_low.value), 1e-3) < 0.01
        AND abs(rb_temp_high.value - fw_temp_high.value) / greatest(abs(fw_temp_high.value), 1e-3) < 0.01
    ) AS readback_matches_fw_temp,
    (
        rb_vpd_low.value IS NOT NULL
        AND rb_vpd_high.value IS NOT NULL
        AND fw_vpd_low.value IS NOT NULL
        AND fw_vpd_high.value IS NOT NULL
        AND abs(rb_vpd_low.value - fw_vpd_low.value) / greatest(abs(fw_vpd_low.value), 1e-3) < 0.01
        AND abs(rb_vpd_high.value - fw_vpd_high.value) / greatest(abs(fw_vpd_high.value), 1e-3) < 0.01
    ) AS readback_matches_fw_vpd,
    (
        rb_temp_low.value IS NOT NULL
        AND rb_temp_high.value IS NOT NULL
        AND rb_vpd_low.value IS NOT NULL
        AND rb_vpd_high.value IS NOT NULL
        AND fw_temp_low.value IS NOT NULL
        AND fw_temp_high.value IS NOT NULL
        AND fw_vpd_low.value IS NOT NULL
        AND fw_vpd_high.value IS NOT NULL
        AND abs(rb_temp_low.value - fw_temp_low.value) / greatest(abs(fw_temp_low.value), 1e-3) < 0.01
        AND abs(rb_temp_high.value - fw_temp_high.value) / greatest(abs(fw_temp_high.value), 1e-3) < 0.01
        AND abs(rb_vpd_low.value - fw_vpd_low.value) / greatest(abs(fw_vpd_low.value), 1e-3) < 0.01
        AND abs(rb_vpd_high.value - fw_vpd_high.value) / greatest(abs(fw_vpd_high.value), 1e-3) < 0.01
    ) AS readback_matches_fw_band,
    fw_temp_low.value - crop.temp_low AS fw_minus_crop_temp_low_f,
    fw_temp_high.value - crop.temp_high AS fw_minus_crop_temp_high_f,
    fw_vpd_low.value - house.crop_vpd_low AS fw_minus_crop_vpd_low_kpa,
    fw_vpd_high.value - house.crop_vpd_high AS fw_minus_crop_vpd_high_kpa,
    CASE
        WHEN crop.temp_low IS NULL
          OR crop.temp_high IS NULL
          OR house.crop_vpd_low IS NULL
          OR house.crop_vpd_high IS NULL
            THEN 'missing_crop_band'
        WHEN fw_temp_low.value IS NULL
          OR fw_temp_high.value IS NULL
          OR fw_vpd_low.value IS NULL
          OR fw_vpd_high.value IS NULL
            THEN 'missing_fw_band'
        WHEN rb_temp_low.value IS NULL
          OR rb_temp_high.value IS NULL
          OR rb_vpd_low.value IS NULL
          OR rb_vpd_high.value IS NULL
            THEN 'missing_readback'
        WHEN NOT (
            abs(rb_temp_low.value - fw_temp_low.value) / greatest(abs(fw_temp_low.value), 1e-3) < 0.01
            AND abs(rb_temp_high.value - fw_temp_high.value) / greatest(abs(fw_temp_high.value), 1e-3) < 0.01
            AND abs(rb_vpd_low.value - fw_vpd_low.value) / greatest(abs(fw_vpd_low.value), 1e-3) < 0.01
            AND abs(rb_vpd_high.value - fw_vpd_high.value) / greatest(abs(fw_vpd_high.value), 1e-3) < 0.01
        )
            THEN 'readback_drift'
        ELSE 'ok'
    END AS trace_quality_flag
FROM climate_window cw
CROSS JOIN LATERAL fn_band_setpoints(cw.ts) AS crop
CROSS JOIN LATERAL fn_house_vpd_control_band(cw.ts) AS house
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_low'
       AND ts <= cw.ts
       AND (expired_at IS NULL OR expired_at > cw.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS fw_temp_low ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_high'
       AND ts <= cw.ts
       AND (expired_at IS NULL OR expired_at > cw.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS fw_temp_high ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_low'
       AND ts <= cw.ts
       AND (expired_at IS NULL OR expired_at > cw.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS fw_vpd_low ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_changes
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_high'
       AND ts <= cw.ts
       AND (expired_at IS NULL OR expired_at > cw.ts)
     ORDER BY ts DESC
     LIMIT 1
) AS fw_vpd_high ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_snapshot
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_low'
       AND ts <= cw.ts
     ORDER BY ts DESC
     LIMIT 1
) AS rb_temp_low ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_snapshot
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'temp_high'
       AND ts <= cw.ts
     ORDER BY ts DESC
     LIMIT 1
) AS rb_temp_high ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_snapshot
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_low'
       AND ts <= cw.ts
     ORDER BY ts DESC
     LIMIT 1
) AS rb_vpd_low ON true
LEFT JOIN LATERAL (
    SELECT value, ts
      FROM setpoint_snapshot
     WHERE greenhouse_id = p_greenhouse_id
       AND parameter = 'vpd_high'
       AND ts <= cw.ts
     ORDER BY ts DESC
     LIMIT 1
) AS rb_vpd_high ON true
ORDER BY cw.ts;
$$;


ALTER FUNCTION public.fn_band_trace(p_start timestamp with time zone, p_end timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_band_trace(p_start timestamp with time zone, p_end timestamp with time zone, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_band_trace(p_start timestamp with time zone, p_end timestamp with time zone, p_greenhouse_id text) IS 'Canonical sample-level band trace: raw/smoothed climate, crop targets, firmware setpoints, cfg readbacks, compliance flags, and trace quality.';


--
-- Name: fn_center_band_setpoints(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_center_band_setpoints(target_ts timestamp with time zone) RETURNS TABLE(temp_low double precision, temp_high double precision, vpd_low double precision, vpd_high double precision)
    LANGUAGE plpgsql STABLE ROWS 1
    AS $$
DECLARE
    v_season text;
    night_tl double precision; night_th double precision; night_vl double precision; night_vh double precision;
    day_tl double precision; day_th double precision; day_vl double precision; day_vh double precision;
BEGIN
    v_season := fn_current_season();

    -- endpoints from the active orchid (center) profile rows, catalog+is_active join
    SELECT avg(p.temp_ideal_min) FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
           avg(p.temp_ideal_max) FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
           avg(p.vpd_ideal_min)  FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
           avg(p.vpd_ideal_max)  FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
           avg(p.temp_ideal_min) FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
           avg(p.temp_ideal_max) FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
           avg(p.vpd_ideal_min)  FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
           avg(p.vpd_ideal_max)  FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15)
      INTO night_tl, night_th, night_vl, night_vh, day_tl, day_th, day_vl, day_vh
      FROM crop_target_profiles p
      JOIN crops c ON c.crop_catalog_id = p.crop_catalog_id
                  AND c.is_active
                  AND c.greenhouse_id = p.greenhouse_id
     WHERE p.crop_catalog_id = 9            -- orchid
       AND p.greenhouse_id = 'vallery'
       AND p.season = v_season;

    -- nearest-season fallback: if the current season has no rows, use spring
    -- (the authored active-season baseline) so no hour ever returns NULL.
    IF night_tl IS NULL OR day_tl IS NULL THEN
        SELECT avg(p.temp_ideal_min) FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
               avg(p.temp_ideal_max) FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
               avg(p.vpd_ideal_min)  FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
               avg(p.vpd_ideal_max)  FILTER (WHERE p.hour_of_day BETWEEN 0 AND 5),
               avg(p.temp_ideal_min) FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
               avg(p.temp_ideal_max) FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
               avg(p.vpd_ideal_min)  FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15),
               avg(p.vpd_ideal_max)  FILTER (WHERE p.hour_of_day BETWEEN 13 AND 15)
          INTO night_tl, night_th, night_vl, night_vh, day_tl, day_th, day_vl, day_vh
          FROM crop_target_profiles p
          JOIN crops c ON c.crop_catalog_id = p.crop_catalog_id
                      AND c.is_active
                      AND c.greenhouse_id = p.greenhouse_id
         WHERE p.crop_catalog_id = 9
           AND p.greenhouse_id = 'vallery'
           AND p.season = 'spring';
    END IF;

    -- final defensive fallback to the design anchors if the profile is missing
    -- entirely (e.g. orchid de-activated) so the served band is never NULL.
    night_tl := COALESCE(night_tl, 61.0); night_th := COALESCE(night_th, 67.0);
    night_vl := COALESCE(night_vl, 0.75);  night_vh := COALESCE(night_vh, 0.85);
    day_tl   := COALESCE(day_tl, 77.4);    day_th   := COALESCE(day_th, 87.3);
    day_vl   := COALESCE(day_vl, 0.94);    day_vh   := COALESCE(day_vh, 1.19);

    temp_low  := fn_diurnal_interp(target_ts, night_tl, day_tl);
    temp_high := fn_diurnal_interp(target_ts, night_th, day_th);
    vpd_low   := fn_diurnal_interp(target_ts, night_vl, day_vl);
    vpd_high  := fn_diurnal_interp(target_ts, night_vh, day_vh);
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_center_band_setpoints(target_ts timestamp with time zone) OWNER TO verdify;

--
-- Name: fn_climate_action_effectiveness(interval); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_climate_action_effectiveness(p_window interval) RETURNS TABLE(action_ts timestamp with time zone, greenhouse_id text, climate_action text, priority_axis text, plan_id text, trigger_id uuid, planner_instance text, temp_band_error_before_f double precision, vpd_band_error_before_kpa double precision, temp_band_error_after_f double precision, vpd_band_error_after_kpa double precision, temp_abs_error_delta_f double precision, vpd_abs_error_delta_kpa double precision, recovered_within_window boolean, time_to_recover_s double precision, wet_relay_duty_pct double precision, vent_fan_duty_pct double precision, fog_duty_pct double precision, mister_water_delta_gal double precision, outdoor_temp_f double precision, outdoor_dewpoint_f double precision, solar_irradiance_w_m2 double precision, wet_assist_allowed boolean, wet_assist_block_reason text, fog_allowed boolean, fog_block_reason text, relay_truth jsonb, resource_cost_estimate jsonb)
    LANGUAGE sql STABLE
    AS $$
WITH base AS (
    SELECT
        l.*,
        c0.ts AS before_climate_ts,
        c0.temp_avg AS before_temp_f,
        c0.vpd_avg AS before_vpd_kpa,
        c0.mister_water_today AS before_mister_water_gal,
        c0.outdoor_temp_f,
        c0.outdoor_rh_pct,
        c0.dew_point AS before_dew_point_f,
        c0.solar_irradiance_w_m2,
        c1.ts AS after_climate_ts,
        c1.temp_avg AS after_temp_f,
        c1.vpd_avg AS after_vpd_kpa,
        c1.mister_water_today AS after_mister_water_gal,
        fn_setpoint_at(l.greenhouse_id, 'temp_low', COALESCE(c1.ts, l.ts)) AS after_temp_low,
        fn_setpoint_at(l.greenhouse_id, 'temp_high', COALESCE(c1.ts, l.ts)) AS after_temp_high,
        fn_setpoint_at(l.greenhouse_id, 'vpd_low', COALESCE(c1.ts, l.ts)) AS after_vpd_low,
        fn_setpoint_at(l.greenhouse_id, 'vpd_high', COALESCE(c1.ts, l.ts)) AS after_vpd_high
    FROM public.climate_action_log l
    LEFT JOIN LATERAL (
        SELECT c.*
        FROM public.climate c
        WHERE COALESCE(c.greenhouse_id, 'vallery') = COALESCE(l.greenhouse_id, 'vallery')
          AND c.temp_avg IS NOT NULL
          AND c.vpd_avg IS NOT NULL
          AND c.ts <= l.ts
        ORDER BY c.ts DESC
        LIMIT 1
    ) c0 ON true
    LEFT JOIN LATERAL (
        SELECT c.*
        FROM public.climate c
        WHERE COALESCE(c.greenhouse_id, 'vallery') = COALESCE(l.greenhouse_id, 'vallery')
          AND c.temp_avg IS NOT NULL
          AND c.vpd_avg IS NOT NULL
          AND c.ts >= l.ts + p_window
          AND c.ts <= l.ts + p_window + interval '3 minutes'
        ORDER BY c.ts ASC
        LIMIT 1
    ) c1 ON true
    WHERE l.ts >= now() - interval '14 days'
),
scored AS (
    SELECT
        b.*,
        CASE
            WHEN b.after_temp_f IS NULL OR b.after_temp_low IS NULL OR b.after_temp_high IS NULL THEN NULL
            WHEN b.after_temp_f < b.after_temp_low THEN b.after_temp_f - b.after_temp_low
            WHEN b.after_temp_f > b.after_temp_high THEN b.after_temp_f - b.after_temp_high
            ELSE 0.0
        END AS after_temp_band_error,
        CASE
            WHEN b.after_vpd_kpa IS NULL OR b.after_vpd_low IS NULL OR b.after_vpd_high IS NULL THEN NULL
            WHEN b.after_vpd_kpa < b.after_vpd_low THEN b.after_vpd_kpa - b.after_vpd_low
            WHEN b.after_vpd_kpa > b.after_vpd_high THEN b.after_vpd_kpa - b.after_vpd_high
            ELSE 0.0
        END AS after_vpd_band_error
    FROM base b
)
SELECT
    s.ts AS action_ts,
    s.greenhouse_id,
    s.climate_action,
    s.priority_axis,
    s.plan_id,
    s.trigger_id,
    s.planner_instance,
    s.temp_band_error_f AS temp_band_error_before_f,
    s.vpd_band_error_kpa AS vpd_band_error_before_kpa,
    s.after_temp_band_error AS temp_band_error_after_f,
    s.after_vpd_band_error AS vpd_band_error_after_kpa,
    CASE
        WHEN s.after_temp_band_error IS NULL OR s.temp_band_error_f IS NULL THEN NULL
        ELSE abs(s.after_temp_band_error) - abs(s.temp_band_error_f)
    END AS temp_abs_error_delta_f,
    CASE
        WHEN s.after_vpd_band_error IS NULL OR s.vpd_band_error_kpa IS NULL THEN NULL
        ELSE abs(s.after_vpd_band_error) - abs(s.vpd_band_error_kpa)
    END AS vpd_abs_error_delta_kpa,
    recovery.time_to_recover_s IS NOT NULL AS recovered_within_window,
    recovery.time_to_recover_s,
    duty.wet_relay_duty_pct,
    duty.vent_fan_duty_pct,
    duty.fog_duty_pct,
    CASE
        WHEN s.before_mister_water_gal IS NULL OR s.after_mister_water_gal IS NULL THEN NULL
        ELSE greatest(0.0, s.after_mister_water_gal - s.before_mister_water_gal)
    END AS mister_water_delta_gal,
    s.outdoor_temp_f,
    CASE
        WHEN s.outdoor_temp_f IS NULL OR s.outdoor_rh_pct IS NULL OR s.outdoor_rh_pct <= 0 THEN NULL
        ELSE (
            243.04 * (
                ln(s.outdoor_rh_pct / 100.0)
                + ((17.625 * ((s.outdoor_temp_f - 32.0) * 5.0 / 9.0))
                   / (243.04 + ((s.outdoor_temp_f - 32.0) * 5.0 / 9.0)))
            )
            / (
                17.625
                - ln(s.outdoor_rh_pct / 100.0)
                - ((17.625 * ((s.outdoor_temp_f - 32.0) * 5.0 / 9.0))
                   / (243.04 + ((s.outdoor_temp_f - 32.0) * 5.0 / 9.0)))
            )
        ) * 9.0 / 5.0 + 32.0
    END AS outdoor_dewpoint_f,
    s.solar_irradiance_w_m2,
    s.wet_assist_allowed,
    s.wet_assist_block_reason,
    s.fog_allowed,
    s.fog_block_reason,
    s.relay_truth,
    s.resource_cost_estimate
FROM scored s
LEFT JOIN LATERAL (
    SELECT extract(epoch FROM min(c.ts - s.ts))::double precision AS time_to_recover_s
    FROM public.climate c
    WHERE COALESCE(c.greenhouse_id, 'vallery') = COALESCE(s.greenhouse_id, 'vallery')
      AND c.ts >= s.ts
      AND c.ts <= s.ts + p_window
      AND c.temp_avg BETWEEN COALESCE(fn_setpoint_at(s.greenhouse_id, 'temp_low', c.ts), -1000)
                         AND COALESCE(fn_setpoint_at(s.greenhouse_id, 'temp_high', c.ts), 1000)
      AND c.vpd_avg BETWEEN COALESCE(fn_setpoint_at(s.greenhouse_id, 'vpd_low', c.ts), -1000)
                        AND COALESCE(fn_setpoint_at(s.greenhouse_id, 'vpd_high', c.ts), 1000)
) recovery ON true
LEFT JOIN LATERAL (
    SELECT
        round((avg((
            COALESCE(fn_equip_at('fog', sample_ts), false)
            OR COALESCE(fn_equip_at('mister_south', sample_ts), false)
            OR COALESCE(fn_equip_at('mister_west', sample_ts), false)
            OR COALESCE(fn_equip_at('mister_center', sample_ts), false)
        )::int) * 100.0)::numeric, 2)::double precision AS wet_relay_duty_pct,
        round((avg((
            COALESCE(fn_equip_at('vent', sample_ts), false)
            OR COALESCE(fn_equip_at('fan1', sample_ts), false)
            OR COALESCE(fn_equip_at('fan2', sample_ts), false)
        )::int) * 100.0)::numeric, 2)::double precision AS vent_fan_duty_pct,
        round((avg(COALESCE(fn_equip_at('fog', sample_ts), false)::int) * 100.0)::numeric, 2)::double precision
            AS fog_duty_pct
    FROM generate_series(s.ts, s.ts + p_window, interval '1 minute') AS sample(sample_ts)
) duty ON true;
$$;


