-- Name: fn_deactivate_future_plans(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_deactivate_future_plans() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE setpoint_plan SET is_active = false WHERE ts > now() AND is_active = true;
END;
$$;


