--
-- Name: fn_equipment_health(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_equipment_health() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    score INT := 100;
    rssi FLOAT;
    heap FLOAT;
    stuck_count INT;
    probe TEXT;
BEGIN
    SELECT wifi_rssi, heap_bytes, probe_health
    INTO rssi, heap, probe
    FROM diagnostics
    ORDER BY ts DESC LIMIT 1;

    -- WiFi deductions
    IF rssi IS NOT NULL THEN
        IF rssi < -85 THEN score := score - 25;
        ELSIF rssi < -75 THEN score := score - 10;
        END IF;
    END IF;

    -- Heap deductions (heap_bytes is stored in KB)
    IF heap IS NOT NULL THEN
        IF heap < 15 THEN score := score - 25;
        ELSIF heap < 30 THEN score := score - 10;
        END IF;
    END IF;

    -- Stuck relay deductions
    BEGIN
        SELECT COUNT(*) INTO stuck_count
        FROM v_relay_stuck
        WHERE is_stuck = TRUE;
        score := score - (stuck_count * 20);
    EXCEPTION WHEN undefined_table THEN
        NULL;
    END;

    -- Probe health deductions
    IF probe IS NOT NULL AND probe != 'OK' THEN
        score := score - 15;
    END IF;

    RETURN GREATEST(0, score);
END;
$$;


ALTER FUNCTION public.fn_equipment_health() OWNER TO verdify;

--
-- Name: fn_forecast_correction(text, numeric); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_forecast_correction(param text, lead_hours_max numeric DEFAULT 24) RETURNS TABLE(parameter text, avg_error numeric, samples bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    param AS parameter,
    CASE param
      WHEN 'temp_f' THEN ROUND(AVG(temp_error)::numeric, 1)
      WHEN 'solar_w_m2' THEN ROUND(AVG(solar_error)::numeric, 0)
    END AS avg_error,
    count(*) AS samples
  FROM v_forecast_vs_actual
  WHERE hour > now() - interval '7 days'
  AND actual_temp IS NOT NULL
  AND EXTRACT(EPOCH FROM now() - hour) / 3600 <= lead_hours_max;
$$;


ALTER FUNCTION public.fn_forecast_correction(param text, lead_hours_max numeric) OWNER TO verdify;

--
-- Name: FUNCTION fn_forecast_correction(param text, lead_hours_max numeric); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_forecast_correction(param text, lead_hours_max numeric) IS 'Rolling 7-day forecast bias. Usage: SELECT * FROM fn_forecast_correction(''temp_f'', 24) → avg temp error for ≤24h forecasts.';


--
-- Name: fn_forecast_dli(date); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_forecast_dli(target_date date DEFAULT (CURRENT_DATE + 1)) RETURNS TABLE(predicted_dli numeric, gl_hours_needed numeric, recommended_gl_start integer, recommended_gl_end integer)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  POLY_DIRECT_TRANSMISSION CONSTANT float := 0.20;   -- frosted polycarbonate direct
  POLY_DIFFUSE_TRANSMISSION CONSTANT float := 0.25;   -- frosted polycarbonate diffuse
  UMOL_PER_W CONSTANT float := 2.02;                  -- PAR conversion (W/m² → µmol/m²/s)
  ACHIEVABLE_DLI_TARGET CONSTANT float := 10.0;       -- realistic target (not 14)
  GL_DLI_PER_HOUR CONSTANT float := 1.15;             -- grow light contribution (mol/m²/d per hour)
  -- Shadow window: house blocks before 11 AM local, trees block after 4 PM local
  SHADOW_START CONSTANT int := 11;  -- hour (local) house shadow clears
  SHADOW_END CONSTANT int := 16;    -- hour (local) tree shadow starts
BEGIN
  RETURN QUERY
  WITH hourly AS (
    SELECT DISTINCT ON (f.ts)
      EXTRACT(HOUR FROM f.ts AT TIME ZONE 'America/Denver')::int AS local_hour,
      f.direct_radiation_w_m2,
      f.diffuse_radiation_w_m2,
      f.sunshine_duration_s,
      -- Shadow factor: 0 if blocked, 1 if clear, partial for transition hours
      CASE
        WHEN EXTRACT(HOUR FROM f.ts AT TIME ZONE 'America/Denver') < SHADOW_START THEN 0.1  -- house shadow
        WHEN EXTRACT(HOUR FROM f.ts AT TIME ZONE 'America/Denver') >= SHADOW_END THEN 0.1   -- tree shadow
        ELSE 1.0  -- clear window
      END AS shadow_factor
    FROM weather_forecast f
    WHERE f.ts::date = target_date
    AND f.direct_radiation_w_m2 IS NOT NULL
    ORDER BY f.ts, f.fetched_at DESC
  ),
  dli_calc AS (
    SELECT SUM(
      (
        COALESCE(direct_radiation_w_m2, 0) * POLY_DIRECT_TRANSMISSION * shadow_factor
        + COALESCE(diffuse_radiation_w_m2, 0) * POLY_DIFFUSE_TRANSMISSION
      ) * UMOL_PER_W  -- µmol/m²/s indoor
      * COALESCE(sunshine_duration_s, 3600) / 1e6  -- convert to mol for this hour
    ) AS natural_dli
    FROM hourly
    WHERE direct_radiation_w_m2 > 0 OR diffuse_radiation_w_m2 > 0
  )
  SELECT
    ROUND(dc.natural_dli::numeric, 1) AS predicted_dli,
    ROUND(GREATEST(0, (ACHIEVABLE_DLI_TARGET - dc.natural_dli) / GL_DLI_PER_HOUR)::numeric, 1) AS gl_hours_needed,
    -- Recommend grow lights before shadow clears (morning fill) and after shadow falls (evening extend)
    7 AS recommended_gl_start,  -- 7 AM (before 11 AM shadow clear)
    19 AS recommended_gl_end    -- 7 PM (after 4 PM shadow fall)
  FROM dli_calc dc;
END;
$$;


ALTER FUNCTION public.fn_forecast_dli(target_date date) OWNER TO verdify;

--
-- Name: FUNCTION fn_forecast_dli(target_date date); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_forecast_dli(target_date date) IS 'Predict natural DLI from Open-Meteo forecast. Accounts for polycarbonate transmission (20% direct, 25% diffuse) and house/tree shadow window (11AM-4PM clear). Returns predicted DLI + grow light hours needed to reach 10 mol/m²/d.';


--
-- Name: fn_glazing_transmission(double precision); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_glazing_transmission(azimuth_deg double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN azimuth_deg BETWEEN 210 AND 240 THEN 0.235  -- SW: best angle
    WHEN azimuth_deg BETWEEN 240 AND 300 THEN 0.200  -- West
    WHEN azimuth_deg BETWEEN 150 AND 210 THEN 0.149  -- South (solar noon)
    WHEN azimuth_deg BETWEEN 120 AND 150 THEN 0.084  -- SE
    WHEN azimuth_deg BETWEEN 60 AND 120  THEN 0.069  -- East (tree shadow)
    WHEN azimuth_deg < 60 OR azimuth_deg > 300 THEN 0.05  -- North-facing (minimal)
    ELSE 0.15  -- fallback average
  END;
$$;


ALTER FUNCTION public.fn_glazing_transmission(azimuth_deg double precision) OWNER TO verdify;

--
-- Name: fn_grade_credit(numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_grade_credit(x numeric, stress_lo numeric, ideal_lo numeric, ideal_hi numeric, stress_hi numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN x IS NULL THEN NULL
    WHEN x BETWEEN ideal_lo AND ideal_hi THEN 1.0
    WHEN x < stress_lo OR x > stress_hi THEN 0.0
    WHEN x < ideal_lo  THEN GREATEST(0, (x - stress_lo)/NULLIF(ideal_lo - stress_lo, 0))
    ELSE                    GREATEST(0, (stress_hi - x)/NULLIF(stress_hi - ideal_hi, 0))
  END;
$$;


ALTER FUNCTION public.fn_grade_credit(x numeric, stress_lo numeric, ideal_lo numeric, ideal_hi numeric, stress_hi numeric) OWNER TO verdify;

--
-- Name: FUNCTION fn_grade_credit(x numeric, stress_lo numeric, ideal_lo numeric, ideal_hi numeric, stress_hi numeric); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_grade_credit(x numeric, stress_lo numeric, ideal_lo numeric, ideal_hi numeric, stress_hi numeric) IS 'Graded compliance credit g in [0,1] for reading x against (stress_lo, ideal_lo, ideal_hi, stress_hi). 1.0 in ideal, linear partial across each stress shoulder, 0 beyond. Continuous at all edges. Apply independently to temp and VPD; zone sample score = sqrt(g_temp*g_vpd). (band-compliance design §6.1)';


--
-- Name: fn_heat_staging_inversion(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_heat_staging_inversion() RETURNS TABLE(heat2_on_since timestamp with time zone, heat1_state boolean, duration_s double precision, temp_avg double precision, temp_low double precision, d_heat_stage_2 double precision)
    LANGUAGE sql STABLE
    AS $$
    WITH latest_h2 AS (
        SELECT ts, state FROM equipment_state
        WHERE equipment = 'heat2' ORDER BY ts DESC LIMIT 1
    ),
    latest_h1 AS (
        SELECT ts, state FROM equipment_state
        WHERE equipment = 'heat1' ORDER BY ts DESC LIMIT 1
    ),
    latest_climate AS (
        SELECT temp_avg FROM climate
        WHERE temp_avg IS NOT NULL ORDER BY ts DESC LIMIT 1
    ),
    latest_sp AS (
        SELECT
            MAX(value) FILTER (WHERE parameter = 'temp_low') AS temp_low,
            MAX(value) FILTER (WHERE parameter = 'd_heat_stage_2') AS d_heat_stage_2
        FROM (
            SELECT DISTINCT ON (parameter) parameter, value
            FROM setpoint_snapshot
            WHERE parameter IN ('temp_low', 'd_heat_stage_2')
              AND ts > now() - interval '10 minutes'
            ORDER BY parameter, ts DESC
        ) sub
    )
    SELECT h2.ts, h1.state, EXTRACT(EPOCH FROM now() - h2.ts),
           c.temp_avg, sp.temp_low, sp.d_heat_stage_2
    FROM latest_h2 h2, latest_h1 h1, latest_climate c, latest_sp sp
    WHERE h2.state = true AND h1.state = false
      AND EXTRACT(EPOCH FROM now() - h2.ts) > 60;
$$;


ALTER FUNCTION public.fn_heat_staging_inversion() OWNER TO verdify;

--
-- Name: fn_house_compliance(interval); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_house_compliance(lookback interval) RETURNS TABLE(house_raw_graded_pct numeric, house_controller_attributable_pct numeric, house_unachievable_frac numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH v AS (SELECT * FROM fn_compliance_v2(lookback)),
       w AS (SELECT zone, weight FROM compliance_zone_weights WHERE greenhouse_id='vallery')
  SELECT
    ROUND((SUM(w.weight::numeric * v.overall_graded) / NULLIF(SUM(w.weight::numeric) FILTER (WHERE v.overall_graded IS NOT NULL),0)), 1),
    ROUND((SUM(w.weight::numeric * v.overall_controller_attributable)
          / NULLIF(SUM(w.weight::numeric) FILTER (WHERE v.overall_controller_attributable IS NOT NULL),0)), 1),
    ROUND((SUM(w.weight::numeric * v.unachievable_frac)
          / NULLIF(SUM(w.weight::numeric) FILTER (WHERE v.unachievable_frac IS NOT NULL),0)), 4)
  FROM v JOIN w ON w.zone = v.zone
  WHERE w.weight > 0;  -- empty zones (weight 0) excluded from the house number
$$;


ALTER FUNCTION public.fn_house_compliance(lookback interval) OWNER TO verdify;

--
-- Name: FUNCTION fn_house_compliance(lookback interval); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_house_compliance(lookback interval) IS 'Priority-weighted house compliance (band-compliance design §6.3): center 0.60 / east 0.40 / others 0. Emits raw graded + controller-attributable + unachievable_frac. Plugs drop-in into the planner_score form.';


--
-- Name: fn_house_vpd_control_band(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_house_vpd_control_band(target_ts timestamp with time zone) RETURNS TABLE(crop_vpd_low double precision, crop_vpd_high double precision, vpd_target_south double precision, vpd_target_west double precision, vpd_target_east double precision, vpd_target_center double precision, zone_vpd_min double precision, zone_vpd_median double precision, zone_vpd_max double precision, house_vpd_low double precision, house_vpd_high double precision, house_vpd_min_width_kpa double precision, house_vpd_low_margin_kpa double precision)
    LANGUAGE plpgsql STABLE ROWS 1
    AS $$
DECLARE
    v_base_low double precision;
    v_base_high double precision;
    v_south double precision;
    v_west double precision;
    v_east double precision;
    v_center double precision;
    v_targets double precision[];
    v_n integer;
    v_house_low double precision;
    v_house_high double precision;
    v_min_width constant double precision := 0.55;
    v_low_margin constant double precision := 0.20;
BEGIN
    SELECT b.vpd_low, b.vpd_high
      INTO v_base_low, v_base_high
      FROM fn_center_band_setpoints(target_ts) AS b
     LIMIT 1;

    IF v_base_low IS NULL OR v_base_high IS NULL THEN
        RETURN;
    END IF;

    SELECT z.vpd_target_south, z.vpd_target_west, z.vpd_target_east, z.vpd_target_center
      INTO v_south, v_west, v_east, v_center
      FROM fn_zone_vpd_targets(target_ts) AS z
     LIMIT 1;

    SELECT array_agg(v ORDER BY v)
      INTO v_targets
      FROM (VALUES (v_south), (v_west), (v_east), (v_center)) AS target_values(v)
     WHERE v IS NOT NULL AND v > 0 AND v < 10;

    v_n := COALESCE(array_length(v_targets, 1), 0);

    crop_vpd_low := v_base_low;
    crop_vpd_high := v_base_high;
    vpd_target_south := v_south;
    vpd_target_west := v_west;
    vpd_target_east := v_east;
    vpd_target_center := v_center;
    house_vpd_min_width_kpa := v_min_width;
    house_vpd_low_margin_kpa := v_low_margin;

    IF v_n = 0 THEN
        house_vpd_low := v_base_low;
        house_vpd_high := v_base_high;
        RETURN NEXT;
        RETURN;
    END IF;

    zone_vpd_min := v_targets[1];
    zone_vpd_max := v_targets[v_n];
    IF mod(v_n, 2) = 1 THEN
        zone_vpd_median := v_targets[(v_n + 1) / 2];
    ELSE
        zone_vpd_median := (v_targets[v_n / 2] + v_targets[(v_n / 2) + 1]) / 2.0;
    END IF;

    v_house_high := least(zone_vpd_max, greatest(v_base_high, zone_vpd_median));
    v_house_low := greatest(v_base_low, zone_vpd_min - v_low_margin);
    v_house_low := least(v_house_low, v_house_high - v_min_width);
    v_house_low := greatest(0.1, v_house_low);

    IF v_house_high - v_house_low < v_min_width THEN
        v_house_low := greatest(0.1, v_house_high - v_min_width);
    END IF;

    -- inversion guard (design §5): never return low > high.
    IF v_house_low > v_house_high THEN
        v_house_low := v_house_high;
    END IF;

    house_vpd_low := round(v_house_low::numeric, 3)::double precision;
    house_vpd_high := round(v_house_high::numeric, 3)::double precision;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION public.fn_house_vpd_control_band(target_ts timestamp with time zone) OWNER TO verdify;

--
-- Name: FUNCTION fn_house_vpd_control_band(target_ts timestamp with time zone); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_house_vpd_control_band(target_ts timestamp with time zone) IS 'Firmware house VPD band derived from crop VPD envelope plus zone VPD targets. Mirrors dispatcher control semantics: median zone high, 0.55 kPa minimum width, low-side relaxation.';


--
-- Name: fn_lighting_circuit_policy(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_lighting_circuit_policy(p_ts timestamp with time zone DEFAULT now(), p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(greenhouse_id text, ts timestamp with time zone, light_key text, equipment text, dli_target double precision, start_hour integer, cutoff_hour integer, lux_on_threshold double precision, lux_hysteresis double precision, lux_off_threshold double precision, min_on_s integer, min_off_s integer, auto_enabled boolean, source_chain text, controller_contract text)
    LANGUAGE sql STABLE
    AS $$
WITH base AS (
    SELECT * FROM fn_lighting_policy(p_ts, p_greenhouse_id)
),
recommendation AS (
    SELECT * FROM fn_lighting_lux_threshold_recommendation(p_ts, p_greenhouse_id)
),
circuits AS (
    SELECT *
    FROM (VALUES
        ('main'::text, 'grow_light_main'::text),
        ('grow'::text, 'grow_light_grow'::text)
    ) AS v(light_key, equipment)
),
latest_changes AS (
    SELECT DISTINCT ON (parameter)
        parameter,
        value::double precision AS value
    FROM setpoint_changes
    WHERE COALESCE(greenhouse_id, p_greenhouse_id) = p_greenhouse_id
      AND COALESCE(source, '') <> 'esp32'
    ORDER BY parameter, ts DESC
),
resolved AS (
    SELECT
        c.light_key,
        c.equipment,
        COALESCE(dli.value, legacy_dli.value, b.target_dli)::double precision AS dli_target,
        COALESCE(start_h.value, legacy_start.value, b.sunrise_hour)::integer AS start_hour,
        COALESCE(cutoff_h.value, legacy_cutoff.value, b.cutoff_hour)::integer AS cutoff_hour,
        COALESCE(
            lux_on.value,
            legacy_lux.value,
            r.current_gl_lux_threshold,
            r.recommended_gl_lux_threshold,
            40000.0
        )::double precision AS lux_on_threshold,
        COALESCE(
            lux_hyst.value,
            legacy_hyst.value,
            r.current_gl_lux_hysteresis,
            r.recommended_gl_lux_hysteresis,
            8000.0
        )::double precision AS lux_hysteresis,
        COALESCE(min_on.value, 120.0)::integer AS min_on_s,
        COALESCE(min_off.value, 60.0)::integer AS min_off_s,
        COALESCE(auto_mode.value, legacy_auto.value, 1.0) >= 0.5 AS auto_enabled
    FROM circuits c
    CROSS JOIN base b
    CROSS JOIN recommendation r
    LEFT JOIN latest_changes legacy_dli ON legacy_dli.parameter = 'gl_dli_target'
    LEFT JOIN latest_changes legacy_start ON legacy_start.parameter = 'gl_sunrise_hour'
    LEFT JOIN latest_changes legacy_cutoff ON legacy_cutoff.parameter = 'gl_sunset_hour'
    LEFT JOIN latest_changes legacy_lux ON legacy_lux.parameter = 'gl_lux_threshold'
    LEFT JOIN latest_changes legacy_hyst ON legacy_hyst.parameter = 'gl_lux_hysteresis'
    LEFT JOIN latest_changes legacy_auto ON legacy_auto.parameter = 'sw_gl_auto_mode'
    LEFT JOIN latest_changes dli ON dli.parameter = 'gl_' || c.light_key || '_dli_target'
    LEFT JOIN latest_changes start_h ON start_h.parameter = 'gl_' || c.light_key || '_sunrise_hour'
    LEFT JOIN latest_changes cutoff_h ON cutoff_h.parameter = 'gl_' || c.light_key || '_sunset_hour'
    LEFT JOIN latest_changes lux_on ON lux_on.parameter = 'gl_' || c.light_key || '_lux_threshold'
    LEFT JOIN latest_changes lux_hyst ON lux_hyst.parameter = 'gl_' || c.light_key || '_lux_hysteresis'
    LEFT JOIN latest_changes min_on ON min_on.parameter = 'gl_' || c.light_key || '_min_on_s'
    LEFT JOIN latest_changes min_off ON min_off.parameter = 'gl_' || c.light_key || '_min_off_s'
    LEFT JOIN latest_changes auto_mode ON auto_mode.parameter = 'sw_gl_' || c.light_key || '_auto_mode'
)
SELECT
    p_greenhouse_id AS greenhouse_id,
    p_ts AS ts,
    r.light_key,
    r.equipment,
    greatest(1.0, least(50.0, r.dli_target)) AS dli_target,
    greatest(0, least(23, r.start_hour)) AS start_hour,
    greatest(0, least(23, r.cutoff_hour)) AS cutoff_hour,
    greatest(100.0, least(100000.0, r.lux_on_threshold)) AS lux_on_threshold,
    greatest(0.0, least(25000.0, r.lux_hysteresis)) AS lux_hysteresis,
    greatest(100.0, least(100000.0, r.lux_on_threshold))
        + greatest(0.0, least(25000.0, r.lux_hysteresis)) AS lux_off_threshold,
    greatest(0, least(3600, r.min_on_s)) AS min_on_s,
    greatest(0, least(3600, r.min_off_s)) AS min_off_s,
    r.auto_enabled,
    'active crops.target_dli + Tempest lux history -> fn_lighting_circuit_policy() -> planner/default setpoints -> dispatcher/API -> ESP32 per-circuit lighting state machines -> Lutron switches -> equipment_state'::text
        AS source_chain,
    'Each circuit turns on independently inside its window when DLI is below its goal and Tempest outdoor lux is below its ON threshold; each circuit holds until lux reaches ON+hysteresis or the window/DLI/auto gate exits.'::text
        AS controller_contract
FROM resolved r;
$$;


ALTER FUNCTION public.fn_lighting_circuit_policy(p_ts timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_lighting_circuit_policy(p_ts timestamp with time zone, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_lighting_circuit_policy(p_ts timestamp with time zone, p_greenhouse_id text) IS 'Per-circuit lighting policy for ESP32 lighting state machines. Crop/DLI policy seeds defaults; planner-managed gl_main_* and gl_grow_* setpoints can diverge each circuit.';


--
-- Name: fn_lighting_lux_threshold_recommendation(timestamp with time zone, text, interval); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_lighting_lux_threshold_recommendation(p_ts timestamp with time zone DEFAULT now(), p_greenhouse_id text DEFAULT 'vallery'::text, p_window interval DEFAULT '30 days'::interval) RETURNS TABLE(greenhouse_id text, ts timestamp with time zone, sample_count integer, overcast_sample_count integer, clear_sample_count integer, overcast_p80_lux double precision, clear_p20_lux double precision, recommended_gl_lux_threshold double precision, recommended_gl_lux_hysteresis double precision, current_gl_lux_threshold double precision, current_gl_lux_hysteresis double precision, source_chain text)
    LANGUAGE sql STABLE
    AS $$
WITH daylight AS (
    SELECT
        c.ts,
        c.outdoor_lux::double precision AS outdoor_lux,
        c.solar_irradiance_w_m2::double precision AS solar_w_m2,
        fn_solar_altitude(c.ts)::double precision AS altitude_deg
    FROM climate c
    WHERE c.ts >= p_ts - p_window
      AND c.ts <= p_ts
      AND COALESCE(c.greenhouse_id, 'vallery') = p_greenhouse_id
      AND c.outdoor_lux IS NOT NULL
      AND c.solar_irradiance_w_m2 IS NOT NULL
      AND fn_solar_altitude(c.ts) >= 10
),
normalized AS (
    SELECT
        *,
        outdoor_lux / NULLIF(sin(radians(greatest(altitude_deg, 1.0))), 0.0) AS lux_norm,
        solar_w_m2 / NULLIF(sin(radians(greatest(altitude_deg, 1.0))), 0.0) AS solar_norm
    FROM daylight
),
clear_reference AS (
    SELECT
        percentile_cont(0.90) WITHIN GROUP (ORDER BY solar_norm) AS clear_solar_norm
    FROM normalized
),
classified AS (
    SELECT
        n.*,
        n.solar_norm / NULLIF(c.clear_solar_norm, 0.0) AS solar_clear_ratio
    FROM normalized n
    CROSS JOIN clear_reference c
),
stats AS (
    SELECT
        count(*)::integer AS sample_count,
        count(*) FILTER (WHERE solar_clear_ratio < 0.35)::integer AS overcast_sample_count,
        count(*) FILTER (WHERE solar_clear_ratio > 0.70)::integer AS clear_sample_count,
        percentile_cont(0.80) WITHIN GROUP (ORDER BY outdoor_lux)
            FILTER (WHERE solar_clear_ratio < 0.35) AS overcast_p80_lux,
        percentile_cont(0.20) WITHIN GROUP (ORDER BY outdoor_lux)
            FILTER (WHERE solar_clear_ratio > 0.70) AS clear_p20_lux,
        percentile_cont(0.20) WITHIN GROUP (ORDER BY outdoor_lux) AS daylight_p20_lux
    FROM classified
),
latest_thresholds AS (
    SELECT DISTINCT ON (parameter)
        parameter,
        value::double precision AS value
    FROM setpoint_changes
    WHERE COALESCE(greenhouse_id, p_greenhouse_id) = p_greenhouse_id
      AND parameter IN ('gl_main_lux_threshold', 'gl_grow_lux_threshold', 'gl_lux_threshold')
      AND COALESCE(source, '') <> 'esp32'
    ORDER BY parameter, ts DESC
),
latest_hysteresis AS (
    SELECT DISTINCT ON (parameter)
        parameter,
        value::double precision AS value
    FROM setpoint_changes
    WHERE COALESCE(greenhouse_id, p_greenhouse_id) = p_greenhouse_id
      AND parameter IN ('gl_main_lux_hysteresis', 'gl_grow_lux_hysteresis', 'gl_lux_hysteresis')
      AND COALESCE(source, '') <> 'esp32'
    ORDER BY parameter, ts DESC
),
current_threshold AS (
    SELECT
        COALESCE(
            max(value) FILTER (WHERE parameter = 'gl_main_lux_threshold'),
            max(value) FILTER (WHERE parameter = 'gl_grow_lux_threshold'),
            max(value) FILTER (WHERE parameter = 'gl_lux_threshold')
        ) AS current_gl_lux_threshold
    FROM latest_thresholds
),
current_hysteresis AS (
    SELECT
        COALESCE(
            max(value) FILTER (WHERE parameter = 'gl_main_lux_hysteresis'),
            max(value) FILTER (WHERE parameter = 'gl_grow_lux_hysteresis'),
            max(value) FILTER (WHERE parameter = 'gl_lux_hysteresis')
        ) AS current_gl_lux_hysteresis
    FROM latest_hysteresis
),
current_policy AS (
    SELECT
        current_threshold.current_gl_lux_threshold,
        current_hysteresis.current_gl_lux_hysteresis
    FROM current_threshold
    CROSS JOIN current_hysteresis
),
recommendation AS (
    SELECT
        stats.*,
        round(
            greatest(
                5000.0,
                least(
                    40000.0,
                    COALESCE(
                        (stats.overcast_p80_lux + stats.clear_p20_lux) / 2.0,
                        stats.daylight_p20_lux,
                        30000.0
                    )
                )
            )::numeric,
            -2
        )::double precision AS recommended_gl_lux_threshold
    FROM stats
)
SELECT
    p_greenhouse_id AS greenhouse_id,
    p_ts AS ts,
    r.sample_count,
    r.overcast_sample_count,
    r.clear_sample_count,
    r.overcast_p80_lux,
    r.clear_p20_lux,
    r.recommended_gl_lux_threshold,
    round(greatest(1500.0, least(10000.0, r.recommended_gl_lux_threshold * 0.20))::numeric, -2)::double precision
        AS recommended_gl_lux_hysteresis,
    COALESCE(cp.current_gl_lux_threshold, r.recommended_gl_lux_threshold, 40000.0) AS current_gl_lux_threshold,
    COALESCE(
        cp.current_gl_lux_hysteresis,
        round(greatest(1500.0, least(10000.0, r.recommended_gl_lux_threshold * 0.20))::numeric, -2)::double precision,
        8000.0
    ) AS current_gl_lux_hysteresis,
    'Tempest outdoor_lux + solar_irradiance_w_m2 history -> fn_lighting_lux_threshold_recommendation() -> Iris planner -> per-circuit gl_main_*/gl_grow_* lux tunables -> dispatcher/API -> ESP32 lighting state machines'::text
        AS source_chain
FROM recommendation r
LEFT JOIN current_policy cp ON true;
$$;


ALTER FUNCTION public.fn_lighting_lux_threshold_recommendation(p_ts timestamp with time zone, p_greenhouse_id text, p_window interval) OWNER TO verdify;

--
-- Name: FUNCTION fn_lighting_lux_threshold_recommendation(p_ts timestamp with time zone, p_greenhouse_id text, p_window interval); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_lighting_lux_threshold_recommendation(p_ts timestamp with time zone, p_greenhouse_id text, p_window interval) IS 'Recommends grow-light lux threshold/hysteresis from recent Tempest outdoor lux and solar irradiance. Overcast is solar_clear_ratio < 0.35; clear sun is > 0.70; threshold is the midpoint between overcast p80 and clear p20, clamped 5k-40k lux.';


--
-- Name: fn_lighting_minutes_policy(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_lighting_minutes_policy(p_ts timestamp with time zone DEFAULT now(), p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(greenhouse_id text, ts timestamp with time zone, light_key text, equipment text, target_light_minutes integer, start_hour integer, cutoff_hour integer, lux_on_threshold double precision, lux_hysteresis double precision, lux_off_threshold double precision, min_on_s integer, min_off_s integer, auto_enabled boolean, legacy_dli_target double precision, source_chain text, controller_contract text)
    LANGUAGE sql STABLE ROWS 2
    AS $$
WITH base AS (
    SELECT * FROM fn_lighting_policy(p_ts, p_greenhouse_id)
),
recommendation AS (
    SELECT * FROM fn_lighting_lux_threshold_recommendation(p_ts, p_greenhouse_id)
),
circuits AS (
    SELECT *
    FROM (VALUES
        ('main'::text, 'grow_light_main'::text),
        ('grow'::text, 'grow_light_grow'::text)
    ) AS v(light_key, equipment)
),
tracked_params AS (
    SELECT unnest(ARRAY[
        'gl_dli_target',
        'gl_sunrise_hour',
        'gl_sunset_hour',
        'gl_lux_threshold',
        'gl_lux_hysteresis',
        'sw_gl_auto_mode',
        'gl_main_target_light_minutes',
        'gl_main_dli_target',
        'gl_main_sunrise_hour',
        'gl_main_sunset_hour',
        'gl_main_lux_threshold',
        'gl_main_lux_hysteresis',
        'gl_main_min_on_s',
        'gl_main_min_off_s',
        'sw_gl_main_auto_mode',
        'gl_grow_target_light_minutes',
        'gl_grow_dli_target',
        'gl_grow_sunrise_hour',
        'gl_grow_sunset_hour',
        'gl_grow_lux_threshold',
        'gl_grow_lux_hysteresis',
        'gl_grow_min_on_s',
        'gl_grow_min_off_s',
        'sw_gl_grow_auto_mode'
    ]::text[]) AS parameter
),
latest_snapshot AS (
    SELECT DISTINCT ON (ss.parameter)
        ss.parameter,
        ss.value::double precision AS value,
        ss.ts,
        1 AS source_rank
    FROM setpoint_snapshot ss
    JOIN tracked_params tp ON tp.parameter = ss.parameter
    WHERE COALESCE(ss.greenhouse_id, p_greenhouse_id) = p_greenhouse_id
    ORDER BY ss.parameter, ss.ts DESC
),
latest_confirmed_changes AS (
    SELECT DISTINCT ON (sc.parameter)
        sc.parameter,
        sc.value::double precision AS value,
        COALESCE(sc.confirmed_at, sc.ts) AS ts,
        2 AS source_rank
    FROM setpoint_changes sc
    JOIN tracked_params tp ON tp.parameter = sc.parameter
    WHERE COALESCE(sc.greenhouse_id, p_greenhouse_id) = p_greenhouse_id
      AND COALESCE(sc.source, '') <> 'esp32'
      AND (
          sc.confirmed_at IS NOT NULL
          OR COALESCE(sc.delivery_status, '') = 'confirmed'
      )
      AND COALESCE(sc.delivery_status, '') NOT IN ('pending', 'superseded', 'expired', 'deferred_heap_pressure')
    ORDER BY sc.parameter, COALESCE(sc.confirmed_at, sc.ts) DESC
),
latest_switch_actual AS (
    SELECT
        'sw_gl_auto_mode'::text AS parameter,
        CASE WHEN e.state THEN 1.0 ELSE 0.0 END AS value,
        e.ts,
        0 AS source_rank
    FROM (
        SELECT DISTINCT ON (equipment) equipment, state, ts
        FROM equipment_state
        WHERE COALESCE(greenhouse_id, p_greenhouse_id) = p_greenhouse_id
          AND equipment = 'gl_auto_mode'
        ORDER BY equipment, ts DESC
    ) e
),
latest_values AS (
    SELECT DISTINCT ON (parameter)
        parameter,
        value
    FROM (
        SELECT * FROM latest_switch_actual
        UNION ALL
        SELECT * FROM latest_snapshot
        UNION ALL
        SELECT * FROM latest_confirmed_changes
    ) values_union
    ORDER BY parameter, source_rank, ts DESC
),
resolved AS (
    SELECT
        c.light_key,
        c.equipment,
        COALESCE(target_min.value, b.target_light_hours * 60.0)::double precision AS target_light_minutes,
        COALESCE(start_h.value, legacy_start.value, b.sunrise_hour)::integer AS start_hour,
        COALESCE(cutoff_h.value, legacy_cutoff.value, b.cutoff_hour)::integer AS cutoff_hour,
        COALESCE(
            lux_on.value,
            legacy_lux.value,
            r.current_gl_lux_threshold,
            r.recommended_gl_lux_threshold,
            40000.0
        )::double precision AS lux_on_threshold,
        COALESCE(
            lux_hyst.value,
            legacy_hyst.value,
            r.current_gl_lux_hysteresis,
            r.recommended_gl_lux_hysteresis,
            8000.0
        )::double precision AS lux_hysteresis,
        COALESCE(min_on.value, 120.0)::integer AS min_on_s,
        COALESCE(min_off.value, 60.0)::integer AS min_off_s,
        COALESCE(auto_mode.value, legacy_auto.value, 1.0) >= 0.5 AS auto_enabled,
        COALESCE(dli.value, legacy_dli.value, b.target_dli)::double precision AS legacy_dli_target
    FROM circuits c
    CROSS JOIN base b
    CROSS JOIN recommendation r
    LEFT JOIN latest_values legacy_dli ON legacy_dli.parameter = 'gl_dli_target'
    LEFT JOIN latest_values legacy_start ON legacy_start.parameter = 'gl_sunrise_hour'
    LEFT JOIN latest_values legacy_cutoff ON legacy_cutoff.parameter = 'gl_sunset_hour'
    LEFT JOIN latest_values legacy_lux ON legacy_lux.parameter = 'gl_lux_threshold'
    LEFT JOIN latest_values legacy_hyst ON legacy_hyst.parameter = 'gl_lux_hysteresis'
    LEFT JOIN latest_values legacy_auto ON legacy_auto.parameter = 'sw_gl_auto_mode'
    LEFT JOIN latest_values target_min ON target_min.parameter = 'gl_' || c.light_key || '_target_light_minutes'
    LEFT JOIN latest_values dli ON dli.parameter = 'gl_' || c.light_key || '_dli_target'
    LEFT JOIN latest_values start_h ON start_h.parameter = 'gl_' || c.light_key || '_sunrise_hour'
    LEFT JOIN latest_values cutoff_h ON cutoff_h.parameter = 'gl_' || c.light_key || '_sunset_hour'
    LEFT JOIN latest_values lux_on ON lux_on.parameter = 'gl_' || c.light_key || '_lux_threshold'
    LEFT JOIN latest_values lux_hyst ON lux_hyst.parameter = 'gl_' || c.light_key || '_lux_hysteresis'
    LEFT JOIN latest_values min_on ON min_on.parameter = 'gl_' || c.light_key || '_min_on_s'
    LEFT JOIN latest_values min_off ON min_off.parameter = 'gl_' || c.light_key || '_min_off_s'
    LEFT JOIN latest_values auto_mode ON auto_mode.parameter = 'sw_gl_' || c.light_key || '_auto_mode'
)
SELECT
    p_greenhouse_id AS greenhouse_id,
    p_ts AS ts,
    r.light_key,
    r.equipment,
    greatest(0, least(1080, round(r.target_light_minutes)::integer)) AS target_light_minutes,
    greatest(0, least(23, r.start_hour)) AS start_hour,
    greatest(0, least(23, r.cutoff_hour)) AS cutoff_hour,
    greatest(100.0, least(100000.0, r.lux_on_threshold)) AS lux_on_threshold,
    greatest(0.0, least(25000.0, r.lux_hysteresis)) AS lux_hysteresis,
    greatest(100.0, least(100000.0, r.lux_on_threshold))
        + greatest(0.0, least(25000.0, r.lux_hysteresis)) AS lux_off_threshold,
    greatest(0, least(3600, r.min_on_s)) AS min_on_s,
    greatest(0, least(3600, r.min_off_s)) AS min_off_s,
    r.auto_enabled,
    greatest(1.0, least(50.0, r.legacy_dli_target)) AS legacy_dli_target,
    'confirmed cfg/readback policy -> dispatcher/API -> ESP32 per-circuit qualified-minutes state machines -> Lutron switches -> equipment_state'::text
        AS source_chain,
    'Each circuit starts counting at sunrise. A minute qualifies once when natural lux is at or above the ON threshold OR the actual switch is ON. The circuit turns ON below threshold until target_light_minutes is met, with ON+hysteresis as the OFF threshold.'::text
        AS controller_contract
FROM resolved r;
$$;


ALTER FUNCTION public.fn_lighting_minutes_policy(p_ts timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_lighting_minutes_policy(p_ts timestamp with time zone, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_lighting_minutes_policy(p_ts timestamp with time zone, p_greenhouse_id text) IS 'Per-circuit qualified-light-minutes policy from confirmed cfg/readback state. Pending desired rows are intentionally excluded.';


--
-- Name: fn_lighting_policy(timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_lighting_policy(p_ts timestamp with time zone DEFAULT now(), p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(greenhouse_id text, ts timestamp with time zone, local_date date, target_dli double precision, target_ppfd_umol_m2_s double precision, target_light_hours integer, sunrise_hour integer, natural_sunset_hour integer, cutoff_hour integer, max_crop_name text, max_crop_stage text, source_chain text, controller_contract text)
    LANGUAGE sql STABLE
    AS $$
WITH crop_targets AS (
    SELECT
        c.name,
        c.stage,
        COALESCE(c.target_dli, max(ctp.dli_target_mol))::double precision AS target_dli
    FROM crops c
    LEFT JOIN crop_target_profiles ctp
      ON COALESCE(ctp.greenhouse_id, 'vallery') = p_greenhouse_id
     AND lower(ctp.crop_type) = lower(c.name)
     AND lower(COALESCE(ctp.growth_stage, 'vegetative')) = lower(COALESCE(c.stage, 'vegetative'))
    WHERE c.is_active IS TRUE
      AND COALESCE(c.greenhouse_id, 'vallery') = p_greenhouse_id
    GROUP BY c.id, c.name, c.stage, c.target_dli
),
max_crop AS (
    SELECT name, stage, target_dli
    FROM crop_targets
    WHERE target_dli IS NOT NULL
    ORDER BY target_dli DESC, name
    LIMIT 1
),
policy_input AS (
    SELECT
        COALESCE((SELECT target_dli FROM max_crop), 14.0)::double precision AS target_dli,
        400.0::double precision AS target_ppfd_umol_m2_s,
        COALESCE((SELECT name FROM max_crop), 'fallback') AS max_crop_name,
        COALESCE((SELECT stage FROM max_crop), 'unknown') AS max_crop_stage
),
local_day AS (
    SELECT date_trunc('day', p_ts AT TIME ZONE 'America/Denver') AS midnight_local
),
hourly_sun AS (
    SELECT
        h.hour_of_day,
        fn_solar_altitude((d.midnight_local + make_interval(hours => h.hour_of_day)) AT TIME ZONE 'America/Denver') AS altitude_deg
    FROM local_day d
    CROSS JOIN generate_series(0, 23) AS h(hour_of_day)
),
sun_window AS (
    SELECT
        COALESCE(min(hour_of_day) FILTER (WHERE altitude_deg > 0), 6)::integer AS sunrise_hour,
        LEAST(COALESCE(max(hour_of_day) FILTER (WHERE altitude_deg > 0), 20) + 1, 23)::integer AS natural_sunset_hour
    FROM hourly_sun
),
policy AS (
    SELECT
        p.target_dli,
        p.target_ppfd_umol_m2_s,
        GREATEST(
            10,
            LEAST(
                18,
                CEIL(p.target_dli * 1000000.0 / (p.target_ppfd_umol_m2_s * 3600.0))::integer
            )
        ) AS target_light_hours,
        p.max_crop_name,
        p.max_crop_stage
    FROM policy_input p
)
SELECT
    p_greenhouse_id AS greenhouse_id,
    p_ts AS ts,
    (p_ts AT TIME ZONE 'America/Denver')::date AS local_date,
    policy.target_dli,
    policy.target_ppfd_umol_m2_s,
    policy.target_light_hours,
    sun_window.sunrise_hour,
    sun_window.natural_sunset_hour,
    LEAST(sun_window.sunrise_hour + policy.target_light_hours, 23)::integer AS cutoff_hour,
    policy.max_crop_name,
    policy.max_crop_stage,
    'active crops.target_dli -> fn_lighting_policy() -> setpoint_dispatcher/API fallback -> ESP32 grow-light loop -> Home Assistant light services'::text AS source_chain,
    'ESP32 turns both grow-light circuits on during the crop light window when DLI is below target and lux is below threshold; deterministic cutoff remains local-hour based.'::text AS controller_contract
FROM policy
CROSS JOIN sun_window;
$$;


ALTER FUNCTION public.fn_lighting_policy(p_ts timestamp with time zone, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_lighting_policy(p_ts timestamp with time zone, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_lighting_policy(p_ts timestamp with time zone, p_greenhouse_id text) IS 'Crop-driven grow-light policy. Highest active crop DLI sets target_light_hours at 400 umol/m2/s; window starts at computed local sunrise and ends at the ESP32 cutoff hour.';


--
-- Name: fn_lighting_timeline(timestamp with time zone, timestamp with time zone, interval, text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_lighting_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval DEFAULT '00:30:00'::interval, p_greenhouse_id text DEFAULT 'vallery'::text) RETURNS TABLE(ts timestamp with time zone, natural_lux double precision, natural_lux_source text, main_lux_on_threshold double precision, main_lux_off_threshold double precision, grow_lux_on_threshold double precision, grow_lux_off_threshold double precision, main_expected_on double precision, grow_expected_on double precision, main_dli_target double precision, grow_dli_target double precision, main_target_light_minutes integer, grow_target_light_minutes integer, main_qualified_light_minutes double precision, grow_qualified_light_minutes double precision)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    r record;
    main_on boolean;
    grow_on boolean;
    main_minutes double precision := 0.0;
    grow_minutes double precision := 0.0;
    main_pre_minutes double precision;
    grow_pre_minutes double precision;
    main_in_window boolean;
    grow_in_window boolean;
    main_natural_qualified boolean;
    grow_natural_qualified boolean;
    main_want_on boolean;
    grow_want_on boolean;
    last_local_date date;
    last_local_hour integer := -1;
    step_minutes double precision := greatest(0.0, extract(epoch FROM p_step) / 60.0);
BEGIN
    SELECT COALESCE((
        SELECT e.state
        FROM equipment_state e
        WHERE COALESCE(e.greenhouse_id, p_greenhouse_id) = p_greenhouse_id
          AND e.equipment = 'grow_light_main'
          AND e.ts <= p_start
        ORDER BY e.ts DESC
        LIMIT 1
    ), false)
    INTO main_on;

    SELECT COALESCE((
        SELECT e.state
        FROM equipment_state e
        WHERE COALESCE(e.greenhouse_id, p_greenhouse_id) = p_greenhouse_id
          AND e.equipment = 'grow_light_grow'
          AND e.ts <= p_start
        ORDER BY e.ts DESC
        LIMIT 1
    ), false)
    INTO grow_on;

    FOR r IN
        WITH bounds AS (
            SELECT
                p_start AS start_ts,
                p_end AS end_ts,
                p_step AS step,
                now() AS now_ts
        ),
        series AS (
            SELECT generate_series(b.start_ts, b.end_ts, b.step) AS bucket_ts
            FROM bounds b
        ),
        observed AS (
            SELECT
                time_bucket((SELECT step FROM bounds), c.ts) AS bucket,
                avg(COALESCE(c.outdoor_lux, c.lux))::double precision AS natural_lux
            FROM climate c
            CROSS JOIN bounds b
            WHERE c.ts >= b.start_ts
              AND c.ts <= least(b.end_ts, b.now_ts)
              AND COALESCE(c.greenhouse_id, p_greenhouse_id) = p_greenhouse_id
              AND COALESCE(c.outdoor_lux, c.lux) IS NOT NULL
            GROUP BY 1
            ORDER BY 1
            LIMIT 2000
        ),
        forecast AS (
            SELECT DISTINCT ON (time_bucket((SELECT step FROM bounds), wf.ts))
                time_bucket((SELECT step FROM bounds), wf.ts) AS bucket,
                (wf.solar_w_m2 * 120.0)::double precision AS natural_lux
            FROM weather_forecast wf
            CROSS JOIN bounds b
            WHERE wf.ts > b.now_ts
              AND wf.ts >= b.start_ts
              AND wf.ts <= b.end_ts
              AND wf.solar_w_m2 IS NOT NULL
            ORDER BY time_bucket((SELECT step FROM bounds), wf.ts), wf.fetched_at DESC
        ),
        policy AS MATERIALIZED (
            SELECT * FROM fn_lighting_minutes_policy((SELECT now_ts FROM bounds), p_greenhouse_id)
        ),
        main_policy AS (
            SELECT * FROM policy WHERE light_key = 'main'
        ),
        grow_policy AS (
            SELECT * FROM policy WHERE light_key = 'grow'
        )
        SELECT
            s.bucket_ts,
            COALESCE(o.natural_lux, f.natural_lux, 0.0)::double precision AS row_natural_lux,
            CASE
                WHEN o.natural_lux IS NOT NULL THEN 'tempest_observed'
                WHEN f.natural_lux IS NOT NULL THEN 'forecast_solar_w_m2_x120'
                ELSE 'missing'
            END AS row_natural_lux_source,
            (s.bucket_ts AT TIME ZONE 'America/Denver')::date AS row_local_date,
            EXTRACT(hour FROM s.bucket_ts AT TIME ZONE 'America/Denver')::integer AS row_local_hour,
            m.target_light_minutes AS row_main_target_light_minutes,
            m.start_hour AS row_main_start_hour,
            m.cutoff_hour AS row_main_cutoff_hour,
            m.lux_on_threshold AS row_main_lux_on_threshold,
            m.lux_off_threshold AS row_main_lux_off_threshold,
            m.auto_enabled AS row_main_auto_enabled,
            m.legacy_dli_target AS row_main_legacy_dli_target,
            g.target_light_minutes AS row_grow_target_light_minutes,
            g.start_hour AS row_grow_start_hour,
            g.cutoff_hour AS row_grow_cutoff_hour,
            g.lux_on_threshold AS row_grow_lux_on_threshold,
            g.lux_off_threshold AS row_grow_lux_off_threshold,
            g.auto_enabled AS row_grow_auto_enabled,
            g.legacy_dli_target AS row_grow_legacy_dli_target
        FROM series s
        LEFT JOIN observed o ON o.bucket = time_bucket((SELECT step FROM bounds), s.bucket_ts)
        LEFT JOIN forecast f ON f.bucket = time_bucket((SELECT step FROM bounds), s.bucket_ts)
        CROSS JOIN main_policy m
        CROSS JOIN grow_policy g
        ORDER BY s.bucket_ts
    LOOP
        IF last_local_date IS NULL OR r.row_local_date <> last_local_date THEN
            main_minutes := 0.0;
            grow_minutes := 0.0;
        END IF;

        IF r.row_local_hour = r.row_main_start_hour AND last_local_hour <> r.row_main_start_hour THEN
            main_minutes := 0.0;
        END IF;
        IF r.row_local_hour = r.row_grow_start_hour AND last_local_hour <> r.row_grow_start_hour THEN
            grow_minutes := 0.0;
        END IF;

        main_pre_minutes := main_minutes;
        grow_pre_minutes := grow_minutes;

        main_in_window := r.row_main_auto_enabled AND (
            CASE
                WHEN r.row_main_start_hour <= r.row_main_cutoff_hour THEN
                    r.row_local_hour >= r.row_main_start_hour
                    AND r.row_local_hour < r.row_main_cutoff_hour
                ELSE
                    r.row_local_hour >= r.row_main_start_hour
                    OR r.row_local_hour < r.row_main_cutoff_hour
            END
        );
        grow_in_window := r.row_grow_auto_enabled AND (
            CASE
                WHEN r.row_grow_start_hour <= r.row_grow_cutoff_hour THEN
                    r.row_local_hour >= r.row_grow_start_hour
                    AND r.row_local_hour < r.row_grow_cutoff_hour
                ELSE
                    r.row_local_hour >= r.row_grow_start_hour
                    OR r.row_local_hour < r.row_grow_cutoff_hour
            END
        );

        main_natural_qualified := r.row_natural_lux >= r.row_main_lux_on_threshold;
        grow_natural_qualified := r.row_natural_lux >= r.row_grow_lux_on_threshold;

        main_want_on := main_in_window
            AND main_pre_minutes < r.row_main_target_light_minutes
            AND (
                (NOT main_on AND r.row_natural_lux < r.row_main_lux_on_threshold)
                OR (main_on AND r.row_natural_lux < r.row_main_lux_off_threshold)
            );
        grow_want_on := grow_in_window
            AND grow_pre_minutes < r.row_grow_target_light_minutes
            AND (
                (NOT grow_on AND r.row_natural_lux < r.row_grow_lux_on_threshold)
                OR (grow_on AND r.row_natural_lux < r.row_grow_lux_off_threshold)
            );

        main_on := main_want_on;
        grow_on := grow_want_on;

        IF main_in_window AND (main_natural_qualified OR main_on) THEN
            main_minutes := main_minutes + step_minutes;
        END IF;
        IF grow_in_window AND (grow_natural_qualified OR grow_on) THEN
            grow_minutes := grow_minutes + step_minutes;
        END IF;

        ts := r.bucket_ts;
        natural_lux := NULLIF(r.row_natural_lux, 0.0);
        natural_lux_source := r.row_natural_lux_source;
        main_lux_on_threshold := r.row_main_lux_on_threshold;
        main_lux_off_threshold := r.row_main_lux_off_threshold;
        grow_lux_on_threshold := r.row_grow_lux_on_threshold;
        grow_lux_off_threshold := r.row_grow_lux_off_threshold;
        main_expected_on := CASE WHEN main_on THEN 1.0 ELSE 0.0 END;
        grow_expected_on := CASE WHEN grow_on THEN 1.0 ELSE 0.0 END;
        main_dli_target := r.row_main_legacy_dli_target;
        grow_dli_target := r.row_grow_legacy_dli_target;
        main_target_light_minutes := r.row_main_target_light_minutes;
        grow_target_light_minutes := r.row_grow_target_light_minutes;
        main_qualified_light_minutes := main_minutes;
        grow_qualified_light_minutes := grow_minutes;

        last_local_date := r.row_local_date;
        last_local_hour := r.row_local_hour;
        RETURN NEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION public.fn_lighting_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_lighting_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_lighting_timeline(p_start timestamp with time zone, p_end timestamp with time zone, p_step interval, p_greenhouse_id text) IS 'Graph-safe observed/forecast lux timeline. Expected-on projection follows firmware ON/OFF hysteresis, target_light_minutes, window, and auto gates; legacy DLI target columns remain compatibility-only.';


--
-- Name: fn_operational_health(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_operational_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    checks jsonb := '[]'::jsonb;
    total_score int := 0;
    max_score int := 105;
    v_ts timestamptz;
    v_age interval;
    v_count int;
    v_detail text;
    v_score int;
    v_date date;
BEGIN
    -- 1. Data freshness: climate row < 2min old = 10pts
    SELECT ts INTO v_ts FROM climate ORDER BY ts DESC LIMIT 1;
    v_age := now() - v_ts;
    IF v_ts IS NOT NULL AND v_age < interval '2 minutes' THEN
        v_score := 10;
        v_detail := format('Latest row %s ago', to_char(v_age, 'MI:SS'));
    ELSIF v_ts IS NOT NULL THEN
        v_score := 0;
        v_detail := format('Stale: last row %s ago', to_char(v_age, 'HH24:MI:SS'));
    ELSE
        v_score := 0;
        v_detail := 'No climate data';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'data_freshness', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 2. All 6 probes reporting = 10pts
    -- Probes: temp_north, temp_south, temp_east, temp_west, temp_intake, temp_case
    SELECT COUNT(*) INTO v_count
    FROM (
        SELECT 1 WHERE (SELECT temp_north FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT temp_south FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT temp_east FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT temp_west FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT temp_intake FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT temp_case FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
    ) probes;
    IF v_count = 6 THEN
        v_score := 10;
        v_detail := '6/6 probes reporting';
    ELSE
        v_score := 0;
        v_detail := format('%s/6 probes reporting', v_count);
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'probe_coverage', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 3. Ingestor liveness: most recent climate row < 5min (proxy for systemd active) = 10pts
    -- DB cannot check systemd directly; use data freshness as proxy
    IF v_ts IS NOT NULL AND (now() - v_ts) < interval '5 minutes' THEN
        v_score := 10;
        v_detail := 'Ingestor alive (data flowing)';
    ELSE
        v_score := 0;
        v_detail := 'Ingestor may be down (no recent data)';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'ingestor_liveness', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 4. Active plan: future waypoints > 0 = 10pts
    SELECT COUNT(*) INTO v_count
    FROM setpoint_plan
    WHERE is_active = true AND ts > now();
    IF v_count > 0 THEN
        v_score := 10;
        v_detail := format('%s future waypoints', v_count);
    ELSE
        v_score := 0;
        v_detail := 'No active future waypoints';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'active_plan', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 5. Dispatcher: last setpoint push < 10min = 10pts
    SELECT ts INTO v_ts FROM setpoint_changes ORDER BY ts DESC LIMIT 1;
    IF v_ts IS NOT NULL AND (now() - v_ts) < interval '10 minutes' THEN
        v_score := 10;
        v_detail := format('Last push %s ago', to_char(now() - v_ts, 'MI:SS'));
    ELSIF v_ts IS NOT NULL THEN
        v_score := 0;
        v_detail := format('Last push %s ago', to_char(now() - v_ts, 'HH24:MI:SS'));
    ELSE
        v_score := 0;
        v_detail := 'No setpoint changes recorded';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'dispatcher_active', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 6. Equipment assets populated = 5pts
    SELECT COUNT(*) INTO v_count FROM equipment_assets;
    IF v_count > 0 THEN
        v_score := 5;
        v_detail := format('%s assets registered', v_count);
    ELSE
        v_score := 0;
        v_detail := 'No equipment assets';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'equipment_assets', 'score', v_score, 'max', 5,
        'status', CASE WHEN v_score = 5 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 7. Nutrient recipes populated = 5pts
    SELECT COUNT(*) INTO v_count FROM nutrient_recipes;
    IF v_count > 0 THEN
        v_score := 5;
        v_detail := format('%s recipes defined', v_count);
    ELSE
        v_score := 0;
        v_detail := 'No nutrient recipes';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'nutrient_recipes', 'score', v_score, 'max', 5,
        'status', CASE WHEN v_score = 5 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 8. Active crops > 0 = 5pts
    SELECT COUNT(*) INTO v_count FROM crops WHERE is_active = true;
    IF v_count > 0 THEN
        v_score := 5;
        v_detail := format('%s active crops', v_count);
    ELSE
        v_score := 0;
        v_detail := 'No active crops';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'active_crops', 'score', v_score, 'max', 5,
        'status', CASE WHEN v_score = 5 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 9. No relay stuck alerts = 10pts
    BEGIN
        SELECT COUNT(*) INTO v_count FROM v_relay_stuck WHERE is_stuck = true;
        IF v_count = 0 THEN
            v_score := 10;
            v_detail := 'No stuck relays';
        ELSE
            v_score := 0;
            v_detail := format('%s stuck relay(s)', v_count);
        END IF;
    EXCEPTION WHEN undefined_table THEN
        v_score := 10;
        v_detail := 'Relay stuck view not available (assumed ok)';
    END;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'relay_health', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 10. Forecast data < 6h old = 10pts
    SELECT MAX(fetched_at) INTO v_ts FROM weather_forecast;
    IF v_ts IS NOT NULL AND (now() - v_ts) < interval '6 hours' THEN
        v_score := 10;
        v_detail := format('Forecast fetched %s ago', to_char(now() - v_ts, 'HH24:MI'));
    ELSIF v_ts IS NOT NULL THEN
        v_score := 0;
        v_detail := format('Forecast stale: fetched %s ago', to_char(now() - v_ts, 'HH24:MI'));
    ELSE
        v_score := 0;
        v_detail := 'No forecast data';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'forecast_freshness', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score = 10 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 11. Daily summary current = 5pts
    SELECT MAX(date) INTO v_date FROM daily_summary;
    IF v_date IS NOT NULL AND v_date >= (CURRENT_DATE - 1) THEN
        v_score := 5;
        v_detail := format('Latest summary: %s', v_date);
    ELSIF v_date IS NOT NULL THEN
        v_score := 0;
        v_detail := format('Summary stale: last %s', v_date);
    ELSE
        v_score := 0;
        v_detail := 'No daily summaries';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'daily_summary', 'score', v_score, 'max', 5,
        'status', CASE WHEN v_score = 5 THEN 'ok' ELSE 'fail' END, 'detail', v_detail);

    -- 12. Soil sensors reporting = 10pts
    -- Check soil_moisture_south_1, soil_moisture_south_2, soil_moisture_west from latest climate row
    SELECT COUNT(*) INTO v_count
    FROM (
        SELECT 1 WHERE (SELECT soil_moisture_south_1 FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT soil_moisture_south_2 FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
        UNION ALL
        SELECT 1 WHERE (SELECT soil_moisture_west FROM climate ORDER BY ts DESC LIMIT 1) IS NOT NULL
    ) soil;
    IF v_count = 3 THEN
        v_score := 10;
        v_detail := '3/3 soil sensors reporting';
    ELSIF v_count > 0 THEN
        v_score := 5;
        v_detail := format('%s/3 soil sensors reporting', v_count);
    ELSE
        v_score := 0;
        v_detail := 'No soil sensors reporting';
    END IF;
    total_score := total_score + v_score;
    checks := checks || jsonb_build_object(
        'name', 'soil_sensors', 'score', v_score, 'max', 10,
        'status', CASE WHEN v_score >= 10 THEN 'ok' WHEN v_score > 0 THEN 'degraded' ELSE 'fail' END, 'detail', v_detail);

    RETURN jsonb_build_object(
        'score', total_score,
        'max_score', max_score,
        'checks', checks
    );
END;
$$;


