--
-- Name: fn_plan_anchor_score(text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_plan_anchor_score(p_plan_id text) RETURNS smallint
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_comp numeric;
  v_str  numeric;
  v_frac numeric;
  v_anchor smallint;
  v_penalty smallint := 0;
BEGIN
  SELECT compliance_pct, total_stress_h, governed_day_fraction
    INTO v_comp, v_str, v_frac
    FROM v_plan_window_scorecard
   WHERE plan_id = p_plan_id;

  IF NOT FOUND OR v_frac IS NULL OR v_frac < 0.05 THEN
    RETURN NULL;
  END IF;

  IF v_comp IS NULL OR v_str IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_comp >= 90 AND v_str <  2 THEN v_anchor := 10;
  ELSIF v_comp >= 85 AND v_str <  3 THEN v_anchor :=  9;
  ELSIF v_comp >= 75 AND v_str <  5 THEN v_anchor :=  8;
  ELSIF v_comp >= 70 AND v_str <  7 THEN v_anchor :=  7;
  ELSIF v_comp >= 60 AND v_str < 10 THEN v_anchor :=  6;
  ELSIF v_comp >= 50 AND v_str < 14 THEN v_anchor :=  5;
  ELSIF v_comp >= 40 AND v_str < 20 THEN v_anchor :=  4;
  ELSIF v_comp >= 25 AND v_str < 28 THEN v_anchor :=  3;
  ELSIF v_comp >= 10                THEN v_anchor :=  2;
  ELSE v_anchor := 1;
  END IF;

  SELECT COALESCE(guardrail_penalty, 0)
    INTO v_penalty
    FROM v_plan_guardrail_scorecard
   WHERE plan_id = p_plan_id;

  RETURN GREATEST(1, v_anchor - COALESCE(v_penalty, 0));
END;
$$;


ALTER FUNCTION public.fn_plan_anchor_score(p_plan_id text) OWNER TO verdify;

--
-- Name: FUNCTION fn_plan_anchor_score(p_plan_id text); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_plan_anchor_score(p_plan_id text) IS 'Re-anchored (migration 147): day-weighted compliance_v2_attributable_pct + graded total stress, tiered via plan_anchor_ladder.comp_cut_graded (quantile-matched to the frozen anchors). Same guardrail-penalty + GREATEST(1,...) clamp. Existing anchor_score rows are FROZEN; only NULL anchors are backfilled.';


--
-- Name: fn_plan_transition_audit(text, interval, interval); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_plan_transition_audit(p_plan_id text DEFAULT NULL::text, p_lookback interval DEFAULT '36:00:00'::interval, p_window interval DEFAULT '00:10:00'::interval) RETURNS TABLE(plan_id text, plan_created_at timestamp with time zone, transition_ts timestamp with time zone, parameter text, planned_value double precision, prior_value double precision, applied_value double precision, readback_value double precision, status text, guardrail_reason text, push_ts timestamp with time zone, push_latency_s integer, confirmed_at timestamp with time zone, confirm_latency_s integer, matching_push_ts timestamp with time zone, readback_ts timestamp with time zone, trigger_id uuid, planner_instance text)
    LANGUAGE sql STABLE
    AS $$
WITH scoped AS (
    SELECT sp.*,
           lag(sp.value) OVER (PARTITION BY sp.plan_id, sp.parameter ORDER BY sp.ts) AS prev_plan_value
      FROM setpoint_plan sp
     WHERE sp.is_active IS TRUE
       AND sp.parameter NOT IN ('temp_low', 'temp_high', 'vpd_low', 'vpd_high')
       AND (
            (p_plan_id IS NOT NULL AND sp.plan_id = p_plan_id)
         OR (p_plan_id IS NULL AND sp.created_at >= now() - p_lookback)
       )
), transitions AS (
    SELECT *
      FROM scoped
     WHERE ts <= now()
       AND (prev_plan_value IS NULL OR abs(value - prev_plan_value) > 0.0001)
)
SELECT
    t.plan_id,
    t.created_at AS plan_created_at,
    t.ts AS transition_ts,
    t.parameter,
    t.value AS planned_value,
    prior.value AS prior_value,
    COALESCE(first_push.value, guardrail.applied, prior.value) AS applied_value,
    readback.value AS readback_value,
    CASE
      WHEN prior.value IS NOT NULL AND abs(prior.value - t.value) <= 0.0001
        THEN 'already_at_value'
      WHEN first_push.ts IS NOT NULL AND abs(first_push.value - t.value) <= 0.0001
        THEN 'matched'
      WHEN guardrail.ts IS NOT NULL AND first_push.ts IS NOT NULL
        THEN 'guardrailed'
      WHEN guardrail.ts IS NOT NULL
        THEN 'held_by_guardrail'
      WHEN first_push.ts IS NULL
        THEN 'missed'
      ELSE 'mismatch'
    END AS status,
    guardrail.reason AS guardrail_reason,
    first_push.ts AS push_ts,
    CASE WHEN first_push.ts IS NULL THEN NULL
         ELSE extract(epoch FROM first_push.ts - t.ts)::int
    END AS push_latency_s,
    first_push.confirmed_at,
    CASE WHEN first_push.confirmed_at IS NULL OR first_push.ts IS NULL THEN NULL
         ELSE extract(epoch FROM first_push.confirmed_at - first_push.ts)::int
    END AS confirm_latency_s,
    matching_push.ts AS matching_push_ts,
    readback.ts AS readback_ts,
    t.trigger_id,
    t.planner_instance
FROM transitions t
LEFT JOIN LATERAL (
    SELECT sc.ts, sc.value
      FROM setpoint_changes sc
     WHERE sc.greenhouse_id = t.greenhouse_id
       AND sc.parameter = t.parameter
       AND sc.ts < t.ts
     ORDER BY sc.ts DESC
     LIMIT 1
) prior ON TRUE
LEFT JOIN LATERAL (
    SELECT sc.ts, sc.value, sc.confirmed_at
      FROM setpoint_changes sc
     WHERE sc.greenhouse_id = t.greenhouse_id
       AND sc.parameter = t.parameter
       AND sc.ts >= t.ts
       AND sc.ts < t.ts + p_window
       AND sc.source = 'plan'
     ORDER BY sc.ts ASC
     LIMIT 1
) first_push ON TRUE
LEFT JOIN LATERAL (
    SELECT sc.ts, sc.value
      FROM setpoint_changes sc
     WHERE sc.greenhouse_id = t.greenhouse_id
       AND sc.parameter = t.parameter
       AND sc.ts >= t.ts
       AND sc.ts < t.ts + interval '2 hours'
       AND sc.source = 'plan'
       AND abs(sc.value - t.value) <= 0.0001
     ORDER BY sc.ts ASC
     LIMIT 1
) matching_push ON TRUE
LEFT JOIN LATERAL (
    SELECT c.ts, c.applied, c.reason, c.status
      FROM setpoint_clamps c
     WHERE c.greenhouse_id = t.greenhouse_id
       AND c.parameter = t.parameter
       AND (
            (c.plan_id = t.plan_id AND c.plan_ts = t.ts)
         OR (c.plan_id IS NULL AND c.ts >= t.ts - interval '30 seconds' AND c.ts < t.ts + p_window)
       )
     ORDER BY c.ts ASC
     LIMIT 1
) guardrail ON TRUE
LEFT JOIN LATERAL (
    SELECT ss.ts, ss.value
      FROM setpoint_snapshot ss
     WHERE ss.greenhouse_id = t.greenhouse_id
       AND ss.parameter = t.parameter
       AND ss.ts >= t.ts
       AND ss.ts < t.ts + p_window
     ORDER BY ss.ts ASC
     LIMIT 1
) readback ON TRUE
ORDER BY t.created_at DESC, t.ts ASC, t.parameter ASC;
$$;


ALTER FUNCTION public.fn_plan_transition_audit(p_plan_id text, p_lookback interval, p_window interval) OWNER TO verdify;

--
-- Name: FUNCTION fn_plan_transition_audit(p_plan_id text, p_lookback interval, p_window interval); Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON FUNCTION public.fn_plan_transition_audit(p_plan_id text, p_lookback interval, p_window interval) IS 'Guardrail-aware transition audit for planner-owned params. Statuses: already_at_value, matched, guardrailed, held_by_guardrail, missed, mismatch.';


--
-- Name: fn_planner_scorecard(date); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_planner_scorecard(p_date date DEFAULT CURRENT_DATE) RETURNS TABLE(metric text, value numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT 'planner_score'::text, k.planner_score FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'compliance_pct', k.compliance_pct FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'temp_compliance_pct', k.temp_compliance_pct FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'vpd_compliance_pct', k.vpd_compliance_pct FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'total_stress_h', k.total_stress_h FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'heat_stress_h', k.heat_stress_h FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'cold_stress_h', k.cold_stress_h FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'vpd_high_stress_h', k.vpd_high_stress_h FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'vpd_low_stress_h', k.vpd_low_stress_h FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'kwh', k.kwh FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'therms', k.therms FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'water_gal', k.water_gal FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'mister_water_gal', k.mister_water_gal FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'cost_electric', k.cost_electric FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'cost_gas', k.cost_gas FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'cost_water', k.cost_water FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'cost_total', k.cost_total FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'dp_margin_min_f', k.dp_margin_min_f FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT 'dp_risk_hours', k.dp_risk_hours FROM v_daily_kpi k WHERE k.date = p_date
    UNION ALL SELECT '7d_avg_score', round(avg(k.planner_score), 1) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1
    UNION ALL SELECT '7d_avg_compliance', round(avg(k.compliance_pct), 1) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1
    UNION ALL SELECT '7d_avg_cost', round(avg(k.cost_total), 2) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1
    UNION ALL SELECT '7d_avg_kwh', round(avg(k.kwh), 1) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1
    UNION ALL SELECT '7d_avg_therms', round(avg(k.therms), 3) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1
    UNION ALL SELECT '7d_avg_water_gal', round(avg(k.water_gal), 0) FROM v_daily_kpi k WHERE k.date BETWEEN p_date - 7 AND p_date - 1;
END;
$$;


ALTER FUNCTION public.fn_planner_scorecard(p_date date) OWNER TO verdify;

--
-- Name: fn_runtime_power_30m(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_runtime_power_30m(p_start timestamp with time zone, p_end timestamp with time zone) RETURNS TABLE(bucket timestamp with time zone, total_watts double precision, heat1_watts double precision, fans_watts double precision, other_watts double precision)
    LANGUAGE sql STABLE
    AS $$
WITH bounds AS (
    SELECT
        time_bucket('30 minutes', p_start) AS start_ts,
        time_bucket('30 minutes', p_end) + interval '30 minutes' AS end_ts
), wattages AS (
    SELECT equipment, wattage::double precision AS wattage
    FROM equipment_assets
    WHERE wattage IS NOT NULL
), seed AS (
    SELECT
        b.start_ts AS ts,
        w.equipment,
        COALESCE((
            SELECT es.state
            FROM equipment_state es
            WHERE es.equipment = w.equipment
              AND es.ts <= b.start_ts
            ORDER BY es.ts DESC
            LIMIT 1
        ), false) AS state,
        w.wattage
    FROM bounds b
    CROSS JOIN wattages w
), changes AS (
    SELECT es.ts, es.equipment, es.state, w.wattage
    FROM equipment_state es
    JOIN wattages w USING (equipment)
    CROSS JOIN bounds b
    WHERE es.ts > b.start_ts
      AND es.ts < b.end_ts
), events AS (
    SELECT * FROM seed
    UNION ALL
    SELECT * FROM changes
), segments AS (
    SELECT
        equipment,
        wattage,
        state,
        ts AS start_ts,
        LEAD(ts) OVER (PARTITION BY equipment ORDER BY ts) AS next_ts
    FROM events
), active_segments AS (
    SELECT
        s.equipment,
        s.wattage,
        GREATEST(s.start_ts, b.start_ts) AS start_ts,
        LEAST(COALESCE(s.next_ts, b.end_ts), b.end_ts) AS end_ts
    FROM segments s
    CROSS JOIN bounds b
    WHERE s.state IS TRUE
      AND COALESCE(s.next_ts, b.end_ts) > b.start_ts
      AND s.start_ts < b.end_ts
), expanded AS (
    SELECT
        gs.bucket,
        a.equipment,
        a.wattage
            * GREATEST(
                EXTRACT(EPOCH FROM LEAST(a.end_ts, gs.bucket + interval '30 minutes') - GREATEST(a.start_ts, gs.bucket)),
                0
            )
            / 1800.0 AS avg_watts
    FROM active_segments a
    CROSS JOIN LATERAL generate_series(
        time_bucket('30 minutes', a.start_ts),
        time_bucket('30 minutes', a.end_ts - interval '1 microsecond'),
        interval '30 minutes'
    ) AS gs(bucket)
), buckets AS (
    SELECT generate_series(
        (SELECT start_ts FROM bounds),
        (SELECT end_ts FROM bounds) - interval '30 minutes',
        interval '30 minutes'
    ) AS bucket
)
SELECT
    b.bucket,
    round(COALESCE(SUM(e.avg_watts), 0)::numeric, 2)::double precision AS total_watts,
    round(COALESCE(SUM(e.avg_watts) FILTER (WHERE e.equipment = 'heat1'), 0)::numeric, 2)::double precision AS heat1_watts,
    round(COALESCE(SUM(e.avg_watts) FILTER (WHERE e.equipment IN ('fan1', 'fan2')), 0)::numeric, 2)::double precision AS fans_watts,
    round(COALESCE(SUM(e.avg_watts) FILTER (WHERE e.equipment NOT IN ('heat1', 'fan1', 'fan2')), 0)::numeric, 2)::double precision AS other_watts
FROM buckets b
LEFT JOIN expanded e USING (bucket)
GROUP BY b.bucket
ORDER BY b.bucket;
$$;


