--
-- Name: fn_search_embeddings(public.vector, integer, text[]); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.fn_search_embeddings(query_embedding public.vector, p_top_k integer DEFAULT 10, p_source_types text[] DEFAULT ARRAY['lesson'::text, 'plan'::text, 'site_doc'::text, 'playbook'::text, 'observation'::text]) RETURNS TABLE(source_type text, source_id text, chunk_idx integer, content text, metadata jsonb, distance double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT e.source_type, e.source_id, e.chunk_idx, e.content, e.metadata,
           (e.embedding <=> query_embedding)::float AS distance
      FROM verdify_embeddings e
      LEFT JOIN planner_lessons pl
        ON e.source_type = 'lesson'
       AND pl.id::text = e.source_id
     WHERE e.source_type = ANY(p_source_types)
       AND (
             e.source_type <> 'lesson'
             OR (pl.is_active = true AND pl.superseded_by IS NULL)
           )
     ORDER BY e.embedding <=> query_embedding
     LIMIT p_top_k;
END;
$$;


