CREATE FUNCTION public.normalize_changes_param() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.parameter := normalize_param_name(NEW.parameter);
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.normalize_changes_param() OWNER TO verdify;

--
-- Name: normalize_param_name(text); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.normalize_param_name(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN CASE p
        WHEN 'set_vpd_high_kpa' THEN 'vpd_high'
        WHEN 'set_vpd_low_kpa' THEN 'vpd_low'
        WHEN 'set_temp_low__f' THEN 'temp_low'
        WHEN 'set_temp_high__f' THEN 'temp_high'
        WHEN 'vpd_mister_engage_kpa' THEN 'mister_engage_kpa'
        WHEN 'vpd_mister_all_kpa' THEN 'mister_all_kpa'
        ELSE p
    END;
END;
$$;


ALTER FUNCTION public.normalize_param_name(p text) OWNER TO verdify;

