--

CREATE FUNCTION public.notify_setpoint_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify(
        'setpoint_changed',
        json_build_object(
            'parameter', NEW.parameter,
            'value', NEW.value,
            'source', NEW.source
        )::text
    );
    RETURN NEW;
END;
$$;


