--
-- Name: prevent_retired_irrigation_compat_write(); Type: FUNCTION; Schema: public; Owner: verdify
--

CREATE FUNCTION public.prevent_retired_irrigation_compat_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF lower(COALESCE(current_setting('verdify.allow_retired_irrigation_compat_write', true), '')) IN ('on', 'true', '1') THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION
        'retired irrigation compatibility table % is read-only; use v_irrigation_schedule_current and v_irrigation_fertigation_runs',
        TG_TABLE_NAME
        USING ERRCODE = '55000';
END;
$$;


ALTER FUNCTION public.prevent_retired_irrigation_compat_write() OWNER TO verdify;

