--
-- Name: override_events; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.override_events (
    ts timestamp with time zone DEFAULT now() NOT NULL,
    override_type text NOT NULL,
    mode text,
    details jsonb,
    greenhouse_id text DEFAULT 'vallery'::text NOT NULL
);


ALTER TABLE public.override_events OWNER TO verdify;

--
-- Name: TABLE override_events; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.override_events IS 'Firmware silent-override audit trail. Written when ESP32 ignores planner intent (occupancy inhibit, fog gate, relief breaker, temp-near-safety, VPD dry override, etc.). Lets planner correlate compliance misses with overrides she cannot see otherwise.';


--
-- Name: COLUMN override_events.override_type; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.override_events.override_type IS 'occupancy_blocks_moisture | fog_gate_rh | fog_gate_temp | fog_gate_window | relief_cycle_breaker | seal_blocked_temp | vpd_dry_override | enthalpy_stale';


--
-- Name: COLUMN override_events.mode; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.override_events.mode IS 'Firmware control mode when override fired (IDLE, VENTILATE, SEALED_MIST, DEHUM_VENT, THERMAL_RELIEF, SAFETY_COOL, SAFETY_HEAT, SENSOR_FAULT)';


--
-- Name: COLUMN override_events.details; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.override_events.details IS 'Override-specific context: {"rh_pct": 92.1, "ceiling": 90} or {"count": 5, "max": 4}';


