-- Name: setpoint_clamps; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.setpoint_clamps (
    ts timestamp with time zone DEFAULT now() NOT NULL,
    parameter text NOT NULL,
    requested double precision NOT NULL,
    applied double precision NOT NULL,
    band_lo double precision,
    band_hi double precision,
    reason text NOT NULL,
    greenhouse_id text DEFAULT 'vallery'::text NOT NULL,
    status text DEFAULT 'clamped'::text,
    plan_id text,
    plan_ts timestamp with time zone,
    trigger_id uuid,
    planner_instance text
);


ALTER TABLE public.setpoint_clamps OWNER TO verdify;

--
-- Name: TABLE setpoint_clamps; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.setpoint_clamps IS 'Dispatcher clamp audit. Written when planner_val was clamped to band edge in setpoint_dispatcher. Without this, Iris has no way to know her requested setpoint was modified before reaching the device.';


--
-- Name: COLUMN setpoint_clamps.reason; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.setpoint_clamps.reason IS 'band_lo | band_hi — which edge triggered the clamp';


--
-- Name: COLUMN setpoint_clamps.status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.setpoint_clamps.status IS 'clamped = legacy/default; guardrailed = adjusted value was dispatched; held_by_guardrail = requested transition was intentionally held and no setpoint_changes row was emitted; rejected = registry/schema rejected the value.';


--
-- Name: COLUMN setpoint_clamps.plan_id; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.setpoint_clamps.plan_id IS 'Planner plan_id associated with the requested value, copied from v_active_plan when available.';


--
-- Name: COLUMN setpoint_clamps.plan_ts; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.setpoint_clamps.plan_ts IS 'Setpoint_plan transition timestamp associated with the requested value, copied from v_active_plan when available.';


