--
-- Name: diagnostics; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.diagnostics (
    ts timestamp with time zone NOT NULL,
    wifi_rssi double precision,
    heap_bytes double precision,
    uptime_s double precision,
    probe_health text,
    reset_reason text,
    greenhouse_id text DEFAULT 'vallery'::text,
    firmware_version text,
    active_probe_count integer,
    relief_cycle_count integer,
    vent_latch_timer_s integer,
    sealed_timer_s integer,
    vpd_watch_timer_s integer,
    mist_backoff_timer_s integer,
    vent_mist_assist_active integer,
    heap_min_free_kb double precision,
    heap_largest_free_block_kb double precision,
    controller_time_epoch bigint,
    controller_local_hour integer,
    sntp_valid integer,
    sntp_miss_count integer,
    last_sntp_sync_age_s integer,
    effective_heat_target_f double precision,
    effective_cool_stage2_delta_f double precision,
    effective_vpd_hysteresis_kpa double precision,
    effective_dehum_aggressive_kpa double precision,
    zone_wet_granted text,
    band_source text
);


ALTER TABLE public.diagnostics OWNER TO verdify;

--
-- Name: COLUMN diagnostics.active_probe_count; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.active_probe_count IS 'FW-10: number of zone probes (0-4) contributing to avg_temp/rh/vpd aggregates at this sample. <4 means one or more probes are stale (>5 min Modbus timeout).';


--
-- Name: COLUMN diagnostics.relief_cycle_count; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.relief_cycle_count IS 'OBS-3: ControlState.relief_cycle_count at this sample — how many consecutive SEALED_MIST → THERMAL_RELIEF cycles have fired without a VPD-in-band reset. Hits max_relief_cycles → firmware latches VENTILATE (relief_cycle_breaker override).';


--
-- Name: COLUMN diagnostics.vent_latch_timer_s; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.vent_latch_timer_s IS 'OBS-3: ControlState.vent_latch_timer_ms converted to seconds. Nonzero when firmware is in the post-relief VENTILATE latch (FW-8). Resets to 0 on successful seal entry or after 1800 s (30 min) timeout.';


--
-- Name: COLUMN diagnostics.sealed_timer_s; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.sealed_timer_s IS 'Controller v2: seconds spent in the current SEALED_MIST attempt.';


--
-- Name: COLUMN diagnostics.vpd_watch_timer_s; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.vpd_watch_timer_s IS 'Controller v2: seconds VPD has remained above band before humidification/backoff decisions.';


--
-- Name: COLUMN diagnostics.mist_backoff_timer_s; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.mist_backoff_timer_s IS 'Controller v2: seconds remaining/elapsed in post-timeout mist backoff lockout.';


--
-- Name: COLUMN diagnostics.vent_mist_assist_active; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.vent_mist_assist_active IS 'Controller v2: 1 when VENTILATE is also carrying mister demand for high VPD.';


--
-- Name: COLUMN diagnostics.heap_min_free_kb; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.heap_min_free_kb IS 'ESP32 minimum free heap since boot, in kB; persists the Minimum Free Heap sensor.';


--
-- Name: COLUMN diagnostics.heap_largest_free_block_kb; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.heap_largest_free_block_kb IS 'ESP32 largest allocatable heap block, in kB; primary fragmentation signal for heap-pressure alerts.';


--
-- Name: COLUMN diagnostics.effective_heat_target_f; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.effective_heat_target_f IS 'Controller diagnostic: validated effective heat target in deg F after crop-band width clamp and lower-quartile policy.';


--
-- Name: COLUMN diagnostics.effective_cool_stage2_delta_f; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.effective_cool_stage2_delta_f IS 'Controller diagnostic: validated effective stage-2 cooling delta in deg F after band/safety clamps.';


--
-- Name: COLUMN diagnostics.effective_vpd_hysteresis_kpa; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.effective_vpd_hysteresis_kpa IS 'Controller diagnostic: validated effective VPD hysteresis in kPa after house-band width clamps.';


--
-- Name: COLUMN diagnostics.effective_dehum_aggressive_kpa; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.diagnostics.effective_dehum_aggressive_kpa IS 'Controller diagnostic: validated dehumidification aggressive margin in kPa after house-band clamps.';


