--

CREATE TABLE public.plan_delivery_log (
    id integer NOT NULL,
    delivered_at timestamp with time zone DEFAULT now() NOT NULL,
    event_type text NOT NULL,
    event_label text,
    session_key text,
    wake_mode text,
    gateway_status integer,
    gateway_body text,
    resulting_plan_id text,
    plan_written_at timestamp with time zone,
    greenhouse_id text DEFAULT 'vallery'::text NOT NULL,
    trigger_id uuid,
    instance text,
    acked_at timestamp with time zone,
    status text DEFAULT 'pending'::text,
    hermes_run_id text,
    CONSTRAINT plan_delivery_log_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'acked'::text, 'plan_written'::text, 'timed_out'::text, 'delivery_failed'::text])))
);


ALTER TABLE public.plan_delivery_log OWNER TO verdify;

--
-- Name: TABLE plan_delivery_log; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.plan_delivery_log IS 'Sprint 24.6 / F14: Iris planner delivery audit. One row per send_to_iris call; resulting_plan_id populated by the verification pass when a plan lands. Core diagnostic: "SELECT event_type, count(*) FILTER (WHERE resulting_plan_id IS NOT NULL) AS planned, count(*) AS delivered FROM plan_delivery_log WHERE delivered_at > now() - interval ''24 hours'' GROUP BY event_type" — a working Iris gives planned ~ delivered.';


--
-- Name: COLUMN plan_delivery_log.trigger_id; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.plan_delivery_log.trigger_id IS 'UUID correlation key (contract v1.4 §2.D). Populated by ingestor on send_to_iris; stamped by MCP server onto plan_journal.trigger_id + setpoint_changes.trigger_id when headers flow through from OpenClaw /hooks/agent. NULL for pre-v1.4 rows.';


--
-- Name: COLUMN plan_delivery_log.instance; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.plan_delivery_log.instance IS 'Planner instance handling the trigger: opus | local. Backfilled to iris-planner for pre-v1.4 rows. Disambiguates cloud Opus vs local vLLM gemma peers.';


--
-- Name: COLUMN plan_delivery_log.acked_at; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.plan_delivery_log.acked_at IS 'Set by MCP acknowledge_trigger(trigger_id, reason) when Iris correctly defers a cycle without writing a plan. Distinguishes "read + no-change-needed" from "silently dropped"; the exact ambiguity that caused the 2026-04-19 false-stale.';


--
-- Name: COLUMN plan_delivery_log.status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.plan_delivery_log.status IS 'Lifecycle: pending (trigger in flight) -> plan_written (resulting_plan_id set), acked (via MCP acknowledge_trigger), timed_out (SLA breached), delivery_failed (gateway non-2xx). Drives alert_monitor rule 7 over per-pair SLA tables.';


--
-- Name: COLUMN plan_delivery_log.hermes_run_id; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON COLUMN public.plan_delivery_log.hermes_run_id IS 'Hermes /v1/runs run.id when AI_GATEWAY_PROVIDER=hermes (or per-event override). NULL for OpenClaw deliveries.';


--
-- Name: plan_delivery_log_id_seq; Type: SEQUENCE; Schema: public; Owner: verdify
--

