--
-- Name: v_active_plan; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_active_plan AS
 SELECT DISTINCT ON (parameter) parameter,
    value,
    ts,
    plan_id,
    reason,
    created_at,
    trigger_id,
    planner_instance
   FROM public.setpoint_plan
  WHERE ((ts <= now()) AND (is_active = true))
  ORDER BY parameter, created_at DESC, ts DESC;


ALTER VIEW public.v_active_plan OWNER TO verdify;

--
-- Name: VIEW v_active_plan; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_active_plan IS 'Currently active plan value per parameter. Resolves supersession: latest created_at wins.';


--
-- Name: v_alert_lifecycle_quality; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_alert_lifecycle_quality AS
 SELECT severity,
    alert_type,
    count(*) AS alerts,
    count(*) FILTER (WHERE (disposition = 'open'::text)) AS open_alerts,
    count(*) FILTER (WHERE ((disposition = 'acknowledged'::text) AND (resolved_at IS NULL))) AS acknowledged_unresolved,
    count(*) FILTER (WHERE (disposition = 'suppressed'::text)) AS suppressed_alerts,
    round(avg((EXTRACT(epoch FROM (resolved_at - ts)) / 60.0)) FILTER (WHERE (resolved_at IS NOT NULL)), 1) AS avg_mttr_min,
    max(ts) AS latest_ts
   FROM public.alert_log
  GROUP BY severity, alert_type
  ORDER BY (max(ts)) DESC;


ALTER VIEW public.v_alert_lifecycle_quality OWNER TO verdify;

--
-- Name: VIEW v_alert_lifecycle_quality; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_alert_lifecycle_quality IS 'Alert lifecycle health: open/ack/suppressed counts and mean time to resolution by alert type.';


--
-- Name: v_band_trace_latest; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_band_trace_latest AS
 SELECT ts,
    greenhouse_id,
    temp_avg,
    vpd_avg,
    rh_avg,
    dew_point,
    temp_avg_smooth_15m,
    vpd_avg_smooth_30m,
    crop_temp_low,
    crop_temp_high,
    crop_vpd_low,
    crop_vpd_high,
    vpd_target_south,
    vpd_target_west,
    vpd_target_east,
    vpd_target_center,
    house_vpd_low,
    house_vpd_high,
    fw_temp_low,
    fw_temp_high,
    fw_vpd_low,
    fw_vpd_high,
    fw_temp_low_ts,
    fw_temp_high_ts,
    fw_vpd_low_ts,
    fw_vpd_high_ts,
    rb_temp_low,
    rb_temp_high,
    rb_vpd_low,
    rb_vpd_high,
    rb_temp_low_ts,
    rb_temp_high_ts,
    rb_vpd_low_ts,
    rb_vpd_high_ts,
    crop_temp_in_band,
    crop_vpd_in_band,
    crop_both_in_band,
    fw_temp_in_band,
