   FROM public.fn_band_trace((now() - '02:00:00'::interval), now(), 'vallery'::text) fn_band_trace(ts, greenhouse_id, temp_avg, vpd_avg, rh_avg, dew_point, temp_avg_smooth_15m, vpd_avg_smooth_30m, crop_temp_low, crop_temp_high, crop_vpd_low, crop_vpd_high, vpd_target_south, vpd_target_west, vpd_target_east, vpd_target_center, house_vpd_low, house_vpd_high, fw_temp_low, fw_temp_high, fw_vpd_low, fw_vpd_high, fw_temp_low_ts, fw_temp_high_ts, fw_vpd_low_ts, fw_vpd_high_ts, rb_temp_low, rb_temp_high, rb_vpd_low, rb_vpd_high, rb_temp_low_ts, rb_temp_high_ts, rb_vpd_low_ts, rb_vpd_high_ts, crop_temp_in_band, crop_vpd_in_band, crop_both_in_band, fw_temp_in_band, fw_vpd_in_band, fw_both_in_band, readback_matches_fw_temp, readback_matches_fw_vpd, readback_matches_fw_band, fw_minus_crop_temp_low_f, fw_minus_crop_temp_high_f, fw_minus_crop_vpd_low_kpa, fw_minus_crop_vpd_high_kpa, trace_quality_flag)
