--
-- Name: v_clamp_activity_24h; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_clamp_activity_24h AS
 SELECT parameter,
    count(*) AS clamp_events,
    round((avg(abs((requested - applied))))::numeric, 3) AS avg_clamp_delta,
    round((max(abs((requested - applied))))::numeric, 3) AS max_clamp_delta,
    min(ts) AS first_seen,
    max(ts) AS last_seen
   FROM public.setpoint_clamps
  WHERE (ts > (now() - '24:00:00'::interval))
  GROUP BY parameter
  ORDER BY (count(*)) DESC;


