--
-- Name: v_climate_merged; Type: MATERIALIZED VIEW; Schema: public; Owner: verdify
--

CREATE MATERIALIZED VIEW public.v_climate_merged AS
 SELECT public.time_bucket('00:30:00'::interval, ts) AS bucket,
    avg(temp_avg) FILTER (WHERE (temp_avg IS NOT NULL)) AS temp_avg,
    avg(temp_north) FILTER (WHERE (temp_north IS NOT NULL)) AS temp_north,
    avg(temp_south) FILTER (WHERE (temp_south IS NOT NULL)) AS temp_south,
    avg(rh_avg) FILTER (WHERE (rh_avg IS NOT NULL)) AS rh_avg,
    avg(vpd_avg) FILTER (WHERE (vpd_avg IS NOT NULL)) AS vpd_avg,
    avg(co2_ppm) FILTER (WHERE (co2_ppm IS NOT NULL)) AS co2_ppm,
    avg(lux) FILTER (WHERE (lux IS NOT NULL)) AS lux,
    max(dli_today) FILTER (WHERE (dli_today IS NOT NULL)) AS dli_today,
    avg(outdoor_temp_f) FILTER (WHERE (outdoor_temp_f IS NOT NULL)) AS outdoor_temp_f,
    avg(outdoor_rh_pct) FILTER (WHERE (outdoor_rh_pct IS NOT NULL)) AS outdoor_rh_pct,
    avg(solar_irradiance_w_m2) FILTER (WHERE (solar_irradiance_w_m2 IS NOT NULL)) AS solar_w_m2,
    avg(solar_altitude_deg) FILTER (WHERE (solar_altitude_deg IS NOT NULL)) AS solar_alt,
    avg(solar_azimuth_deg) FILTER (WHERE (solar_azimuth_deg IS NOT NULL)) AS solar_az,
    avg(wind_speed_mph) FILTER (WHERE (wind_speed_mph IS NOT NULL)) AS wind_mph,
    avg(pressure_hpa) FILTER (WHERE (pressure_hpa IS NOT NULL)) AS pressure_hpa,
    avg(outdoor_lux) FILTER (WHERE (outdoor_lux IS NOT NULL)) AS outdoor_lux,
    avg(flow_gpm) FILTER (WHERE (flow_gpm IS NOT NULL)) AS flow_gpm,
    avg(enthalpy_delta) FILTER (WHERE (enthalpy_delta IS NOT NULL)) AS enthalpy_delta
   FROM public.climate
  GROUP BY (public.time_bucket('00:30:00'::interval, ts))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.v_climate_merged OWNER TO verdify;

--
-- Name: v_cost_today; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_cost_today AS
 SELECT round((COALESCE(ds.cost_electric, (0)::double precision))::numeric, 2) AS cost_electric,
    round((COALESCE(ds.cost_gas, (0)::double precision))::numeric, 2) AS cost_gas,
    round((COALESCE(ds.cost_water, (0)::double precision))::numeric, 2) AS cost_water,
    round((COALESCE(ds.cost_total, (0)::double precision))::numeric, 2) AS cost_total
   FROM (( SELECT 1 AS "?column?") anchor
     LEFT JOIN public.daily_summary ds ON ((ds.date = CURRENT_DATE)));


ALTER VIEW public.v_cost_today OWNER TO verdify;

--
-- Name: v_crop_catalog_with_profiles; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_crop_catalog_with_profiles AS
 SELECT id AS crop_catalog_id,
    slug,
    common_name,
    scientific_name,
    category,
    season,
    cycle_days_min,
    cycle_days_max,
    base_temp_f,
    default_target_dli,
    default_target_vpd_low,
    default_target_vpd_high,
    default_ph_low,
    default_ph_high,
    default_ec_low,
    default_ec_high,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('growth_stage', p.growth_stage, 'season', p.season, 'hours_covered', p.hours_covered, 'temp_ideal_min_24h', p.temp_ideal_min_24h, 'temp_ideal_max_24h', p.temp_ideal_max_24h, 'vpd_ideal_min_24h', p.vpd_ideal_min_24h, 'vpd_ideal_max_24h', p.vpd_ideal_max_24h, 'dli_target_mol', p.dli_target_mol) ORDER BY p.growth_stage, p.season) AS jsonb_agg
           FROM ( SELECT ctp.growth_stage,
                    ctp.season,
                    (count(*))::integer AS hours_covered,
                    avg(ctp.temp_ideal_min) AS temp_ideal_min_24h,
                    avg(ctp.temp_ideal_max) AS temp_ideal_max_24h,
                    avg(ctp.vpd_ideal_min) AS vpd_ideal_min_24h,
                    avg(ctp.vpd_ideal_max) AS vpd_ideal_max_24h,
                    avg(ctp.dli_target_mol) AS dli_target_mol
                   FROM public.crop_target_profiles ctp
                  WHERE (ctp.crop_catalog_id = cc.id)
                  GROUP BY ctp.growth_stage, ctp.season) p), '[]'::jsonb) AS stage_season_profiles
   FROM public.crop_catalog cc
  ORDER BY slug;


ALTER VIEW public.v_crop_catalog_with_profiles OWNER TO verdify;

--
-- Name: VIEW v_crop_catalog_with_profiles; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_crop_catalog_with_profiles IS 'Sprint 22: per-crop reference data + stage/season band aggregates. Drives the website crop-profile pages (currently hand-typed per variety).';


--
-- Name: v_crop_health_trend; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_crop_health_trend AS
 SELECT c.name AS crop_name,
    c.zone,
    (o.ts AT TIME ZONE 'America/Denver'::text) AS observed,
    o.health_score,
    o.obs_type AS observation_type,
    o.notes,
    o.source
   FROM (public.observations o
     JOIN public.crops c ON ((o.crop_id = c.id)))
  WHERE (o.ts > (now() - '30 days'::interval))
  ORDER BY c.name, o.ts DESC;


ALTER VIEW public.v_crop_health_trend OWNER TO verdify;

--
-- Name: zones; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.zones (
    id integer NOT NULL,
    greenhouse_id text DEFAULT 'vallery'::text NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    orientation text,
    sensor_modbus_addr integer,
    peak_temp_f double precision,
    status text DEFAULT 'active'::text NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT zones_sensor_modbus_addr_check CHECK (((sensor_modbus_addr >= 1) AND (sensor_modbus_addr <= 247))),
    CONSTRAINT zones_slug_check CHECK ((slug ~ '^[a-z][a-z0-9_]*$'::text)),
    CONSTRAINT zones_status_check CHECK ((status = ANY (ARRAY['active'::text, 'offline'::text, 'decommissioned'::text])))
);


ALTER TABLE public.zones OWNER TO verdify;

--
-- Name: TABLE zones; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.zones IS 'Sprint 22: physical zones (south/north/east/west/center). Replaces free-text `zone` columns on crops/observations/alert_log with FK targets.';


--
-- Name: v_crop_history; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_crop_history AS
 SELECT p.id AS position_id,
    p.greenhouse_id,
    p.label AS position_label,
    z.slug AS zone_slug,
    c.id AS crop_id,
    c.name AS crop_name,
    c.variety AS crop_variety,
    c.stage AS final_stage,
    c.planted_date,
    c.cleared_at,
    c.is_active,
    ((c.cleared_at)::date - c.planted_date) AS days_in_place,
    cc.slug AS crop_catalog_slug,
    cc.common_name AS crop_common_name,
    ( SELECT count(*) AS count
           FROM public.crop_events e
          WHERE (e.crop_id = c.id)) AS event_count,
    ( SELECT count(*) AS count
           FROM public.observations o
          WHERE (o.crop_id = c.id)) AS observation_count,
    ( SELECT count(*) AS count
           FROM public.harvests h
          WHERE (h.crop_id = c.id)) AS harvest_count
   FROM ((((public.crops c
     LEFT JOIN public.positions p ON ((p.id = c.position_id)))
     LEFT JOIN public.shelves sh ON ((sh.id = p.shelf_id)))
     LEFT JOIN public.zones z ON ((z.id = sh.zone_id)))
     LEFT JOIN public.crop_catalog cc ON ((cc.id = c.crop_catalog_id)))
  ORDER BY p.label, c.planted_date DESC;


ALTER VIEW public.v_crop_history OWNER TO verdify;

--
-- Name: VIEW v_crop_history; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_crop_history IS 'Sprint 23: every crop ever recorded at a position, in reverse-chronological order. Drives website position history + /api/v1/positions/{id}/crops.';


--
-- Name: v_crop_lifecycle; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_crop_lifecycle AS
 SELECT c.id AS crop_id,
    c.greenhouse_id,
    c.name AS crop_name,
    c.variety,
    c.stage AS current_stage,
    c.is_active,
    c.planted_date,
    c.cleared_at,
    (COALESCE((c.cleared_at)::date, CURRENT_DATE) - c.planted_date) AS days_alive,
    z.slug AS current_zone_slug,
    p.label AS current_position_label,
    cc.slug AS crop_catalog_slug,
    cc.common_name AS catalog_name,
    cc.category AS catalog_category,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('ts', e.ts, 'event_type', e.event_type, 'old_stage', e.old_stage, 'new_stage', e.new_stage, 'position_id', e.position_id, 'notes', e.notes, 'source', e.source) ORDER BY e.ts) AS jsonb_agg
           FROM public.crop_events e
          WHERE (e.crop_id = c.id)), '[]'::jsonb) AS events,
    COALESCE(( SELECT sum(h.weight_kg) AS sum
           FROM public.harvests h
          WHERE (h.crop_id = c.id)), (0)::double precision) AS total_weight_kg,
    COALESCE(( SELECT sum(h.unit_count) AS sum
           FROM public.harvests h
          WHERE (h.crop_id = c.id)), (0)::bigint) AS total_units,
    COALESCE(( SELECT sum(h.revenue) AS sum
           FROM public.harvests h
          WHERE (h.crop_id = c.id)), (0)::double precision) AS total_revenue_usd,
    ( SELECT count(*) AS count
           FROM public.observations o
          WHERE (o.crop_id = c.id)) AS observation_count,
    ( SELECT (avg(o.health_score))::numeric(4,3) AS avg
           FROM public.observations o
          WHERE ((o.crop_id = c.id) AND (o.health_score IS NOT NULL))) AS avg_health_score,
    ( SELECT max(o.ts) AS max
           FROM public.observations o
          WHERE (o.crop_id = c.id)) AS latest_observation_ts
   FROM ((((public.crops c
     LEFT JOIN public.positions p ON ((p.id = c.position_id)))
     LEFT JOIN public.shelves sh ON ((sh.id = p.shelf_id)))
     LEFT JOIN public.zones z ON ((z.id = sh.zone_id)))
     LEFT JOIN public.crop_catalog cc ON ((cc.id = c.crop_catalog_id)))
  ORDER BY c.is_active DESC, c.planted_date DESC;


ALTER VIEW public.v_crop_lifecycle OWNER TO verdify;

--
-- Name: VIEW v_crop_lifecycle; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_crop_lifecycle IS 'Sprint 23: per-crop timeline with events JSONB array + harvest totals + observation summary. Drives /api/v1/crops/{id}/lifecycle and the MCP crop_lifecycle tool.';


--
-- Name: v_crop_lifecycle_completeness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_crop_lifecycle_completeness AS
 SELECT id AS crop_id,
    name,
    variety,
    zone,
    "position",
    stage,
    is_active,
    count,
    expected_harvest,
    crop_catalog_id,
    target_dli,
    target_vpd_low,
    target_vpd_high,
    array_remove(ARRAY[
        CASE
            WHEN (count IS NULL) THEN 'count'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (expected_harvest IS NULL) THEN 'expected_harvest'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (crop_catalog_id IS NULL) THEN 'crop_catalog_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (stage IS NULL) THEN 'stage'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (target_dli IS NULL) THEN 'target_dli'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((target_vpd_low IS NULL) OR (target_vpd_high IS NULL)) THEN 'target_vpd'::text
            ELSE NULL::text
        END], NULL::text) AS missing_fields,
    cardinality(array_remove(ARRAY[
        CASE
            WHEN (count IS NULL) THEN 'count'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (expected_harvest IS NULL) THEN 'expected_harvest'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (crop_catalog_id IS NULL) THEN 'crop_catalog_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (stage IS NULL) THEN 'stage'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (target_dli IS NULL) THEN 'target_dli'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((target_vpd_low IS NULL) OR (target_vpd_high IS NULL)) THEN 'target_vpd'::text
            ELSE NULL::text
        END], NULL::text)) AS missing_count
   FROM public.crops c;


ALTER VIEW public.v_crop_lifecycle_completeness OWNER TO verdify;

--
-- Name: VIEW v_crop_lifecycle_completeness; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_crop_lifecycle_completeness IS 'Crop rows with lifecycle/outcome fields required for agronomic analysis.';


--
-- Name: v_cycle_count_audit; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_cycle_count_audit AS
 WITH equipment_edges AS (
         SELECT (date_trunc('day'::text, (e_1.ts AT TIME ZONE 'America/Denver'::text)))::date AS date,
            e_1.equipment,
            count(*) FILTER (WHERE ((e_1.state IS TRUE) AND (COALESCE(e_1.lag_state, false) IS FALSE))) AS equipment_cycles
           FROM ( SELECT equipment_state.ts,
                    equipment_state.equipment,
                    equipment_state.state,
                    lag(equipment_state.state) OVER (PARTITION BY equipment_state.equipment, (date_trunc('day'::text, (equipment_state.ts AT TIME ZONE 'America/Denver'::text))) ORDER BY equipment_state.ts) AS lag_state
                   FROM public.equipment_state
                  WHERE (equipment_state.equipment = ANY (ARRAY['mister_south'::text, 'mister_west'::text, 'mister_center'::text, 'drip_wall'::text, 'drip_center'::text]))) e_1
          GROUP BY ((date_trunc('day'::text, (e_1.ts AT TIME ZONE 'America/Denver'::text)))::date), e_1.equipment
        ), firmware_cycles AS (
         SELECT daily_summary.date,
            'mister_south'::text AS equipment,
            daily_summary.cycles_mister_south AS firmware_cycles
           FROM public.daily_summary
        UNION ALL
         SELECT daily_summary.date,
            'mister_west'::text,
            daily_summary.cycles_mister_west
           FROM public.daily_summary
        UNION ALL
         SELECT daily_summary.date,
            'mister_center'::text,
            daily_summary.cycles_mister_center
           FROM public.daily_summary
        UNION ALL
         SELECT daily_summary.date,
            'drip_wall'::text,
            daily_summary.cycles_drip_wall
           FROM public.daily_summary
        UNION ALL
         SELECT daily_summary.date,
            'drip_center'::text,
            daily_summary.cycles_drip_center
           FROM public.daily_summary
        )
 SELECT f.date,
    f.equipment,
    f.firmware_cycles,
    COALESCE(e.equipment_cycles, (0)::bigint) AS equipment_cycles,
    (f.firmware_cycles - COALESCE(e.equipment_cycles, (0)::bigint)) AS cycle_delta,
        CASE
            WHEN (f.firmware_cycles IS NULL) THEN 'missing_firmware_counter'::text
            WHEN (GREATEST((f.firmware_cycles)::bigint, COALESCE(e.equipment_cycles, (0)::bigint)) = 0) THEN 'ok'::text
            WHEN (((abs((f.firmware_cycles - COALESCE(e.equipment_cycles, (0)::bigint))))::numeric / (GREATEST((f.firmware_cycles)::bigint, COALESCE(e.equipment_cycles, (0)::bigint)))::numeric) > 0.05) THEN 'warn'::text
            ELSE 'ok'::text
        END AS audit_status
   FROM (firmware_cycles f
     LEFT JOIN equipment_edges e ON (((e.date = f.date) AND (e.equipment = f.equipment))));


ALTER VIEW public.v_cycle_count_audit OWNER TO verdify;

--
-- Name: VIEW v_cycle_count_audit; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_cycle_count_audit IS 'Compares firmware per-zone mister/drip cycle counters against equipment_state rising-edge counts; >5% divergence is warn.';


--
-- Name: v_daily_checklist; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_daily_checklist AS
 WITH last_done AS (
         SELECT daily_checklist_log.template_id,
            max(daily_checklist_log.date) FILTER (WHERE (daily_checklist_log.completed_at IS NOT NULL)) AS last_completed
           FROM public.daily_checklist_log
          GROUP BY daily_checklist_log.template_id
        )
 SELECT t.id AS template_id,
    t.task,
    t.zone,
    t.priority,
    t.frequency,
    t.role,
        CASE t.frequency
            WHEN 'daily'::text THEN true
            WHEN 'weekly'::text THEN ((ld.last_completed IS NULL) OR ((CURRENT_DATE - ld.last_completed) > 6))
            WHEN 'biweekly'::text THEN ((ld.last_completed IS NULL) OR ((CURRENT_DATE - ld.last_completed) > 13))
            WHEN 'monthly'::text THEN ((ld.last_completed IS NULL) OR ((CURRENT_DATE - ld.last_completed) > 29))
            ELSE NULL::boolean
        END AS is_due_today,
    ld.last_completed,
    log.completed_at,
    log.completed_by,
    log.skipped,
    log.skip_reason,
    log.notes AS log_notes
   FROM ((public.daily_checklist_template t
     LEFT JOIN last_done ld ON ((ld.template_id = t.id)))
     LEFT JOIN public.daily_checklist_log log ON (((log.template_id = t.id) AND (log.date = CURRENT_DATE))))
  WHERE (t.is_active = true)
  ORDER BY (log.completed_at IS NOT NULL), t.priority, t.zone;


ALTER VIEW public.v_daily_checklist OWNER TO verdify;

--
-- Name: VIEW v_daily_checklist; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_daily_checklist IS 'Today''s checklist: shows all active tasks, whether due today, completion status. Incomplete + due items sort first.';


--
-- Name: v_daily_kpi; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_daily_kpi AS
 SELECT date,
    round((COALESCE(compliance_pct, (0)::double precision))::numeric, 1) AS compliance_pct,
    round((COALESCE(temp_compliance_pct, (0)::double precision))::numeric, 1) AS temp_compliance_pct,
    round((COALESCE(vpd_compliance_pct, (0)::double precision))::numeric, 1) AS vpd_compliance_pct,
    round((COALESCE(stress_hours_heat, (0)::double precision))::numeric, 2) AS heat_stress_h,
    round((COALESCE(stress_hours_cold, (0)::double precision))::numeric, 2) AS cold_stress_h,
    round((COALESCE(stress_hours_vpd_high, (0)::double precision))::numeric, 2) AS vpd_high_stress_h,
    round((COALESCE(stress_hours_vpd_low, (0)::double precision))::numeric, 2) AS vpd_low_stress_h,
    round(((((COALESCE(stress_hours_heat, (0)::double precision) + COALESCE(stress_hours_cold, (0)::double precision)) + COALESCE(stress_hours_vpd_high, (0)::double precision)) + COALESCE(stress_hours_vpd_low, (0)::double precision)))::numeric, 2) AS total_stress_h,
    round((COALESCE(kwh_total, kwh_estimated, (0)::double precision))::numeric, 2) AS kwh,
    round((COALESCE(therms_estimated, gas_used_therms, (0)::double precision))::numeric, 3) AS therms,
    round((COALESCE(water_used_gal, (0)::double precision))::numeric, 0) AS water_gal,
    round((COALESCE(mister_water_gal, (0)::double precision))::numeric, 0) AS mister_water_gal,
    round((COALESCE(cost_electric, (0)::double precision))::numeric, 2) AS cost_electric,
    round((COALESCE(cost_gas, (0)::double precision))::numeric, 2) AS cost_gas,
    round((COALESCE(cost_water, (0)::double precision))::numeric, 2) AS cost_water,
    round((COALESCE(cost_total, (0)::double precision))::numeric, 2) AS cost_total,
    round((temp_min)::numeric, 1) AS temp_min,
    round((temp_max)::numeric, 1) AS temp_max,
    round((temp_avg)::numeric, 1) AS temp_avg,
    round((vpd_min)::numeric, 2) AS vpd_min,
    round((vpd_max)::numeric, 2) AS vpd_max,
    round((vpd_avg)::numeric, 2) AS vpd_avg,
    round((dli_final)::numeric, 1) AS dli,
    round((min_dp_margin_f)::numeric, 1) AS dp_margin_min_f,
    round((COALESCE(dp_risk_hours, (0)::double precision))::numeric, 1) AS dp_risk_hours,
    round(((((COALESCE(compliance_pct, (0)::double precision) / (100.0)::double precision) * (80)::double precision) + (GREATEST((0)::double precision, ((1.0)::double precision - LEAST((COALESCE(cost_total, (0)::double precision) / (15.0)::double precision), (1.0)::double precision))) * (20)::double precision)))::numeric, 1) AS planner_score
   FROM public.daily_summary
  WHERE (date IS NOT NULL)
  ORDER BY date;


ALTER VIEW public.v_daily_kpi OWNER TO verdify;

--
-- Name: v_daily_oscillation; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_daily_oscillation AS
 WITH hourly AS (
         SELECT date_trunc('day'::text, equipment_state.ts) AS date,
            date_trunc('hour'::text, equipment_state.ts) AS hour,
            equipment_state.equipment,
            count(*) AS transitions
           FROM public.equipment_state
          GROUP BY (date_trunc('day'::text, equipment_state.ts)), (date_trunc('hour'::text, equipment_state.ts)), equipment_state.equipment
        )
 SELECT (date)::date AS date,
    equipment,
    max(transitions) AS peak_transitions_per_hour,
    (array_agg(hour ORDER BY transitions DESC))[1] AS peak_hour,
    round(avg(transitions), 1) AS avg_transitions_per_hour,
    count(*) AS active_hours
   FROM hourly
  GROUP BY ((date)::date), equipment
  ORDER BY ((date)::date) DESC, equipment;


ALTER VIEW public.v_daily_oscillation OWNER TO verdify;

--
-- Name: VIEW v_daily_oscillation; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_daily_oscillation IS 'FW-2: per-day, per-equipment peak hourly transition count. Use to detect oscillation regressions after dispatcher/firmware changes.';


--
-- Name: v_daily_oscillation_summary; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_daily_oscillation_summary AS
 SELECT date,
    sum(peak_transitions_per_hour) AS total_peak_per_hour,
    max(peak_transitions_per_hour) AS worst_equipment_peak,
    (array_agg(equipment ORDER BY peak_transitions_per_hour DESC))[1] AS worst_equipment,
    (array_agg(peak_hour ORDER BY peak_transitions_per_hour DESC))[1] AS worst_hour,
    round(avg(avg_transitions_per_hour), 1) AS avg_across_equipment
   FROM public.v_daily_oscillation
  GROUP BY date
  ORDER BY date DESC;


ALTER VIEW public.v_daily_oscillation_summary OWNER TO verdify;

--
-- Name: VIEW v_daily_oscillation_summary; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_daily_oscillation_summary IS 'FW-2: single-row-per-day oscillation scorecard. worst_equipment + worst_hour identify the peak oscillation event of the day.';


--
-- Name: v_daily_plan_archive_self_check; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_daily_plan_archive_self_check AS
 WITH db_counts AS (
         SELECT ("substring"(plan_journal.plan_id, 'iris-(\d{8})'::text))::date AS date,
            count(*) AS db_plan_count
           FROM public.plan_journal
          WHERE ((plan_journal.plan_id !~~ 'iris-reactive%'::text) AND (plan_journal.plan_id !~~ 'iris-fix%'::text) AND ("substring"(plan_journal.plan_id, 'iris-(\d{8})'::text) IS NOT NULL))
          GROUP BY ("substring"(plan_journal.plan_id, 'iris-(\d{8})'::text))::date
        )
 SELECT ds.date,
    a.generated_at,
    a.page_path,
    COALESCE(a.generated_plan_count, 0) AS generated_plan_count,
    COALESCE((a.db_plan_count)::bigint, dbc.db_plan_count, (0)::bigint) AS db_plan_count,
    a.generated_cost_total,
    ds.cost_total AS db_cost_total,
    a.generated_water_gal,
    ds.water_used_gal AS db_water_gal,
    a.content_checksum,
        CASE
            WHEN (a.date IS NULL) THEN true
            WHEN (a.generated_plan_count <> COALESCE(dbc.db_plan_count, (0)::bigint)) THEN true
            WHEN (abs((COALESCE(a.generated_cost_total, ds.cost_total, (0)::double precision) - COALESCE(ds.cost_total, (0)::double precision))) > (0.01)::double precision) THEN true
            WHEN (abs((COALESCE(a.generated_water_gal, ds.water_used_gal, (0)::double precision) - COALESCE(ds.water_used_gal, (0)::double precision))) > (0.1)::double precision) THEN true
            WHEN ((ds.captured_at IS NOT NULL) AND (a.generated_at < ds.captured_at)) THEN true
            ELSE false
        END AS stale,
        CASE
            WHEN (a.date IS NULL) THEN 'missing_archive_audit'::text
            WHEN (a.generated_plan_count <> COALESCE(dbc.db_plan_count, (0)::bigint)) THEN 'plan_count_mismatch'::text
            WHEN (abs((COALESCE(a.generated_cost_total, ds.cost_total, (0)::double precision) - COALESCE(ds.cost_total, (0)::double precision))) > (0.01)::double precision) THEN 'cost_mismatch'::text
            WHEN (abs((COALESCE(a.generated_water_gal, ds.water_used_gal, (0)::double precision) - COALESCE(ds.water_used_gal, (0)::double precision))) > (0.1)::double precision) THEN 'water_mismatch'::text
            WHEN ((ds.captured_at IS NOT NULL) AND (a.generated_at < ds.captured_at)) THEN 'archive_older_than_summary'::text
            ELSE 'ok'::text
        END AS status
   FROM ((public.daily_summary ds
     LEFT JOIN public.daily_plan_archive_audit a USING (date))
     LEFT JOIN db_counts dbc USING (date))
  WHERE (ds.date >= '2026-03-24'::date);


ALTER VIEW public.v_daily_plan_archive_self_check OWNER TO verdify;

--
-- Name: VIEW v_daily_plan_archive_self_check; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_daily_plan_archive_self_check IS 'Generated daily plan page self-check against daily_summary and plan_journal.';


--
-- Name: v_data_pipeline_health; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_data_pipeline_health AS
 SELECT 'climate'::text AS source,
    count(*) FILTER (WHERE (climate.ts > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (climate.ts > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(climate.ts))))::integer, 0) AS age_s,
    ((100.0)::double precision * ((count(*) FILTER (WHERE ((climate.ts > (now() - '01:00:00'::interval)) AND ((climate.temp_avg IS NULL) OR (climate.rh_avg IS NULL) OR (climate.vpd_avg IS NULL) OR (climate.dew_point IS NULL)))))::double precision / (NULLIF(count(*) FILTER (WHERE (climate.ts > (now() - '01:00:00'::interval))), 0))::double precision)) AS null_pct_1h
   FROM public.climate
UNION ALL
 SELECT 'hydro'::text AS source,
    count(*) FILTER (WHERE ((climate.ts > (now() - '01:00:00'::interval)) AND ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL)))) AS rows_1h,
    count(*) FILTER (WHERE ((climate.ts > (now() - '24:00:00'::interval)) AND ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL)))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(climate.ts) FILTER (WHERE ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL))))))::integer, 0) AS age_s,
    ((100.0)::double precision * ((count(*) FILTER (WHERE ((climate.ts > (now() - '01:00:00'::interval)) AND ((climate.hydro_ph IS NULL) OR (climate.hydro_ec_us_cm IS NULL)) AND ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL)))))::double precision / (NULLIF(count(*) FILTER (WHERE ((climate.ts > (now() - '01:00:00'::interval)) AND ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL)))), 0))::double precision)) AS null_pct_1h
   FROM public.climate
UNION ALL
 SELECT 'equipment'::text AS source,
    count(*) FILTER (WHERE (equipment_state.ts > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (equipment_state.ts > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(equipment_state.ts))))::integer, 0) AS age_s,
    NULL::double precision AS null_pct_1h
   FROM public.equipment_state
UNION ALL
 SELECT 'diagnostics'::text AS source,
    count(*) FILTER (WHERE (diagnostics.ts > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (diagnostics.ts > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(diagnostics.ts))))::integer, 0) AS age_s,
    ((100.0)::double precision * ((count(*) FILTER (WHERE ((diagnostics.ts > (now() - '01:00:00'::interval)) AND ((diagnostics.wifi_rssi IS NULL) OR (diagnostics.heap_bytes IS NULL) OR (diagnostics.uptime_s IS NULL) OR (diagnostics.active_probe_count IS NULL)))))::double precision / (NULLIF(count(*) FILTER (WHERE (diagnostics.ts > (now() - '01:00:00'::interval))), 0))::double precision)) AS null_pct_1h
   FROM public.diagnostics
UNION ALL
 SELECT 'energy'::text AS source,
    count(*) FILTER (WHERE (energy.ts > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (energy.ts > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(energy.ts))))::integer, 0) AS age_s,
    NULL::double precision AS null_pct_1h
   FROM public.energy
UNION ALL
 SELECT 'setpoints'::text AS source,
    count(*) FILTER (WHERE (setpoint_changes.ts > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (setpoint_changes.ts > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(setpoint_changes.ts))))::integer, 0) AS age_s,
    NULL::double precision AS null_pct_1h
   FROM public.setpoint_changes
UNION ALL
 SELECT 'forecast'::text AS source,
    count(*) FILTER (WHERE (weather_forecast.fetched_at > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (weather_forecast.fetched_at > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(weather_forecast.fetched_at))))::integer, 0) AS age_s,
    ((100.0)::double precision * ((count(*) FILTER (WHERE ((weather_forecast.fetched_at = ( SELECT max(weather_forecast_1.fetched_at) AS max
           FROM public.weather_forecast weather_forecast_1)) AND ((weather_forecast.temp_f IS NULL) OR (weather_forecast.rh_pct IS NULL) OR (weather_forecast.solar_w_m2 IS NULL)))))::double precision / (NULLIF(count(*) FILTER (WHERE (weather_forecast.fetched_at = ( SELECT max(weather_forecast_1.fetched_at) AS max
           FROM public.weather_forecast weather_forecast_1))), 0))::double precision)) AS null_pct_1h
   FROM public.weather_forecast
UNION ALL
 SELECT 'daily_summary'::text AS source,
    count(*) FILTER (WHERE (daily_summary.captured_at > (now() - '01:00:00'::interval))) AS rows_1h,
    count(*) FILTER (WHERE (daily_summary.captured_at > (now() - '24:00:00'::interval))) AS rows_24h,
    GREATEST((EXTRACT(epoch FROM (now() - max(daily_summary.captured_at))))::integer, 0) AS age_s,
    ((100.0)::double precision * ((count(*) FILTER (WHERE ((daily_summary.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 1)) AND ((daily_summary.temp_avg IS NULL) OR (daily_summary.rh_avg IS NULL) OR (daily_summary.vpd_avg IS NULL) OR (daily_summary.compliance_pct IS NULL)))))::double precision / (NULLIF(count(*) FILTER (WHERE (daily_summary.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 1))), 0))::double precision)) AS null_pct_1h
   FROM public.daily_summary;


ALTER VIEW public.v_data_pipeline_health OWNER TO verdify;

--
-- Name: v_energy_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_energy_daily AS
 WITH samples AS (
         SELECT ((((energy.ts AT TIME ZONE 'America/Denver'::text))::date)::timestamp without time zone AT TIME ZONE 'America/Denver'::text) AS day,
            energy.ts,
            energy.watts_total,
            lead(energy.ts) OVER (PARTITION BY (((energy.ts AT TIME ZONE 'America/Denver'::text))::date) ORDER BY energy.ts) AS next_ts
           FROM public.energy
          WHERE (energy.watts_total IS NOT NULL)
        ), durations AS (
         SELECT samples.day,
            samples.watts_total,
            (LEAST(GREATEST(EXTRACT(epoch FROM (COALESCE(samples.next_ts, samples.ts) - samples.ts)), (0)::numeric), (900)::numeric) / 3600.0) AS hours_observed
           FROM samples
        )
 SELECT (day)::date AS date,
    round((sum(((watts_total * (hours_observed)::double precision) / (1000.0)::double precision)))::numeric, 3) AS measured_kwh,
    round((avg(watts_total))::numeric, 1) AS avg_watts,
    round((max(watts_total))::numeric, 1) AS peak_watts
   FROM durations
  GROUP BY ((day)::date)
  ORDER BY ((day)::date);


ALTER VIEW public.v_energy_daily OWNER TO verdify;

--
-- Name: v_energy_estimate_reconciliation; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_energy_estimate_reconciliation AS
 SELECT ds.date,
    ds.kwh_estimated,
    ed.measured_kwh,
    round(((ds.kwh_estimated - (ed.measured_kwh)::double precision))::numeric, 3) AS estimate_delta_kwh,
        CASE
            WHEN (ed.measured_kwh IS NULL) THEN 'missing_measured'::text
            WHEN (ds.kwh_estimated IS NULL) THEN 'missing_runtime_estimate'::text
            WHEN ((ed.measured_kwh = (0)::numeric) AND (ds.kwh_estimated > (1)::double precision)) THEN 'meter_runtime_divergence'::text
            WHEN ((ds.kwh_estimated = (0)::double precision) AND (ed.measured_kwh > (1)::numeric)) THEN 'meter_runtime_divergence'::text
            WHEN ((ds.kwh_estimated / NULLIF((ed.measured_kwh)::double precision, (0)::double precision)) > (3)::double precision) THEN 'meter_runtime_divergence'::text
            WHEN (((ed.measured_kwh)::double precision / NULLIF(ds.kwh_estimated, (0)::double precision)) > (3)::double precision) THEN 'meter_runtime_divergence'::text
            WHEN (abs((ds.kwh_estimated - (ed.measured_kwh)::double precision)) > (5)::double precision) THEN 'meter_runtime_delta'::text
            ELSE 'ok'::text
        END AS quality_flag
   FROM (public.daily_summary ds
     LEFT JOIN public.v_energy_daily ed USING (date))
  WHERE (ds.date IS NOT NULL);


ALTER VIEW public.v_energy_estimate_reconciliation OWNER TO verdify;

--
-- Name: VIEW v_energy_estimate_reconciliation; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_energy_estimate_reconciliation IS 'Compares runtime-modeled electric kWh from published equipment wattage and observed on-time against Shelly watt-time integration. Divergence is expected while Shelly circuit coverage is partial; the public electric cost uses runtime-modeled kWh.';


--
-- Name: v_irrigation_schedule_current; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_schedule_current AS
 WITH param_defaults(parameter, default_value) AS (
         VALUES ('irrig_wall_start_hour'::text,10.0), ('irrig_wall_start_min'::text,30.0), ('irrig_wall_duration_min'::text,10.0), ('irrig_wall_fert_duration_min'::text,6.0), ('irrig_wall_fert_every_n'::text,0.0), ('irrig_wall_days_mask'::text,127.0), ('irrig_wall_fert_days_mask'::text,127.0), ('irrig_wall_flush_min'::text,2.0), ('irrig_wall_interval_days'::text,1.0), ('irrig_center_start_hour'::text,10.0), ('irrig_center_start_min'::text,30.0), ('irrig_center_duration_min'::text,10.0), ('irrig_center_fert_duration_min'::text,6.0), ('irrig_center_fert_every_n'::text,0.0), ('irrig_center_days_mask'::text,127.0), ('irrig_center_fert_days_mask'::text,127.0), ('irrig_center_flush_min'::text,2.0), ('irrig_center_interval_days'::text,1.0)
        ), latest_snapshot AS (
         SELECT DISTINCT ON (setpoint_snapshot.parameter) setpoint_snapshot.parameter,
            setpoint_snapshot.value,
            setpoint_snapshot.ts
           FROM public.setpoint_snapshot
          WHERE (setpoint_snapshot.parameter IN ( SELECT param_defaults.parameter
                   FROM param_defaults))
          ORDER BY setpoint_snapshot.parameter, setpoint_snapshot.ts DESC
        ), latest_esp32 AS (
         SELECT DISTINCT ON (setpoint_changes.parameter) setpoint_changes.parameter,
            setpoint_changes.value,
            setpoint_changes.ts
           FROM public.setpoint_changes
          WHERE ((setpoint_changes.source = 'esp32'::text) AND (setpoint_changes.parameter IN ( SELECT param_defaults.parameter
                   FROM param_defaults)))
          ORDER BY setpoint_changes.parameter, setpoint_changes.ts DESC
        ), values_by_param AS (
         SELECT d.parameter,
            COALESCE(ap.value, e.value, s.value, (d.default_value)::double precision) AS value,
                CASE
                    WHEN (ap.value IS NOT NULL) THEN 'active_plan'::text
                    WHEN (e.value IS NOT NULL) THEN 'esp32_observed'::text
                    WHEN (s.value IS NOT NULL) THEN 'cfg_readback'::text
                    ELSE 'default'::text
                END AS source,
            ap.plan_id,
            ap.ts AS plan_ts,
            e.ts AS esp32_ts,
            s.ts AS readback_ts,
            s.value AS readback_value,
            d.default_value
           FROM (((param_defaults d
             LEFT JOIN public.v_active_plan ap ON ((ap.parameter = d.parameter)))
             LEFT JOIN latest_esp32 e ON ((e.parameter = d.parameter)))
             LEFT JOIN latest_snapshot s ON ((s.parameter = d.parameter)))
        ), pivoted AS (
         SELECT max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_start_hour'::text)) AS wall_start_hour,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_start_min'::text)) AS wall_start_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_duration_min'::text)) AS wall_duration_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_fert_duration_min'::text)) AS wall_fert_duration_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_fert_every_n'::text)) AS wall_fert_every_n,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_days_mask'::text)) AS wall_days_mask,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_fert_days_mask'::text)) AS wall_fert_days_mask,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_flush_min'::text)) AS wall_flush_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_wall_interval_days'::text)) AS wall_interval_days,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_start_hour'::text)) AS center_start_hour,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_start_min'::text)) AS center_start_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_duration_min'::text)) AS center_duration_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_fert_duration_min'::text)) AS center_fert_duration_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_fert_every_n'::text)) AS center_fert_every_n,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_days_mask'::text)) AS center_days_mask,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_fert_days_mask'::text)) AS center_fert_days_mask,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_flush_min'::text)) AS center_flush_min,
            max(values_by_param.value) FILTER (WHERE (values_by_param.parameter = 'irrig_center_interval_days'::text)) AS center_interval_days
           FROM values_by_param
        ), source_rollup AS (
         SELECT
                CASE
                    WHEN (count(*) FILTER (WHERE (values_by_param.source = 'active_plan'::text)) > 0) THEN 'active_plan'::text
                    WHEN (count(*) FILTER (WHERE (values_by_param.source = 'esp32_observed'::text)) > 0) THEN 'esp32_observed'::text
                    WHEN (count(*) FILTER (WHERE (values_by_param.source = 'cfg_readback'::text)) > 0) THEN 'cfg_readback'::text
                    ELSE 'default'::text
                END AS schedule_source,
            max(values_by_param.plan_id) FILTER (WHERE (values_by_param.plan_id IS NOT NULL)) AS plan_id,
            max(values_by_param.plan_ts) AS plan_ts,
            count(*) FILTER (WHERE ((values_by_param.readback_ts IS NULL) OR (values_by_param.readback_ts < (now() - '00:15:00'::interval)))) AS stale_readback_count,
            count(*) FILTER (WHERE ((values_by_param.readback_value IS NOT NULL) AND ((abs((values_by_param.readback_value - values_by_param.value)) / GREATEST(abs(values_by_param.value), (0.001)::double precision)) >= (0.01)::double precision))) AS readback_drift_count
           FROM values_by_param
        ), latest_equipment AS (
         SELECT DISTINCT ON (equipment_state.equipment) equipment_state.equipment,
            equipment_state.state,
            equipment_state.ts
           FROM public.equipment_state
          WHERE (equipment_state.equipment = ANY (ARRAY['irrigation_enabled'::text, 'irrigation_wall_enabled'::text, 'irrigation_center_enabled'::text]))
          ORDER BY equipment_state.equipment, equipment_state.ts DESC
        )
 SELECT 'wall_shared'::text AS schedule_id,
    'wall_shared'::text AS zone_path,
    'Wall shared drip + south/west misters'::text AS display_name,
    ARRAY['south'::text, 'west'::text] AS serves_zones,
    (COALESCE(( SELECT latest_equipment.state
           FROM latest_equipment
          WHERE (latest_equipment.equipment = 'irrigation_enabled'::text)), true) AND COALESCE(( SELECT latest_equipment.state
           FROM latest_equipment
          WHERE (latest_equipment.equipment = 'irrigation_wall_enabled'::text)), true)) AS enabled,
    make_time(GREATEST(0, LEAST(23, (round(p.wall_start_hour))::integer)), GREATEST(0, LEAST(59, (round(p.wall_start_min))::integer)), (0)::double precision) AS start_time,
    (round(p.wall_duration_min))::integer AS clean_duration_min,
    (round(p.wall_fert_duration_min))::integer AS fert_duration_min,
    (round(p.wall_flush_min))::integer AS flush_min,
    (round(p.wall_interval_days))::integer AS interval_days,
    (round(p.wall_days_mask))::integer AS days_mask,
    (round(p.wall_fert_days_mask))::integer AS fert_days_mask,
    (round(p.wall_fert_every_n))::integer AS fert_every_n,
    (((round(p.wall_fert_duration_min))::integer > 0) AND (((round(p.wall_fert_days_mask))::integer <> 0) OR ((round(p.wall_fert_every_n))::integer > 0))) AS fertigation_enabled,
    ARRAY['drip_wall_fert'::text, 'mister_south_fert'::text, 'mister_west_fert'::text] AS fert_relays,
    ARRAY['drip_wall'::text, 'mister_south'::text, 'mister_west'::text] AS flush_relays,
    s.schedule_source,
    s.plan_id,
    s.plan_ts,
    s.stale_readback_count,
    s.readback_drift_count,
    'One wall drip path serves south and west; firmware queues wall drip, south mister, and west mister fert jobs from this schedule.'::text AS notes
   FROM (pivoted p
     CROSS JOIN source_rollup s)
UNION ALL
 SELECT 'center'::text AS schedule_id,
    'center'::text AS zone_path,
    'Center drip'::text AS display_name,
    ARRAY['center'::text] AS serves_zones,
    (COALESCE(( SELECT latest_equipment.state
           FROM latest_equipment
          WHERE (latest_equipment.equipment = 'irrigation_enabled'::text)), true) AND COALESCE(( SELECT latest_equipment.state
           FROM latest_equipment
          WHERE (latest_equipment.equipment = 'irrigation_center_enabled'::text)), true)) AS enabled,
    make_time(GREATEST(0, LEAST(23, (round(p.center_start_hour))::integer)), GREATEST(0, LEAST(59, (round(p.center_start_min))::integer)), (0)::double precision) AS start_time,
    (round(p.center_duration_min))::integer AS clean_duration_min,
    (round(p.center_fert_duration_min))::integer AS fert_duration_min,
    (round(p.center_flush_min))::integer AS flush_min,
    (round(p.center_interval_days))::integer AS interval_days,
    (round(p.center_days_mask))::integer AS days_mask,
    (round(p.center_fert_days_mask))::integer AS fert_days_mask,
    (round(p.center_fert_every_n))::integer AS fert_every_n,
    (((round(p.center_fert_duration_min))::integer > 0) AND (((round(p.center_fert_days_mask))::integer <> 0) OR ((round(p.center_fert_every_n))::integer > 0))) AS fertigation_enabled,
    ARRAY['drip_center_fert'::text] AS fert_relays,
    ARRAY['drip_center'::text] AS flush_relays,
    s.schedule_source,
    s.plan_id,
    s.plan_ts,
    s.stale_readback_count,
    s.readback_drift_count,
    'Center drip/fert path; center root-zone and runoff feedback remain pending physical instrumentation.'::text AS notes
   FROM (pivoted p
     CROSS JOIN source_rollup s);


ALTER VIEW public.v_irrigation_schedule_current OWNER TO verdify;

--
-- Name: VIEW v_irrigation_schedule_current; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_schedule_current IS 'Canonical current irrigation schedule. Values prefer v_active_plan, then ESP32 observed number states, then cfg_* readbacks, then firmware defaults.';


--
-- Name: v_irrigation_fertigation_runs; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_fertigation_runs AS
 WITH raw AS (
         SELECT e.equipment,
            e.ts,
            e.state,
            lag(e.state) OVER (PARTITION BY e.equipment ORDER BY e.ts) AS prev_state
           FROM public.equipment_state e
          WHERE (e.equipment = ANY (ARRAY['drip_wall_fert'::text, 'drip_wall'::text, 'mister_south_fert'::text, 'mister_south'::text, 'mister_west_fert'::text, 'mister_west'::text, 'drip_center_fert'::text, 'drip_center'::text, 'fert_master_valve'::text, 'water_flowing'::text]))
        ), changes AS (
         SELECT raw.equipment,
            raw.ts,
            raw.state
           FROM raw
          WHERE ((raw.prev_state IS NULL) OR (raw.prev_state IS DISTINCT FROM raw.state))
        ), intervals AS (
         SELECT changes.equipment,
            changes.ts AS start_ts,
            lead(changes.ts) OVER (PARTITION BY changes.equipment ORDER BY changes.ts) AS end_ts,
            changes.state
           FROM changes
        ), on_intervals AS (
         SELECT intervals.equipment,
            intervals.start_ts,
            intervals.end_ts
           FROM intervals
          WHERE ((intervals.state IS TRUE) AND (intervals.end_ts IS NOT NULL) AND (intervals.end_ts > intervals.start_ts))
        ), fert_map(fert_relay, flush_relay, zone_path, serves_zones, schedule_id, expected_fert_min, expected_flush_min) AS (
         VALUES ('drip_wall_fert'::text,'drip_wall'::text,'wall_shared'::text,ARRAY['south'::text, 'west'::text],'wall_shared'::text,6,2), ('mister_south_fert'::text,'mister_south'::text,'south_wall_mister'::text,ARRAY['south'::text],'wall_shared'::text,6,2), ('mister_west_fert'::text,'mister_west'::text,'west_wall_mister'::text,ARRAY['west'::text],'wall_shared'::text,6,2), ('drip_center_fert'::text,'drip_center'::text,'center'::text,ARRAY['center'::text],'center'::text,6,2)
        ), fert_jobs AS (
         SELECT f.fert_relay,
            f.flush_relay,
            f.zone_path,
            f.serves_zones,
            f.schedule_id,
            COALESCE(s.fert_duration_min, f.expected_fert_min) AS expected_fert_min,
            COALESCE(s.flush_min, f.expected_flush_min) AS expected_flush_min,
            oi.start_ts AS fert_start,
            oi.end_ts AS fert_end
           FROM ((on_intervals oi
             JOIN fert_map f ON ((f.fert_relay = oi.equipment)))
             LEFT JOIN public.v_irrigation_schedule_current s ON ((s.schedule_id = f.schedule_id)))
        ), paired AS (
         SELECT fj.fert_relay,
            fj.flush_relay,
            fj.zone_path,
            fj.serves_zones,
            fj.schedule_id,
            fj.expected_fert_min,
            fj.expected_flush_min,
            fj.fert_start,
            fj.fert_end,
            fl.start_ts AS flush_start,
            fl.end_ts AS flush_end
           FROM (fert_jobs fj
             LEFT JOIN LATERAL ( SELECT oi.start_ts,
                    oi.end_ts
                   FROM on_intervals oi
                  WHERE ((oi.equipment = fj.flush_relay) AND (oi.start_ts >= (fj.fert_end - '00:00:30'::interval)) AND (oi.start_ts <= (fj.fert_end + '00:10:00'::interval)))
                  ORDER BY oi.start_ts
                 LIMIT 1) fl ON (true))
        ), measured AS (
         SELECT p.fert_relay,
            p.flush_relay,
            p.zone_path,
            p.serves_zones,
            p.schedule_id,
            p.expected_fert_min,
            p.expected_flush_min,
            p.fert_start,
            p.fert_end,
            p.flush_start,
            p.flush_end,
            COALESCE(p.flush_end, p.fert_end) AS run_end,
            master.overlap_min AS fert_master_overlap_min,
            water.overlap_min AS water_flowing_overlap_min,
            meter.samples AS meter_samples,
            meter.min_total_gal,
            meter.max_total_gal,
                CASE
                    WHEN (meter.samples >= 2) THEN GREATEST((0.0)::double precision, (meter.max_total_gal - meter.min_total_gal))
                    ELSE NULL::double precision
                END AS meter_delta_gal,
            meter.avg_flow_gpm,
            meter.max_flow_gpm
           FROM (((paired p
             LEFT JOIN LATERAL ( SELECT (round((sum(EXTRACT(epoch FROM (LEAST(m.end_ts, p.fert_end) - GREATEST(m.start_ts, p.fert_start)))) / 60.0), 2))::double precision AS overlap_min
                   FROM on_intervals m
                  WHERE ((m.equipment = 'fert_master_valve'::text) AND (m.start_ts < p.fert_end) AND (m.end_ts > p.fert_start))) master ON (true))
             LEFT JOIN LATERAL ( SELECT (round((sum(EXTRACT(epoch FROM (LEAST(w.end_ts, COALESCE(p.flush_end, p.fert_end)) - GREATEST(w.start_ts, p.fert_start)))) / 60.0), 2))::double precision AS overlap_min
                   FROM on_intervals w
                  WHERE ((w.equipment = 'water_flowing'::text) AND (w.start_ts < COALESCE(p.flush_end, p.fert_end)) AND (w.end_ts > p.fert_start))) water ON (true))
             LEFT JOIN LATERAL ( SELECT stats.samples,
                    first_sample.water_total_gal AS min_total_gal,
                    last_sample.water_total_gal AS max_total_gal,
                    stats.avg_flow_gpm,
                    stats.max_flow_gpm
                   FROM ((( SELECT (count(*))::integer AS samples,
                            avg(c.flow_gpm) AS avg_flow_gpm,
                            max(c.flow_gpm) AS max_flow_gpm
                           FROM public.climate c
                          WHERE ((c.ts >= (p.fert_start - '00:00:30'::interval)) AND (c.ts <= (COALESCE(p.flush_end, p.fert_end) + '00:01:30'::interval)) AND (c.water_total_gal IS NOT NULL) AND (c.water_total_gal > (0)::double precision))) stats
                     LEFT JOIN LATERAL ( SELECT c.water_total_gal
                           FROM public.climate c
                          WHERE ((c.ts >= (p.fert_start - '00:00:30'::interval)) AND (c.ts <= (COALESCE(p.flush_end, p.fert_end) + '00:01:30'::interval)) AND (c.water_total_gal IS NOT NULL) AND (c.water_total_gal > (0)::double precision))
                          ORDER BY c.ts
                         LIMIT 1) first_sample ON (true))
                     LEFT JOIN LATERAL ( SELECT c.water_total_gal
                           FROM public.climate c
                          WHERE ((c.ts >= (p.fert_start - '00:00:30'::interval)) AND (c.ts <= (COALESCE(p.flush_end, p.fert_end) + '00:01:30'::interval)) AND (c.water_total_gal IS NOT NULL) AND (c.water_total_gal > (0)::double precision))
                          ORDER BY c.ts DESC
                         LIMIT 1) last_sample ON (true))) meter ON (true))
        ), flagged AS (
         SELECT md5(((measured.fert_relay || '|'::text) || (measured.fert_start)::text)) AS run_id,
            ((measured.fert_start AT TIME ZONE 'America/Denver'::text))::date AS day,
            measured.zone_path,
            measured.serves_zones,
            measured.schedule_id,
            measured.fert_relay,
            measured.flush_relay,
            measured.fert_start,
            measured.fert_end,
            (round((EXTRACT(epoch FROM (measured.fert_end - measured.fert_start)) / 60.0), 2))::double precision AS fert_duration_min,
            measured.flush_start,
            measured.flush_end,
                CASE
                    WHEN ((measured.flush_start IS NOT NULL) AND (measured.flush_end IS NOT NULL)) THEN (round((EXTRACT(epoch FROM (measured.flush_end - measured.flush_start)) / 60.0), 2))::double precision
                    ELSE NULL::double precision
                END AS flush_duration_min,
            measured.fert_start AS run_start,
            measured.run_end,
            (round((EXTRACT(epoch FROM (measured.run_end - measured.fert_start)) / 60.0), 2))::double precision AS total_duration_min,
            measured.expected_fert_min,
            measured.expected_flush_min,
            COALESCE(measured.fert_master_overlap_min, (0.0)::double precision) AS fert_master_overlap_min,
            COALESCE(measured.water_flowing_overlap_min, (0.0)::double precision) AS water_flowing_overlap_min,
            measured.meter_samples,
            measured.min_total_gal,
            measured.max_total_gal,
            measured.meter_delta_gal,
            measured.avg_flow_gpm,
            measured.max_flow_gpm,
            array_remove(ARRAY[
                CASE
                    WHEN (measured.flush_start IS NULL) THEN 'missing_flush'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(measured.fert_master_overlap_min, (0.0)::double precision) < (GREATEST(0.5, ((EXTRACT(epoch FROM (measured.fert_end - measured.fert_start)) / 60.0) * 0.95)))::double precision) THEN 'low_master_overlap'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((measured.meter_samples IS NULL) OR (measured.meter_samples < 2)) THEN 'meter_sparse'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((measured.meter_samples >= 2) AND (COALESCE(measured.meter_delta_gal, (0.0)::double precision) <= (0.0)::double precision)) THEN 'zero_meter_delta'::text
                    ELSE NULL::text
                END], NULL::text) AS quality_flags
           FROM measured
        )
 SELECT run_id,
    day,
    zone_path,
    serves_zones,
    schedule_id,
    fert_relay,
    flush_relay,
    fert_start,
    fert_end,
    fert_duration_min,
    flush_start,
    flush_end,
    flush_duration_min,
    run_start,
    run_end,
    total_duration_min,
    expected_fert_min,
    expected_flush_min,
    fert_master_overlap_min,
    water_flowing_overlap_min,
    meter_samples,
    min_total_gal,
    max_total_gal,
    meter_delta_gal,
    avg_flow_gpm,
    max_flow_gpm,
    quality_flags,
        CASE
            WHEN (array_length(quality_flags, 1) IS NULL) THEN 'ok'::text
            ELSE array_to_string(quality_flags, ','::text)
        END AS quality_flag
   FROM flagged
  ORDER BY fert_start DESC, fert_relay;


ALTER VIEW public.v_irrigation_fertigation_runs OWNER TO verdify;

--
-- Name: VIEW v_irrigation_fertigation_runs; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_fertigation_runs IS 'Equipment-derived fertigation runs. Compresses duplicate relay state rows, pairs fert relays with clean flush relays, measures fertilizer master overlap, and computes per-run water-meter delta.';


--
-- Name: v_irrigation_program_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_program_daily AS
 SELECT day AS date,
    count(*) AS fertigation_events,
    (round((sum(total_duration_min))::numeric, 1))::double precision AS runtime_min,
    (round((sum(fert_duration_min))::numeric, 1))::double precision AS fert_runtime_min,
    (round((sum(COALESCE(flush_duration_min, (0)::double precision)))::numeric, 1))::double precision AS flush_runtime_min,
    (round((sum(fert_master_overlap_min))::numeric, 1))::double precision AS fert_master_overlap_min,
    (round((sum(COALESCE(meter_delta_gal, (0)::double precision)))::numeric, 2))::double precision AS meter_delta_gal,
    count(*) FILTER (WHERE (quality_flag <> 'ok'::text)) AS flagged_events,
    max(run_end) AS latest_event
   FROM public.v_irrigation_fertigation_runs
  GROUP BY day
  ORDER BY day DESC;


ALTER VIEW public.v_irrigation_program_daily OWNER TO verdify;

--
-- Name: VIEW v_irrigation_program_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_program_daily IS 'Daily rollup of equipment-derived irrigation/fertigation runs.';


--
-- Name: v_planner_trigger_health; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_planner_trigger_health AS
 WITH recent AS (
         SELECT planner_trigger_ledger.id,
            planner_trigger_ledger.greenhouse_id,
            planner_trigger_ledger.event_type,
            planner_trigger_ledger.event_label,
            planner_trigger_ledger.instance,
            planner_trigger_ledger.expected_at,
            planner_trigger_ledger.due_at,
            planner_trigger_ledger.delivered_at,
            planner_trigger_ledger.resolved_at,
            planner_trigger_ledger.status,
            planner_trigger_ledger.expected_action,
            planner_trigger_ledger.sla_seconds,
            planner_trigger_ledger.catchup,
            planner_trigger_ledger.plan_delivery_log_id,
            planner_trigger_ledger.trigger_id,
            planner_trigger_ledger.resulting_plan_id,
            planner_trigger_ledger.notes,
            planner_trigger_ledger.created_at,
            planner_trigger_ledger.updated_at
           FROM public.planner_trigger_ledger
          WHERE (planner_trigger_ledger.expected_at >= (now() - '36:00:00'::interval))
        ), latest_required AS (
         SELECT DISTINCT ON (recent.event_type) recent.event_type,
            recent.event_label,
            recent.instance,
            recent.expected_at,
            recent.due_at,
            recent.delivered_at,
            recent.resolved_at,
            recent.status,
            recent.resulting_plan_id,
            recent.trigger_id
           FROM recent
          WHERE (recent.event_type = ANY (ARRAY['SUNRISE'::text, 'SUNSET'::text, 'MIDNIGHT'::text]))
          ORDER BY recent.event_type, recent.expected_at DESC
        ), last_required_recovery AS (
         SELECT max(recent.expected_at) AS expected_at
           FROM recent
          WHERE ((recent.event_type = ANY (ARRAY['SUNRISE'::text, 'SUNSET'::text, 'MIDNIGHT'::text])) AND (recent.status = 'plan_written'::text))
        ), unrecovered_required_failures AS (
         SELECT r.id,
            r.greenhouse_id,
            r.event_type,
            r.event_label,
            r.instance,
            r.expected_at,
            r.due_at,
            r.delivered_at,
            r.resolved_at,
            r.status,
            r.expected_action,
            r.sla_seconds,
            r.catchup,
            r.plan_delivery_log_id,
            r.trigger_id,
            r.resulting_plan_id,
            r.notes,
            r.created_at,
            r.updated_at
           FROM (recent r
             CROSS JOIN last_required_recovery lrr)
          WHERE ((r.event_type = ANY (ARRAY['SUNRISE'::text, 'SUNSET'::text, 'MIDNIGHT'::text])) AND (r.status = ANY (ARRAY['missed'::text, 'timed_out'::text, 'delivery_failed'::text])) AND ((lrr.expected_at IS NULL) OR (r.expected_at > lrr.expected_at)))
        )
 SELECT now() AS generated_at,
    (( SELECT count(*) AS count
           FROM recent
          WHERE ((recent.status = 'expected'::text) AND (recent.due_at < now()))))::integer AS missed_expected_count,
    (( SELECT count(*) AS count
           FROM recent
          WHERE ((recent.status = 'delivered'::text) AND (recent.due_at < now()))))::integer AS overdue_delivered_count,
    (( SELECT count(*) AS count
           FROM unrecovered_required_failures))::integer AS required_failure_count,
    (( SELECT count(*) AS count
           FROM recent
          WHERE (recent.status = ANY (ARRAY['plan_written'::text, 'acked'::text]))))::integer AS resolved_count,
    (( SELECT count(*) AS count
           FROM recent))::integer AS recent_expected_count,
    COALESCE(( SELECT jsonb_agg(to_jsonb(latest_required.*) ORDER BY latest_required.expected_at DESC) AS jsonb_agg
           FROM latest_required), '[]'::jsonb) AS latest_required;


ALTER VIEW public.v_planner_trigger_health OWNER TO verdify;

--
-- Name: VIEW v_planner_trigger_health; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_planner_trigger_health IS 'Public/ops-safe summary of expected planner trigger health over the last 36h. Historical required failures recover after a later required plan writes successfully.';


--
-- Name: v_sensor_staleness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_sensor_staleness AS
 WITH last_readings AS (
         SELECT sr.sensor_id,
            sr.type,
            sr.zone,
            sr.expected_interval_s,
            sr.source_table,
            sr.source_column,
                CASE sr.source_table
                    WHEN 'climate'::text THEN ( SELECT max(c.ts) AS max
                       FROM public.climate c
                      WHERE ((c.ts > (now() - GREATEST('02:00:00'::interval, ((sr.expected_interval_s)::double precision * '00:00:02'::interval)))) AND (
                            CASE sr.source_column
                                WHEN 'temp_avg'::text THEN c.temp_avg
                                WHEN 'temp_north'::text THEN c.temp_north
                                WHEN 'temp_south'::text THEN c.temp_south
                                WHEN 'temp_east'::text THEN c.temp_east
                                WHEN 'temp_west'::text THEN c.temp_west
                                WHEN 'temp_case'::text THEN c.temp_case
                                WHEN 'temp_control'::text THEN c.temp_control
                                WHEN 'temp_intake'::text THEN c.temp_intake
                                WHEN 'rh_avg'::text THEN c.rh_avg
                                WHEN 'rh_north'::text THEN c.rh_north
                                WHEN 'rh_south'::text THEN c.rh_south
                                WHEN 'rh_east'::text THEN c.rh_east
                                WHEN 'rh_west'::text THEN c.rh_west
                                WHEN 'rh_case'::text THEN c.rh_case
                                WHEN 'intake_rh'::text THEN c.intake_rh
                                WHEN 'vpd_avg'::text THEN c.vpd_avg
                                WHEN 'vpd_north'::text THEN c.vpd_north
                                WHEN 'vpd_south'::text THEN c.vpd_south
                                WHEN 'vpd_east'::text THEN c.vpd_east
                                WHEN 'vpd_west'::text THEN c.vpd_west
                                WHEN 'vpd_control'::text THEN c.vpd_control
                                WHEN 'intake_vpd'::text THEN c.intake_vpd
                                WHEN 'co2_ppm'::text THEN c.co2_ppm
                                WHEN 'lux'::text THEN c.lux
                                WHEN 'dli_today'::text THEN c.dli_today
                                WHEN 'ppfd'::text THEN c.ppfd
                                WHEN 'dli_par_today'::text THEN c.dli_par_today
                                WHEN 'dew_point'::text THEN c.dew_point
                                WHEN 'abs_humidity'::text THEN c.abs_humidity
                                WHEN 'enthalpy_delta'::text THEN c.enthalpy_delta
                                WHEN 'flow_gpm'::text THEN c.flow_gpm
                                WHEN 'water_total_gal'::text THEN c.water_total_gal
                                WHEN 'mister_water_today'::text THEN c.mister_water_today
                                WHEN 'outdoor_temp_f'::text THEN c.outdoor_temp_f
                                WHEN 'outdoor_rh_pct'::text THEN c.outdoor_rh_pct
                                WHEN 'wind_speed_mph'::text THEN c.wind_speed_mph
                                WHEN 'wind_direction_deg'::text THEN c.wind_direction_deg
                                WHEN 'wind_gust_mph'::text THEN c.wind_gust_mph
                                WHEN 'wind_lull_mph'::text THEN c.wind_lull_mph
                                WHEN 'wind_speed_avg_mph'::text THEN c.wind_speed_avg_mph
                                WHEN 'wind_direction_avg_deg'::text THEN c.wind_direction_avg_deg
                                WHEN 'outdoor_lux'::text THEN c.outdoor_lux
                                WHEN 'outdoor_illuminance'::text THEN c.outdoor_illuminance
                                WHEN 'solar_irradiance_w_m2'::text THEN c.solar_irradiance_w_m2
                                WHEN 'solar_altitude_deg'::text THEN c.solar_altitude_deg
                                WHEN 'solar_azimuth_deg'::text THEN c.solar_azimuth_deg
                                WHEN 'pressure_hpa'::text THEN c.pressure_hpa
                                WHEN 'uv_index'::text THEN c.uv_index
                                WHEN 'precip_in'::text THEN c.precip_in
                                WHEN 'precip_intensity_in_h'::text THEN c.precip_intensity_in_h
                                WHEN 'feels_like_f'::text THEN c.feels_like_f
                                WHEN 'wet_bulb_temp_f'::text THEN c.wet_bulb_temp_f
                                WHEN 'vapor_pressure_inhg'::text THEN c.vapor_pressure_inhg
                                WHEN 'air_density_kg_m3'::text THEN c.air_density_kg_m3
                                WHEN 'lightning_count'::text THEN (c.lightning_count)::double precision
                                WHEN 'lightning_avg_dist_mi'::text THEN c.lightning_avg_dist_mi
                                WHEN 'hydro_ec_us_cm'::text THEN c.hydro_ec_us_cm
                                WHEN 'hydro_ph'::text THEN c.hydro_ph
                                WHEN 'hydro_tds_ppm'::text THEN c.hydro_tds_ppm
                                WHEN 'hydro_water_temp_f'::text THEN c.hydro_water_temp_f
                                WHEN 'hydro_orp_mv'::text THEN c.hydro_orp_mv
                                WHEN 'hydro_battery_pct'::text THEN c.hydro_battery_pct
                                WHEN 'soil_moisture_south_1'::text THEN c.soil_moisture_south_1
                                WHEN 'soil_temp_south_1'::text THEN c.soil_temp_south_1
                                WHEN 'soil_ec_south_1'::text THEN c.soil_ec_south_1
                                WHEN 'soil_moisture_south_2'::text THEN c.soil_moisture_south_2
                                WHEN 'soil_temp_south_2'::text THEN c.soil_temp_south_2
                                WHEN 'soil_moisture_west'::text THEN c.soil_moisture_west
                                WHEN 'soil_temp_west'::text THEN c.soil_temp_west
                                WHEN 'ph_input'::text THEN c.ph_input
                                WHEN 'ec_input'::text THEN c.ec_input
                                WHEN 'ph_runoff_wall'::text THEN c.ph_runoff_wall
                                WHEN 'ec_runoff_wall'::text THEN c.ec_runoff_wall
                                WHEN 'ph_runoff_center'::text THEN c.ph_runoff_center
                                WHEN 'ec_runoff_center'::text THEN c.ec_runoff_center
                                WHEN 'leaf_temp_north'::text THEN c.leaf_temp_north
                                WHEN 'leaf_temp_south'::text THEN c.leaf_temp_south
                                WHEN 'leaf_wetness_north'::text THEN c.leaf_wetness_north
                                WHEN 'leaf_wetness_south'::text THEN c.leaf_wetness_south
                                ELSE NULL::double precision
                            END IS NOT NULL)))
                    WHEN 'equipment_state'::text THEN ( SELECT max(es.ts) AS max
                       FROM public.equipment_state es
                      WHERE (es.equipment = sr.source_column))
                    WHEN 'system_state'::text THEN ( SELECT max(ss.ts) AS max
                       FROM public.system_state ss
                      WHERE (ss.entity = sr.source_column))
                    WHEN 'diagnostics'::text THEN ( SELECT max(d.ts) AS max
                       FROM public.diagnostics d
                      WHERE (d.ts > (now() - '02:00:00'::interval)))
                    ELSE NULL::timestamp with time zone
                END AS last_seen_at
           FROM public.sensor_registry sr
          WHERE (sr.active = true)
        )
 SELECT sensor_id,
    type,
    zone,
    expected_interval_s,
    last_seen_at,
    (EXTRACT(epoch FROM (now() - last_seen_at)))::integer AS seconds_since,
        CASE
            WHEN (last_seen_at IS NULL) THEN true
            WHEN (EXTRACT(epoch FROM (now() - last_seen_at)) > ((expected_interval_s * 2))::numeric) THEN true
            ELSE false
        END AS is_stale,
        CASE
            WHEN (last_seen_at IS NULL) THEN NULL::numeric
            ELSE round((EXTRACT(epoch FROM (now() - last_seen_at)) / (NULLIF(expected_interval_s, 0))::numeric), 1)
        END AS staleness_ratio
   FROM last_readings;


ALTER VIEW public.v_sensor_staleness OWNER TO verdify;

--
-- Name: v_required_sensor_coverage; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_required_sensor_coverage AS
 SELECT cfg.greenhouse_id,
    cfg.target_table,
    cfg.target_column,
    cfg.entity_name,
    cfg.entity_type,
    cfg.is_required,
    sr.sensor_id,
    COALESCE(sr.active, false) AS registry_active,
    vs.last_seen_at,
    vs.seconds_since,
    COALESCE(vs.is_stale, true) AS is_stale,
        CASE
            WHEN (sr.sensor_id IS NULL) THEN 'missing_registry'::text
            WHEN (sr.active IS NOT TRUE) THEN 'inactive_registry'::text
            WHEN vs.is_stale THEN 'stale'::text
            ELSE 'ok'::text
        END AS coverage_status
   FROM ((public.greenhouse_sensor_config cfg
     LEFT JOIN public.sensor_registry sr ON (((sr.source_table = cfg.target_table) AND (sr.source_column = cfg.target_column))))
     LEFT JOIN public.v_sensor_staleness vs ON ((vs.sensor_id = sr.sensor_id)))
  WHERE (cfg.is_required = true);


ALTER VIEW public.v_required_sensor_coverage OWNER TO verdify;

--
-- Name: VIEW v_required_sensor_coverage; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_required_sensor_coverage IS 'Required configured sensors joined to registry and live staleness status.';


--
-- Name: v_water_budget; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_water_budget AS
 SELECT ds.date,
    ds.water_used_gal AS total_gal,
    ds.mister_water_gal AS mister_gal,
    COALESCE(ipd.meter_delta_gal, ds.irrigation_water_gal, drip.drip_runtime_gal, (0)::double precision) AS drip_gal,
    ((ds.water_used_gal - COALESCE(ds.mister_water_gal, (0)::double precision)) - COALESCE(ipd.meter_delta_gal, ds.irrigation_water_gal, drip.drip_runtime_gal, (0)::double precision)) AS unaccounted_gal,
        CASE
            WHEN (ds.stress_hours_vpd_high > (0)::double precision) THEN round(((COALESCE(ds.mister_water_gal, (0)::double precision) / ds.stress_hours_vpd_high))::numeric, 1)
            ELSE NULL::numeric
        END AS gal_per_vpd_stress_hour,
    COALESCE(ipd.meter_delta_gal, ds.fertigation_water_gal, (0)::double precision) AS fertigation_gal,
    COALESCE(ds.runtime_irrigation_clean_h, drip.clean_runtime_h, (0)::double precision) AS clean_runtime_h,
    COALESCE(ds.runtime_irrigation_fert_h, drip.fert_runtime_h, (0)::double precision) AS fert_runtime_h,
    COALESCE(ds.runtime_fert_master_h, (0)::double precision) AS fert_master_runtime_h
   FROM ((public.daily_summary ds
     LEFT JOIN public.v_irrigation_program_daily ipd ON ((ipd.date = ds.date)))
     LEFT JOIN LATERAL ( SELECT ((((COALESCE(ds.runtime_drip_wall_h, (0)::double precision) + COALESCE(ds.runtime_drip_center_h, (0)::double precision)) * (60)::double precision) * (2.0)::double precision) + (((((COALESCE(ds.runtime_drip_wall_fert_h, (0)::double precision) + COALESCE(ds.runtime_drip_center_fert_h, (0)::double precision)) + COALESCE(ds.runtime_mister_south_fert_h, (0)::double precision)) + COALESCE(ds.runtime_mister_west_fert_h, (0)::double precision)) * (60)::double precision) * (2.0)::double precision)) AS drip_runtime_gal,
            ((((COALESCE(ds.runtime_drip_wall_h, (0)::double precision) + COALESCE(ds.runtime_drip_center_h, (0)::double precision)) + COALESCE(ds.runtime_mister_south_h, (0)::double precision)) + COALESCE(ds.runtime_mister_west_h, (0)::double precision)) + COALESCE(ds.runtime_mister_center_h, (0)::double precision)) AS clean_runtime_h,
            (((COALESCE(ds.runtime_drip_wall_fert_h, (0)::double precision) + COALESCE(ds.runtime_drip_center_fert_h, (0)::double precision)) + COALESCE(ds.runtime_mister_south_fert_h, (0)::double precision)) + COALESCE(ds.runtime_mister_west_fert_h, (0)::double precision)) AS fert_runtime_h) drip ON (true))
  WHERE ((ds.water_used_gal IS NOT NULL) AND (ds.water_used_gal > (0)::double precision));


ALTER VIEW public.v_water_budget OWNER TO verdify;

--
-- Name: VIEW v_water_budget; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_water_budget IS 'Daily water decomposition including equipment-derived fertigation gallons and fert/master relay runtime.';


--
-- Name: v_water_accountability; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_water_accountability AS
 SELECT date,
    total_gal,
    mister_gal,
    drip_gal,
    unaccounted_gal,
    gal_per_vpd_stress_hour,
        CASE
            WHEN (total_gal IS NULL) THEN 'missing_total'::text
            WHEN (total_gal < (0)::double precision) THEN 'negative_total'::text
            WHEN (mister_gal > (total_gal + (5)::double precision)) THEN 'mister_exceeds_total'::text
            WHEN (unaccounted_gal < ('-5'::integer)::double precision) THEN 'negative_unaccounted'::text
            WHEN (unaccounted_gal > GREATEST((25)::double precision, (total_gal * (0.25)::double precision))) THEN 'high_unaccounted'::text
            ELSE 'ok'::text
        END AS quality_flag
   FROM public.v_water_budget;


ALTER VIEW public.v_water_accountability OWNER TO verdify;

--
-- Name: VIEW v_water_accountability; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_water_accountability IS 'Water decomposition plus quality flag. Flags accounting rows that should not be used as proof without investigation.';


--
-- Name: v_data_trust_ledger; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_data_trust_ledger AS
 SELECT 'climate_freshness'::text AS check_name,
        CASE
            WHEN (v_data_pipeline_health.age_s <= 300) THEN 'ok'::text
            ELSE 'fail'::text
        END AS status,
    (v_data_pipeline_health.age_s)::numeric AS metric_value,
    (300)::numeric AS threshold_value,
    (v_data_pipeline_health.source || ' age seconds'::text) AS details
   FROM public.v_data_pipeline_health
  WHERE (v_data_pipeline_health.source = 'climate'::text)
UNION ALL
 SELECT 'forecast_freshness'::text AS check_name,
        CASE
            WHEN (v_data_pipeline_health.age_s <= 21600) THEN 'ok'::text
            ELSE 'fail'::text
        END AS status,
    (v_data_pipeline_health.age_s)::numeric AS metric_value,
    (21600)::numeric AS threshold_value,
    'weather_forecast fetched_at age seconds'::text AS details
   FROM public.v_data_pipeline_health
  WHERE (v_data_pipeline_health.source = 'forecast'::text)
UNION ALL
 SELECT 'required_sensor_coverage'::text AS check_name,
        CASE
            WHEN (count(*) FILTER (WHERE (v_required_sensor_coverage.coverage_status <> 'ok'::text)) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*) FILTER (WHERE (v_required_sensor_coverage.coverage_status <> 'ok'::text)))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'required configured sensors not ok'::text AS details
   FROM public.v_required_sensor_coverage
UNION ALL
 SELECT 'alert_lifecycle_mismatch'::text AS check_name,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'alerts with resolved_at set but disposition not resolved'::text AS details
   FROM public.alert_log
  WHERE ((alert_log.resolved_at IS NOT NULL) AND (alert_log.disposition <> 'resolved'::text))
UNION ALL
 SELECT 'open_critical_or_high_alerts'::text AS check_name,
        CASE
            WHEN (count(*) = 0) THEN 'ok'::text
            ELSE 'fail'::text
        END AS status,
    (count(*))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'open critical/high alerts'::text AS details
   FROM public.alert_log
  WHERE ((alert_log.disposition = 'open'::text) AND (alert_log.severity = ANY (ARRAY['critical'::text, 'high'::text])))
UNION ALL
 SELECT 'planner_trigger_sla_36h'::text AS check_name,
        CASE
            WHEN (v_planner_trigger_health.required_failure_count > 0) THEN 'fail'::text
            WHEN ((v_planner_trigger_health.missed_expected_count > 0) OR (v_planner_trigger_health.overdue_delivered_count > 0)) THEN 'warn'::text
            ELSE 'ok'::text
        END AS status,
    (((v_planner_trigger_health.required_failure_count + v_planner_trigger_health.missed_expected_count) + v_planner_trigger_health.overdue_delivered_count))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'unrecovered required planner trigger failures or currently overdue expected/delivered triggers in last 36h'::text AS details
   FROM public.v_planner_trigger_health
UNION ALL
 SELECT 'data_gap_hours_24h'::text AS check_name,
        CASE
            WHEN (COALESCE(sum(data_gaps.duration_s), (0)::double precision) = (0)::double precision) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    round(((COALESCE(sum(data_gaps.duration_s), (0)::double precision) / (3600.0)::double precision))::numeric, 2) AS metric_value,
    (0)::numeric AS threshold_value,
    'telemetry gap hours ending in the last 24h'::text AS details
   FROM public.data_gaps
  WHERE (data_gaps.end_ts > (now() - '24:00:00'::interval))
UNION ALL
 SELECT 'water_accounting_14d'::text AS check_name,
        CASE
            WHEN (count(*) FILTER (WHERE (v_water_accountability.quality_flag = ANY (ARRAY['missing_total'::text, 'negative_total'::text, 'mister_exceeds_total'::text, 'negative_unaccounted'::text]))) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*) FILTER (WHERE (v_water_accountability.quality_flag = ANY (ARRAY['missing_total'::text, 'negative_total'::text, 'mister_exceeds_total'::text, 'negative_unaccounted'::text]))))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'hard water-accounting failures in last 14 local days; unattributed water remains an instrumentation limitation'::text AS details
   FROM public.v_water_accountability
  WHERE (v_water_accountability.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 14))
UNION ALL
 SELECT 'irrigation_logging_14d'::text AS check_name,
        CASE
            WHEN ((expected.starts_14d = 0) OR (logged.logs_14d >= expected.starts_14d)) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (GREATEST((expected.starts_14d - logged.logs_14d), (0)::bigint))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'fertigation starts in equipment_state without canonical run rows in last 14 days'::text AS details
   FROM (( WITH ordered AS (
                 SELECT equipment_state.ts,
                    equipment_state.equipment,
                    equipment_state.state,
                    lag(equipment_state.state) OVER (PARTITION BY equipment_state.equipment ORDER BY equipment_state.ts) AS prev_state
                   FROM public.equipment_state
                  WHERE ((equipment_state.equipment = ANY (ARRAY['drip_wall_fert'::text, 'mister_south_fert'::text, 'mister_west_fert'::text, 'drip_center_fert'::text])) AND (equipment_state.ts >= (now() - '14 days'::interval)))
                )
         SELECT count(*) AS starts_14d
           FROM ordered
          WHERE ((ordered.state = true) AND (COALESCE(ordered.prev_state, false) = false))) expected
     CROSS JOIN ( SELECT count(DISTINCT v_irrigation_fertigation_runs.run_id) AS logs_14d
           FROM public.v_irrigation_fertigation_runs
          WHERE (v_irrigation_fertigation_runs.run_start >= (now() - '14 days'::interval))) logged)
UNION ALL
 SELECT 'energy_reconciliation_14d'::text AS check_name,
        CASE
            WHEN (count(*) FILTER (WHERE (v_energy_estimate_reconciliation.quality_flag <> 'ok'::text)) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*) FILTER (WHERE (v_energy_estimate_reconciliation.quality_flag <> 'ok'::text)))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'daily_summary measured kWh sync mismatches in last 14 local days'::text AS details
   FROM public.v_energy_estimate_reconciliation
  WHERE (v_energy_estimate_reconciliation.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 14))
UNION ALL
 SELECT 'forecast_action_outcomes_7d'::text AS check_name,
        CASE
            WHEN (count(*) FILTER (WHERE ((forecast_action_log.outcome IS NULL) OR (forecast_action_log.outcome = 'pending'::text))) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*) FILTER (WHERE ((forecast_action_log.outcome IS NULL) OR (forecast_action_log.outcome = 'pending'::text))))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'forecast action rows past follow-up window without evaluated outcome in last 7 days'::text AS details
   FROM public.forecast_action_log
  WHERE ((forecast_action_log.triggered_at > (now() - '7 days'::interval)) AND (forecast_action_log.triggered_at <= (now() - '06:00:00'::interval)) AND (forecast_action_log.action_taken <> 'evaluated_ok'::text))
UNION ALL
 SELECT 'crop_lifecycle_completeness'::text AS check_name,
        CASE
            WHEN (sum(v_crop_lifecycle_completeness.missing_count) FILTER (WHERE v_crop_lifecycle_completeness.is_active) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (COALESCE(sum(v_crop_lifecycle_completeness.missing_count) FILTER (WHERE v_crop_lifecycle_completeness.is_active), (0)::bigint))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'missing active crop lifecycle fields'::text AS details
   FROM public.v_crop_lifecycle_completeness
UNION ALL
 SELECT 'daily_plan_archive_self_check'::text AS check_name,
        CASE
            WHEN (count(*) FILTER (WHERE v_daily_plan_archive_self_check.stale) = 0) THEN 'ok'::text
            ELSE 'warn'::text
        END AS status,
    (count(*) FILTER (WHERE v_daily_plan_archive_self_check.stale))::numeric AS metric_value,
    (0)::numeric AS threshold_value,
    'completed generated daily plan pages stale or unaudited'::text AS details
   FROM public.v_daily_plan_archive_self_check
  WHERE ((v_daily_plan_archive_self_check.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 14)) AND (v_daily_plan_archive_self_check.date < ((now() AT TIME ZONE 'America/Denver'::text))::date));


ALTER VIEW public.v_data_trust_ledger OWNER TO verdify;

--
-- Name: VIEW v_data_trust_ledger; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_data_trust_ledger IS 'Owner-facing public health checks spanning freshness, coverage, gaps, recovered planner trigger SLA, water hard failures, canonical fertigation logging, measured energy sync, forecasts, crop completeness, and generated archives. Future instrumentation requirements are reported separately from live-system health.';


--
-- Name: v_dew_point_risk; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_dew_point_risk AS
 WITH raw AS (
         SELECT climate.ts,
            ((climate.ts AT TIME ZONE 'America/Denver'::text))::date AS local_date,
            (climate.temp_avg - climate.dew_point) AS margin_f
           FROM public.climate
          WHERE ((climate.temp_avg IS NOT NULL) AND (climate.dew_point IS NOT NULL))
        ), samples AS (
         SELECT raw.ts,
            raw.local_date,
            raw.margin_f,
            lead(raw.ts) OVER (PARTITION BY raw.local_date ORDER BY raw.ts) AS next_ts
           FROM raw
        ), durations AS (
         SELECT samples.local_date AS date,
            samples.margin_f,
            (LEAST(GREATEST(EXTRACT(epoch FROM (COALESCE(samples.next_ts, LEAST(now(), (((samples.local_date + 1))::timestamp without time zone AT TIME ZONE 'America/Denver'::text))) - samples.ts)), (0)::numeric), (300)::numeric) / 3600.0) AS hours_observed
           FROM samples
        )
 SELECT date,
    round((min(margin_f))::numeric, 1) AS min_margin_f,
    round((avg(margin_f))::numeric, 1) AS avg_margin_f,
    round(COALESCE(sum(hours_observed) FILTER (WHERE (margin_f < (5)::double precision)), (0)::numeric), 1) AS risk_hours,
    round(COALESCE(sum(hours_observed) FILTER (WHERE (margin_f < (3)::double precision)), (0)::numeric), 1) AS critical_hours
   FROM durations
  GROUP BY date
  ORDER BY date;


ALTER VIEW public.v_dew_point_risk OWNER TO verdify;

--
-- Name: VIEW v_dew_point_risk; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_dew_point_risk IS 'Indoor condensation risk by America/Denver day. Durations use observed sample intervals capped at 5 minutes, not a fixed sample cadence.';


--
-- Name: v_dif; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_dif AS
 SELECT date_trunc('day'::text, (ts AT TIME ZONE 'America/Denver'::text)) AS date,
    round((avg(
        CASE
            WHEN ((EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) >= (7)::numeric) AND (EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) <= (18)::numeric)) THEN temp_avg
            ELSE NULL::double precision
        END))::numeric, 2) AS day_avg_temp,
    round((avg(
        CASE
            WHEN ((EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) < (7)::numeric) OR (EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) > (18)::numeric)) THEN temp_avg
            ELSE NULL::double precision
        END))::numeric, 2) AS night_avg_temp,
    round(((avg(
        CASE
            WHEN ((EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) >= (7)::numeric) AND (EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) <= (18)::numeric)) THEN temp_avg
            ELSE NULL::double precision
        END) - avg(
        CASE
            WHEN ((EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) < (7)::numeric) OR (EXTRACT(hour FROM (ts AT TIME ZONE 'America/Denver'::text)) > (18)::numeric)) THEN temp_avg
            ELSE NULL::double precision
        END)))::numeric, 2) AS dif
   FROM public.climate
  WHERE (temp_avg IS NOT NULL)
  GROUP BY (date_trunc('day'::text, (ts AT TIME ZONE 'America/Denver'::text)))
  ORDER BY (date_trunc('day'::text, (ts AT TIME ZONE 'America/Denver'::text)));


ALTER VIEW public.v_dif OWNER TO verdify;

--
-- Name: v_disease_risk; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_disease_risk AS
 WITH recent AS (
         SELECT climate.ts,
            climate.rh_avg,
            climate.temp_avg,
            climate.vpd_avg
           FROM public.climate
          WHERE ((climate.ts >= (now() - '24:00:00'::interval)) AND (climate.rh_avg IS NOT NULL) AND (climate.temp_avg IS NOT NULL))
        ), botrytis_windows AS (
         SELECT recent.ts,
                CASE
                    WHEN ((recent.rh_avg > (85)::double precision) AND ((recent.temp_avg >= (60)::double precision) AND (recent.temp_avg <= (80)::double precision))) THEN 1
                    ELSE 0
                END AS botrytis_flag,
                CASE
                    WHEN (recent.vpd_avg < (0.4)::double precision) THEN 1
                    ELSE 0
                END AS condensation_flag
           FROM recent
        )
 SELECT date_trunc('hour'::text, ts) AS hour,
    round((avg(botrytis_flag) * (100)::numeric), 1) AS botrytis_risk_pct,
    round((avg(condensation_flag) * (100)::numeric), 1) AS condensation_risk_pct,
    round((((sum(botrytis_flag))::numeric * 2.0) / 60.0), 2) AS botrytis_consecutive_hours,
    round((((sum(condensation_flag))::numeric * 2.0) / 60.0), 2) AS condensation_consecutive_hours
   FROM botrytis_windows
  GROUP BY (date_trunc('hour'::text, ts))
  ORDER BY (date_trunc('hour'::text, ts));


ALTER VIEW public.v_disease_risk OWNER TO verdify;

