--
-- Name: v_estimated_dli; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_estimated_dli AS
 WITH readings AS (
         SELECT climate.ts,
            (date_trunc('day'::text, (climate.ts AT TIME ZONE 'America/Denver'::text)))::date AS date,
            ((climate.outdoor_lux * public.fn_glazing_transmission(climate.solar_azimuth_deg)) * (0.0185)::double precision) AS ppfd,
            COALESCE(EXTRACT(epoch FROM (lead(climate.ts) OVER (PARTITION BY ((date_trunc('day'::text, (climate.ts AT TIME ZONE 'America/Denver'::text)))::date) ORDER BY climate.ts) - climate.ts)), (300)::numeric) AS dt_sec
           FROM public.climate
          WHERE ((climate.outdoor_lux > (0)::double precision) AND (climate.solar_azimuth_deg IS NOT NULL) AND (climate.solar_altitude_deg > (0)::double precision))
        )
 SELECT date,
    round(((sum((ppfd * (LEAST(dt_sec, (900)::numeric))::double precision)) / (1000000)::double precision))::numeric, 1) AS est_natural_dli,
    count(*) AS readings
   FROM readings
  WHERE ((dt_sec > (0)::numeric) AND (dt_sec < (900)::numeric))
  GROUP BY date
  ORDER BY date;


ALTER VIEW public.v_estimated_dli OWNER TO verdify;

--
-- Name: v_estimated_indoor_light; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_estimated_indoor_light AS
 SELECT public.time_bucket('00:15:00'::interval, ts) AS bucket,
    round((avg((outdoor_lux * public.fn_glazing_transmission(solar_azimuth_deg))))::numeric, 0) AS est_indoor_lux,
    round((avg(((outdoor_lux * public.fn_glazing_transmission(solar_azimuth_deg)) * (0.0185)::double precision)))::numeric, 1) AS est_ppfd,
    round((avg(solar_altitude_deg))::numeric, 1) AS sun_altitude,
    round((avg(outdoor_lux))::numeric, 0) AS outdoor_lux,
    round((avg((public.fn_glazing_transmission(solar_azimuth_deg) * (100)::double precision)))::numeric, 1) AS transmission_pct
   FROM public.climate
  WHERE ((outdoor_lux > (0)::double precision) AND (solar_azimuth_deg IS NOT NULL) AND (solar_altitude_deg > (0)::double precision))
  GROUP BY (public.time_bucket('00:15:00'::interval, ts))
  ORDER BY (public.time_bucket('00:15:00'::interval, ts));


ALTER VIEW public.v_estimated_indoor_light OWNER TO verdify;

--
-- Name: v_estimated_plant_dli; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_estimated_plant_dli AS
 SELECT date,
    round((COALESCE(dli_final, (0)::double precision))::numeric, 1) AS sensor_dli,
    round(((COALESCE(dli_final, (0)::double precision) * (3.5)::double precision))::numeric, 1) AS corrected_solar_dli,
    round(((COALESCE(runtime_grow_light_min, (0)::double precision) / (60.0)::double precision))::numeric, 1) AS grow_light_hours,
    round((((COALESCE(runtime_grow_light_min, (0)::double precision) / (60.0)::double precision) * (0.8)::double precision))::numeric, 1) AS grow_light_dli,
    round((((COALESCE(dli_final, (0)::double precision) * (3.5)::double precision) + ((COALESCE(runtime_grow_light_min, (0)::double precision) / (60.0)::double precision) * (0.8)::double precision)))::numeric, 1) AS estimated_plant_dli,
        CASE
            WHEN (((COALESCE(dli_final, (0)::double precision) * (3.5)::double precision) + ((COALESCE(runtime_grow_light_min, (0)::double precision) / (60.0)::double precision) * (0.8)::double precision)) < (12)::double precision) THEN 'LOW'::text
            WHEN (((COALESCE(dli_final, (0)::double precision) * (3.5)::double precision) + ((COALESCE(runtime_grow_light_min, (0)::double precision) / (60.0)::double precision) * (0.8)::double precision)) > (30)::double precision) THEN 'HIGH'::text
            ELSE 'OK'::text
        END AS dli_status
   FROM public.daily_summary ds
  ORDER BY date DESC;


ALTER VIEW public.v_estimated_plant_dli OWNER TO verdify;

--
-- Name: VIEW v_estimated_plant_dli; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_estimated_plant_dli IS 'Estimated actual plant DLI: sensor × 3.5 correction + grow light hours × 0.8 mol/hr. LOW<12, OK=12-30, HIGH>30.';


--
-- Name: v_exterior_vpd; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_exterior_vpd AS
 SELECT ts,
        CASE
            WHEN ((outdoor_temp_f IS NOT NULL) AND (outdoor_rh_pct IS NOT NULL)) THEN round(((((0.6108)::double precision * exp((((17.27)::double precision * (((outdoor_temp_f - (32)::double precision) * (5.0)::double precision) / (9.0)::double precision)) / ((((outdoor_temp_f - (32)::double precision) * (5.0)::double precision) / (9.0)::double precision) + (237.3)::double precision)))) * ((1)::double precision - (outdoor_rh_pct / (100.0)::double precision))))::numeric, 3)
            ELSE NULL::numeric
        END AS exterior_vpd_kpa
   FROM public.climate
  WHERE (outdoor_temp_f IS NOT NULL);


ALTER VIEW public.v_exterior_vpd OWNER TO verdify;

--
-- Name: v_fan_balance_7d; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_fan_balance_7d AS
 WITH bounds AS (
         SELECT (now() - '7 days'::interval) AS start_ts,
            now() AS end_ts
        ), fan_set AS (
         SELECT DISTINCT es.greenhouse_id,
            es.equipment
           FROM public.equipment_state es
          WHERE (es.equipment = ANY (ARRAY['fan1'::text, 'fan2'::text]))
        ), seed AS (
         SELECT DISTINCT ON (fs.greenhouse_id, fs.equipment) fs.greenhouse_id,
            fs.equipment,
            b_1.start_ts AS ts,
            COALESCE(es.state, false) AS state
           FROM ((fan_set fs
             CROSS JOIN bounds b_1)
             LEFT JOIN public.equipment_state es ON (((es.greenhouse_id = fs.greenhouse_id) AND (es.equipment = fs.equipment) AND (es.ts <= b_1.start_ts))))
          ORDER BY fs.greenhouse_id, fs.equipment, es.ts DESC NULLS LAST
        ), events AS (
         SELECT seed.greenhouse_id,
            seed.equipment,
            seed.ts,
            seed.state
           FROM seed
        UNION ALL
         SELECT es.greenhouse_id,
            es.equipment,
            es.ts,
            es.state
           FROM (public.equipment_state es
             CROSS JOIN bounds b_1)
          WHERE ((es.equipment = ANY (ARRAY['fan1'::text, 'fan2'::text])) AND (es.ts > b_1.start_ts) AND (es.ts <= b_1.end_ts))
        ), ordered AS (
         SELECT e.greenhouse_id,
            e.equipment,
            e.ts,
            e.state,
            lag(e.state) OVER (PARTITION BY e.greenhouse_id, e.equipment ORDER BY e.ts) AS prev_state,
            lead(e.ts) OVER (PARTITION BY e.greenhouse_id, e.equipment ORDER BY e.ts) AS next_ts
           FROM events e
        ), rollup AS (
         SELECT o.greenhouse_id,
            o.equipment,
            sum((EXTRACT(epoch FROM (LEAST(COALESCE(o.next_ts, b_1.end_ts), b_1.end_ts) - GREATEST(o.ts, b_1.start_ts))) / 60.0)) FILTER (WHERE (o.state IS TRUE)) AS on_minutes,
            count(*) FILTER (WHERE ((o.state IS TRUE) AND (COALESCE(o.prev_state, false) IS FALSE) AND (o.ts > b_1.start_ts))) AS cycles
           FROM (ordered o
             CROSS JOIN bounds b_1)
          WHERE ((o.ts < b_1.end_ts) AND (COALESCE(o.next_ts, b_1.end_ts) > b_1.start_ts))
          GROUP BY o.greenhouse_id, o.equipment
        )
 SELECT COALESCE(f1.greenhouse_id, f2.greenhouse_id) AS greenhouse_id,
    b.start_ts AS window_start,
    b.end_ts AS window_end,
    round(COALESCE(f1.on_minutes, (0)::numeric), 1) AS fan1_minutes,
    round(COALESCE(f2.on_minutes, (0)::numeric), 1) AS fan2_minutes,
    COALESCE(f1.cycles, (0)::bigint) AS fan1_cycles,
    COALESCE(f2.cycles, (0)::bigint) AS fan2_cycles,
    round(abs((COALESCE(f1.on_minutes, (0)::numeric) - COALESCE(f2.on_minutes, (0)::numeric))), 1) AS imbalance_minutes,
    round(((100.0 * abs((COALESCE(f1.on_minutes, (0)::numeric) - COALESCE(f2.on_minutes, (0)::numeric)))) / NULLIF(GREATEST(COALESCE(f1.on_minutes, (0)::numeric), COALESCE(f2.on_minutes, (0)::numeric)), (0)::numeric)), 1) AS imbalance_pct,
        CASE
            WHEN (COALESCE(f1.on_minutes, (0)::numeric) <= COALESCE(f2.on_minutes, (0)::numeric)) THEN 'fan1'::text
            ELSE 'fan2'::text
        END AS lower_runtime_fan,
    (abs((COALESCE(f1.on_minutes, (0)::numeric) - COALESCE(f2.on_minutes, (0)::numeric))) > 10.0) AS rebalance_needed
   FROM ((bounds b
     LEFT JOIN rollup f1 ON ((f1.equipment = 'fan1'::text)))
     LEFT JOIN rollup f2 ON (((f2.equipment = 'fan2'::text) AND (f2.greenhouse_id = f1.greenhouse_id))));


ALTER VIEW public.v_fan_balance_7d OWNER TO verdify;

--
-- Name: VIEW v_fan_balance_7d; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_fan_balance_7d IS 'Rolling seven-day fan runtime/cycle balance from equipment_state, clipped at the exact window bounds. Used to audit runtime-aware lead selection.';


--
-- Name: v_forecast_accuracy; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_accuracy AS
 WITH forecast_deduped AS (
         SELECT DISTINCT ON (f_1.ts) f_1.ts,
            f_1.fetched_at,
            f_1.temp_f,
            f_1.vpd_kpa,
            f_1.solar_w_m2
           FROM public.weather_forecast f_1
          WHERE ((f_1.ts < now()) AND (f_1.fetched_at <= f_1.ts))
          ORDER BY f_1.ts, f_1.fetched_at DESC
        )
 SELECT f.ts AS forecast_hour,
    f.fetched_at,
    round((EXTRACT(epoch FROM (f.ts - f.fetched_at)) / 3600.0), 1) AS lead_hours,
    f.temp_f AS forecast_temp,
    m.outdoor_temp_f AS actual_temp,
    round(((f.temp_f - m.outdoor_temp_f))::numeric, 1) AS temp_error_f,
    f.vpd_kpa AS forecast_vpd,
    m.vpd_avg AS actual_vpd,
    round(((f.vpd_kpa - m.vpd_avg))::numeric, 2) AS vpd_error_kpa,
    f.solar_w_m2 AS forecast_solar,
    m.solar_w_m2 AS actual_solar,
    round(((f.solar_w_m2 - m.solar_w_m2))::numeric, 1) AS solar_error_w
   FROM (forecast_deduped f
     JOIN public.v_climate_merged m ON ((public.time_bucket('01:00:00'::interval, m.bucket) = f.ts)));


ALTER VIEW public.v_forecast_accuracy OWNER TO verdify;

--
-- Name: VIEW v_forecast_accuracy; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_accuracy IS 'Forecast vs observed comparison using the latest forecast fetched before the observed hour. lead_hours is non-negative planning lead time.';


--
-- Name: v_forecast_accuracy_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_accuracy_daily AS
 WITH forecast_deduped AS (
         SELECT DISTINCT ON (f_1.ts) f_1.ts,
            f_1.fetched_at,
            f_1.temp_f,
            f_1.rh_pct,
            f_1.cloud_cover_pct
           FROM public.weather_forecast f_1
          WHERE ((f_1.ts >= (now() - '14 days'::interval)) AND (f_1.ts <= now()) AND (f_1.fetched_at <= f_1.ts))
          ORDER BY f_1.ts, f_1.fetched_at DESC
        ), forecast_daily AS (
         SELECT ((forecast_deduped.ts AT TIME ZONE 'America/Denver'::text))::date AS date,
            avg(forecast_deduped.temp_f) AS fc_temp_avg,
            avg(forecast_deduped.rh_pct) AS fc_rh_avg,
            avg(forecast_deduped.cloud_cover_pct) AS fc_cloud_avg,
            avg((EXTRACT(epoch FROM (forecast_deduped.ts - forecast_deduped.fetched_at)) / 3600.0)) AS horizon_hours
           FROM forecast_deduped
          GROUP BY (((forecast_deduped.ts AT TIME ZONE 'America/Denver'::text))::date)
        ), observed_daily AS (
         SELECT ((climate.ts AT TIME ZONE 'America/Denver'::text))::date AS date,
            avg(climate.outdoor_temp_f) AS obs_temp_avg,
            avg(climate.outdoor_rh_pct) AS obs_rh_avg
           FROM public.climate
          WHERE ((climate.ts >= (now() - '14 days'::interval)) AND (climate.ts <= now()))
          GROUP BY (((climate.ts AT TIME ZONE 'America/Denver'::text))::date)
        )
 SELECT f.date,
    p.param,
        CASE p.param
            WHEN 'temp_f'::text THEN f.fc_temp_avg
            WHEN 'rh_pct'::text THEN f.fc_rh_avg
            WHEN 'cloud_cover_pct'::text THEN f.fc_cloud_avg
            ELSE NULL::double precision
        END AS forecast_avg,
        CASE p.param
            WHEN 'temp_f'::text THEN o.obs_temp_avg
            WHEN 'rh_pct'::text THEN o.obs_rh_avg
            WHEN 'cloud_cover_pct'::text THEN NULL::double precision
            ELSE NULL::double precision
        END AS observed_avg,
        CASE p.param
            WHEN 'temp_f'::text THEN (f.fc_temp_avg - o.obs_temp_avg)
            WHEN 'rh_pct'::text THEN (f.fc_rh_avg - o.obs_rh_avg)
            WHEN 'cloud_cover_pct'::text THEN NULL::double precision
            ELSE NULL::double precision
        END AS bias,
        CASE p.param
            WHEN 'temp_f'::text THEN abs((f.fc_temp_avg - o.obs_temp_avg))
            WHEN 'rh_pct'::text THEN abs((f.fc_rh_avg - o.obs_rh_avg))
            WHEN 'cloud_cover_pct'::text THEN NULL::double precision
            ELSE NULL::double precision
        END AS abs_error,
    round(f.horizon_hours, 1) AS horizon_hours
   FROM ((forecast_daily f
     JOIN observed_daily o USING (date))
     CROSS JOIN ( VALUES ('temp_f'::text), ('rh_pct'::text), ('cloud_cover_pct'::text)) p(param))
  ORDER BY f.date DESC, p.param;


ALTER VIEW public.v_forecast_accuracy_daily OWNER TO verdify;

--
-- Name: VIEW v_forecast_accuracy_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_accuracy_daily IS 'Daily forecast-vs-observed bias/MAE using only forecasts fetched before the observed hour.';


--
-- Name: v_forecast_accuracy_lead_buckets; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_accuracy_lead_buckets AS
 WITH paired AS (
         SELECT ((f.ts AT TIME ZONE 'America/Denver'::text))::date AS date,
                CASE
                    WHEN ((EXTRACT(epoch FROM (f.ts - f.fetched_at)) / 3600.0) < (6)::numeric) THEN '00-06h'::text
                    WHEN ((EXTRACT(epoch FROM (f.ts - f.fetched_at)) / 3600.0) < (24)::numeric) THEN '06-24h'::text
                    WHEN ((EXTRACT(epoch FROM (f.ts - f.fetched_at)) / 3600.0) < (48)::numeric) THEN '24-48h'::text
                    ELSE '48h+'::text
                END AS lead_bucket,
            (f.temp_f - m.outdoor_temp_f) AS temp_error_f,
            (f.vpd_kpa - m.vpd_avg) AS vpd_error_kpa,
            (f.solar_w_m2 - m.solar_w_m2) AS solar_error_w
           FROM (public.weather_forecast f
             JOIN public.v_climate_merged m ON ((public.time_bucket('01:00:00'::interval, m.bucket) = f.ts)))
          WHERE ((f.ts < now()) AND (f.ts >= (now() - '30 days'::interval)) AND (f.fetched_at <= f.ts))
        )
 SELECT paired.date,
    paired.lead_bucket,
    'temp_f'::text AS param,
    count(paired.temp_error_f) AS samples,
    round((avg(paired.temp_error_f))::numeric, 2) AS bias,
    round((avg(abs(paired.temp_error_f)))::numeric, 2) AS mae
   FROM paired
  WHERE (paired.temp_error_f IS NOT NULL)
  GROUP BY paired.date, paired.lead_bucket
UNION ALL
 SELECT paired.date,
    paired.lead_bucket,
    'vpd_kpa'::text AS param,
    count(paired.vpd_error_kpa) AS samples,
    round((avg(paired.vpd_error_kpa))::numeric, 3) AS bias,
    round((avg(abs(paired.vpd_error_kpa)))::numeric, 3) AS mae
   FROM paired
  WHERE (paired.vpd_error_kpa IS NOT NULL)
  GROUP BY paired.date, paired.lead_bucket
UNION ALL
 SELECT paired.date,
    paired.lead_bucket,
    'solar_w_m2'::text AS param,
    count(paired.solar_error_w) AS samples,
    round((avg(paired.solar_error_w))::numeric, 1) AS bias,
    round((avg(abs(paired.solar_error_w)))::numeric, 1) AS mae
   FROM paired
  WHERE (paired.solar_error_w IS NOT NULL)
  GROUP BY paired.date, paired.lead_bucket;


ALTER VIEW public.v_forecast_accuracy_lead_buckets OWNER TO verdify;

--
-- Name: VIEW v_forecast_accuracy_lead_buckets; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_accuracy_lead_buckets IS 'Forecast accuracy by local day and fixed lead-time bucket. Uses all forecasts fetched before each observed hour.';


--
-- Name: v_forecast_action_outcomes; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_action_outcomes AS
 SELECT fl.id,
    fl.rule_name,
    fl.triggered_at,
    fl.action_taken,
    fl.plan_id,
    fl.param,
    fl.old_value,
    fl.new_value,
    COALESCE(fl.outcome, 'pending'::text) AS outcome,
    fl.outcome_evaluated_at,
    fl.outcome_metrics,
    ds.date AS outcome_date,
    ds.compliance_pct,
    ds.stress_hours_heat,
    ds.stress_hours_vpd_high,
    ds.water_used_gal,
    ds.cost_total
   FROM (public.forecast_action_log fl
     LEFT JOIN public.daily_summary ds ON ((ds.date = ((fl.triggered_at AT TIME ZONE 'America/Denver'::text))::date)));


ALTER VIEW public.v_forecast_action_outcomes OWNER TO verdify;

--
-- Name: VIEW v_forecast_action_outcomes; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_action_outcomes IS 'Forecast action log joined to later climate/day outcomes. Historical rows are backfilled with coarse stress-window outcomes.';


--
-- Name: v_forecast_actions_recent; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_actions_recent AS
 SELECT (triggered_at AT TIME ZONE 'America/Denver'::text) AS triggered,
    rule_name,
    action_taken,
    param,
    old_value,
    new_value,
    plan_id,
    (forecast_condition ->> 'trigger_value'::text) AS trigger_value,
    (forecast_condition ->> 'trigger_hour'::text) AS trigger_hour,
    outcome
   FROM public.forecast_action_log fl
  WHERE (triggered_at > (now() - '7 days'::interval))
  ORDER BY triggered_at DESC;


