    solar_w_m2,
    dew_point_f,
    feels_like_f,
    vpd_kpa,
    precip_in,
    rain_in,
    snow_in,
    wind_gust_mph,
    uv_index,
    et0_mm,
    direct_radiation_w_m2,
    diffuse_radiation_w_m2,
    sunshine_duration_s,
    weather_code,
    cloud_cover_low_pct,
    cloud_cover_high_pct,
    surface_pressure_hpa,
    soil_temp_f,
    visibility_m
   FROM public.weather_forecast
  WHERE (ts > (now() - '24:00:00'::interval))
