-- Name: VIEW v_forecast_latest; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_latest IS 'Most recent forecast for each hour. Use instead of weather_forecast directly.';


--
-- Name: v_plan_tactical_outcome_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_tactical_outcome_daily AS
 SELECT sp.plan_id,
    ((min(sp.created_at) AT TIME ZONE 'America/Denver'::text))::date AS plan_date,
    sp.parameter,
    count(*) AS waypoints,
    round((avg(sp.value))::numeric, 3) AS avg_value,
    round((min(sp.value))::numeric, 3) AS min_value,
    round((max(sp.value))::numeric, 3) AS max_value,
    ds.compliance_pct,
    ds.temp_compliance_pct,
    ds.vpd_compliance_pct,
    ds.stress_hours_heat,
    ds.stress_hours_vpd_high,
    ds.stress_hours_cold,
    ds.stress_hours_vpd_low,
    ds.water_used_gal,
    ds.mister_water_gal,
    ds.cost_total
   FROM (public.setpoint_plan sp
     LEFT JOIN public.daily_summary ds ON ((ds.date = ((sp.ts AT TIME ZONE 'America/Denver'::text))::date)))
  WHERE (sp.parameter = ANY (ARRAY['d_cool_stage_2'::text, 'dwell_gate_ms'::text, 'enthalpy_close'::text, 'enthalpy_open'::text, 'fog_escalation_kpa'::text, 'heat_hysteresis'::text, 'min_fog_off_s'::text, 'min_fog_on_s'::text, 'mist_backoff_s'::text, 'mist_max_closed_vent_s'::text, 'mist_thermal_relief_s'::text, 'mister_all_delay_s'::text, 'mister_all_kpa'::text, 'mister_engage_delay_s'::text, 'mister_engage_kpa'::text, 'mister_pulse_gap_s'::text, 'mister_pulse_on_s'::text, 'mister_vpd_weight'::text, 'mister_water_budget_gal'::text, 'outdoor_staleness_max_s'::text, 'sw_dwell_gate_enabled'::text, 'sw_fog_closes_vent'::text, 'sw_mister_closes_vent'::text, 'sw_summer_vent_enabled'::text, 'temp_hysteresis'::text, 'vent_prefer_dp_delta_f'::text, 'vent_prefer_temp_delta_f'::text, 'vpd_hysteresis'::text, 'vpd_watch_dwell_s'::text]))
  GROUP BY sp.plan_id, sp.parameter, ds.date, ds.compliance_pct, ds.temp_compliance_pct, ds.vpd_compliance_pct, ds.stress_hours_heat, ds.stress_hours_vpd_high, ds.stress_hours_cold, ds.stress_hours_vpd_low, ds.water_used_gal, ds.mister_water_gal, ds.cost_total;


ALTER VIEW public.v_plan_tactical_outcome_daily OWNER TO verdify;

--
-- Name: VIEW v_plan_tactical_outcome_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_tactical_outcome_daily IS 'Planner Tier 1 tactical parameter posture joined to same-day compliance, stress, water, and cost outcomes. Directional, not causal.';


--
-- Name: v_forecast_plan_outcome_mart; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_plan_outcome_mart AS
 WITH plan_days AS (
         SELECT pj.plan_id,
            ((pj.created_at AT TIME ZONE 'America/Denver'::text))::date AS date,
            pj.created_at,
            pj.hypothesis,
            pj.experiment,
            pj.expected_outcome,
            pj.actual_outcome,
            pj.outcome_score,
            pj.validated_at,
            pj.planner_instance,
            pj.trigger_id
           FROM public.plan_journal pj
          WHERE (pj.plan_id !~~ 'iris-reactive%'::text)
        ), forecast_day AS (
         SELECT v_forecast_accuracy_lead_buckets.date,
            avg(v_forecast_accuracy_lead_buckets.mae) FILTER (WHERE (v_forecast_accuracy_lead_buckets.param = 'temp_f'::text)) AS temp_mae_f,
            avg(v_forecast_accuracy_lead_buckets.mae) FILTER (WHERE (v_forecast_accuracy_lead_buckets.param = 'vpd_kpa'::text)) AS vpd_mae_kpa,
            avg(v_forecast_accuracy_lead_buckets.mae) FILTER (WHERE (v_forecast_accuracy_lead_buckets.param = 'solar_w_m2'::text)) AS solar_mae_w
           FROM public.v_forecast_accuracy_lead_buckets
          GROUP BY v_forecast_accuracy_lead_buckets.date
        ), plan_posture AS (
         SELECT v_plan_tactical_outcome_daily.plan_id,
            jsonb_object_agg(v_plan_tactical_outcome_daily.parameter, v_plan_tactical_outcome_daily.avg_value) AS avg_tunables
           FROM public.v_plan_tactical_outcome_daily
          GROUP BY v_plan_tactical_outcome_daily.plan_id
        )
 SELECT pd.plan_id,
    pd.date,
    pd.created_at,
    pd.planner_instance,
    pd.trigger_id,
    fd.temp_mae_f,
    fd.vpd_mae_kpa,
    fd.solar_mae_w,
    pp.avg_tunables,
    ds.compliance_pct,
    ds.temp_compliance_pct,
    ds.vpd_compliance_pct,
    ds.stress_hours_heat,
    ds.stress_hours_vpd_high,
    ds.stress_hours_cold,
    ds.stress_hours_vpd_low,
    ds.water_used_gal,
    ds.mister_water_gal,
    COALESCE(ds.kwh_total, ds.kwh_estimated) AS kwh,
    ds.therms_estimated,
    ds.cost_total,
    pd.hypothesis,
    pd.experiment,
    pd.expected_outcome,
    pd.actual_outcome,
    pd.outcome_score,
    pd.validated_at
   FROM (((plan_days pd
     LEFT JOIN public.daily_summary ds ON ((ds.date = pd.date)))
     LEFT JOIN forecast_day fd ON ((fd.date = pd.date)))
     LEFT JOIN plan_posture pp ON ((pp.plan_id = pd.plan_id)));


ALTER VIEW public.v_forecast_plan_outcome_mart OWNER TO verdify;

--
-- Name: VIEW v_forecast_plan_outcome_mart; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_plan_outcome_mart IS 'Forecast regime, Iris tactical posture, measured climate/resource outcome, and plan evaluation in one story mart.';


--
-- Name: v_forecast_vs_actual; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_forecast_vs_actual AS
 SELECT DISTINCT ON (f.ts) f.ts AS hour,
    round((f.temp_f)::numeric, 1) AS forecast_temp,
    round((f.rh_pct)::numeric, 0) AS forecast_rh,
    round((f.vpd_kpa)::numeric, 2) AS forecast_vpd,
    round((f.solar_w_m2)::numeric, 0) AS forecast_solar,
    round((c.outdoor_temp)::numeric, 1) AS actual_temp,
    round((c.outdoor_rh)::numeric, 0) AS actual_rh,
    round((c.solar)::numeric, 0) AS actual_solar,
    round(((f.temp_f - c.outdoor_temp))::numeric, 1) AS temp_error,
    round(((f.solar_w_m2 - c.solar))::numeric, 0) AS solar_error
   FROM (public.weather_forecast f
     LEFT JOIN LATERAL ( SELECT avg(climate.outdoor_temp_f) AS outdoor_temp,
            avg(climate.outdoor_rh_pct) AS outdoor_rh,
            avg(climate.solar_irradiance_w_m2) AS solar
           FROM public.climate
          WHERE ((climate.ts >= f.ts) AND (climate.ts < (f.ts + '01:00:00'::interval)) AND (climate.outdoor_temp_f IS NOT NULL))) c ON (true))
  WHERE ((f.ts < now()) AND (f.ts > (now() - '7 days'::interval)))
  ORDER BY f.ts, f.fetched_at DESC;


ALTER VIEW public.v_forecast_vs_actual OWNER TO verdify;

--
-- Name: VIEW v_forecast_vs_actual; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_forecast_vs_actual IS 'Hourly Open-Meteo forecast vs actual outdoor conditions. temp_error/solar_error show systematic forecast bias.';


--
-- Name: v_gdd; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_gdd AS
 WITH daily_temps AS (
         SELECT date_trunc('day'::text, climate.ts) AS date,
            avg(climate.temp_avg) AS avg_temp_f
           FROM public.climate
          WHERE (climate.temp_avg IS NOT NULL)
          GROUP BY (date_trunc('day'::text, climate.ts))
        )
 SELECT c.id AS crop_id,
    c.name,
    c."position",
    dt.date,
    GREATEST((0)::double precision, (dt.avg_temp_f - c.base_temp_f)) AS gdd_day,
    sum(GREATEST((0)::double precision, (dt.avg_temp_f - c.base_temp_f))) OVER (PARTITION BY c.id ORDER BY dt.date ROWS UNBOUNDED PRECEDING) AS gdd_cumulative
   FROM (public.crops c
     JOIN daily_temps dt ON ((dt.date >= (c.planted_date)::timestamp with time zone)))
  WHERE (c.is_active = true)
  ORDER BY c.id, dt.date;


ALTER VIEW public.v_gdd OWNER TO verdify;

--
-- Name: v_gpu_power_latest; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_gpu_power_latest AS
 WITH latest AS (
         SELECT DISTINCT ON (gpu_power.greenhouse_id, gpu_power.host, gpu_power.gpu) gpu_power.ts,
            gpu_power.host,
            gpu_power.vm_name,
            gpu_power.purpose,
            gpu_power.gpu,
            gpu_power.device,
            gpu_power.model_name,
            gpu_power.watts,
            gpu_power.gpu_util_pct,
            gpu_power.temperature_c,
            gpu_power.memory_used_mb,
            gpu_power.memory_free_mb,
            gpu_power.source,
            gpu_power.raw,
            gpu_power.greenhouse_id
           FROM public.gpu_power
          ORDER BY gpu_power.greenhouse_id, gpu_power.host, gpu_power.gpu, gpu_power.ts DESC
        )
 SELECT ts,
    host,
    vm_name,
    purpose,
    gpu,
    device,
    model_name,
    watts,
    gpu_util_pct,
    temperature_c,
    memory_used_mb,
    memory_free_mb,
    source,
    raw,
    greenhouse_id,
    (EXTRACT(epoch FROM (now() - ts)))::integer AS age_s
   FROM latest;


ALTER VIEW public.v_gpu_power_latest OWNER TO verdify;

--
-- Name: v_greenhouse_id_default_audit; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_greenhouse_id_default_audit AS
 SELECT c.table_name,
    c.column_default,
    c.is_nullable,
    (c.column_default IS NOT NULL) AS has_default,
    ((c.column_default)::text = '''vallery''::text'::text) AS uses_single_site_default
   FROM (information_schema.columns c
     JOIN information_schema.tables t ON ((((t.table_schema)::name = (c.table_schema)::name) AND ((t.table_name)::name = (c.table_name)::name))))
  WHERE (((c.table_schema)::name = 'public'::name) AND ((t.table_type)::text = 'BASE TABLE'::text) AND ((c.column_name)::name = 'greenhouse_id'::name))
  ORDER BY c.table_name;


ALTER VIEW public.v_greenhouse_id_default_audit OWNER TO verdify;

--
-- Name: v_greenhouse_now; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_greenhouse_now AS
 SELECT c.ts,
    round((c.temp_avg)::numeric, 1) AS temp_avg,
    round((c.temp_north)::numeric, 1) AS temp_north,
    round((c.temp_south)::numeric, 1) AS temp_south,
    round((c.temp_east)::numeric, 1) AS temp_east,
    round((c.temp_west)::numeric, 1) AS temp_west,
    round((c.rh_avg)::numeric, 1) AS rh_avg,
    round((c.vpd_avg)::numeric, 2) AS vpd_avg,
    round((c.co2_ppm)::numeric, 0) AS co2_ppm,
    round((c.lux)::numeric, 0) AS lux,
    round((c.dli_today)::numeric, 2) AS dli_today,
    o.outdoor_temp_f,
    o.outdoor_rh_pct,
    o.wind_mph,
    o.pressure_hpa,
    round((c.mister_water_today)::numeric, 1) AS mister_water_today,
    h.hydro_ph,
    h.hydro_ec_us_cm,
    h.hydro_tds_ppm,
    h.hydro_water_temp_f,
    d.wifi_rssi,
    round((d.heap_bytes)::numeric, 0) AS heap_kb,
    round((d.uptime_s)::numeric, 0) AS uptime_s,
    ( SELECT system_state.value
           FROM public.system_state
          WHERE (system_state.entity = 'greenhouse_state'::text)
          ORDER BY system_state.ts DESC
         LIMIT 1) AS state,
    ( SELECT system_state.value
           FROM public.system_state
          WHERE (system_state.entity = 'lead_fan'::text)
          ORDER BY system_state.ts DESC
         LIMIT 1) AS lead_fan,
    public.fn_system_health() AS health_score,
    ( SELECT count(*) AS count
           FROM public.alert_log
          WHERE (alert_log.disposition = 'open'::text)) AS open_alerts,
    cost.cost_electric,
    cost.cost_gas,
    cost.cost_water,
    cost.cost_total
   FROM ((((public.climate c
     LEFT JOIN LATERAL ( SELECT diagnostics.wifi_rssi,
            diagnostics.heap_bytes,
            diagnostics.uptime_s
           FROM public.diagnostics
          ORDER BY diagnostics.ts DESC
         LIMIT 1) d ON (true))
     LEFT JOIN LATERAL ( SELECT round((climate.outdoor_temp_f)::numeric, 1) AS outdoor_temp_f,
            round((climate.outdoor_rh_pct)::numeric, 0) AS outdoor_rh_pct,
            round((climate.wind_speed_mph)::numeric, 1) AS wind_mph,
            round((climate.pressure_hpa)::numeric, 1) AS pressure_hpa
           FROM public.climate
          WHERE ((climate.outdoor_temp_f IS NOT NULL) AND (climate.ts > (now() - '00:30:00'::interval)))
          ORDER BY climate.ts DESC
         LIMIT 1) o ON (true))
     LEFT JOIN LATERAL ( SELECT round((climate.hydro_ph)::numeric, 1) AS hydro_ph,
            round((climate.hydro_ec_us_cm)::numeric, 0) AS hydro_ec_us_cm,
            round((climate.hydro_tds_ppm)::numeric, 0) AS hydro_tds_ppm,
            round((climate.hydro_water_temp_f)::numeric, 1) AS hydro_water_temp_f
           FROM public.climate
          WHERE ((climate.hydro_ph IS NOT NULL) AND (climate.ts > (now() - '00:30:00'::interval)))
          ORDER BY climate.ts DESC
         LIMIT 1) h ON (true))
     CROSS JOIN public.v_cost_today cost)
  WHERE (c.temp_avg IS NOT NULL)
  ORDER BY c.ts DESC
 LIMIT 1;


ALTER VIEW public.v_greenhouse_now OWNER TO verdify;

--
-- Name: v_greenhouse_state; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_greenhouse_state AS
 WITH state_base AS (
         SELECT c.ts,
            c.temp_avg,
            c.vpd_avg,
            c.rh_avg,
            c.dew_point,
            c.temp_north,
            c.temp_south,
            c.temp_east,
            c.temp_west,
            c.vpd_south,
            c.vpd_west,
            c.vpd_east,
            c.lux,
            c.solar_irradiance_w_m2,
            c.dli_today,
            c.co2_ppm,
            c.abs_humidity,
            c.enthalpy_delta,
            c.outdoor_temp_f,
            c.outdoor_rh_pct,
            round(((c.temp_avg - COALESCE(c.dew_point, (c.temp_avg - (10)::double precision))))::numeric, 1) AS dp_margin_f,
            public.fn_equip_at('fan1'::text, c.ts) AS fan1,
            public.fn_equip_at('fan2'::text, c.ts) AS fan2,
            public.fn_equip_at('vent'::text, c.ts) AS vent,
            public.fn_equip_at('fog'::text, c.ts) AS fog,
            public.fn_equip_at('heat1'::text, c.ts) AS heat1,
            public.fn_equip_at('heat2'::text, c.ts) AS heat2,
            public.fn_equip_at('mister_south'::text, c.ts) AS mist_south,
            public.fn_equip_at('mister_west'::text, c.ts) AS mist_west,
            public.fn_equip_at('mister_center'::text, c.ts) AS mist_center,
            public.fn_setpoint_at('temp_high'::text, c.ts) AS sp_temp_high,
            public.fn_setpoint_at('temp_low'::text, c.ts) AS sp_temp_low,
            public.fn_setpoint_at('vpd_high'::text, c.ts) AS sp_vpd_high,
            public.fn_setpoint_at('vpd_low'::text, c.ts) AS sp_vpd_low,
            public.fn_setpoint_at('bias_cool'::text, c.ts) AS sp_bias_cool,
            public.fn_setpoint_at('bias_heat'::text, c.ts) AS sp_bias_heat,
            public.fn_setpoint_at('vpd_hysteresis'::text, c.ts) AS sp_vpd_hysteresis,
            public.fn_setpoint_at('mist_max_closed_vent_s'::text, c.ts) AS sp_sealed_max_s,
            public.fn_setpoint_at('mist_thermal_relief_s'::text, c.ts) AS sp_relief_s,
            public.fn_setpoint_at('vpd_watch_dwell_s'::text, c.ts) AS sp_watch_dwell_s,
            public.fn_setpoint_at('d_cool_stage_2'::text, c.ts) AS sp_d_cool_s2,
            public.fn_setpoint_at('mister_engage_kpa'::text, c.ts) AS sp_mister_engage,
                CASE
                    WHEN ((c.temp_avg >= COALESCE(public.fn_setpoint_at('temp_low'::text, c.ts), (58)::double precision)) AND (c.temp_avg <= COALESCE(public.fn_setpoint_at('temp_high'::text, c.ts), (82)::double precision))) THEN true
                    ELSE false
                END AS temp_in_band,
                CASE
                    WHEN ((c.vpd_avg >= COALESCE(public.fn_setpoint_at('vpd_low'::text, c.ts), (0.5)::double precision)) AND (c.vpd_avg <= COALESCE(public.fn_setpoint_at('vpd_high'::text, c.ts), (1.5)::double precision))) THEN true
                    ELSE false
                END AS vpd_in_band,
            ( SELECT system_state.value
                   FROM public.system_state
                  WHERE ((system_state.entity = 'greenhouse_state'::text) AND (system_state.ts <= c.ts))
                  ORDER BY system_state.ts DESC
                 LIMIT 1) AS greenhouse_mode
           FROM public.climate c
          WHERE ((c.temp_avg IS NOT NULL) AND (c.ts >= (now() - '14 days'::interval)))
        )
 SELECT ts,
    temp_avg,
    vpd_avg,
    rh_avg,
    dew_point,
    temp_north,
    temp_south,
    temp_east,
    temp_west,
    vpd_south,
    vpd_west,
    vpd_east,
    lux,
    solar_irradiance_w_m2,
    dli_today,
    co2_ppm,
    abs_humidity,
    enthalpy_delta,
    outdoor_temp_f,
    outdoor_rh_pct,
    dp_margin_f,
    fan1,
    fan2,
    vent,
    fog,
    heat1,
    heat2,
    mist_south,
    mist_west,
    mist_center,
    sp_temp_high,
    sp_temp_low,
    sp_vpd_high,
    sp_vpd_low,
    sp_bias_cool,
    sp_bias_heat,
    sp_vpd_hysteresis,
    sp_sealed_max_s,
    sp_relief_s,
    sp_watch_dwell_s,
    sp_d_cool_s2,
    sp_mister_engage,
    temp_in_band,
    vpd_in_band,
    greenhouse_mode,
    round((((sp_temp_low + sp_temp_high) / (2.0)::double precision))::numeric, 2) AS sp_temp_target,
    round((((sp_vpd_low + sp_vpd_high) / (2.0)::double precision))::numeric, 3) AS sp_vpd_target,
    round(((temp_avg - ((sp_temp_low + sp_temp_high) / (2.0)::double precision)))::numeric, 2) AS temp_target_delta_f,
    round(((vpd_avg - ((sp_vpd_low + sp_vpd_high) / (2.0)::double precision)))::numeric, 3) AS vpd_target_delta_kpa,
    round((
        CASE
            WHEN (temp_avg < sp_temp_low) THEN (temp_avg - sp_temp_low)
            WHEN (temp_avg > sp_temp_high) THEN (temp_avg - sp_temp_high)
            ELSE (0.0)::double precision
        END)::numeric, 2) AS temp_band_error_f,
    round((
        CASE
            WHEN (vpd_avg < sp_vpd_low) THEN (vpd_avg - sp_vpd_low)
            WHEN (vpd_avg > sp_vpd_high) THEN (vpd_avg - sp_vpd_high)
            ELSE (0.0)::double precision
        END)::numeric, 3) AS vpd_band_error_kpa
   FROM state_base;


ALTER VIEW public.v_greenhouse_state OWNER TO verdify;

--
-- Name: VIEW v_greenhouse_state; Type: COMMENT; Schema: public; Owner: verdify
