COMMENT ON VIEW public.v_greenhouse_state IS 'Live rolling 14-day greenhouse time series. One row per sensor reading with equipment, setpoints, compliance, mode, dispatcher-owned targets, and signed target deltas.';


--
-- Name: v_grower_economics_story; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_grower_economics_story AS
 WITH harvest_daily AS (
         SELECT ((harvests.ts AT TIME ZONE 'America/Denver'::text))::date AS date,
            sum(COALESCE(harvests.salable_weight_kg, harvests.weight_kg, (0)::double precision)) AS salable_kg,
            sum(COALESCE(harvests.cull_weight_kg, (0)::double precision)) AS cull_kg,
            sum(COALESCE(harvests.revenue, (harvests.unit_price * (harvests.unit_count)::double precision), (0)::double precision)) AS revenue
           FROM public.harvests
          GROUP BY (((harvests.ts AT TIME ZONE 'America/Denver'::text))::date)
        )
 SELECT ds.date,
    hd.salable_kg,
    hd.cull_kg,
    hd.revenue,
    ds.dli_final,
    ds.water_used_gal,
    COALESCE(ds.kwh_total, ds.kwh_estimated) AS kwh,
    ds.therms_estimated,
    ds.cost_total,
    (((ds.stress_hours_heat + ds.stress_hours_vpd_high) + ds.stress_hours_cold) + ds.stress_hours_vpd_low) AS stress_hours,
        CASE
            WHEN (ds.dli_final > (0)::double precision) THEN (hd.salable_kg / ds.dli_final)
            ELSE NULL::double precision
        END AS kg_per_mol_dli,
        CASE
            WHEN (ds.water_used_gal > (0)::double precision) THEN (hd.salable_kg / ds.water_used_gal)
            ELSE NULL::double precision
        END AS kg_per_gal,
        CASE
            WHEN (COALESCE(ds.kwh_total, ds.kwh_estimated) > (0)::double precision) THEN (hd.salable_kg / COALESCE(ds.kwh_total, ds.kwh_estimated))
            ELSE NULL::double precision
        END AS kg_per_kwh,
        CASE
            WHEN (ds.cost_total > (0)::double precision) THEN (hd.revenue / ds.cost_total)
            ELSE NULL::double precision
        END AS revenue_per_cost_dollar
   FROM (public.daily_summary ds
     LEFT JOIN harvest_daily hd USING (date))
  WHERE (ds.date IS NOT NULL)
  ORDER BY ds.date DESC;


ALTER VIEW public.v_grower_economics_story OWNER TO verdify;

--
-- Name: VIEW v_grower_economics_story; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_grower_economics_story IS 'Yield, quality, revenue, DLI, water, energy, cost, and stress-hour economics by local day.';


--
-- Name: v_growth_observation_quality; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_growth_observation_quality AS
 SELECT ((ts AT TIME ZONE 'America/Denver'::text))::date AS date,
    crop_id,
    count(*) AS observations,
    count(*) FILTER (WHERE (health_score IS NOT NULL)) AS health_scores,
    count(*) FILTER (WHERE ((plant_height_cm IS NOT NULL) OR (leaf_count IS NOT NULL) OR (canopy_cover_pct IS NOT NULL) OR (flowering_count IS NOT NULL) OR (fruit_count IS NOT NULL) OR (root_condition IS NOT NULL) OR (mortality_count IS NOT NULL) OR (stress_tags IS NOT NULL))) AS structured_growth_observations,
    count(*) FILTER (WHERE ((severity IS NOT NULL) OR (affected_pct IS NOT NULL))) AS structured_stress_observations,
    avg(health_score) AS avg_health_score
   FROM public.observations
  GROUP BY (((ts AT TIME ZONE 'America/Denver'::text))::date), crop_id
  ORDER BY (((ts AT TIME ZONE 'America/Denver'::text))::date) DESC, crop_id;


ALTER VIEW public.v_growth_observation_quality OWNER TO verdify;

--
-- Name: VIEW v_growth_observation_quality; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_growth_observation_quality IS 'Daily observation structure coverage: health, phenology/growth, and stress evidence.';


--
-- Name: v_harvest_story; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_harvest_story AS
 SELECT h.id,
    h.ts,
    ((h.ts AT TIME ZONE 'America/Denver'::text))::date AS date,
    h.greenhouse_id,
    h.crop_id,
    c.name AS crop_name,
    h.position_id,
    h.zone,
    COALESCE(h.salable_weight_kg, h.weight_kg) AS salable_weight_kg,
    h.cull_weight_kg,
    h.unit_count,
    h.quality_grade,
    h.quality_reason,
    h.destination,
    h.unit_price,
    COALESCE(h.revenue, (h.unit_price * (h.unit_count)::double precision)) AS revenue,
    ds.dli_final,
    ds.water_used_gal,
    ds.kwh_total,
        CASE
            WHEN (ds.dli_final > (0)::double precision) THEN (COALESCE(h.salable_weight_kg, h.weight_kg) / ds.dli_final)
            ELSE NULL::double precision
        END AS kg_per_mol_dli,
        CASE
            WHEN (ds.water_used_gal > (0)::double precision) THEN (COALESCE(h.salable_weight_kg, h.weight_kg) / ds.water_used_gal)
            ELSE NULL::double precision
        END AS kg_per_gal,
        CASE
            WHEN (ds.kwh_total > (0)::double precision) THEN (COALESCE(h.salable_weight_kg, h.weight_kg) / ds.kwh_total)
            ELSE NULL::double precision
        END AS kg_per_kwh
   FROM ((public.harvests h
     LEFT JOIN public.crops c ON ((c.id = h.crop_id)))
     LEFT JOIN public.daily_summary ds ON ((ds.date = ((h.ts AT TIME ZONE 'America/Denver'::text))::date)));


ALTER VIEW public.v_harvest_story OWNER TO verdify;

--
-- Name: VIEW v_harvest_story; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_harvest_story IS 'Harvest outcome evidence normalized by DLI, gallons, and measured kWh when available.';


--
-- Name: v_heat_in_band_7d; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_heat_in_band_7d AS
 WITH samples AS (
         SELECT bt.ts,
            bt.greenhouse_id,
            bt.timeline_phase,
            bt.crop_temp_low,
            bt.crop_temp_high,
            bt.crop_vpd_low,
            bt.crop_vpd_high,
            bt.projected_temp_low,
            bt.projected_temp_high,
            bt.projected_vpd_low,
            bt.projected_vpd_high,
            bt.actual_temp_low,
            bt.actual_temp_high,
            bt.actual_vpd_low,
            bt.actual_vpd_high,
            bt.firmware_temp_low,
            bt.firmware_temp_high,
            bt.firmware_vpd_low,
            bt.firmware_vpd_high,
            bt.temp_width_f,
            bt.vpd_width_kpa,
            bt.sw_fsm_controller_enabled,
            bt.indoor_temp_f,
            bt.indoor_vpd_kpa,
            bt.outdoor_temp_f,
            bt.outdoor_vpd_kpa,
            bt.solar_w_m2,
            bt.outdoor_cold_for_vent,
            bt.temp_hysteresis_f,
            bt.heat_hysteresis_f,
            bt.d_heat_stage_2_f,
            bt.d_cool_stage_2_f,
            bt.bias_heat_f,
            bt.bias_cool_f,
            bt.vpd_hysteresis_kpa,
            bt.vpd_hysteresis_effective_kpa,
            bt.fog_escalation_kpa,
            bt.temp_heat_target_f,
            bt.temp_heat_on_below_f,
            bt.temp_heat2_on_below_f,
            bt.temp_heat2_clear_f,
            bt.temp_cool_on_above_f,
            bt.temp_cool_hold_until_f,
            bt.temp_cooling_entry_margin_f,
            bt.temp_cooling_exit_hysteresis_f,
            bt.solar_cooling_lead_f,
            bt.temp_cool_stage2_delta_f,
            bt.temp_cool_stage2_on_above_f,
            bt.vpd_humidify_on_above_kpa,
            bt.vpd_humidify_resolved_below_kpa,
            bt.vpd_dehum_on_below_kpa,
            bt.vpd_dehum_resolved_above_kpa,
            bt.vpd_low_eff_kpa,
            bt.vpd_high_eff_kpa,
            bt.vpd_vent_fog_on_above_kpa,
            bt.vpd_sealed_fog_on_above_kpa,
            lead(bt.ts) OVER (PARTITION BY bt.greenhouse_id ORDER BY bt.ts) AS next_ts,
            public.fn_equip_at('heat1'::text, bt.ts) AS heat1_on,
            public.fn_equip_at('heat2'::text, bt.ts) AS heat2_on
           FROM public.fn_band_timeline((now() - '7 days'::interval), now(), '00:05:00'::interval, 'vallery'::text) bt(ts, greenhouse_id, timeline_phase, crop_temp_low, crop_temp_high, crop_vpd_low, crop_vpd_high, projected_temp_low, projected_temp_high, projected_vpd_low, projected_vpd_high, actual_temp_low, actual_temp_high, actual_vpd_low, actual_vpd_high, firmware_temp_low, firmware_temp_high, firmware_vpd_low, firmware_vpd_high, temp_width_f, vpd_width_kpa, sw_fsm_controller_enabled, indoor_temp_f, indoor_vpd_kpa, outdoor_temp_f, outdoor_vpd_kpa, solar_w_m2, outdoor_cold_for_vent, temp_hysteresis_f, heat_hysteresis_f, d_heat_stage_2_f, d_cool_stage_2_f, bias_heat_f, bias_cool_f, vpd_hysteresis_kpa, vpd_hysteresis_effective_kpa, fog_escalation_kpa, temp_heat_target_f, temp_heat_on_below_f, temp_heat2_on_below_f, temp_heat2_clear_f, temp_cool_on_above_f, temp_cool_hold_until_f, temp_cooling_entry_margin_f, temp_cooling_exit_hysteresis_f, solar_cooling_lead_f, temp_cool_stage2_delta_f, temp_cool_stage2_on_above_f, vpd_humidify_on_above_kpa, vpd_humidify_resolved_below_kpa, vpd_dehum_on_below_kpa, vpd_dehum_resolved_above_kpa, vpd_low_eff_kpa, vpd_high_eff_kpa, vpd_vent_fog_on_above_kpa, vpd_sealed_fog_on_above_kpa)
          WHERE (bt.timeline_phase = 'actual'::text)
        ), classified AS (
         SELECT s.ts,
            s.greenhouse_id,
            s.timeline_phase,
            s.crop_temp_low,
            s.crop_temp_high,
            s.crop_vpd_low,
            s.crop_vpd_high,
            s.projected_temp_low,
            s.projected_temp_high,
            s.projected_vpd_low,
            s.projected_vpd_high,
            s.actual_temp_low,
            s.actual_temp_high,
            s.actual_vpd_low,
            s.actual_vpd_high,
            s.firmware_temp_low,
            s.firmware_temp_high,
            s.firmware_vpd_low,
            s.firmware_vpd_high,
            s.temp_width_f,
            s.vpd_width_kpa,
            s.sw_fsm_controller_enabled,
            s.indoor_temp_f,
            s.indoor_vpd_kpa,
            s.outdoor_temp_f,
            s.outdoor_vpd_kpa,
            s.solar_w_m2,
            s.outdoor_cold_for_vent,
            s.temp_hysteresis_f,
            s.heat_hysteresis_f,
            s.d_heat_stage_2_f,
            s.d_cool_stage_2_f,
            s.bias_heat_f,
            s.bias_cool_f,
            s.vpd_hysteresis_kpa,
            s.vpd_hysteresis_effective_kpa,
            s.fog_escalation_kpa,
            s.temp_heat_target_f,
            s.temp_heat_on_below_f,
            s.temp_heat2_on_below_f,
            s.temp_heat2_clear_f,
            s.temp_cool_on_above_f,
            s.temp_cool_hold_until_f,
            s.temp_cooling_entry_margin_f,
            s.temp_cooling_exit_hysteresis_f,
            s.solar_cooling_lead_f,
            s.temp_cool_stage2_delta_f,
            s.temp_cool_stage2_on_above_f,
            s.vpd_humidify_on_above_kpa,
            s.vpd_humidify_resolved_below_kpa,
            s.vpd_dehum_on_below_kpa,
            s.vpd_dehum_resolved_above_kpa,
            s.vpd_low_eff_kpa,
            s.vpd_high_eff_kpa,
            s.vpd_vent_fog_on_above_kpa,
            s.vpd_sealed_fog_on_above_kpa,
            s.next_ts,
            s.heat1_on,
            s.heat2_on,
            (GREATEST(0.0, LEAST(EXTRACT(epoch FROM (COALESCE(s.next_ts, now()) - s.ts)), 300.0)) / 60.0) AS sample_minutes,
            ((s.indoor_temp_f >= s.firmware_temp_low) AND (s.indoor_temp_f <= s.firmware_temp_high)) AS temp_in_band,
            (s.indoor_temp_f < s.firmware_temp_low) AS temp_below_band,
            (s.indoor_temp_f > s.firmware_temp_high) AS temp_above_band
           FROM samples s
          WHERE ((s.indoor_temp_f IS NOT NULL) AND (s.firmware_temp_low IS NOT NULL) AND (s.firmware_temp_high IS NOT NULL))
        )
 SELECT greenhouse_id,
    min(ts) AS window_start,
    max(ts) AS window_end,
    count(*) AS samples,
    round(sum(sample_minutes) FILTER (WHERE heat1_on), 1) AS heat1_minutes,
    round(sum(sample_minutes) FILTER (WHERE heat2_on), 1) AS heat2_minutes,
    round(sum(sample_minutes) FILTER (WHERE (heat1_on AND temp_in_band)), 1) AS heat1_in_band_minutes,
    round(sum(sample_minutes) FILTER (WHERE (heat2_on AND temp_in_band)), 1) AS heat2_in_band_minutes,
    round(sum(sample_minutes) FILTER (WHERE (heat1_on AND temp_below_band)), 1) AS heat1_below_band_minutes,
    round(sum(sample_minutes) FILTER (WHERE (heat2_on AND temp_below_band)), 1) AS heat2_below_band_minutes,
    round(sum(sample_minutes) FILTER (WHERE ((heat1_on OR heat2_on) AND temp_above_band)), 1) AS heat_above_band_minutes,
    round(((100.0 * sum(sample_minutes) FILTER (WHERE ((heat1_on OR heat2_on) AND temp_in_band))) / NULLIF(sum(sample_minutes) FILTER (WHERE (heat1_on OR heat2_on)), (0)::numeric)), 1) AS heat_runtime_in_band_pct
   FROM classified
  GROUP BY greenhouse_id;


ALTER VIEW public.v_heat_in_band_7d OWNER TO verdify;

--
-- Name: VIEW v_heat_in_band_7d; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_heat_in_band_7d IS 'Rolling seven-day sampled heat runtime classified against fn_band_timeline crop-band thresholds. Highlights resource use while already inside band.';


--
-- Name: v_heating_staging; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_heating_staging AS
 WITH heat_events AS (
         SELECT equipment_state.ts,
            equipment_state.equipment,
            equipment_state.state,
            lead(equipment_state.ts) OVER (PARTITION BY equipment_state.equipment ORDER BY equipment_state.ts) AS next_ts
           FROM public.equipment_state
          WHERE (equipment_state.equipment = ANY (ARRAY['heat1'::text, 'heat2'::text]))
        ), heat2_on AS (
         SELECT heat_events.ts AS on_ts,
            COALESCE(heat_events.next_ts, now()) AS off_ts
           FROM heat_events
          WHERE ((heat_events.equipment = 'heat2'::text) AND (heat_events.state = true))
        )
 SELECT (on_ts AT TIME ZONE 'America/Denver'::text) AS heat2_on_mdt,
    (off_ts AT TIME ZONE 'America/Denver'::text) AS heat2_off_mdt,
    round((EXTRACT(epoch FROM (off_ts - on_ts)) / (60)::numeric), 1) AS duration_min,
    ( SELECT equipment_state.state
           FROM public.equipment_state
          WHERE ((equipment_state.equipment = 'heat1'::text) AND (equipment_state.ts <= h2.on_ts))
          ORDER BY equipment_state.ts DESC
         LIMIT 1) AS heat1_was_on,
    ( SELECT round((climate.temp_avg)::numeric, 1) AS round
           FROM public.climate
          WHERE ((climate.ts <= h2.on_ts) AND (climate.temp_avg IS NOT NULL))
          ORDER BY climate.ts DESC
         LIMIT 1) AS temp_at_engage,
    public.fn_setpoint_at('temp_low'::text, on_ts) AS setpoint_temp_low
   FROM heat2_on h2
  ORDER BY on_ts DESC;


ALTER VIEW public.v_heating_staging OWNER TO verdify;

--
-- Name: v_heating_staging_summary; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_heating_staging_summary AS
 SELECT (date_trunc('day'::text, heat2_on_mdt))::date AS date,
    count(*) AS heat2_events,
    count(*) FILTER (WHERE (NOT COALESCE(heat1_was_on, false))) AS inversions,
    round(((100.0 * (count(*) FILTER (WHERE (NOT COALESCE(heat1_was_on, false))))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS inversion_pct,
    round(avg(temp_at_engage), 1) AS avg_engage_temp,
    round(sum(duration_min), 1) AS total_heat2_min
   FROM public.v_heating_staging
  GROUP BY ((date_trunc('day'::text, heat2_on_mdt))::date)
  ORDER BY ((date_trunc('day'::text, heat2_on_mdt))::date) DESC;


ALTER VIEW public.v_heating_staging_summary OWNER TO verdify;

--
-- Name: v_hydro_status; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_hydro_status AS
 SELECT ts,
    round((hydro_ph)::numeric, 1) AS ph,
    round((hydro_ec_us_cm)::numeric, 0) AS ec_us_cm,
    round((hydro_tds_ppm)::numeric, 0) AS tds_ppm,
    round((hydro_orp_mv)::numeric, 0) AS orp_mv,
    round((hydro_water_temp_f)::numeric, 1) AS water_temp_f,
    round((hydro_battery_pct)::numeric, 0) AS battery_pct,
    ((hydro_ph >= (5.5)::double precision) AND (hydro_ph <= (6.5)::double precision)) AS ph_in_range,
    ((hydro_ec_us_cm >= (800)::double precision) AND (hydro_ec_us_cm <= (2000)::double precision)) AS ec_in_range,
    ((hydro_water_temp_f >= (60)::double precision) AND (hydro_water_temp_f <= (75)::double precision)) AS temp_in_range,
    (hydro_battery_pct > (20)::double precision) AS battery_ok
   FROM public.climate c
  WHERE (hydro_ph IS NOT NULL)
  ORDER BY ts DESC
 LIMIT 1;


ALTER VIEW public.v_hydro_status OWNER TO verdify;

--
-- Name: v_indoor_outdoor_correlation; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_indoor_outdoor_correlation AS
 SELECT public.time_bucket('01:00:00'::interval, ts) AS hour,
    round((avg(temp_avg))::numeric, 1) AS indoor_temp,
    round((avg(outdoor_temp_f))::numeric, 1) AS outdoor_temp,
    round(((avg(temp_avg) - avg(outdoor_temp_f)))::numeric, 1) AS thermal_gain,
    round((avg(solar_irradiance_w_m2))::numeric, 0) AS solar_w_m2,
    round((avg(vpd_avg))::numeric, 2) AS indoor_vpd,
    round((avg(outdoor_rh_pct))::numeric, 0) AS outdoor_rh,
    round((avg(wind_speed_mph))::numeric, 1) AS wind_mph,
        CASE
            WHEN (avg(solar_irradiance_w_m2) > (50)::double precision) THEN round(((((avg(temp_avg) - avg(outdoor_temp_f)) / NULLIF(avg(solar_irradiance_w_m2), (0)::double precision)) * (100)::double precision))::numeric, 2)
            ELSE NULL::numeric
        END AS gain_per_100w,
    count(*) AS samples
   FROM public.climate
  WHERE ((temp_avg IS NOT NULL) AND (outdoor_temp_f IS NOT NULL))
  GROUP BY (public.time_bucket('01:00:00'::interval, ts))
  ORDER BY (public.time_bucket('01:00:00'::interval, ts)) DESC;


ALTER VIEW public.v_indoor_outdoor_correlation OWNER TO verdify;

--
-- Name: VIEW v_indoor_outdoor_correlation; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_indoor_outdoor_correlation IS 'Hourly indoor vs outdoor temperature correlation. thermal_gain = indoor - outdoor. gain_per_100w = thermal gain coefficient per 100 W/m² solar load.';


--
-- Name: v_infra_cpu_latest; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_infra_cpu_latest AS
 WITH latest AS (
         SELECT DISTINCT ON (infra_cpu.greenhouse_id, infra_cpu.host) infra_cpu.ts,
            infra_cpu.host,
            infra_cpu.vm_name,
            infra_cpu.purpose,
            infra_cpu.cpu_util_pct,
            infra_cpu.load1,
            infra_cpu.cores,
            infra_cpu.memory_used_pct,
            infra_cpu.source,
            infra_cpu.raw,
            infra_cpu.greenhouse_id
           FROM public.infra_cpu
          ORDER BY infra_cpu.greenhouse_id, infra_cpu.host, infra_cpu.ts DESC
        )
 SELECT ts,
    host,
    vm_name,
    purpose,
    cpu_util_pct,
    load1,
    cores,
    memory_used_pct,
    source,
    raw,
    greenhouse_id,
    (EXTRACT(epoch FROM (now() - ts)))::integer AS age_s
   FROM latest;


ALTER VIEW public.v_infra_cpu_latest OWNER TO verdify;

--
-- Name: v_instrumentation_readiness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_instrumentation_readiness AS
 SELECT requirement_id,
    category,
    metric,
    current_status,
    blocks_story,
    recommended_source,
    priority,
        CASE
            WHEN (current_status = ANY (ARRAY['installed'::text, 'complete'::text])) THEN 'ok'::text
            WHEN (current_status = 'partial'::text) THEN 'warn'::text
            ELSE 'blocked'::text
        END AS readiness_status
   FROM public.instrumentation_requirements
  ORDER BY priority, category, requirement_id;


ALTER VIEW public.v_instrumentation_readiness OWNER TO verdify;

--
-- Name: VIEW v_instrumentation_readiness; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_instrumentation_readiness IS 'Hardware/operator instrumentation requirements that block stronger data stories.';


--
-- Name: v_system_health_score; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_system_health_score AS
 SELECT 'sensor_health'::text AS component,
    round(((100.0 * (count(*) FILTER (WHERE (NOT v_sensor_staleness.is_stale)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS score_pct,
    jsonb_build_object('total_sensors', count(*), 'healthy', count(*) FILTER (WHERE (NOT v_sensor_staleness.is_stale)), 'stale', count(*) FILTER (WHERE v_sensor_staleness.is_stale)) AS details,
    now() AS checked_at
   FROM public.v_sensor_staleness
UNION ALL
 SELECT 'alert_load'::text AS component,
    GREATEST((0)::numeric, round((100.0 - (COALESCE(sum(
        CASE alert_log.severity
            WHEN 'critical'::text THEN 10
            WHEN 'warning'::text THEN 3
            WHEN 'info'::text THEN 1
            ELSE 0
        END), (0)::bigint))::numeric), 1)) AS score_pct,
    jsonb_build_object('open_total', count(*), 'critical', count(*) FILTER (WHERE (alert_log.severity = 'critical'::text)), 'warning', count(*) FILTER (WHERE (alert_log.severity = 'warning'::text))) AS details,
    now() AS checked_at
   FROM public.alert_log
  WHERE (alert_log.disposition = 'open'::text)
UNION ALL
 SELECT 'equipment_health'::text AS component,
    (public.fn_equipment_health())::numeric AS score_pct,
    jsonb_build_object('score', public.fn_equipment_health()) AS details,
    now() AS checked_at
UNION ALL
 SELECT 'controller'::text AS component,
    round((
        CASE
            WHEN (d.ts IS NULL) THEN (0)::double precision
            ELSE LEAST((100)::double precision, (((GREATEST((0)::numeric, ((40)::numeric - (EXTRACT(epoch FROM (now() - d.ts)) / 15.0))))::double precision + LEAST((30)::double precision, GREATEST((0)::double precision, ((d.wifi_rssi + (80)::double precision) * (1.0)::double precision)))) + LEAST((30)::double precision, (d.uptime_s / (120.0)::double precision))))
        END)::numeric, 1) AS score_pct,
    jsonb_build_object('wifi_rssi_dbm', d.wifi_rssi, 'uptime_s', d.uptime_s, 'heap_bytes', d.heap_bytes) AS details,
    now() AS checked_at
   FROM ( SELECT diagnostics.ts,
            diagnostics.wifi_rssi,
            diagnostics.uptime_s,
            diagnostics.heap_bytes
           FROM public.diagnostics
          WHERE (diagnostics.ts > (now() - '00:10:00'::interval))
          ORDER BY diagnostics.ts DESC
         LIMIT 1) d;


ALTER VIEW public.v_system_health_score OWNER TO verdify;

--
-- Name: v_iris_planning_context; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_iris_planning_context AS
 SELECT now() AS query_ts,
    ( SELECT json_build_object('temp_avg', round((avg(climate.temp_avg))::numeric, 1), 'vpd_avg', round((avg(climate.vpd_avg))::numeric, 2), 'rh_avg', round((avg(climate.rh_avg))::numeric, 1), 'outdoor_temp_f', round((avg(climate.outdoor_temp_f))::numeric, 1), 'dli_today', round((max(climate.dli_today))::numeric, 2), 'co2_ppm', round((avg(climate.co2_ppm))::numeric, 0)) AS json_build_object
           FROM public.climate
          WHERE ((climate.ts >= (now() - '01:00:00'::interval)) AND (climate.temp_avg IS NOT NULL))) AS current_conditions,
    ( SELECT json_build_object('north', round((avg(climate.temp_north))::numeric, 1), 'south', round((avg(climate.temp_south))::numeric, 1), 'east', round((avg(climate.temp_east))::numeric, 1), 'west', round((avg(climate.temp_west))::numeric, 1)) AS json_build_object
           FROM public.climate
          WHERE ((climate.ts >= (now() - '01:00:00'::interval)) AND (climate.temp_avg IS NOT NULL))) AS zone_context,
    ( SELECT json_build_object('date', daily_summary.date, 'cost_total', daily_summary.cost_total, 'dli_final', daily_summary.dli_final, 'stress_hours_vpd_high', daily_summary.stress_hours_vpd_high, 'water_used_gal', daily_summary.water_used_gal) AS json_build_object
           FROM public.daily_summary
          ORDER BY daily_summary.date DESC
         LIMIT 1) AS yesterday_summary,
    ( SELECT json_build_object('predicted_dli', fn_forecast_dli.predicted_dli, 'gl_hours_needed', fn_forecast_dli.gl_hours_needed) AS json_build_object
           FROM public.fn_forecast_dli((CURRENT_DATE + 1)) fn_forecast_dli(predicted_dli, gl_hours_needed, recommended_gl_start, recommended_gl_end)) AS dli_forecast,
    ( SELECT json_object_agg(sub.parameter, sub.value) AS json_object_agg
           FROM ( SELECT DISTINCT ON (setpoint_changes.parameter) setpoint_changes.parameter,
                    setpoint_changes.value
                   FROM public.setpoint_changes
                  ORDER BY setpoint_changes.parameter, setpoint_changes.ts DESC) sub) AS current_setpoints,
    ( SELECT json_agg(row_to_json(sub.*) ORDER BY sub.ts) AS json_agg
           FROM ( SELECT setpoint_plan.ts,
                    setpoint_plan.parameter,
                    setpoint_plan.value,
                    setpoint_plan.reason
                   FROM public.setpoint_plan
                  WHERE ((setpoint_plan.ts > now()) AND (setpoint_plan.is_active = true) AND (setpoint_plan.parameter <> 'plan_metadata'::text))
                  ORDER BY setpoint_plan.ts) sub) AS active_plan,
    ( SELECT json_build_object('composite_score', public.fn_system_health(), 'components', ( SELECT json_agg(json_build_object('component', v_system_health_score.component, 'score', v_system_health_score.score_pct)) AS json_agg
                   FROM public.v_system_health_score)) AS json_build_object) AS system_health,
    ( SELECT json_build_object('electric_per_kwh', 0.111, 'gas_per_therm', 0.83, 'water_per_gal', 0.00484) AS json_build_object) AS cost_rates;


ALTER VIEW public.v_iris_planning_context OWNER TO verdify;

--
-- Name: VIEW v_iris_planning_context; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_iris_planning_context IS 'Single-query planning context for Iris. v4 filters active_plan to is_active=true so superseded future rows are invisible.';


--
-- Name: v_irrigation_accountability; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_accountability AS
 SELECT day AS date,
    zone_path AS zone,
    count(*) AS events,
    round((sum(total_duration_min))::numeric, 1) AS runtime_min,
    round((sum(COALESCE(meter_delta_gal, (0)::double precision)))::numeric, 2) AS volume_gal,
    count(*) FILTER (WHERE (meter_delta_gal IS NULL)) AS missing_volume_events,
    (0)::bigint AS weather_skip_events,
    count(*) AS fertigation_events,
    max(run_start) AS latest_event
   FROM public.v_irrigation_fertigation_runs
  GROUP BY day, zone_path
  ORDER BY day DESC, zone_path;


ALTER VIEW public.v_irrigation_accountability OWNER TO verdify;

--
-- Name: VIEW v_irrigation_accountability; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_accountability IS 'Compatibility accountability view backed by equipment-derived fertigation runs instead of retired irrigation_log rows.';


--
-- Name: v_irrigation_log; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_log AS
 SELECT (((('x'::text || substr(run_id, 1, 8)))::bit(32))::integer & 2147483647) AS id,
    run_start AS ts,
    zone_path AS zone,
    NULL::integer AS schedule_id,
    ((run_start AT TIME ZONE 'America/Denver'::text))::time without time zone AS scheduled_time,
    run_start AS actual_start,
    run_end AS actual_end,
    (round((COALESCE(meter_delta_gal, (0)::double precision))::numeric, 2))::numeric(8,2) AS volume_gal,
    'equipment_state'::text AS source,
    concat_ws(' '::text, 'retired compatibility row reconstructed from v_irrigation_fertigation_runs;', ('run_id='::text || run_id), ('fert_relay='::text || fert_relay), ('flush_relay='::text || flush_relay), ('quality='::text || quality_flag)) AS notes,
    run_end AS created_at,
    'vallery'::text AS greenhouse_id,
    false AS weather_skip,
    true AS fertigation,
    'water_total_gal'::text AS metering_method,
    (round((total_duration_min * (60)::double precision)))::integer AS duration_s
   FROM public.v_irrigation_fertigation_runs
  ORDER BY run_start DESC, fert_relay;


ALTER VIEW public.v_irrigation_log OWNER TO verdify;

--
-- Name: VIEW v_irrigation_log; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_log IS 'Retired compatibility view reconstructed from v_irrigation_fertigation_runs. Do not read irrigation_log for canonical irrigation/fertigation events.';


--
-- Name: v_irrigation_sensor_feedback_status; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_irrigation_sensor_feedback_status AS
 WITH latest AS (
         SELECT climate.ts,
            climate.soil_moisture_south_1,
            climate.soil_temp_south_1,
            climate.soil_ec_south_1,
            climate.soil_moisture_south_2,
            climate.soil_temp_south_2,
            climate.moisture_center,
            climate.ph_runoff_center,
            climate.ec_runoff_center
           FROM public.climate
          ORDER BY climate.ts DESC
         LIMIT 1
        ), windowed AS (
         SELECT count(*) FILTER (WHERE (climate.ts >= (now() - '24:00:00'::interval))) AS samples_24h,
            count(*) FILTER (WHERE ((climate.ts >= (now() - '24:00:00'::interval)) AND (climate.soil_moisture_south_1 IS NOT NULL))) AS south_1_samples_24h,
            count(*) FILTER (WHERE ((climate.ts >= (now() - '24:00:00'::interval)) AND (climate.soil_moisture_south_1 > (0)::double precision) AND (climate.soil_moisture_south_1 <= (100)::double precision))) AS south_1_positive_24h,
            min(climate.soil_moisture_south_1) FILTER (WHERE (climate.ts >= (now() - '24:00:00'::interval))) AS south_1_min_24h,
            max(climate.soil_moisture_south_1) FILTER (WHERE (climate.ts >= (now() - '24:00:00'::interval))) AS south_1_max_24h,
            max(climate.ts) FILTER (WHERE ((climate.soil_moisture_south_1 > (0)::double precision) AND (climate.soil_moisture_south_1 <= (100)::double precision))) AS south_1_moisture_last_positive_ts,
            max(climate.ts) FILTER (WHERE (climate.soil_ec_south_1 > (0)::double precision)) AS south_1_ec_last_positive_ts,
            count(*) FILTER (WHERE ((climate.ts >= (now() - '24:00:00'::interval)) AND (climate.soil_moisture_south_2 IS NOT NULL))) AS south_2_samples_24h,
            count(*) FILTER (WHERE ((climate.ts >= (now() - '24:00:00'::interval)) AND (climate.soil_moisture_south_2 > (0)::double precision) AND (climate.soil_moisture_south_2 <= (100)::double precision))) AS south_2_positive_24h,
            min(climate.soil_moisture_south_2) FILTER (WHERE (climate.ts >= (now() - '24:00:00'::interval))) AS south_2_min_24h,
            max(climate.soil_moisture_south_2) FILTER (WHERE (climate.ts >= (now() - '24:00:00'::interval))) AS south_2_max_24h,
            max(climate.ts) FILTER (WHERE ((climate.soil_moisture_south_2 > (0)::double precision) AND (climate.soil_moisture_south_2 <= (100)::double precision))) AS south_2_last_positive_ts,
            max(climate.ts) FILTER (WHERE ((climate.moisture_center >= (0)::double precision) AND (climate.moisture_center <= (100)::double precision))) AS center_moisture_last_valid_ts,
            max(climate.ts) FILTER (WHERE ((climate.ph_runoff_center >= (0)::double precision) AND (climate.ph_runoff_center <= (14)::double precision))) AS center_ph_last_valid_ts,
            max(climate.ts) FILTER (WHERE (climate.ec_runoff_center >= (0)::double precision)) AS center_ec_last_valid_ts
           FROM public.climate
        )
 SELECT 'south_soil_probe_1'::text AS feedback_key,
    'south'::text AS zone,
    'soil_moisture_south_1'::text AS signal,
    latest.ts AS last_sample_ts,
    latest.soil_moisture_south_1 AS latest_value,
        CASE
            WHEN (windowed.south_1_samples_24h = 0) THEN 'missing'::text
            WHEN (windowed.south_1_positive_24h = 0) THEN 'stuck_zero'::text
            ELSE 'ok'::text
        END AS status,
    jsonb_build_object('samples_24h', windowed.south_1_samples_24h, 'positive_samples_24h', windowed.south_1_positive_24h, 'min_24h', windowed.south_1_min_24h, 'max_24h', windowed.south_1_max_24h, 'last_positive_ts', windowed.south_1_moisture_last_positive_ts, 'soil_temp_south_1', latest.soil_temp_south_1, 'soil_ec_south_1', latest.soil_ec_south_1, 'soil_ec_south_1_last_positive_ts', windowed.south_1_ec_last_positive_ts, 'south_2_reference_samples_24h', windowed.south_2_samples_24h, 'south_2_reference_positive_samples_24h', windowed.south_2_positive_24h, 'south_2_reference_min_24h', windowed.south_2_min_24h, 'south_2_reference_max_24h', windowed.south_2_max_24h, 'south_2_reference_last_positive_ts', windowed.south_2_last_positive_ts, 'soil_moisture_south_2_reference', latest.soil_moisture_south_2, 'soil_temp_south_2_reference', latest.soil_temp_south_2) AS details,
        CASE
            WHEN ((windowed.south_1_positive_24h = 0) AND (windowed.south_2_positive_24h > 0) AND (latest.soil_temp_south_1 IS NOT NULL)) THEN 'Repair or replace south SEN0601/address-7 probe; south_1 temperature and nearby south_2 moisture are updating, so prioritize probe/media contact or channel failure over shared ingestion. Last positive timestamps are in details.'::text
            ELSE 'Repair or replace south SEN0601/address-7 probe; verify nonzero response after irrigation. Last positive timestamps are in details.'::text
        END AS required_action
   FROM (latest
     CROSS JOIN windowed)
UNION ALL
 SELECT 'center_root_zone_moisture'::text AS feedback_key,
    'center'::text AS zone,
    'moisture_center'::text AS signal,
    windowed.center_moisture_last_valid_ts AS last_sample_ts,
    latest.moisture_center AS latest_value,
        CASE
            WHEN ((latest.moisture_center IS NOT NULL) AND (NOT ((latest.moisture_center >= (0)::double precision) AND (latest.moisture_center <= (100)::double precision)))) THEN 'invalid'::text
            WHEN (windowed.center_moisture_last_valid_ts IS NULL) THEN 'missing'::text
            WHEN (windowed.center_moisture_last_valid_ts < (now() - '24:00:00'::interval)) THEN 'stale'::text
            ELSE 'ok'::text
        END AS status,
    jsonb_build_object('last_valid_sample_ts', windowed.center_moisture_last_valid_ts, 'latest_raw_value', latest.moisture_center) AS details,
    'Install/map center root-zone moisture sensor.'::text AS required_action
   FROM (latest
     CROSS JOIN windowed)
UNION ALL
 SELECT 'center_runoff_ph'::text AS feedback_key,
    'center'::text AS zone,
    'ph_runoff_center'::text AS signal,
    windowed.center_ph_last_valid_ts AS last_sample_ts,
    latest.ph_runoff_center AS latest_value,
        CASE
            WHEN ((latest.ph_runoff_center IS NOT NULL) AND (NOT ((latest.ph_runoff_center >= (0)::double precision) AND (latest.ph_runoff_center <= (14)::double precision)))) THEN 'invalid'::text
            WHEN (windowed.center_ph_last_valid_ts IS NULL) THEN 'missing'::text
            WHEN (windowed.center_ph_last_valid_ts < (now() - '7 days'::interval)) THEN 'stale'::text
            ELSE 'ok'::text
        END AS status,
    jsonb_build_object('last_valid_sample_ts', windowed.center_ph_last_valid_ts, 'latest_raw_value', latest.ph_runoff_center) AS details,
    'Install/map center runoff pH feedback.'::text AS required_action
   FROM (latest
     CROSS JOIN windowed)
UNION ALL
 SELECT 'center_runoff_ec'::text AS feedback_key,
    'center'::text AS zone,
    'ec_runoff_center'::text AS signal,
    windowed.center_ec_last_valid_ts AS last_sample_ts,
    latest.ec_runoff_center AS latest_value,
        CASE
            WHEN ((latest.ec_runoff_center IS NOT NULL) AND (latest.ec_runoff_center < (0)::double precision)) THEN 'invalid'::text
            WHEN (windowed.center_ec_last_valid_ts IS NULL) THEN 'missing'::text
            WHEN (windowed.center_ec_last_valid_ts < (now() - '7 days'::interval)) THEN 'stale'::text
            ELSE 'ok'::text
        END AS status,
    jsonb_build_object('last_valid_sample_ts', windowed.center_ec_last_valid_ts, 'latest_raw_value', latest.ec_runoff_center) AS details,
    'Install/map center runoff EC feedback.'::text AS required_action
   FROM (latest
     CROSS JOIN windowed)
  ORDER BY 2, 3;


ALTER VIEW public.v_irrigation_sensor_feedback_status OWNER TO verdify;

--
-- Name: VIEW v_irrigation_sensor_feedback_status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_irrigation_sensor_feedback_status IS 'Operational status for physical irrigation feedback gaps: south soil probe 1 and center root-zone/runoff instrumentation.';


--
-- Name: v_latest_observations; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_latest_observations AS
 SELECT DISTINCT ON (zone) zone,
    ts,
    camera,
    confidence,
    crops_observed,
    environment_notes,
    recommended_actions
   FROM public.image_observations
  ORDER BY zone, ts DESC;


ALTER VIEW public.v_latest_observations OWNER TO verdify;

--
-- Name: v_light_transmission; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_light_transmission AS
 WITH indoor AS (
         SELECT public.time_bucket('00:05:00'::interval, climate.ts) AS bucket,
            avg(climate.lux) AS lux
           FROM public.climate
          WHERE (climate.lux IS NOT NULL)
          GROUP BY (public.time_bucket('00:05:00'::interval, climate.ts))
        ), outdoor AS (
         SELECT public.time_bucket('00:05:00'::interval, climate.ts) AS bucket,
            avg(climate.outdoor_lux) AS ppfd
           FROM public.climate
          WHERE ((climate.outdoor_lux IS NOT NULL) AND (climate.outdoor_lux > (0)::double precision))
          GROUP BY (public.time_bucket('00:05:00'::interval, climate.ts))
        )
 SELECT indoor.bucket AS ts,
    round((((indoor.lux / outdoor.ppfd) * (100)::double precision))::numeric, 1) AS transmission_pct
   FROM (indoor
     JOIN outdoor ON ((indoor.bucket = outdoor.bucket)));


ALTER VIEW public.v_light_transmission OWNER TO verdify;

--
-- Name: v_lighting_circuit_status_now; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_circuit_status_now AS
 WITH policy AS (
         SELECT fn_lighting_circuit_policy.greenhouse_id,
            fn_lighting_circuit_policy.ts,
            fn_lighting_circuit_policy.light_key,
            fn_lighting_circuit_policy.equipment,
            fn_lighting_circuit_policy.dli_target,
            fn_lighting_circuit_policy.start_hour,
            fn_lighting_circuit_policy.cutoff_hour,
            fn_lighting_circuit_policy.lux_on_threshold,
            fn_lighting_circuit_policy.lux_hysteresis,
            fn_lighting_circuit_policy.lux_off_threshold,
            fn_lighting_circuit_policy.min_on_s,
            fn_lighting_circuit_policy.min_off_s,
            fn_lighting_circuit_policy.auto_enabled,
            fn_lighting_circuit_policy.source_chain,
            fn_lighting_circuit_policy.controller_contract
           FROM public.fn_lighting_circuit_policy(now(), 'vallery'::text) fn_lighting_circuit_policy(greenhouse_id, ts, light_key, equipment, dli_target, start_hour, cutoff_hour, lux_on_threshold, lux_hysteresis, lux_off_threshold, min_on_s, min_off_s, auto_enabled, source_chain, controller_contract)
        ), latest_climate AS (
         SELECT climate.ts,
            climate.dli_today,
            climate.lux,
            climate.outdoor_lux
           FROM public.climate
          WHERE (climate.greenhouse_id = 'vallery'::text)
          ORDER BY climate.ts DESC
         LIMIT 1
        ), latest_equipment AS (
         SELECT DISTINCT ON (equipment_state.equipment) equipment_state.equipment,
            equipment_state.state,
            equipment_state.ts
           FROM public.equipment_state
          WHERE (equipment_state.equipment = ANY (ARRAY['grow_light_main'::text, 'grow_light_grow'::text]))
          ORDER BY equipment_state.equipment, equipment_state.ts DESC
        ), firmware_ordered AS (
         SELECT diagnostics.ts,
            diagnostics.firmware_version,
            lag(diagnostics.firmware_version) OVER (ORDER BY diagnostics.ts) AS previous_firmware_version
           FROM public.diagnostics
          WHERE ((diagnostics.firmware_version IS NOT NULL) AND (diagnostics.firmware_version <> ''::text) AND (diagnostics.ts > (now() - '30 days'::interval)))
        ), current_firmware AS (
         SELECT diagnostics.firmware_version
           FROM public.diagnostics
          WHERE ((diagnostics.firmware_version IS NOT NULL) AND (diagnostics.firmware_version <> ''::text))
          ORDER BY diagnostics.ts DESC
         LIMIT 1
        ), current_firmware_start AS (
         SELECT max(fo.ts) AS ts
           FROM (firmware_ordered fo
             CROSS JOIN current_firmware cf)
          WHERE ((fo.firmware_version = cf.firmware_version) AND (fo.previous_firmware_version IS DISTINCT FROM fo.firmware_version))
        ), latest_reason AS (
         SELECT DISTINCT ON (system_state.entity) system_state.entity,
            system_state.value,
            system_state.ts
           FROM public.system_state
          WHERE (system_state.entity = ANY (ARRAY['gl_main_state'::text, 'gl_main_reason'::text, 'gl_grow_state'::text, 'gl_grow_reason'::text]))
          ORDER BY system_state.entity, system_state.ts DESC
        ), joined AS (
         SELECT p.greenhouse_id,
            p.ts,
            p.light_key,
            p.equipment,
            p.dli_target,
            p.start_hour,
            p.cutoff_hour,
            p.lux_on_threshold,
            p.lux_hysteresis,
            p.lux_off_threshold,
            p.min_on_s,
            p.min_off_s,
            p.auto_enabled,
            p.source_chain,
            p.controller_contract,
            c.ts AS climate_ts,
            c.dli_today,
            c.lux AS indoor_lux,
            c.outdoor_lux,
            COALESCE(c.outdoor_lux, c.lux, (0.0)::double precision) AS natural_lux,
            (EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer AS local_hour,
            e.state AS equipment_state,
            e.ts AS equipment_ts,
            state_row.value AS firmware_state_raw,
            state_row.ts AS firmware_state_ts,
            reason_row.value AS firmware_reason_raw,
            reason_row.ts AS firmware_reason_ts,
            ((state_row.ts >= COALESCE(( SELECT current_firmware_start.ts
                   FROM current_firmware_start), (now() - '00:10:00'::interval))) AND (reason_row.ts >= COALESCE(( SELECT current_firmware_start.ts
                   FROM current_firmware_start), (now() - '00:10:00'::interval))) AND (state_row.ts > (now() - '00:10:00'::interval)) AND (reason_row.ts > (now() - '00:10:00'::interval))) AS firmware_telemetry_fresh
           FROM ((((policy p
             LEFT JOIN latest_climate c ON (true))
             LEFT JOIN latest_equipment e ON ((e.equipment = p.equipment)))
             LEFT JOIN latest_reason state_row ON ((state_row.entity = (('gl_'::text || p.light_key) || '_state'::text))))
             LEFT JOIN latest_reason reason_row ON ((reason_row.entity = (('gl_'::text || p.light_key) || '_reason'::text))))
        )
 SELECT greenhouse_id,
    ts,
    light_key,
    equipment,
    dli_target,
    start_hour,
    cutoff_hour,
    lux_on_threshold,
    lux_hysteresis,
    lux_off_threshold,
    min_on_s,
    min_off_s,
    auto_enabled,
    source_chain,
    controller_contract,
    climate_ts,
    dli_today,
    indoor_lux,
    outdoor_lux,
    natural_lux,
    local_hour,
        CASE
            WHEN (start_hour <= cutoff_hour) THEN ((local_hour >= start_hour) AND (local_hour < cutoff_hour))
            ELSE ((local_hour >= start_hour) OR (local_hour < cutoff_hour))
        END AS in_light_window,
    (COALESCE(dli_today, (0.0)::double precision) < dli_target) AS dli_below_target,
    (natural_lux < lux_on_threshold) AS lux_below_on_threshold,
    (natural_lux < lux_off_threshold) AS lux_below_off_threshold,
    (auto_enabled AND
        CASE
            WHEN (start_hour <= cutoff_hour) THEN ((local_hour >= start_hour) AND (local_hour < cutoff_hour))
            ELSE ((local_hour >= start_hour) OR (local_hour < cutoff_hour))
        END AND (COALESCE(dli_today, (0.0)::double precision) < dli_target) AND ((natural_lux < lux_on_threshold) OR ((COALESCE(equipment_state, false) OR (firmware_telemetry_fresh AND (upper(COALESCE(firmware_state_raw, ''::text)) = 'ON'::text))) AND (natural_lux < lux_off_threshold)))) AS expected_on,
    COALESCE(equipment_state, false) AS actual_on,
        CASE
            WHEN firmware_telemetry_fresh THEN firmware_state_raw
            ELSE NULL::text
        END AS firmware_state,
        CASE
            WHEN firmware_telemetry_fresh THEN firmware_reason_raw
            ELSE NULL::text
        END AS firmware_reason,
    equipment_ts,
    firmware_state_raw,
    firmware_reason_raw,
    firmware_state_ts,
    firmware_reason_ts,
    firmware_telemetry_fresh
   FROM joined j;


ALTER VIEW public.v_lighting_circuit_status_now OWNER TO verdify;

--
-- Name: VIEW v_lighting_circuit_status_now; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_lighting_circuit_status_now IS 'Current per-circuit lighting policy, expected state, fresh firmware text state, and actual Lutron equipment_state. Firmware state/reason are NULL unless updated after current firmware start and within 10 minutes.';


--
-- Name: v_lighting_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_daily AS
 WITH runtime AS (
         SELECT v_equipment_runtime_daily.day,
            v_equipment_runtime_daily.equipment,
            v_equipment_runtime_daily.on_minutes,
            v_equipment_runtime_daily.cycles
           FROM public.v_equipment_runtime_daily
          WHERE (v_equipment_runtime_daily.equipment = ANY (ARRAY['grow_light_main'::text, 'grow_light_grow'::text]))
        )
 SELECT ds.date,
    ((ds.date + '12:00:00'::time without time zone))::timestamp with time zone AS ts,
    ds.dli_final AS sensor_dli,
    (ds.runtime_grow_light_min / (60.0)::double precision) AS grow_light_hours,
    (COALESCE(main_rt.on_minutes, 0.0) / 60.0) AS main_light_hours,
    (COALESCE(grow_rt.on_minutes, 0.0) / 60.0) AS grow_light_circuit_hours,
    COALESCE(main_rt.cycles, (0)::bigint) AS main_light_cycles,
    COALESCE(grow_rt.cycles, (0)::bigint) AS grow_light_circuit_cycles,
    p.target_dli,
    p.target_light_hours,
    p.sunrise_hour,
    p.natural_sunset_hour,
    p.cutoff_hour,
    p.max_crop_name
   FROM (((public.daily_summary ds
     CROSS JOIN LATERAL public.fn_lighting_policy(((ds.date + '12:00:00'::time without time zone))::timestamp with time zone, 'vallery'::text) p(greenhouse_id, ts, local_date, target_dli, target_ppfd_umol_m2_s, target_light_hours, sunrise_hour, natural_sunset_hour, cutoff_hour, max_crop_name, max_crop_stage, source_chain, controller_contract))
     LEFT JOIN runtime main_rt ON (((main_rt.day = ds.date) AND (main_rt.equipment = 'grow_light_main'::text))))
     LEFT JOIN runtime grow_rt ON (((grow_rt.day = ds.date) AND (grow_rt.equipment = 'grow_light_grow'::text))))
  WHERE (ds.dli_final IS NOT NULL);


ALTER VIEW public.v_lighting_daily OWNER TO verdify;

--
-- Name: VIEW v_lighting_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_lighting_daily IS 'Daily DLI and separate lighting-circuit runtimes joined to crop-driven lighting policy.';


--
-- Name: v_lighting_minutes_status_now; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_minutes_status_now AS
 WITH policy AS (
         SELECT fn_lighting_minutes_policy.greenhouse_id,
            fn_lighting_minutes_policy.ts,
            fn_lighting_minutes_policy.light_key,
            fn_lighting_minutes_policy.equipment,
            fn_lighting_minutes_policy.target_light_minutes,
            fn_lighting_minutes_policy.start_hour,
            fn_lighting_minutes_policy.cutoff_hour,
            fn_lighting_minutes_policy.lux_on_threshold,
            fn_lighting_minutes_policy.lux_hysteresis,
            fn_lighting_minutes_policy.lux_off_threshold,
            fn_lighting_minutes_policy.min_on_s,
            fn_lighting_minutes_policy.min_off_s,
            fn_lighting_minutes_policy.auto_enabled,
            fn_lighting_minutes_policy.legacy_dli_target,
            fn_lighting_minutes_policy.source_chain,
            fn_lighting_minutes_policy.controller_contract
           FROM public.fn_lighting_minutes_policy(now(), 'vallery'::text) fn_lighting_minutes_policy(greenhouse_id, ts, light_key, equipment, target_light_minutes, start_hour, cutoff_hour, lux_on_threshold, lux_hysteresis, lux_off_threshold, min_on_s, min_off_s, auto_enabled, legacy_dli_target, source_chain, controller_contract)
        ), today_window AS (
         SELECT p.light_key,
            p.equipment,
            p.target_light_minutes,
            p.start_hour,
            p.cutoff_hour,
            p.lux_on_threshold,
            p.lux_hysteresis,
            p.lux_off_threshold,
            ((((now() AT TIME ZONE 'America/Denver'::text))::date + make_interval(hours => p.start_hour)) AT TIME ZONE 'America/Denver'::text) AS start_ts,
            LEAST(((((now() AT TIME ZONE 'America/Denver'::text))::date + make_interval(hours => p.cutoff_hour)) AT TIME ZONE 'America/Denver'::text), now()) AS end_ts
           FROM policy p
        ), minute_grid AS (
         SELECT w.light_key,
            w.equipment,
            w.target_light_minutes,
            w.start_hour,
            w.cutoff_hour,
            w.lux_on_threshold,
            w.lux_hysteresis,
            w.lux_off_threshold,
            w.start_ts,
            w.end_ts,
            gs.minute_ts
           FROM (today_window w
             LEFT JOIN LATERAL generate_series(w.start_ts, (w.end_ts - '00:01:00'::interval), '00:01:00'::interval) gs(minute_ts) ON ((w.end_ts > w.start_ts)))
        ), lux_min AS (
         SELECT public.time_bucket('00:01:00'::interval, c.ts) AS minute_ts,
            avg(COALESCE(c.outdoor_lux, c.lux)) AS natural_lux
           FROM public.climate c
          WHERE ((c.greenhouse_id = 'vallery'::text) AND (c.ts >= ( SELECT min(today_window.start_ts) AS min
                   FROM today_window)) AND (c.ts <= ( SELECT max(today_window.end_ts) AS max
                   FROM today_window)) AND (COALESCE(c.outdoor_lux, c.lux) IS NOT NULL))
          GROUP BY (public.time_bucket('00:01:00'::interval, c.ts))
        ), state_seed AS (
         SELECT w.light_key,
            w.equipment,
            w.start_ts AS ts,
            COALESCE(( SELECT e.state
                   FROM public.equipment_state e
                  WHERE ((e.greenhouse_id = 'vallery'::text) AND (e.equipment = w.equipment) AND (e.ts <= w.start_ts))
                  ORDER BY e.ts DESC
                 LIMIT 1), false) AS state
           FROM today_window w
        ), state_events AS (
         SELECT w.light_key,
            w.equipment,
            e.ts,
            e.state
           FROM (today_window w
             JOIN public.equipment_state e ON (((e.greenhouse_id = 'vallery'::text) AND (e.equipment = w.equipment) AND (e.ts >= w.start_ts) AND (e.ts <= w.end_ts))))
        ), state_timeline AS (
         SELECT x.light_key,
            x.equipment,
            x.ts,
            x.state,
            lead(x.ts, 1, w.end_ts) OVER (PARTITION BY x.light_key, x.equipment ORDER BY x.ts) AS next_ts
           FROM (( SELECT state_seed.light_key,
                    state_seed.equipment,
                    state_seed.ts,
                    state_seed.state
                   FROM state_seed
                UNION ALL
                 SELECT state_events.light_key,
                    state_events.equipment,
                    state_events.ts,
                    state_events.state
                   FROM state_events) x
             JOIN today_window w ON (((w.light_key = x.light_key) AND (w.equipment = x.equipment))))
        ), state_segments AS (
         SELECT st.light_key,
            st.equipment,
            GREATEST(st.ts, w.start_ts) AS start_ts,
            LEAST(st.next_ts, w.end_ts) AS end_ts
           FROM (state_timeline st
             JOIN today_window w ON (((w.light_key = st.light_key) AND (w.equipment = st.equipment))))
          WHERE ((st.state IS TRUE) AND (st.ts < w.end_ts) AND (st.next_ts > w.start_ts))
        ), minute_eval AS (
         SELECT mg.light_key,
            mg.equipment,
            mg.minute_ts,
            (COALESCE(lm.natural_lux, (0.0)::double precision) >= mg.lux_on_threshold) AS natural_qualified,
            (EXISTS ( SELECT 1
                   FROM state_segments s
                  WHERE ((s.light_key = mg.light_key) AND (s.equipment = mg.equipment) AND (s.start_ts < (mg.minute_ts + '00:01:00'::interval)) AND (s.end_ts > mg.minute_ts)))) AS switch_on
           FROM (minute_grid mg
             LEFT JOIN lux_min lm ON ((lm.minute_ts = mg.minute_ts)))
        ), today AS (
         SELECT w.light_key,
            w.equipment,
            (count(me.minute_ts))::integer AS observed_minutes,
            (count(me.minute_ts) FILTER (WHERE me.natural_qualified))::integer AS natural_qualified_minutes,
            (count(me.minute_ts) FILTER (WHERE me.switch_on))::integer AS switch_on_minutes,
            (count(me.minute_ts) FILTER (WHERE (me.natural_qualified AND me.switch_on)))::integer AS overlap_minutes,
            (count(me.minute_ts) FILTER (WHERE (me.natural_qualified OR me.switch_on)))::integer AS qualified_light_minutes,
            (count(me.minute_ts) FILTER (WHERE ((NOT me.natural_qualified) AND (NOT me.switch_on))))::integer AS below_threshold_off_minutes
           FROM (today_window w
             LEFT JOIN minute_eval me ON (((me.light_key = w.light_key) AND (me.equipment = w.equipment))))
          GROUP BY w.light_key, w.equipment
        ), latest_climate AS (
         SELECT climate.ts,
            climate.dli_today,
            climate.lux,
            climate.outdoor_lux
           FROM public.climate
          WHERE (climate.greenhouse_id = 'vallery'::text)
          ORDER BY climate.ts DESC
         LIMIT 1
        ), latest_equipment AS (
         SELECT DISTINCT ON (equipment_state.equipment) equipment_state.equipment,
            equipment_state.state,
            equipment_state.ts
           FROM public.equipment_state
          WHERE ((equipment_state.greenhouse_id = 'vallery'::text) AND (equipment_state.equipment = ANY (ARRAY['grow_light_main'::text, 'grow_light_grow'::text])))
          ORDER BY equipment_state.equipment, equipment_state.ts DESC
        ), current_firmware_start AS (
         WITH firmware_ordered AS (
                 SELECT diagnostics.ts,
                    diagnostics.firmware_version,
                    lag(diagnostics.firmware_version) OVER (ORDER BY diagnostics.ts) AS previous_firmware_version
                   FROM public.diagnostics
                  WHERE ((diagnostics.firmware_version IS NOT NULL) AND (diagnostics.firmware_version <> ''::text) AND (diagnostics.ts > (now() - '30 days'::interval)))
                ), current_firmware AS (
                 SELECT diagnostics.firmware_version
                   FROM public.diagnostics
                  WHERE ((diagnostics.firmware_version IS NOT NULL) AND (diagnostics.firmware_version <> ''::text))
                  ORDER BY diagnostics.ts DESC
                 LIMIT 1
                )
         SELECT max(fo.ts) AS ts
           FROM (firmware_ordered fo
             CROSS JOIN current_firmware cf)
          WHERE ((fo.firmware_version = cf.firmware_version) AND (fo.previous_firmware_version IS DISTINCT FROM fo.firmware_version))
        ), latest_reason AS (
         SELECT DISTINCT ON (system_state.entity) system_state.entity,
            system_state.value,
            system_state.ts
           FROM public.system_state
          WHERE (system_state.entity = ANY (ARRAY['gl_main_state'::text, 'gl_main_reason'::text, 'gl_grow_state'::text, 'gl_grow_reason'::text]))
          ORDER BY system_state.entity, system_state.ts DESC
        ), latest_occupancy AS (
         SELECT DISTINCT ON (system_state.entity) system_state.entity,
            system_state.value,
            system_state.ts
           FROM public.system_state
          WHERE (system_state.entity = ANY (ARRAY['occupancy'::text, 'occupancy_until'::text]))
          ORDER BY system_state.entity, system_state.ts DESC
        ), occupancy AS (
         SELECT (COALESCE((state.value = 'occupied'::text), false) AND COALESCE(
                CASE
                    WHEN (until_row.value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T'::text) THEN ((until_row.value)::timestamp with time zone > now())
                    ELSE false
                END, false)) AS occupancy_active
           FROM ((( SELECT 1 AS "?column?") seed
             LEFT JOIN latest_occupancy state ON ((state.entity = 'occupancy'::text)))
             LEFT JOIN latest_occupancy until_row ON ((until_row.entity = 'occupancy_until'::text)))
        ), outdoor_staleness AS (
         SELECT COALESCE(( SELECT GREATEST(120, LEAST(1800, (round(setpoint_snapshot.value))::integer)) AS "greatest"
                   FROM public.setpoint_snapshot
                  WHERE ((COALESCE(setpoint_snapshot.greenhouse_id, 'vallery'::text) = 'vallery'::text) AND (setpoint_snapshot.parameter = 'outdoor_staleness_max_s'::text))
                  ORDER BY setpoint_snapshot.ts DESC
                 LIMIT 1), 600) AS max_age_s
        ), joined AS (
         SELECT p.greenhouse_id,
            p.ts,
            p.light_key,
            p.equipment,
            p.target_light_minutes,
            p.start_hour,
            p.cutoff_hour,
            p.lux_on_threshold,
            p.lux_hysteresis,
            p.lux_off_threshold,
            p.min_on_s,
            p.min_off_s,
            p.auto_enabled,
            p.legacy_dli_target,
            p.source_chain,
            p.controller_contract,
            COALESCE(t.qualified_light_minutes, 0) AS qualified_light_minutes,
            COALESCE(t.natural_qualified_minutes, 0) AS natural_qualified_minutes,
            COALESCE(t.switch_on_minutes, 0) AS switch_on_minutes,
            COALESCE(t.overlap_minutes, 0) AS overlap_minutes,
            GREATEST(0, (p.target_light_minutes - COALESCE(t.qualified_light_minutes, 0))) AS remaining_light_minutes,
            c.ts AS climate_ts,
            c.dli_today,
            c.lux AS indoor_lux,
            c.outdoor_lux,
            c.outdoor_lux AS exterior_lux,
            COALESCE(c.outdoor_lux, c.lux, (0.0)::double precision) AS natural_lux,
            (COALESCE(c.outdoor_lux, c.lux, (0.0)::double precision) >= p.lux_on_threshold) AS natural_qualified_now,
            (EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer AS local_hour,
                CASE
                    WHEN (p.start_hour <= p.cutoff_hour) THEN (((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer >= p.start_hour) AND ((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer < p.cutoff_hour))
                    ELSE (((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer >= p.start_hour) OR ((EXTRACT(hour FROM (now() AT TIME ZONE 'America/Denver'::text)))::integer < p.cutoff_hour))
                END AS in_light_window,
            (COALESCE(t.qualified_light_minutes, 0) < p.target_light_minutes) AS minutes_below_target,
            (COALESCE(c.outdoor_lux, c.lux, (0.0)::double precision) < p.lux_on_threshold) AS lux_below_on_threshold,
            (COALESCE(c.outdoor_lux, c.lux, (0.0)::double precision) < p.lux_off_threshold) AS lux_below_off_threshold,
            ((c.outdoor_lux IS NOT NULL) AND (c.ts > (now() - make_interval(secs => (os.max_age_s)::double precision)))) AS exterior_lux_fresh,
            ((c.outdoor_lux IS NOT NULL) AND (c.ts > (now() - make_interval(secs => (os.max_age_s)::double precision))) AND (c.outdoor_lux < p.lux_on_threshold)) AS exterior_lux_below_on_threshold,
            ((c.outdoor_lux IS NOT NULL) AND (c.ts > (now() - make_interval(secs => (os.max_age_s)::double precision))) AND (c.outdoor_lux < p.lux_off_threshold)) AS exterior_lux_below_off_threshold,
            o.occupancy_active,
            COALESCE(e.state, false) AS actual_on,
            state_row.value AS firmware_state,
            reason_row.value AS firmware_reason,
            ((state_row.ts >= COALESCE(( SELECT current_firmware_start.ts
                   FROM current_firmware_start), (now() - '24:00:00'::interval))) AND (reason_row.ts >= COALESCE(( SELECT current_firmware_start.ts
                   FROM current_firmware_start), (now() - '24:00:00'::interval))) AND (state_row.ts > (now() - '00:15:00'::interval)) AND (reason_row.ts > (now() - '00:15:00'::interval))) AS firmware_telemetry_fresh,
            e.ts AS equipment_ts
           FROM (((((((policy p
             LEFT JOIN today t ON (((t.light_key = p.light_key) AND (t.equipment = p.equipment))))
             LEFT JOIN latest_climate c ON (true))
             LEFT JOIN latest_equipment e ON ((e.equipment = p.equipment)))
             LEFT JOIN latest_reason state_row ON ((state_row.entity = (('gl_'::text || p.light_key) || '_state'::text))))
             LEFT JOIN latest_reason reason_row ON ((reason_row.entity = (('gl_'::text || p.light_key) || '_reason'::text))))
             CROSS JOIN occupancy o)
             CROSS JOIN outdoor_staleness os)
        )
 SELECT greenhouse_id,
    ts,
    light_key,
    equipment,
    target_light_minutes,
    start_hour,
    cutoff_hour,
    lux_on_threshold,
    lux_hysteresis,
    lux_off_threshold,
    min_on_s,
    min_off_s,
    auto_enabled,
    legacy_dli_target,
    source_chain,
    controller_contract,
    qualified_light_minutes,
    natural_qualified_minutes,
    switch_on_minutes,
    overlap_minutes,
    remaining_light_minutes,
    climate_ts,
    dli_today,
    indoor_lux,
    outdoor_lux,
    exterior_lux,
    natural_lux,
    natural_qualified_now,
    local_hour,
    in_light_window,
    minutes_below_target,
    lux_below_on_threshold,
    lux_below_off_threshold,
    exterior_lux_fresh,
    exterior_lux_below_on_threshold,
    exterior_lux_below_off_threshold,
    occupancy_active,
    actual_on,
    firmware_state,
    firmware_reason,
    firmware_telemetry_fresh,
    equipment_ts,
    (auto_enabled AND in_light_window AND minutes_below_target AND (lux_below_on_threshold OR ((actual_on OR (firmware_telemetry_fresh AND (upper(COALESCE(firmware_state, ''::text)) = 'ON'::text))) AND lux_below_off_threshold))) AS plant_supplement_demand,
    (auto_enabled AND occupancy_active AND exterior_lux_fresh AND (exterior_lux_below_on_threshold OR ((actual_on OR (firmware_telemetry_fresh AND (upper(COALESCE(firmware_state, ''::text)) = 'ON'::text))) AND exterior_lux_below_off_threshold))) AS occupancy_lux_demand,
    ((auto_enabled AND in_light_window AND minutes_below_target AND (lux_below_on_threshold OR ((actual_on OR (firmware_telemetry_fresh AND (upper(COALESCE(firmware_state, ''::text)) = 'ON'::text))) AND lux_below_off_threshold))) OR (auto_enabled AND occupancy_active AND exterior_lux_fresh AND (exterior_lux_below_on_threshold OR ((actual_on OR (firmware_telemetry_fresh AND (upper(COALESCE(firmware_state, ''::text)) = 'ON'::text))) AND exterior_lux_below_off_threshold)))) AS expected_on
   FROM joined j;


ALTER VIEW public.v_lighting_minutes_status_now OWNER TO verdify;

--
-- Name: VIEW v_lighting_minutes_status_now; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_lighting_minutes_status_now IS 'Current per-circuit qualified-light-minutes policy, plant supplement demand, lux-gated occupancy task-light demand, firmware state, and actual Lutron switch state.';


--
-- Name: v_lighting_qualified_minutes_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_qualified_minutes_daily AS
 WITH policy AS (
         SELECT fn_lighting_minutes_policy.greenhouse_id,
            fn_lighting_minutes_policy.ts,
            fn_lighting_minutes_policy.light_key,
            fn_lighting_minutes_policy.equipment,
            fn_lighting_minutes_policy.target_light_minutes,
            fn_lighting_minutes_policy.start_hour,
            fn_lighting_minutes_policy.cutoff_hour,
            fn_lighting_minutes_policy.lux_on_threshold,
            fn_lighting_minutes_policy.lux_hysteresis,
            fn_lighting_minutes_policy.lux_off_threshold,
            fn_lighting_minutes_policy.min_on_s,
            fn_lighting_minutes_policy.min_off_s,
            fn_lighting_minutes_policy.auto_enabled,
            fn_lighting_minutes_policy.legacy_dli_target,
            fn_lighting_minutes_policy.source_chain,
            fn_lighting_minutes_policy.controller_contract
           FROM public.fn_lighting_minutes_policy(now(), 'vallery'::text) fn_lighting_minutes_policy(greenhouse_id, ts, light_key, equipment, target_light_minutes, start_hour, cutoff_hour, lux_on_threshold, lux_hysteresis, lux_off_threshold, min_on_s, min_off_s, auto_enabled, legacy_dli_target, source_chain, controller_contract)
        ), days AS (
         SELECT (generate_series(((((now() AT TIME ZONE 'America/Denver'::text))::date - 14))::timestamp with time zone, (((now() AT TIME ZONE 'America/Denver'::text))::date)::timestamp with time zone, '1 day'::interval))::date AS local_date
        ), windows AS (
         SELECT d.local_date,
            p.light_key,
            p.equipment,
            p.target_light_minutes,
            p.start_hour,
            p.cutoff_hour,
            p.lux_on_threshold,
            p.lux_hysteresis,
            p.lux_off_threshold,
            ((d.local_date + make_interval(hours => p.start_hour)) AT TIME ZONE 'America/Denver'::text) AS start_ts,
            LEAST(((d.local_date + make_interval(hours => p.cutoff_hour)) AT TIME ZONE 'America/Denver'::text), now()) AS end_ts
           FROM (days d
             CROSS JOIN policy p)
          WHERE (((d.local_date + make_interval(hours => p.start_hour)) AT TIME ZONE 'America/Denver'::text) < now())
        ), lux_min AS (
         SELECT public.time_bucket('00:01:00'::interval, c.ts) AS minute_ts,
            avg(COALESCE(c.outdoor_lux, c.lux)) AS natural_lux
           FROM public.climate c
          WHERE ((c.greenhouse_id = 'vallery'::text) AND (c.ts >= ( SELECT min(windows.start_ts) AS min
                   FROM windows)) AND (c.ts <= ( SELECT max(windows.end_ts) AS max
                   FROM windows)) AND (COALESCE(c.outdoor_lux, c.lux) IS NOT NULL))
          GROUP BY (public.time_bucket('00:01:00'::interval, c.ts))
        ), lux_samples AS (
         SELECT w_1.local_date,
            w_1.light_key,
            w_1.equipment,
            w_1.target_light_minutes,
            w_1.start_hour,
            w_1.cutoff_hour,
            w_1.lux_on_threshold,
            w_1.lux_hysteresis,
            w_1.lux_off_threshold,
            lm.minute_ts,
            lm.natural_lux,
            (lm.natural_lux >= w_1.lux_on_threshold) AS natural_qualified
           FROM (windows w_1
             JOIN lux_min lm ON (((lm.minute_ts >= w_1.start_ts) AND (lm.minute_ts < w_1.end_ts))))
        ), state_seed AS (
         SELECT w_1.local_date,
            w_1.light_key,
            w_1.equipment,
            w_1.start_ts AS ts,
            COALESCE(( SELECT e.state
                   FROM public.equipment_state e
                  WHERE ((e.greenhouse_id = 'vallery'::text) AND (e.equipment = w_1.equipment) AND (e.ts <= w_1.start_ts))
                  ORDER BY e.ts DESC
                 LIMIT 1), false) AS state
           FROM windows w_1
        ), state_events AS (
         SELECT w_1.local_date,
            w_1.light_key,
            w_1.equipment,
            e.ts,
            e.state
           FROM (windows w_1
             JOIN public.equipment_state e ON (((e.greenhouse_id = 'vallery'::text) AND (e.equipment = w_1.equipment) AND (e.ts >= w_1.start_ts) AND (e.ts <= w_1.end_ts))))
        ), state_timeline AS (
         SELECT x.local_date,
            x.light_key,
            x.equipment,
            x.ts,
            x.state,
            lead(x.ts, 1, w_1.end_ts) OVER (PARTITION BY x.local_date, x.light_key, x.equipment ORDER BY x.ts) AS next_ts
           FROM (( SELECT state_seed.local_date,
                    state_seed.light_key,
                    state_seed.equipment,
                    state_seed.ts,
                    state_seed.state
                   FROM state_seed
                UNION ALL
                 SELECT state_events.local_date,
                    state_events.light_key,
                    state_events.equipment,
                    state_events.ts,
                    state_events.state
                   FROM state_events) x
             JOIN windows w_1 ON (((w_1.local_date = x.local_date) AND (w_1.light_key = x.light_key) AND (w_1.equipment = x.equipment))))
        ), state_segments AS (
         SELECT st.local_date,
            st.light_key,
            st.equipment,
            GREATEST(st.ts, w_1.start_ts) AS start_ts,
            LEAST(st.next_ts, w_1.end_ts) AS end_ts
           FROM (state_timeline st
             JOIN windows w_1 ON (((w_1.local_date = st.local_date) AND (w_1.light_key = st.light_key) AND (w_1.equipment = st.equipment))))
          WHERE ((st.state IS TRUE) AND (st.ts < w_1.end_ts) AND (st.next_ts > w_1.start_ts))
        ), switch_minutes AS (
         SELECT w_1.local_date,
            w_1.light_key,
            w_1.equipment,
            (COALESCE(round((sum(EXTRACT(epoch FROM (s_1.end_ts - s_1.start_ts))) / 60.0), 0), (0)::numeric))::integer AS switch_on_minutes
           FROM (windows w_1
             LEFT JOIN state_segments s_1 ON (((s_1.local_date = w_1.local_date) AND (s_1.light_key = w_1.light_key) AND (s_1.equipment = w_1.equipment))))
          GROUP BY w_1.local_date, w_1.light_key, w_1.equipment
        ), minute_join AS (
         SELECT ls.local_date,
            ls.light_key,
            ls.equipment,
            ls.target_light_minutes,
            ls.start_hour,
            ls.cutoff_hour,
            ls.lux_on_threshold,
            ls.lux_hysteresis,
            ls.lux_off_threshold,
            ls.minute_ts,
            ls.natural_lux,
            ls.natural_qualified,
            (s_1.start_ts IS NOT NULL) AS switch_on
           FROM (lux_samples ls
             LEFT JOIN state_segments s_1 ON (((s_1.local_date = ls.local_date) AND (s_1.light_key = ls.light_key) AND (s_1.equipment = ls.equipment) AND (s_1.start_ts < (ls.minute_ts + '00:01:00'::interval)) AND (s_1.end_ts > ls.minute_ts))))
        ), minute_rollup AS (
         SELECT minute_join.local_date,
            minute_join.light_key,
            minute_join.equipment,
            max(minute_join.target_light_minutes) AS target_light_minutes,
            (count(DISTINCT minute_join.minute_ts))::integer AS observed_minutes,
            (count(DISTINCT minute_join.minute_ts) FILTER (WHERE minute_join.natural_qualified))::integer AS natural_qualified_minutes,
            (count(DISTINCT minute_join.minute_ts) FILTER (WHERE (minute_join.natural_qualified AND minute_join.switch_on)))::integer AS overlap_minutes,
            (count(DISTINCT minute_join.minute_ts) FILTER (WHERE (minute_join.natural_qualified OR minute_join.switch_on)))::integer AS qualified_light_minutes,
            (count(DISTINCT minute_join.minute_ts) FILTER (WHERE ((NOT minute_join.natural_qualified) AND (NOT minute_join.switch_on))))::integer AS below_threshold_off_minutes,
            round((avg(minute_join.natural_lux))::numeric, 0) AS avg_natural_lux,
            max(minute_join.start_hour) AS start_hour,
            max(minute_join.cutoff_hour) AS cutoff_hour,
            max(minute_join.lux_on_threshold) AS lux_on_threshold,
            max(minute_join.lux_hysteresis) AS lux_hysteresis,
            max(minute_join.lux_off_threshold) AS lux_off_threshold
           FROM minute_join
          GROUP BY minute_join.local_date, minute_join.light_key, minute_join.equipment
        )
 SELECT w.local_date,
    w.light_key,
    w.equipment,
    w.target_light_minutes,
    COALESCE(m.observed_minutes, 0) AS observed_minutes,
    COALESCE(m.natural_qualified_minutes, 0) AS natural_qualified_minutes,
    COALESCE(s.switch_on_minutes, 0) AS switch_on_minutes,
    COALESCE(m.overlap_minutes, 0) AS overlap_minutes,
    ((COALESCE(m.natural_qualified_minutes, 0) + COALESCE(s.switch_on_minutes, 0)) - COALESCE(m.overlap_minutes, 0)) AS qualified_light_minutes,
    GREATEST(0, (w.target_light_minutes - ((COALESCE(m.natural_qualified_minutes, 0) + COALESCE(s.switch_on_minutes, 0)) - COALESCE(m.overlap_minutes, 0)))) AS remaining_light_minutes,
    COALESCE(m.below_threshold_off_minutes, 0) AS below_threshold_off_minutes,
    m.avg_natural_lux,
    w.start_hour,
    w.cutoff_hour,
    w.lux_on_threshold,
    w.lux_hysteresis,
    w.lux_off_threshold,
    now() AS computed_at
   FROM ((windows w
     LEFT JOIN minute_rollup m ON (((m.local_date = w.local_date) AND (m.light_key = w.light_key) AND (m.equipment = w.equipment))))
     LEFT JOIN switch_minutes s ON (((s.local_date = w.local_date) AND (s.light_key = w.light_key) AND (s.equipment = w.equipment))));


