--
-- Name: v_lighting_status_now; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_status_now AS
 WITH policy AS (
         SELECT fn_lighting_policy.greenhouse_id,
            fn_lighting_policy.ts,
            fn_lighting_policy.local_date,
            fn_lighting_policy.target_dli,
            fn_lighting_policy.target_ppfd_umol_m2_s,
            fn_lighting_policy.target_light_hours,
            fn_lighting_policy.sunrise_hour,
            fn_lighting_policy.natural_sunset_hour,
            fn_lighting_policy.cutoff_hour,
            fn_lighting_policy.max_crop_name,
            fn_lighting_policy.max_crop_stage,
            fn_lighting_policy.source_chain,
            fn_lighting_policy.controller_contract
           FROM public.fn_lighting_policy(now(), 'vallery'::text) fn_lighting_policy(greenhouse_id, ts, local_date, target_dli, target_ppfd_umol_m2_s, target_light_hours, sunrise_hour, natural_sunset_hour, cutoff_hour, max_crop_name, max_crop_stage, source_chain, controller_contract)
        ), circuits AS (
         SELECT v_lighting_circuit_status_now.greenhouse_id,
            v_lighting_circuit_status_now.ts,
            v_lighting_circuit_status_now.light_key,
            v_lighting_circuit_status_now.equipment,
            v_lighting_circuit_status_now.dli_target,
            v_lighting_circuit_status_now.start_hour,
            v_lighting_circuit_status_now.cutoff_hour,
            v_lighting_circuit_status_now.lux_on_threshold,
            v_lighting_circuit_status_now.lux_hysteresis,
            v_lighting_circuit_status_now.lux_off_threshold,
            v_lighting_circuit_status_now.min_on_s,
            v_lighting_circuit_status_now.min_off_s,
            v_lighting_circuit_status_now.auto_enabled,
            v_lighting_circuit_status_now.source_chain,
            v_lighting_circuit_status_now.controller_contract,
            v_lighting_circuit_status_now.climate_ts,
            v_lighting_circuit_status_now.dli_today,
            v_lighting_circuit_status_now.indoor_lux,
            v_lighting_circuit_status_now.outdoor_lux,
            v_lighting_circuit_status_now.natural_lux,
            v_lighting_circuit_status_now.local_hour,
            v_lighting_circuit_status_now.in_light_window,
            v_lighting_circuit_status_now.dli_below_target,
            v_lighting_circuit_status_now.lux_below_on_threshold,
            v_lighting_circuit_status_now.lux_below_off_threshold,
            v_lighting_circuit_status_now.expected_on,
            v_lighting_circuit_status_now.actual_on,
            v_lighting_circuit_status_now.firmware_state,
            v_lighting_circuit_status_now.firmware_reason,
            v_lighting_circuit_status_now.equipment_ts,
            v_lighting_circuit_status_now.firmware_state_raw,
            v_lighting_circuit_status_now.firmware_reason_raw,
            v_lighting_circuit_status_now.firmware_state_ts,
            v_lighting_circuit_status_now.firmware_reason_ts,
            v_lighting_circuit_status_now.firmware_telemetry_fresh
           FROM public.v_lighting_circuit_status_now
        ), main AS (
         SELECT circuits.greenhouse_id,
            circuits.ts,
            circuits.light_key,
            circuits.equipment,
            circuits.dli_target,
            circuits.start_hour,
            circuits.cutoff_hour,
            circuits.lux_on_threshold,
            circuits.lux_hysteresis,
            circuits.lux_off_threshold,
            circuits.min_on_s,
            circuits.min_off_s,
            circuits.auto_enabled,
            circuits.source_chain,
            circuits.controller_contract,
            circuits.climate_ts,
            circuits.dli_today,
            circuits.indoor_lux,
            circuits.outdoor_lux,
            circuits.natural_lux,
            circuits.local_hour,
            circuits.in_light_window,
            circuits.dli_below_target,
            circuits.lux_below_on_threshold,
            circuits.lux_below_off_threshold,
            circuits.expected_on,
            circuits.actual_on,
            circuits.firmware_state,
            circuits.firmware_reason,
            circuits.equipment_ts,
            circuits.firmware_state_raw,
            circuits.firmware_reason_raw,
            circuits.firmware_state_ts,
            circuits.firmware_reason_ts,
            circuits.firmware_telemetry_fresh
           FROM circuits
          WHERE (circuits.light_key = 'main'::text)
        ), grow AS (
         SELECT circuits.greenhouse_id,
            circuits.ts,
            circuits.light_key,
            circuits.equipment,
            circuits.dli_target,
            circuits.start_hour,
            circuits.cutoff_hour,
            circuits.lux_on_threshold,
            circuits.lux_hysteresis,
            circuits.lux_off_threshold,
            circuits.min_on_s,
            circuits.min_off_s,
            circuits.auto_enabled,
            circuits.source_chain,
            circuits.controller_contract,
            circuits.climate_ts,
            circuits.dli_today,
            circuits.indoor_lux,
            circuits.outdoor_lux,
            circuits.natural_lux,
            circuits.local_hour,
            circuits.in_light_window,
            circuits.dli_below_target,
            circuits.lux_below_on_threshold,
            circuits.lux_below_off_threshold,
            circuits.expected_on,
            circuits.actual_on,
            circuits.firmware_state,
            circuits.firmware_reason,
            circuits.equipment_ts,
            circuits.firmware_state_raw,
            circuits.firmware_reason_raw,
            circuits.firmware_state_ts,
            circuits.firmware_reason_ts,
            circuits.firmware_telemetry_fresh
           FROM circuits
          WHERE (circuits.light_key = 'grow'::text)
        )
 SELECT policy.greenhouse_id,
    policy.ts,
    policy.local_date,
    policy.target_dli,
    policy.target_ppfd_umol_m2_s,
    policy.target_light_hours,
    policy.sunrise_hour,
    policy.natural_sunset_hour,
    policy.cutoff_hour,
    policy.max_crop_name,
    policy.max_crop_stage,
    policy.source_chain,
    policy.controller_contract,
    main.climate_ts,
    main.dli_today,
    main.indoor_lux AS lux,
    main.outdoor_lux,
    main.lux_on_threshold AS gl_lux_threshold,
    main.lux_hysteresis AS gl_lux_hysteresis,
    main.actual_on AS grow_light_main_on,
    grow.actual_on AS grow_light_grow_on,
    main.local_hour,
    main.in_light_window,
    main.dli_below_target,
    main.lux_below_on_threshold AS lux_below_threshold,
    (main.expected_on OR grow.expected_on) AS expected_lights_on,
    main.dli_target AS main_dli_target,
    main.start_hour AS main_start_hour,
    main.cutoff_hour AS main_cutoff_hour,
    main.lux_on_threshold AS main_lux_on_threshold,
    main.lux_off_threshold AS main_lux_off_threshold,
    main.lux_hysteresis AS main_lux_hysteresis,
    main.expected_on AS main_expected_on,
    main.firmware_state AS main_firmware_state,
    main.firmware_reason AS main_firmware_reason,
    grow.dli_target AS grow_dli_target,
    grow.start_hour AS grow_start_hour,
    grow.cutoff_hour AS grow_cutoff_hour,
    grow.lux_on_threshold AS grow_lux_on_threshold,
    grow.lux_off_threshold AS grow_lux_off_threshold,
    grow.lux_hysteresis AS grow_lux_hysteresis,
    grow.expected_on AS grow_expected_on,
    grow.firmware_state AS grow_firmware_state,
    grow.firmware_reason AS grow_firmware_reason,
    main.firmware_state_ts AS main_firmware_state_ts,
    main.firmware_reason_ts AS main_firmware_reason_ts,
    main.firmware_telemetry_fresh AS main_firmware_telemetry_fresh,
    grow.firmware_state_ts AS grow_firmware_state_ts,
    grow.firmware_reason_ts AS grow_firmware_reason_ts,
    grow.firmware_telemetry_fresh AS grow_firmware_telemetry_fresh
   FROM ((policy
     CROSS JOIN main)
     CROSS JOIN grow);


