--

COMMENT ON VIEW public.v_lighting_status_now IS 'Compatibility one-row lighting status with per-circuit policy, expected state, Lutron state, and firmware telemetry freshness.';


--
-- Name: v_lighting_traceability_now; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_lighting_traceability_now AS
 WITH status AS (
         SELECT v_lighting_minutes_status_now.greenhouse_id,
            v_lighting_minutes_status_now.ts,
            v_lighting_minutes_status_now.light_key,
            v_lighting_minutes_status_now.equipment,
            v_lighting_minutes_status_now.target_light_minutes,
            v_lighting_minutes_status_now.start_hour,
            v_lighting_minutes_status_now.cutoff_hour,
            v_lighting_minutes_status_now.lux_on_threshold,
            v_lighting_minutes_status_now.lux_hysteresis,
            v_lighting_minutes_status_now.lux_off_threshold,
            v_lighting_minutes_status_now.min_on_s,
            v_lighting_minutes_status_now.min_off_s,
            v_lighting_minutes_status_now.auto_enabled,
            v_lighting_minutes_status_now.legacy_dli_target,
            v_lighting_minutes_status_now.source_chain,
            v_lighting_minutes_status_now.controller_contract,
            v_lighting_minutes_status_now.qualified_light_minutes,
            v_lighting_minutes_status_now.natural_qualified_minutes,
            v_lighting_minutes_status_now.switch_on_minutes,
            v_lighting_minutes_status_now.overlap_minutes,
            v_lighting_minutes_status_now.remaining_light_minutes,
            v_lighting_minutes_status_now.climate_ts,
            v_lighting_minutes_status_now.dli_today,
            v_lighting_minutes_status_now.indoor_lux,
            v_lighting_minutes_status_now.outdoor_lux,
            v_lighting_minutes_status_now.exterior_lux,
            v_lighting_minutes_status_now.natural_lux,
            v_lighting_minutes_status_now.natural_qualified_now,
            v_lighting_minutes_status_now.local_hour,
            v_lighting_minutes_status_now.in_light_window,
            v_lighting_minutes_status_now.minutes_below_target,
            v_lighting_minutes_status_now.lux_below_on_threshold,
            v_lighting_minutes_status_now.lux_below_off_threshold,
            v_lighting_minutes_status_now.exterior_lux_fresh,
            v_lighting_minutes_status_now.exterior_lux_below_on_threshold,
            v_lighting_minutes_status_now.exterior_lux_below_off_threshold,
            v_lighting_minutes_status_now.occupancy_active,
            v_lighting_minutes_status_now.actual_on,
            v_lighting_minutes_status_now.firmware_state,
            v_lighting_minutes_status_now.firmware_reason,
            v_lighting_minutes_status_now.firmware_telemetry_fresh,
            v_lighting_minutes_status_now.equipment_ts,
            v_lighting_minutes_status_now.plant_supplement_demand,
            v_lighting_minutes_status_now.occupancy_lux_demand,
            v_lighting_minutes_status_now.expected_on
           FROM public.v_lighting_minutes_status_now
        ), latest_desired AS (
         SELECT DISTINCT ON (setpoint_changes.parameter) setpoint_changes.parameter,
            setpoint_changes.value,
            setpoint_changes.delivery_status,
            setpoint_changes.ts
           FROM public.setpoint_changes
          WHERE ((COALESCE(setpoint_changes.greenhouse_id, 'vallery'::text) = 'vallery'::text) AND (COALESCE(setpoint_changes.source, ''::text) <> 'esp32'::text))
          ORDER BY setpoint_changes.parameter, setpoint_changes.ts DESC
        ), latest_cfg AS (
         SELECT DISTINCT ON (setpoint_snapshot.parameter) setpoint_snapshot.parameter,
            setpoint_snapshot.value,
            setpoint_snapshot.ts
           FROM public.setpoint_snapshot
          WHERE (COALESCE(setpoint_snapshot.greenhouse_id, 'vallery'::text) = 'vallery'::text)
          ORDER BY setpoint_snapshot.parameter, setpoint_snapshot.ts DESC
        ), latest_decision AS (
         SELECT DISTINCT ON (system_state.entity) system_state.entity,
            system_state.value,
            system_state.ts
           FROM public.system_state
          WHERE (system_state.entity = ANY (ARRAY['gl_main_decision_epoch'::text, 'gl_grow_decision_epoch'::text]))
          ORDER BY system_state.entity, system_state.ts DESC
        )
 SELECT s.greenhouse_id,
    s.ts,
    s.light_key,
    s.equipment,
    s.target_light_minutes,
    s.start_hour,
    s.cutoff_hour,
    s.lux_on_threshold,
    s.lux_hysteresis,
    s.lux_off_threshold,
    s.min_on_s,
    s.min_off_s,
    s.auto_enabled,
    s.legacy_dli_target,
    s.source_chain,
    s.controller_contract,
    s.qualified_light_minutes,
    s.natural_qualified_minutes,
    s.switch_on_minutes,
    s.overlap_minutes,
    s.remaining_light_minutes,
    s.climate_ts,
    s.dli_today,
    s.indoor_lux,
    s.outdoor_lux,
    s.exterior_lux,
    s.natural_lux,
    s.natural_qualified_now,
    s.local_hour,
    s.in_light_window,
    s.minutes_below_target,
    s.lux_below_on_threshold,
    s.lux_below_off_threshold,
    s.exterior_lux_fresh,
    s.exterior_lux_below_on_threshold,
    s.exterior_lux_below_off_threshold,
    s.occupancy_active,
    s.actual_on,
    s.firmware_state,
    s.firmware_reason,
    s.firmware_telemetry_fresh,
    s.equipment_ts,
    s.plant_supplement_demand,
    s.occupancy_lux_demand,
    s.expected_on,
    cfg_target.value AS cfg_target_light_minutes,
    cfg_lux.value AS cfg_lux_on_threshold,
    cfg_hyst.value AS cfg_lux_hysteresis,
    (cfg_auto.value >= (0.5)::double precision) AS cfg_auto_enabled,
    cfg_auto.ts AS cfg_auto_ts,
    desired_target.value AS desired_target_light_minutes,
    desired_lux.value AS desired_lux_on_threshold,
    desired_hyst.value AS desired_lux_hysteresis,
    (desired_auto.value >= (0.5)::double precision) AS desired_auto_enabled,
    desired_auto.delivery_status AS desired_auto_delivery_status,
    desired_auto.ts AS desired_auto_ts,
        CASE
            WHEN (decision.value ~ '^[0-9]+([.]0+)?$'::text) THEN (round((decision.value)::numeric))::bigint
            ELSE NULL::bigint
        END AS firmware_decision_epoch,
    decision.ts AS firmware_decision_ts,
    (decision.ts > (now() - '00:15:00'::interval)) AS firmware_decision_fresh,
    ((NOT (s.auto_enabled IS DISTINCT FROM (cfg_auto.value >= (0.5)::double precision))) AND (NOT (s.target_light_minutes IS DISTINCT FROM (round(cfg_target.value))::integer)) AND COALESCE((abs((s.lux_on_threshold - cfg_lux.value)) < (0.5)::double precision), false) AND COALESCE((abs((s.lux_hysteresis - cfg_hyst.value)) < (0.5)::double precision), false)) AS policy_matches_cfg
   FROM (((((((((status s
     LEFT JOIN latest_cfg cfg_target ON ((cfg_target.parameter = (('gl_'::text || s.light_key) || '_target_light_minutes'::text))))
     LEFT JOIN latest_cfg cfg_lux ON ((cfg_lux.parameter = (('gl_'::text || s.light_key) || '_lux_threshold'::text))))
     LEFT JOIN latest_cfg cfg_hyst ON ((cfg_hyst.parameter = (('gl_'::text || s.light_key) || '_lux_hysteresis'::text))))
     LEFT JOIN latest_cfg cfg_auto ON ((cfg_auto.parameter = (('sw_gl_'::text || s.light_key) || '_auto_mode'::text))))
     LEFT JOIN latest_desired desired_target ON ((desired_target.parameter = (('gl_'::text || s.light_key) || '_target_light_minutes'::text))))
     LEFT JOIN latest_desired desired_lux ON ((desired_lux.parameter = (('gl_'::text || s.light_key) || '_lux_threshold'::text))))
     LEFT JOIN latest_desired desired_hyst ON ((desired_hyst.parameter = (('gl_'::text || s.light_key) || '_lux_hysteresis'::text))))
     LEFT JOIN latest_desired desired_auto ON ((desired_auto.parameter = (('sw_gl_'::text || s.light_key) || '_auto_mode'::text))))
     LEFT JOIN latest_decision decision ON ((decision.entity = (('gl_'::text || s.light_key) || '_decision_epoch'::text))));


ALTER VIEW public.v_lighting_traceability_now OWNER TO verdify;

--
-- Name: VIEW v_lighting_traceability_now; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_lighting_traceability_now IS 'Lighting policy traceability split into plant supplement demand, lux-gated occupancy task-light demand, desired setpoint rows, confirmed cfg readbacks, exact firmware decision epoch text, and physical Lutron state.';


--
-- Name: v_mister_effectiveness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_mister_effectiveness AS
 WITH mister_events AS (
         SELECT equipment_state.ts,
            equipment_state.equipment,
            equipment_state.state,
            lead(equipment_state.ts) OVER (PARTITION BY equipment_state.equipment ORDER BY equipment_state.ts) AS next_ts,
            lead(equipment_state.state) OVER (PARTITION BY equipment_state.equipment ORDER BY equipment_state.ts) AS next_state
           FROM public.equipment_state
          WHERE ((equipment_state.equipment = ANY (ARRAY['mister_south'::text, 'mister_west'::text, 'mister_center'::text])) AND (equipment_state.ts > (now() - '14 days'::interval)))
        ), mister_cycles AS (
         SELECT mister_events.ts AS on_ts,
            mister_events.equipment,
            mister_events.next_ts AS off_ts,
            (EXTRACT(epoch FROM (mister_events.next_ts - mister_events.ts)))::integer AS duration_s
           FROM mister_events
          WHERE ((mister_events.state = true) AND (mister_events.next_state = false) AND ((mister_events.next_ts - mister_events.ts) < '00:30:00'::interval) AND ((mister_events.next_ts - mister_events.ts) > '00:00:05'::interval))
        )
 SELECT mc.on_ts,
    mc.equipment,
    mc.duration_s,
    round((vpd_before.vpd)::numeric, 2) AS vpd_before,
    round((vpd_after.vpd)::numeric, 2) AS vpd_after,
    round(((vpd_before.vpd - vpd_after.vpd))::numeric, 2) AS vpd_delta,
    round((outdoor.outdoor_temp)::numeric, 1) AS outdoor_temp_f,
    round((outdoor.outdoor_rh)::numeric, 0) AS outdoor_rh_pct
   FROM (((mister_cycles mc
     LEFT JOIN LATERAL ( SELECT climate.vpd_avg AS vpd
           FROM public.climate
          WHERE ((climate.ts <= mc.on_ts) AND (climate.vpd_avg IS NOT NULL))
          ORDER BY climate.ts DESC
         LIMIT 1) vpd_before ON (true))
     LEFT JOIN LATERAL ( SELECT climate.vpd_avg AS vpd
           FROM public.climate
          WHERE ((climate.ts >= mc.off_ts) AND (climate.vpd_avg IS NOT NULL))
          ORDER BY climate.ts
         LIMIT 1) vpd_after ON (true))
     LEFT JOIN LATERAL ( SELECT climate.outdoor_temp_f AS outdoor_temp,
            climate.outdoor_rh_pct AS outdoor_rh
           FROM public.climate
          WHERE ((climate.ts <= mc.on_ts) AND (climate.outdoor_temp_f IS NOT NULL))
          ORDER BY climate.ts DESC
         LIMIT 1) outdoor ON (true))
  ORDER BY mc.on_ts DESC;


ALTER VIEW public.v_mister_effectiveness OWNER TO verdify;

--
-- Name: VIEW v_mister_effectiveness; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_mister_effectiveness IS 'VPD before/after each misting cycle with outdoor context. vpd_delta > 0 = improvement.';


--
-- Name: v_mister_zone_effectiveness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_mister_zone_effectiveness AS
 WITH starts AS (
         SELECT equipment_state.ts AS on_ts,
            equipment_state.equipment,
                CASE equipment_state.equipment
                    WHEN 'mister_south'::text THEN 'south'::text
                    WHEN 'mister_west'::text THEN 'west'::text
                    WHEN 'mister_center'::text THEN 'center'::text
                    ELSE NULL::text
                END AS zone,
            lead(equipment_state.ts) OVER (PARTITION BY equipment_state.equipment ORDER BY equipment_state.ts) AS off_ts
           FROM public.equipment_state
          WHERE ((equipment_state.equipment = ANY (ARRAY['mister_south'::text, 'mister_west'::text, 'mister_center'::text])) AND (equipment_state.state = true) AND (equipment_state.ts > (now() - '30 days'::interval)))
        )
 SELECT s.on_ts,
    s.equipment,
    s.zone,
    (EXTRACT(epoch FROM (s.off_ts - s.on_ts)))::integer AS duration_s,
    before_vpd.vpd AS zone_vpd_before,
    after_vpd.vpd AS zone_vpd_after,
    round(((before_vpd.vpd - after_vpd.vpd))::numeric, 3) AS zone_vpd_delta
   FROM ((starts s
     LEFT JOIN LATERAL ( SELECT
                CASE s.zone
                    WHEN 'south'::text THEN climate.vpd_south
                    WHEN 'west'::text THEN climate.vpd_west
                    ELSE climate.vpd_avg
                END AS vpd
           FROM public.climate
          WHERE (climate.ts <= s.on_ts)
          ORDER BY climate.ts DESC
         LIMIT 1) before_vpd ON (true))
     LEFT JOIN LATERAL ( SELECT
                CASE s.zone
                    WHEN 'south'::text THEN climate.vpd_south
                    WHEN 'west'::text THEN climate.vpd_west
                    ELSE climate.vpd_avg
                END AS vpd
           FROM public.climate
          WHERE (climate.ts >= (COALESCE(s.off_ts, s.on_ts) + '00:05:00'::interval))
          ORDER BY climate.ts
         LIMIT 1) after_vpd ON (true))
  WHERE (s.off_ts IS NOT NULL);


ALTER VIEW public.v_mister_zone_effectiveness OWNER TO verdify;

--
-- Name: VIEW v_mister_zone_effectiveness; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_mister_zone_effectiveness IS 'Mister on-events with zone-local VPD before and after the pulse. Center uses greenhouse average until a center VPD sensor exists.';


--
-- Name: v_mister_fairness_7d; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_mister_fairness_7d AS
 WITH bounds AS (
         SELECT (now() - '7 days'::interval) AS start_ts,
            now() AS end_ts
        ), zone_map AS (
         SELECT z.equipment,
            z.zone
           FROM ( VALUES ('mister_south'::text,'south'::text), ('mister_west'::text,'west'::text), ('mister_center'::text,'center'::text)) z(equipment, zone)
        ), mister_set AS (
         SELECT DISTINCT es.greenhouse_id,
            z.equipment,
            z.zone
           FROM (public.equipment_state es
             JOIN zone_map z ON ((z.equipment = es.equipment)))
        ), seed AS (
         SELECT DISTINCT ON (ms.greenhouse_id, ms.equipment) ms.greenhouse_id,
            ms.equipment,
            ms.zone,
            b.start_ts AS ts,
            COALESCE(es.state, false) AS state
           FROM ((mister_set ms
             CROSS JOIN bounds b)
             LEFT JOIN public.equipment_state es ON (((es.greenhouse_id = ms.greenhouse_id) AND (es.equipment = ms.equipment) AND (es.ts <= b.start_ts))))
          ORDER BY ms.greenhouse_id, ms.equipment, es.ts DESC NULLS LAST
        ), events AS (
         SELECT seed.greenhouse_id,
            seed.equipment,
            seed.zone,
            seed.ts,
            seed.state
           FROM seed
        UNION ALL
         SELECT es.greenhouse_id,
            es.equipment,
            z.zone,
            es.ts,
            es.state
           FROM ((public.equipment_state es
             JOIN zone_map z ON ((z.equipment = es.equipment)))
             CROSS JOIN bounds b)
          WHERE ((es.ts > b.start_ts) AND (es.ts <= b.end_ts))
        ), ordered AS (
         SELECT e_1.greenhouse_id,
            e_1.equipment,
            e_1.zone,
            e_1.ts,
            e_1.state,
            lag(e_1.state) OVER (PARTITION BY e_1.greenhouse_id, e_1.equipment ORDER BY e_1.ts) AS prev_state,
            lead(e_1.ts) OVER (PARTITION BY e_1.greenhouse_id, e_1.equipment ORDER BY e_1.ts) AS next_ts
           FROM events e_1
        ), rollup AS (
         SELECT o.greenhouse_id,
            o.equipment,
            o.zone,
            sum((EXTRACT(epoch FROM (LEAST(COALESCE(o.next_ts, b.end_ts), b.end_ts) - GREATEST(o.ts, b.start_ts))) / 60.0)) FILTER (WHERE (o.state IS TRUE)) AS runtime_min,
            count(*) FILTER (WHERE ((o.state IS TRUE) AND (COALESCE(o.prev_state, false) IS FALSE) AND (o.ts > b.start_ts))) AS cycles
           FROM (ordered o
             CROSS JOIN bounds b)
          WHERE ((o.ts < b.end_ts) AND (COALESCE(o.next_ts, b.end_ts) > b.start_ts))
          GROUP BY o.greenhouse_id, o.equipment, o.zone
        ), totals AS (
         SELECT rollup.greenhouse_id,
            sum(COALESCE(rollup.runtime_min, (0)::numeric)) AS total_runtime_min,
            sum(COALESCE(rollup.cycles, (0)::bigint)) AS total_cycles
           FROM rollup
          GROUP BY rollup.greenhouse_id
        ), effect AS (
         SELECT 'vallery'::text AS greenhouse_id,
            v_mister_zone_effectiveness.zone,
            count(*) AS effect_samples,
            round(avg(v_mister_zone_effectiveness.zone_vpd_delta), 3) AS avg_vpd_delta_kpa
           FROM public.v_mister_zone_effectiveness
          WHERE (v_mister_zone_effectiveness.on_ts > (now() - '7 days'::interval))
          GROUP BY 'vallery'::text, v_mister_zone_effectiveness.zone
        ), fairness AS (
         SELECT daily_summary.greenhouse_id,
            COALESCE(sum(daily_summary.mister_fairness_overrides_today), (0)::bigint) AS fairness_overrides
           FROM public.daily_summary
          WHERE (daily_summary.date >= (((now() AT TIME ZONE 'America/Denver'::text))::date - 6))
          GROUP BY daily_summary.greenhouse_id
        )
 SELECT r.greenhouse_id,
    r.zone,
    r.equipment,
    round(COALESCE(r.runtime_min, (0)::numeric), 1) AS runtime_minutes,
    COALESCE(r.cycles, (0)::bigint) AS cycles,
    round(((100.0 * COALESCE(r.runtime_min, (0)::numeric)) / NULLIF(t.total_runtime_min, (0)::numeric)), 1) AS runtime_share_pct,
    round(((100.0 * (COALESCE(r.cycles, (0)::bigint))::numeric) / NULLIF(t.total_cycles, (0)::numeric)), 1) AS cycle_share_pct,
    e.effect_samples,
    e.avg_vpd_delta_kpa,
    COALESCE(f.fairness_overrides, (0)::bigint) AS fairness_overrides_7d
   FROM (((rollup r
     JOIN totals t ON ((t.greenhouse_id = r.greenhouse_id)))
     LEFT JOIN effect e ON (((e.greenhouse_id = r.greenhouse_id) AND (e.zone = r.zone))))
     LEFT JOIN fairness f ON ((f.greenhouse_id = r.greenhouse_id)))
  ORDER BY r.greenhouse_id, r.zone;


ALTER VIEW public.v_mister_fairness_7d OWNER TO verdify;

--
-- Name: VIEW v_mister_fairness_7d; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_mister_fairness_7d IS 'Rolling seven-day mister zone runtime, cycle share, effectiveness, and firmware fairness override count for resource-balance audits.';


--
-- Name: v_monthly_summary; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_monthly_summary AS
 SELECT (date_trunc('month'::text, (date)::timestamp with time zone))::date AS month_start,
    count(*) AS days,
    round((avg(temp_avg))::numeric, 1) AS temp_avg,
    round((min(temp_min))::numeric, 1) AS temp_min,
    round((max(temp_max))::numeric, 1) AS temp_max,
    round((avg(rh_avg))::numeric, 1) AS rh_avg,
    round((min(rh_min))::numeric, 1) AS rh_min,
    round((max(rh_max))::numeric, 1) AS rh_max,
    round((avg(vpd_avg))::numeric, 2) AS vpd_avg,
    round((min(vpd_min))::numeric, 2) AS vpd_min,
    round((max(vpd_max))::numeric, 2) AS vpd_max,
    round((avg(dli_final))::numeric, 1) AS dli_avg,
    round((avg(co2_avg))::numeric, 0) AS co2_avg,
    round((min(outdoor_temp_min))::numeric, 1) AS outdoor_temp_min,
    round((max(outdoor_temp_max))::numeric, 1) AS outdoor_temp_max,
    round((sum(COALESCE(stress_hours_heat, (0)::double precision)))::numeric, 1) AS stress_hours_heat,
    round((sum(COALESCE(stress_hours_cold, (0)::double precision)))::numeric, 1) AS stress_hours_cold,
    round((sum(COALESCE(stress_hours_vpd_high, (0)::double precision)))::numeric, 1) AS stress_hours_vpd_high,
    round((sum(COALESCE(stress_hours_vpd_low, (0)::double precision)))::numeric, 1) AS stress_hours_vpd_low,
    round((sum(COALESCE(water_used_gal, (0)::double precision)))::numeric, 0) AS total_water_gal,
    round((sum(COALESCE(mister_water_gal, (0)::double precision)))::numeric, 0) AS mister_water_gal,
    round((sum(COALESCE(kwh_total, kwh_estimated, (0)::double precision)))::numeric, 1) AS kwh_total,
    round((sum(COALESCE(therms_estimated, (0)::double precision)))::numeric, 2) AS therms_total,
    round((sum(COALESCE(cost_electric, (0)::double precision)))::numeric, 2) AS cost_electric,
    round((sum(COALESCE(cost_gas, (0)::double precision)))::numeric, 2) AS cost_gas,
    round((sum(COALESCE(cost_water, (0)::double precision)))::numeric, 2) AS cost_water,
    round((sum(COALESCE(cost_total, (0)::double precision)))::numeric, 2) AS total_cost,
    round(((sum(COALESCE(runtime_heat1_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_heat1_h,
    round(((sum(COALESCE(runtime_heat2_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_heat2_h,
    round(((sum(COALESCE((runtime_fan1_min + runtime_fan2_min), (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_fans_h,
    round(((sum(COALESCE(runtime_fog_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_fog_h,
    round(((sum(COALESCE(runtime_vent_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_vent_h,
    round(((sum(COALESCE(runtime_grow_light_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_grow_light_h,
    round((sum(COALESCE(((runtime_mister_south_h + runtime_mister_west_h) + runtime_mister_center_h), (0)::double precision)))::numeric, 1) AS runtime_misters_h,
    sum((COALESCE(cycles_heat1, 0) + COALESCE(cycles_heat2, 0))) AS cycles_heat,
    sum((COALESCE(cycles_fan1, 0) + COALESCE(cycles_fan2, 0))) AS cycles_fans,
    sum(COALESCE(cycles_fog, 0)) AS cycles_fog,
    sum(COALESCE(cycles_vent, 0)) AS cycles_vent
   FROM public.daily_summary
  WHERE (temp_avg IS NOT NULL)
  GROUP BY (date_trunc('month'::text, (date)::timestamp with time zone))
  ORDER BY ((date_trunc('month'::text, (date)::timestamp with time zone))::date);


ALTER VIEW public.v_monthly_summary OWNER TO verdify;

--
-- Name: VIEW v_monthly_summary; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_monthly_summary IS 'Calendar month aggregation of daily_summary.';


--
-- Name: v_nutrient_lab_status; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_nutrient_lab_status AS
 WITH latest_hydro AS (
         SELECT DISTINCT ON (COALESCE(climate.greenhouse_id, 'vallery'::text)) COALESCE(climate.greenhouse_id, 'vallery'::text) AS greenhouse_id,
            climate.ts,
            climate.hydro_ph,
            climate.hydro_ec_us_cm,
            climate.hydro_tds_ppm,
            climate.hydro_orp_mv,
            climate.hydro_battery_pct
           FROM public.climate
          WHERE ((climate.hydro_ph IS NOT NULL) OR (climate.hydro_ec_us_cm IS NOT NULL))
          ORDER BY COALESCE(climate.greenhouse_id, 'vallery'::text), climate.ts DESC
        ), latest_lab AS (
         SELECT DISTINCT ON (lab_results.greenhouse_id, lab_results.sample_type, COALESCE(lab_results.zone, ''::text)) lab_results.greenhouse_id,
            lab_results.sample_type,
            lab_results.zone,
            lab_results.crop_id,
            lab_results.sampled_at,
            lab_results.ph,
            lab_results.ec_ms_cm,
            lab_results.recipe_id
           FROM public.lab_results
          ORDER BY lab_results.greenhouse_id, lab_results.sample_type, COALESCE(lab_results.zone, ''::text), lab_results.sampled_at DESC NULLS LAST, lab_results.ts DESC NULLS LAST
        )
 SELECT h.greenhouse_id,
    h.ts AS hydro_ts,
    h.hydro_ph,
    h.hydro_ec_us_cm,
    h.hydro_tds_ppm,
    h.hydro_orp_mv,
    h.hydro_battery_pct,
    l.sample_type AS latest_lab_sample_type,
    l.zone AS latest_lab_zone,
    l.sampled_at AS latest_lab_sampled_at,
    l.ph AS latest_lab_ph,
    l.ec_ms_cm AS latest_lab_ec_ms_cm,
    nr.name AS recipe_name,
    nr.target_ph_low,
    nr.target_ph_high,
    nr.target_ec,
        CASE
            WHEN (h.hydro_ph IS NULL) THEN 'missing_hydro_ph'::text
            WHEN ((nr.target_ph_low IS NOT NULL) AND (h.hydro_ph < nr.target_ph_low)) THEN 'ph_low'::text
            WHEN ((nr.target_ph_high IS NOT NULL) AND (h.hydro_ph > nr.target_ph_high)) THEN 'ph_high'::text
            WHEN ((nr.target_ec IS NOT NULL) AND (h.hydro_ec_us_cm IS NOT NULL) AND ((h.hydro_ec_us_cm / (1000.0)::double precision) > (nr.target_ec * (1.25)::double precision))) THEN 'ec_high'::text
            WHEN ((nr.target_ec IS NOT NULL) AND (h.hydro_ec_us_cm IS NOT NULL) AND ((h.hydro_ec_us_cm / (1000.0)::double precision) < (nr.target_ec * (0.75)::double precision))) THEN 'ec_low'::text
            ELSE 'ok'::text
        END AS status
   FROM ((latest_hydro h
     LEFT JOIN latest_lab l ON ((l.greenhouse_id = h.greenhouse_id)))
     LEFT JOIN public.nutrient_recipes nr ON (((nr.id = l.recipe_id) OR ((nr.is_active = true) AND (nr.crop_id = l.crop_id)))));


ALTER VIEW public.v_nutrient_lab_status OWNER TO verdify;

--
-- Name: VIEW v_nutrient_lab_status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_nutrient_lab_status IS 'Latest hydro chemistry and lab evidence compared with the linked or active nutrient recipe.';


--
-- Name: v_open_alerts; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_open_alerts AS
 SELECT id,
    ts,
    alert_type,
    severity,
    category,
    sensor_id,
    zone,
    zone_id,
    greenhouse_id,
    message,
    details,
    source,
    disposition,
    acknowledged_at,
    acknowledged_by,
    metric_value,
    threshold_value,
    slack_thread_ts,
    slack_snoozed_until,
    created_at,
    updated_at
   FROM public.alert_log a
  WHERE ((resolved_at IS NULL) AND (disposition <> 'suppressed'::text))
  ORDER BY
        CASE severity
            WHEN 'critical'::text THEN 0
            WHEN 'high'::text THEN 1
            WHEN 'warning'::text THEN 2
            WHEN 'info'::text THEN 3
            ELSE 4
        END, ts DESC;


ALTER VIEW public.v_open_alerts OWNER TO verdify;

--
-- Name: VIEW v_open_alerts; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_open_alerts IS 'Canonical open-alert set (migration 149/M5/B10): resolved_at IS NULL AND disposition <> ''suppressed''. Replaces the inconsistent inline disposition=''open'' predicates. Includes acknowledged-but-unresolved alerts; excludes the auto-resolve ''suppressed'' terminal state. Severity-ordered (critical first). Legacy ''high'' kept in the severity order for any pre-existing rows (deploy-blocker per Phase-0 rules).';


--
-- Name: v_openclaw_usage_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_openclaw_usage_daily AS
 SELECT ((ts AT TIME ZONE 'America/Denver'::text))::date AS day,
    session_type,
    count(*) AS calls,
    sum((COALESCE(tokens_in, 0) + COALESCE(tokens_out, 0))) AS total_tokens,
    sum(COALESCE(duration_ms, 0)) AS total_duration_ms,
    round(avg(duration_ms), 0) AS avg_duration_ms,
    count(*) FILTER (WHERE (NOT success)) AS error_count
   FROM public.openclaw_interaction_log
  GROUP BY (((ts AT TIME ZONE 'America/Denver'::text))::date), session_type;


ALTER VIEW public.v_openclaw_usage_daily OWNER TO verdify;

--
-- Name: v_openclaw_usage_hourly; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_openclaw_usage_hourly AS
 SELECT date_trunc('hour'::text, ts) AS hour,
    session_type,
    count(*) AS calls,
    sum((COALESCE(tokens_in, 0) + COALESCE(tokens_out, 0))) AS total_tokens,
    sum(COALESCE(duration_ms, 0)) AS total_duration_ms,
    count(*) FILTER (WHERE (NOT success)) AS error_count
   FROM public.openclaw_interaction_log
  WHERE (ts > (now() - '7 days'::interval))
  GROUP BY (date_trunc('hour'::text, ts)), session_type;


ALTER VIEW public.v_openclaw_usage_hourly OWNER TO verdify;

--
-- Name: v_override_activity_24h; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_override_activity_24h AS
 SELECT override_type,
    count(*) AS events,
    min(ts) AS first_seen,
    max(ts) AS last_seen,
    count(DISTINCT mode) AS distinct_modes
   FROM public.override_events
  WHERE (ts > (now() - '24:00:00'::interval))
  GROUP BY override_type
  ORDER BY (count(*)) DESC;


ALTER VIEW public.v_override_activity_24h OWNER TO verdify;

--
-- Name: VIEW v_override_activity_24h; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_override_activity_24h IS 'Firmware override frequency over last 24h. First gate on any compliance investigation.';


--
-- Name: v_plan_compliance; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_compliance AS
 SELECT created_at AS planned_ts,
    plan_id,
    'plan_outcome'::text AS parameter,
    'plan_outcome'::text AS target_type,
    outcome_score,
    anchor_score,
    validated_at,
    (outcome_score >= 6) AS plan_achieved,
    ((outcome_score - 10))::numeric AS overshoot,
    round(((outcome_score)::numeric * 10.0), 1) AS accuracy_pct
   FROM public.plan_journal pj
  WHERE (outcome_score IS NOT NULL);


ALTER VIEW public.v_plan_compliance OWNER TO verdify;

--
-- Name: VIEW v_plan_compliance; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_compliance IS 'Per-plan scored outcomes projected from plan_journal.outcome_score (1..10). Repointed in migration 148 off the dead setpoint_plan/climate 7-day join. plan_achieved = outcome_score>=6; overshoot = outcome_score-10 (signed shortfall). Canonical source: plan_journal.';


--
-- Name: v_plan_accuracy; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_accuracy AS
 SELECT plan_id,
    count(*) AS waypoints,
    count(*) FILTER (WHERE plan_achieved) AS achieved,
    round(avg(accuracy_pct), 1) AS accuracy_pct,
    round(avg(abs(overshoot)), 2) AS mean_abs_error,
    min(planned_ts) AS plan_start,
    max(planned_ts) AS plan_end
   FROM public.v_plan_compliance
  GROUP BY plan_id;


ALTER VIEW public.v_plan_accuracy OWNER TO verdify;

--
-- Name: VIEW v_plan_accuracy; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_accuracy IS 'Per-plan accuracy summary over plan_journal outcome scores (repointed in migration 148). accuracy_pct = outcome_score*10; mean_abs_error = mean shortfall from the ideal 10 on the 0..10 scale.';


--
-- Name: v_plan_accuracy_72h; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_accuracy_72h AS
 SELECT plan_id,
    ((floor((EXTRACT(epoch FROM (now() - planned_ts)) / 86400.0)))::integer + 1) AS day_offset,
    count(*) AS waypoints_count,
    count(*) FILTER (WHERE plan_achieved) AS achieved_count,
    round(avg(accuracy_pct), 1) AS accuracy_pct,
    round(avg(abs(overshoot)), 2) AS mean_abs_error
   FROM public.v_plan_compliance
  WHERE (planned_ts > (now() - '72:00:00'::interval))
  GROUP BY plan_id, ((floor((EXTRACT(epoch FROM (now() - planned_ts)) / 86400.0)))::integer + 1)
  ORDER BY plan_id, ((floor((EXTRACT(epoch FROM (now() - planned_ts)) / 86400.0)))::integer + 1);


ALTER VIEW public.v_plan_accuracy_72h OWNER TO verdify;

--
-- Name: VIEW v_plan_accuracy_72h; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_accuracy_72h IS 'Accuracy of plans emitted in the last 72h, bucketed by recency day_offset (1 = 0-24h ago, 2 = 24-48h, 3 = 48-72h). Repointed onto plan_journal in migration 148.';


--
-- Name: v_plan_accuracy_by_day; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_accuracy_by_day AS
 SELECT ((planned_ts AT TIME ZONE 'America/Denver'::text))::date AS day,
    count(*) AS waypoints,
    count(*) FILTER (WHERE plan_achieved) AS achieved,
    round(avg(accuracy_pct), 1) AS accuracy_pct,
    round(avg(abs(overshoot)), 2) AS mean_abs_error,
    count(DISTINCT plan_id) AS plans
   FROM public.v_plan_compliance
  GROUP BY (((planned_ts AT TIME ZONE 'America/Denver'::text))::date)
  ORDER BY (((planned_ts AT TIME ZONE 'America/Denver'::text))::date);


ALTER VIEW public.v_plan_accuracy_by_day OWNER TO verdify;

--
-- Name: VIEW v_plan_accuracy_by_day; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_accuracy_by_day IS 'Per Denver-local-day accuracy over plan_journal outcome scores. Repointed in migration 148.';


--
-- Name: v_plan_comparison; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_comparison AS
 WITH plan_order AS (
         SELECT DISTINCT setpoint_plan.plan_id,
            min(setpoint_plan.created_at) AS created_at
           FROM public.setpoint_plan
          WHERE ((setpoint_plan.plan_id ~~ 'iris-2026%'::text) AND (setpoint_plan.plan_id !~~ '%reactive%'::text) AND (setpoint_plan.plan_id !~~ '%fix%'::text) AND (setpoint_plan.plan_id !~~ '%dev%'::text))
          GROUP BY setpoint_plan.plan_id
          ORDER BY (min(setpoint_plan.created_at)) DESC
         LIMIT 20
        ), plan_pairs AS (
         SELECT plan_order.plan_id,
            plan_order.created_at,
            lag(plan_order.plan_id) OVER (ORDER BY plan_order.created_at) AS prev_plan_id
           FROM plan_order
        ), cur_stats AS (
         SELECT sp.plan_id,
            sp.parameter,
            count(*) AS waypoints,
            round((avg(sp.value))::numeric, 2) AS avg_value,
            round((min(sp.value))::numeric, 2) AS min_value,
            round((max(sp.value))::numeric, 2) AS max_value
           FROM (public.setpoint_plan sp
             JOIN plan_pairs pp_1 ON ((sp.plan_id = pp_1.plan_id)))
          WHERE (sp.parameter = ANY (ARRAY['temp_high'::text, 'temp_low'::text, 'vpd_high'::text, 'vpd_hysteresis'::text, 'd_cool_stage_2'::text, 'mister_engage_kpa'::text, 'mister_all_kpa'::text, 'mister_pulse_on_s'::text, 'mister_pulse_gap_s'::text, 'mister_vpd_weight'::text]))
          GROUP BY sp.plan_id, sp.parameter
        ), prev_stats AS (
         SELECT sp.plan_id AS prev_plan_id,
            sp.parameter,
            count(*) AS waypoints,
            round((avg(sp.value))::numeric, 2) AS avg_value,
            round((min(sp.value))::numeric, 2) AS min_value,
            round((max(sp.value))::numeric, 2) AS max_value
           FROM (public.setpoint_plan sp
             JOIN plan_pairs pp_1 ON ((sp.plan_id = pp_1.prev_plan_id)))
          WHERE (sp.parameter = ANY (ARRAY['temp_high'::text, 'temp_low'::text, 'vpd_high'::text, 'vpd_hysteresis'::text, 'd_cool_stage_2'::text, 'mister_engage_kpa'::text, 'mister_all_kpa'::text, 'mister_pulse_on_s'::text, 'mister_pulse_gap_s'::text, 'mister_vpd_weight'::text]))
          GROUP BY sp.plan_id, sp.parameter
        )
 SELECT pp.plan_id,
    pp.prev_plan_id,
    (pp.created_at AT TIME ZONE 'America/Denver'::text) AS plan_created,
    COALESCE(c.parameter, p.parameter) AS parameter,
    COALESCE(c.waypoints, (0)::bigint) AS cur_waypoints,
    COALESCE(p.waypoints, (0)::bigint) AS prev_waypoints,
    c.avg_value AS cur_avg,
    p.avg_value AS prev_avg,
    round((COALESCE(c.avg_value, (0)::numeric) - COALESCE(p.avg_value, (0)::numeric)), 2) AS delta_avg,
    c.min_value AS cur_min,
    c.max_value AS cur_max,
    p.min_value AS prev_min,
    p.max_value AS prev_max
   FROM ((plan_pairs pp
     LEFT JOIN cur_stats c ON ((pp.plan_id = c.plan_id)))
     LEFT JOIN prev_stats p ON (((pp.prev_plan_id = p.prev_plan_id) AND (COALESCE(c.parameter, p.parameter) = p.parameter))))
  WHERE ((pp.prev_plan_id IS NOT NULL) AND ((c.parameter IS NOT NULL) OR (p.parameter IS NOT NULL)))
  ORDER BY pp.created_at DESC, COALESCE(c.parameter, p.parameter);


ALTER VIEW public.v_plan_comparison OWNER TO verdify;

--
-- Name: v_plan_execution_intervals; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_execution_intervals AS
 WITH iris_plans AS (
         SELECT plan_journal.plan_id,
            plan_journal.created_at,
            plan_journal.trigger_id,
            plan_journal.planner_instance,
            plan_journal.greenhouse_id
           FROM public.plan_journal
          WHERE (plan_journal.plan_id ~~ 'iris-%'::text)
        ), ordered AS (
         SELECT iris_plans.plan_id,
            iris_plans.created_at,
            iris_plans.trigger_id,
            iris_plans.planner_instance,
            iris_plans.greenhouse_id,
            lead(iris_plans.created_at) OVER (PARTITION BY iris_plans.greenhouse_id ORDER BY iris_plans.created_at) AS superseded_at
           FROM iris_plans
        )
 SELECT plan_id,
    greenhouse_id,
    created_at AS interval_start,
    COALESCE(superseded_at, now()) AS interval_end,
    trigger_id,
    planner_instance,
    (EXTRACT(epoch FROM (COALESCE(superseded_at, now()) - created_at)) / 3600.0) AS governed_hours,
    (COALESCE(superseded_at, now()) - created_at) AS governed_duration
   FROM ordered;


ALTER VIEW public.v_plan_execution_intervals OWNER TO verdify;

--
-- Name: VIEW v_plan_execution_intervals; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_execution_intervals IS 'Per-plan wall-clock interval during which the plan was the active "current" plan (until the next plan superseded it). Use this — not created_at::date — when attributing daily scorecards back to plans.';


--
-- Name: v_plan_guardrail_scorecard; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_guardrail_scorecard AS
 SELECT pei.plan_id,
    (count(sc.*))::integer AS guardrail_events,
    (count(*) FILTER (WHERE (sc.status = 'held_by_guardrail'::text)))::integer AS held_guardrail_events,
    (count(*) FILTER (WHERE (sc.status = 'guardrailed'::text)))::integer AS dispatched_guardrail_events,
    (count(*) FILTER (WHERE (sc.reason = 'vpd_high_moisture_guardrail'::text)))::integer AS vpd_high_guardrail_events,
    (
        CASE
            WHEN ((count(sc.*) >= 20) OR (count(*) FILTER (WHERE (sc.status = 'held_by_guardrail'::text)) >= 10)) THEN 3
            WHEN ((count(sc.*) >= 8) OR (count(*) FILTER (WHERE (sc.status = 'held_by_guardrail'::text)) >= 3)) THEN 2
            WHEN ((count(sc.*) >= 3) OR (count(*) FILTER (WHERE (sc.status = 'held_by_guardrail'::text)) >= 1)) THEN 1
            ELSE 0
        END)::smallint AS guardrail_penalty
   FROM (public.v_plan_execution_intervals pei
     LEFT JOIN public.setpoint_clamps sc ON (((sc.greenhouse_id = pei.greenhouse_id) AND (sc.ts >= pei.interval_start) AND (sc.ts < pei.interval_end))))
  GROUP BY pei.plan_id;


ALTER VIEW public.v_plan_guardrail_scorecard OWNER TO verdify;

--
-- Name: VIEW v_plan_guardrail_scorecard; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_guardrail_scorecard IS 'Per-plan guardrail dependence counts and deterministic penalty. Used by fn_plan_anchor_score so plans that repeatedly require dispatcher clamps/holds lose score.';


--
-- Name: v_plan_transition_audit_36h; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_transition_audit_36h AS
 SELECT plan_id,
    plan_created_at,
    transition_ts,
    parameter,
    planned_value,
    prior_value,
    applied_value,
    readback_value,
    status,
    guardrail_reason,
    push_ts,
    push_latency_s,
    confirmed_at,
    confirm_latency_s,
    matching_push_ts,
    readback_ts,
    trigger_id,
    planner_instance
   FROM public.fn_plan_transition_audit(NULL::text, '36:00:00'::interval, '00:10:00'::interval) fn_plan_transition_audit(plan_id, plan_created_at, transition_ts, parameter, planned_value, prior_value, applied_value, readback_value, status, guardrail_reason, push_ts, push_latency_s, confirmed_at, confirm_latency_s, matching_push_ts, readback_ts, trigger_id, planner_instance);


ALTER VIEW public.v_plan_transition_audit_36h OWNER TO verdify;

--
-- Name: VIEW v_plan_transition_audit_36h; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_plan_transition_audit_36h IS 'Last-36h guardrail-aware planner transition audit for operator/planner context.';


--
-- Name: v_planner_performance; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_planner_performance AS
 WITH daily AS (
         SELECT d.date,
            COALESCE(d.stress_hours_heat, (0)::double precision) AS heat_stress_h,
            COALESCE(d.stress_hours_cold, (0)::double precision) AS cold_stress_h,
            COALESCE(d.stress_hours_vpd_high, (0)::double precision) AS vpd_high_stress_h,
            COALESCE(d.stress_hours_vpd_low, (0)::double precision) AS vpd_low_stress_h,
            (((COALESCE(d.stress_hours_heat, (0)::double precision) + COALESCE(d.stress_hours_cold, (0)::double precision)) + COALESCE(d.stress_hours_vpd_high, (0)::double precision)) + COALESCE(d.stress_hours_vpd_low, (0)::double precision)) AS total_stress_h,
            COALESCE(d.compliance_pct, (0)::double precision) AS compliance_pct,
            COALESCE(d.temp_compliance_pct, (0)::double precision) AS temp_compliance_pct,
            COALESCE(d.vpd_compliance_pct, (0)::double precision) AS vpd_compliance_pct,
            COALESCE(d.cost_total, (0)::double precision) AS cost_total,
            COALESCE(d.cost_electric, (0)::double precision) AS cost_electric,
            COALESCE(d.cost_gas, (0)::double precision) AS cost_gas,
            COALESCE(d.cost_water, (0)::double precision) AS cost_water
           FROM public.daily_summary d
          WHERE (d.date IS NOT NULL)
        )
 SELECT date,
    heat_stress_h,
    cold_stress_h,
    vpd_high_stress_h,
    vpd_low_stress_h,
    total_stress_h,
    round((compliance_pct)::numeric, 1) AS compliance_pct,
    round((temp_compliance_pct)::numeric, 1) AS temp_compliance_pct,
    round((vpd_compliance_pct)::numeric, 1) AS vpd_compliance_pct,
    cost_total,
    cost_electric,
    cost_gas,
    cost_water,
        CASE
            WHEN (total_stress_h > (0)::double precision) THEN round(((cost_total / total_stress_h))::numeric, 2)
            ELSE NULL::numeric
        END AS cost_per_stress_hour,
    round(((((compliance_pct / (100.0)::double precision) * (80)::double precision) + (GREATEST((0)::double precision, ((1.0)::double precision - LEAST((cost_total / (15.0)::double precision), (1.0)::double precision))) * (20)::double precision)))::numeric, 1) AS planner_score
   FROM daily;


ALTER VIEW public.v_planner_performance OWNER TO verdify;

--
-- Name: v_plan_window_scorecard; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_plan_window_scorecard AS
 WITH plan_days AS (
         SELECT pei.plan_id,
            (d.d)::date AS day,
            GREATEST((EXTRACT(epoch FROM (LEAST(pei.interval_end, (d.d + '1 day'::interval)) - GREATEST(pei.interval_start, d.d))) / 86400.0), (0)::numeric) AS day_weight
           FROM (public.v_plan_execution_intervals pei
             CROSS JOIN LATERAL generate_series(((pei.interval_start)::date)::timestamp with time zone, (LEAST((pei.interval_end)::date, CURRENT_DATE))::timestamp with time zone, '1 day'::interval) d(d))
        )
 SELECT pd.plan_id,
    sum(pd.day_weight) AS governed_day_fraction,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.heat_stress_h, (0)::double precision))) AS heat_stress_h,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.cold_stress_h, (0)::double precision))) AS cold_stress_h,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.vpd_high_stress_h, (0)::double precision))) AS vpd_high_stress_h,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.vpd_low_stress_h, (0)::double precision))) AS vpd_low_stress_h,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.total_stress_h, (0)::double precision))) AS total_stress_h,
        CASE
            WHEN (sum(pd.day_weight) > (0)::numeric) THEN (sum((pd.day_weight * COALESCE(vpp.compliance_pct, (0)::numeric))) / sum(pd.day_weight))
            ELSE NULL::numeric
        END AS compliance_pct,
        CASE
            WHEN (sum(pd.day_weight) > (0)::numeric) THEN (sum((pd.day_weight * COALESCE(vpp.temp_compliance_pct, (0)::numeric))) / sum(pd.day_weight))
            ELSE NULL::numeric
        END AS temp_compliance_pct,
        CASE
            WHEN (sum(pd.day_weight) > (0)::numeric) THEN (sum((pd.day_weight * COALESCE(vpp.vpd_compliance_pct, (0)::numeric))) / sum(pd.day_weight))
            ELSE NULL::numeric
        END AS vpd_compliance_pct,
    sum(((pd.day_weight)::double precision * COALESCE(vpp.cost_total, (0)::double precision))) AS cost_total,
        CASE
            WHEN (sum(pd.day_weight) > (0)::numeric) THEN (sum((pd.day_weight * COALESCE(vpp.planner_score, (0)::numeric))) / sum(pd.day_weight))
            ELSE NULL::numeric
        END AS planner_score
   FROM (plan_days pd
     LEFT JOIN public.v_planner_performance vpp ON ((vpp.date = pd.day)))
  GROUP BY pd.plan_id;


ALTER VIEW public.v_plan_window_scorecard OWNER TO verdify;

--
-- Name: v_position_current; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_position_current AS
 SELECT p.id AS position_id,
    p.greenhouse_id,
    p.label AS position_label,
    sh.slug AS shelf_slug,
    sh.kind AS shelf_kind,
    z.id AS zone_id,
    z.slug AS zone_slug,
    z.name AS zone_name,
    c.id AS crop_id,
    c.name AS crop_name,
    c.variety AS crop_variety,
    c.stage AS crop_stage,
    c.planted_date AS crop_planted_date,
    c.expected_harvest AS crop_expected_harvest,
    cc.slug AS crop_catalog_slug,
    (CURRENT_DATE - c.planted_date) AS crop_days_in_place,
    (c.id IS NOT NULL) AS is_occupied
   FROM ((((public.positions p
     JOIN public.shelves sh ON ((sh.id = p.shelf_id)))
     JOIN public.zones z ON ((z.id = sh.zone_id)))
     LEFT JOIN public.crops c ON (((c.position_id = p.id) AND c.is_active)))
     LEFT JOIN public.crop_catalog cc ON ((cc.id = c.crop_catalog_id)))
  WHERE p.is_active
  ORDER BY z.slug, sh.slug, p.label;


ALTER VIEW public.v_position_current OWNER TO verdify;

--
-- Name: VIEW v_position_current; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_position_current IS 'Sprint 23: current state of every active position — which crop (if any) is there, how long it has been, which zone/shelf it belongs to. Left-join on crops, so empty slots show up with NULL crop columns.';


--
-- Name: water_systems; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.water_systems (
    id integer NOT NULL,
    greenhouse_id text DEFAULT 'vallery'::text NOT NULL,
    slug text NOT NULL,
    zone_id integer,
    equipment_id integer,
    pressure_group_id integer,
    kind text NOT NULL,
    name text NOT NULL,
    nozzle_count integer,
    head_count integer,
    mount text,
    is_fert_path boolean DEFAULT false NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    effectiveness_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT water_systems_head_count_check CHECK ((head_count >= 0)),
    CONSTRAINT water_systems_kind_check CHECK ((kind = ANY (ARRAY['mister'::text, 'drip'::text, 'fog'::text, 'fertigation'::text, 'nft'::text, 'manual'::text]))),
    CONSTRAINT water_systems_nozzle_count_check CHECK ((nozzle_count >= 0)),
    CONSTRAINT water_systems_slug_check CHECK ((slug ~ '^[a-z][a-z0-9_]*$'::text))
);


ALTER TABLE public.water_systems OWNER TO verdify;

--
-- Name: TABLE water_systems; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.water_systems IS 'Sprint 22: mister/drip/fog systems with head/nozzle counts + pressure group FK. Gives the planner a queryable model of the water manifold.';


--
-- Name: v_pressure_group_status; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_pressure_group_status AS
 SELECT id AS pressure_group_id,
    greenhouse_id,
    slug AS group_slug,
    name AS group_name,
    constraint_kind,
    max_concurrent,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('water_system_slug', w.slug, 'water_system_kind', w.kind, 'equipment_slug', e.slug, 'zone_slug', z.slug, 'is_on', COALESCE(( SELECT es.state
                   FROM public.equipment_state es
                  WHERE ((es.equipment = e.slug) AND (es.greenhouse_id = pg.greenhouse_id))
                  ORDER BY es.ts DESC
                 LIMIT 1), false)) ORDER BY w.slug) AS jsonb_agg
           FROM ((public.water_systems w
             LEFT JOIN public.equipment e ON ((e.id = w.equipment_id)))
             LEFT JOIN public.zones z ON ((z.id = w.zone_id)))
          WHERE ((w.pressure_group_id = pg.id) AND w.is_active)), '[]'::jsonb) AS systems
   FROM public.pressure_groups pg;


ALTER VIEW public.v_pressure_group_status OWNER TO verdify;

--
-- Name: VIEW v_pressure_group_status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_pressure_group_status IS 'Sprint 22: snapshot of pressure-manifold activity. Shows which mister/drip systems are currently on per pressure group. Used to verify firmware "one-at-a-time" rule is being honored.';


--
-- Name: v_reboot_log; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_reboot_log AS
 SELECT ts,
    uptime_s AS uptime_after,
    reset_reason,
    lag(uptime_s) OVER (ORDER BY ts) AS uptime_before,
    (EXTRACT(epoch FROM (ts - lag(ts) OVER (ORDER BY ts))))::integer AS gap_s
   FROM public.diagnostics
  WHERE ((uptime_s < (300)::double precision) AND (ts > (now() - '90 days'::interval)))
  ORDER BY ts DESC;


ALTER VIEW public.v_reboot_log OWNER TO verdify;

--
-- Name: v_relay_stuck; Type: MATERIALIZED VIEW; Schema: public; Owner: verdify
--

CREATE MATERIALIZED VIEW public.v_relay_stuck AS
 WITH latest_on AS (
         SELECT equipment_state.equipment,
            max(equipment_state.ts) AS last_on_ts
           FROM public.equipment_state
          WHERE ((equipment_state.state = true) AND (equipment_state.equipment <> ALL (ARRAY['economiser_enabled'::text, 'economiser_blocked'::text, 'fog_closes_vent'::text, 'irrigation_enabled'::text, 'irrigation_wall_enabled'::text, 'irrigation_center_enabled'::text, 'irrigation_weather_skip'::text, 'sntp_status'::text, 'mister_budget_exceeded'::text, 'fan_burst_active'::text, 'fog_burst_active'::text, 'vent_bypass_active'::text, 'leak_detected'::text, 'water_flowing'::text, 'mister_any'::text, 'gl_auto_mode'::text, 'occupancy_inhibit'::text])))
          GROUP BY equipment_state.equipment
        ), latest_off AS (
         SELECT equipment_state.equipment,
            max(equipment_state.ts) AS last_off_ts
           FROM public.equipment_state
          WHERE (equipment_state.state = false)
          GROUP BY equipment_state.equipment
        ), stuck_check AS (
         SELECT lo.equipment,
            lo.last_on_ts,
            lf.last_off_ts,
            (EXTRACT(epoch FROM (now() - lo.last_on_ts)) / 3600.0) AS hours_on,
                CASE lo.equipment
                    WHEN 'heat1'::text THEN 3
                    WHEN 'heat2'::text THEN 3
                    WHEN 'fan1'::text THEN 4
                    WHEN 'fan2'::text THEN 4
                    WHEN 'fog'::text THEN 2
                    WHEN 'vent'::text THEN 6
                    ELSE 8
                END AS threshold_hours
           FROM (latest_on lo
             LEFT JOIN latest_off lf ON ((lo.equipment = lf.equipment)))
          WHERE (lo.last_on_ts > COALESCE(lf.last_off_ts, '1970-01-01 00:00:00+00'::timestamp with time zone))
        )
 SELECT equipment,
    last_on_ts,
    hours_on,
    threshold_hours,
    (hours_on > (threshold_hours)::numeric) AS is_stuck
   FROM stuck_check
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.v_relay_stuck OWNER TO verdify;

--
-- Name: v_setpoint_change_delivery; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_setpoint_change_delivery AS
 SELECT ts,
    parameter,
    value,
    source,
    greenhouse_id,
    confirmed_at,
    COALESCE(delivery_status,
        CASE
            WHEN (confirmed_at IS NOT NULL) THEN 'confirmed'::text
            ELSE 'pending'::text
        END) AS delivery_status,
    expired_at,
    superseded_by_ts,
    round(EXTRACT(epoch FROM (confirmed_at - ts)), 1) AS confirm_latency_s
   FROM public.setpoint_changes;


ALTER VIEW public.v_setpoint_change_delivery OWNER TO verdify;

--
-- Name: VIEW v_setpoint_change_delivery; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_setpoint_change_delivery IS 'Setpoint change confirmation lifecycle with explicit pending/superseded/expired/confirmed status.';


--
-- Name: v_setpoint_delivery_latency; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_setpoint_delivery_latency AS
 SELECT parameter,
    source,
    count(*) AS changes,
    count(*) FILTER (WHERE (confirmed_at IS NOT NULL)) AS confirmed,
    round(((100.0 * (count(*) FILTER (WHERE (confirmed_at IS NOT NULL)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS confirmed_pct,
    percentile_disc((0.50)::double precision) WITHIN GROUP (ORDER BY (EXTRACT(epoch FROM (confirmed_at - ts)))) FILTER (WHERE (confirmed_at IS NOT NULL)) AS p50_confirm_s,
    percentile_disc((0.95)::double precision) WITHIN GROUP (ORDER BY (EXTRACT(epoch FROM (confirmed_at - ts)))) FILTER (WHERE (confirmed_at IS NOT NULL)) AS p95_confirm_s,
    max(ts) AS latest_change
   FROM public.setpoint_changes
  WHERE (ts > (now() - '7 days'::interval))
  GROUP BY parameter, source;


ALTER VIEW public.v_setpoint_delivery_latency OWNER TO verdify;

--
-- Name: VIEW v_setpoint_delivery_latency; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_setpoint_delivery_latency IS 'Seven-day setpoint push/readback confirmation coverage and latency.';


--
-- Name: v_setpoint_effective_drift_7d; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_setpoint_effective_drift_7d AS
 WITH ranked AS (
         SELECT c.ts,
            c.parameter,
            c.requested,
            c.applied,
            c.band_lo,
            c.band_hi,
            c.reason,
            c.greenhouse_id,
            c.status,
            c.plan_id,
            c.plan_ts,
            c.trigger_id,
            c.planner_instance,
            row_number() OVER (PARTITION BY c.greenhouse_id, c.parameter ORDER BY c.ts DESC) AS rn
           FROM public.setpoint_clamps c
          WHERE (c.ts > (now() - '7 days'::interval))
        )
 SELECT greenhouse_id,
    parameter,
    count(*) AS drift_events,
    count(*) FILTER (WHERE (status = 'guardrailed'::text)) AS guardrailed_events,
    count(*) FILTER (WHERE (status = 'held_by_guardrail'::text)) AS held_events,
    count(*) FILTER (WHERE (status = 'rejected'::text)) AS rejected_events,
    round((avg(abs((requested - applied))))::numeric, 3) AS avg_abs_delta,
    round((max(abs((requested - applied))))::numeric, 3) AS max_abs_delta,
    min(ts) AS first_seen,
    max(ts) AS last_seen,
    max(requested) FILTER (WHERE (rn = 1)) AS latest_requested,
    max(applied) FILTER (WHERE (rn = 1)) AS latest_effective,
    max(reason) FILTER (WHERE (rn = 1)) AS latest_reason,
    max(status) FILTER (WHERE (rn = 1)) AS latest_status,
    max(plan_id) FILTER (WHERE (rn = 1)) AS latest_plan_id
   FROM ranked
  GROUP BY greenhouse_id, parameter
  ORDER BY (count(*)) DESC, parameter;


ALTER VIEW public.v_setpoint_effective_drift_7d OWNER TO verdify;

--
-- Name: VIEW v_setpoint_effective_drift_7d; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_setpoint_effective_drift_7d IS 'Rolling seven-day planner requested vs dispatcher effective/applied drift from setpoint_clamps. Used to find hidden clamp or retired-param pressure.';


--
-- Name: v_setpoint_forward; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_setpoint_forward AS
 SELECT v_active_plan.parameter,
    now() AS ts,
    v_active_plan.value,
    'current'::text AS source
   FROM public.v_active_plan
  WHERE (v_active_plan.parameter = ANY (ARRAY['temp_high'::text, 'temp_low'::text, 'vpd_high'::text, 'vpd_low'::text, 'vpd_hysteresis'::text, 'd_cool_stage_2'::text, 'mister_engage_kpa'::text, 'mister_all_kpa'::text, 'mister_pulse_on_s'::text, 'mister_pulse_gap_s'::text]))
UNION ALL
 SELECT v_active_plan.parameter,
    COALESCE(( SELECT max(weather_forecast.ts) AS max
           FROM public.weather_forecast
          WHERE (weather_forecast.fetched_at > (now() - '12:00:00'::interval))), (now() + '16 days'::interval)) AS ts,
    v_active_plan.value,
    'projection'::text AS source
   FROM public.v_active_plan
  WHERE (v_active_plan.parameter = ANY (ARRAY['temp_high'::text, 'temp_low'::text, 'vpd_high'::text, 'vpd_low'::text, 'vpd_hysteresis'::text, 'd_cool_stage_2'::text, 'mister_engage_kpa'::text, 'mister_all_kpa'::text, 'mister_pulse_on_s'::text, 'mister_pulse_gap_s'::text]))
UNION ALL
 SELECT setpoint_plan.parameter,
    setpoint_plan.ts,
    setpoint_plan.value,
    'plan'::text AS source
   FROM public.setpoint_plan
  WHERE ((setpoint_plan.parameter = ANY (ARRAY['temp_high'::text, 'temp_low'::text, 'vpd_high'::text, 'vpd_low'::text, 'vpd_hysteresis'::text, 'd_cool_stage_2'::text, 'mister_engage_kpa'::text, 'mister_all_kpa'::text, 'mister_pulse_on_s'::text, 'mister_pulse_gap_s'::text])) AND (setpoint_plan.is_active = true) AND (setpoint_plan.ts > now()))
  ORDER BY 1, 2;


ALTER VIEW public.v_setpoint_forward OWNER TO verdify;

--
-- Name: v_setpoint_velocity; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_setpoint_velocity AS
 WITH hourly AS (
         SELECT date_trunc('hour'::text, sc.ts) AS hour,
            sc.parameter,
            sc.source,
            count(*) AS writes,
            count(*) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM public.setpoint_changes sc2
                  WHERE ((sc2.parameter = sc.parameter) AND (sc2.ts > sc.ts) AND (sc2.ts < (sc.ts + '00:10:00'::interval)) AND (sc2.value <> sc.value))))) AS oscillations
           FROM public.setpoint_changes sc
          WHERE (sc.ts > (now() - '30 days'::interval))
          GROUP BY (date_trunc('hour'::text, sc.ts)), sc.parameter, sc.source
        )
 SELECT hour,
    parameter,
    source,
    writes,
    oscillations
   FROM hourly;


ALTER VIEW public.v_setpoint_velocity OWNER TO verdify;

--
-- Name: v_slack_crop_tasks_due; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_slack_crop_tasks_due AS
 SELECT ct.id,
    ct.greenhouse_id,
    ct.task_type,
    ct.priority,
    ct.status,
    ct.due_at,
    ct.crop_id,
    c.name AS crop_name,
    c.variety AS crop_variety,
    c.stage AS crop_stage,
    ct.position_id,
    p.label AS position_label,
    z.slug AS zone_slug,
    ct.notes
   FROM (((public.crop_tasks ct
     LEFT JOIN public.crops c ON ((c.id = ct.crop_id)))
     LEFT JOIN public.positions p ON ((p.id = ct.position_id)))
     LEFT JOIN public.zones z ON ((z.id = COALESCE(ct.zone_id, c.zone_id))))
  WHERE ((ct.status = ANY (ARRAY['open'::text, 'snoozed'::text])) AND (ct.due_at <= (now() + '24:00:00'::interval)))
  ORDER BY ct.due_at, ct.priority DESC, ct.id;


ALTER VIEW public.v_slack_crop_tasks_due OWNER TO verdify;

--
-- Name: v_slack_forecast_triage; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_slack_forecast_triage AS
 WITH items AS (
         SELECT forecast_deviation_log.ts,
            forecast_deviation_log.greenhouse_id,
            'forecast_deviation'::text AS item_type,
            forecast_deviation_log.parameter AS target,
                CASE
                    WHEN forecast_deviation_log.triggered THEN 'triggered'::text
                    ELSE 'observed'::text
                END AS status,
            abs(forecast_deviation_log.delta) AS urgency,
            jsonb_build_object('observed', forecast_deviation_log.observed, 'forecasted', forecast_deviation_log.forecasted, 'delta', forecast_deviation_log.delta, 'threshold', forecast_deviation_log.threshold, 'triggered', forecast_deviation_log.triggered) AS details
           FROM public.forecast_deviation_log
          WHERE (forecast_deviation_log.ts >= (now() - '72:00:00'::interval))
        UNION ALL
         SELECT COALESCE(forecast_action_log.triggered_at, forecast_action_log.outcome_evaluated_at, now()) AS ts,
            forecast_action_log.greenhouse_id,
            'forecast_action'::text AS item_type,
            COALESCE(forecast_action_log.param, forecast_action_log.rule_name) AS target,
            COALESCE(forecast_action_log.outcome, forecast_action_log.action_taken) AS status,
            (
                CASE
                    WHEN (forecast_action_log.action_taken <> 'evaluated_ok'::text) THEN 1
                    ELSE 0
                END)::double precision AS urgency,
            jsonb_build_object('rule_name', forecast_action_log.rule_name, 'action_taken', forecast_action_log.action_taken, 'plan_id', forecast_action_log.plan_id, 'old_value', forecast_action_log.old_value, 'new_value', forecast_action_log.new_value, 'condition', forecast_action_log.forecast_condition, 'outcome_metrics', forecast_action_log.outcome_metrics) AS details
           FROM public.forecast_action_log
          WHERE (COALESCE(forecast_action_log.triggered_at, forecast_action_log.outcome_evaluated_at, now()) >= (now() - '72:00:00'::interval))
        )
 SELECT row_number() OVER (ORDER BY urgency DESC NULLS LAST, ts DESC) AS id,
    ts,
    greenhouse_id,
    item_type,
    target,
    status,
    urgency,
    details
   FROM items
  ORDER BY urgency DESC NULLS LAST, ts DESC;


ALTER VIEW public.v_slack_forecast_triage OWNER TO verdify;

--
-- Name: v_slack_guardrail_summary; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_slack_guardrail_summary AS
 SELECT pj.plan_id,
    pj.created_at,
