--
-- Name: v_slack_public_ops_log; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_slack_public_ops_log AS
 SELECT (slack_command_audit.id)::text AS id,
    slack_command_audit.ts,
    slack_command_audit.greenhouse_id,
    'command'::text AS event_kind,
    slack_command_audit.normalized_intent AS event_type,
    slack_command_audit.status,
    slack_command_audit.role,
    slack_command_audit.record_type,
    slack_command_audit.record_id,
    slack_command_audit.model_routing,
    slack_command_audit.handled_by,
    "left"(regexp_replace(COALESCE(slack_command_audit.response_text, slack_command_audit.command_text), '<@[A-Z0-9]+>'::text, '@user'::text, 'g'::text), 320) AS public_text
   FROM public.slack_command_audit
UNION ALL
 SELECT (slack_notification_events.id)::text AS id,
    slack_notification_events.ts,
    slack_notification_events.greenhouse_id,
    'notification'::text AS event_kind,
    slack_notification_events.event_type,
    slack_notification_events.status,
    NULL::text AS role,
    slack_notification_events.entity_type AS record_type,
    slack_notification_events.entity_id AS record_id,
    'deterministic'::text AS model_routing,
    slack_notification_events.source AS handled_by,
    "left"(COALESCE((slack_notification_events.payload ->> 'text'::text), slack_notification_events.event_type), 320) AS public_text
   FROM public.slack_notification_events
UNION ALL
 SELECT (slack_alert_actions.id)::text AS id,
    slack_alert_actions.ts,
    slack_alert_actions.greenhouse_id,
    'alert_action'::text AS event_kind,
    slack_alert_actions.action AS event_type,
    'executed'::text AS status,
    NULL::text AS role,
    'alert_log'::text AS record_type,
    (slack_alert_actions.alert_id)::text AS record_id,
    'deterministic'::text AS model_routing,
    'python'::text AS handled_by,
    "left"(COALESCE(slack_alert_actions.note, 'alert action recorded'::text), 320) AS public_text
   FROM public.slack_alert_actions;


ALTER VIEW public.v_slack_public_ops_log OWNER TO verdify;

--
-- Name: v_soil_status; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_soil_status AS
 WITH latest AS (
         SELECT climate.ts,
            climate.soil_moisture_south_1,
            climate.soil_temp_south_1,
            climate.soil_ec_south_1,
            climate.soil_moisture_south_2,
            climate.soil_temp_south_2,
            climate.soil_moisture_west,
            climate.soil_temp_west
           FROM public.climate
          WHERE ((climate.soil_moisture_south_1 IS NOT NULL) OR (climate.soil_moisture_west IS NOT NULL))
          ORDER BY climate.ts DESC
         LIMIT 1
        ), trend AS (
         SELECT (array_agg(climate.soil_moisture_south_1 ORDER BY climate.ts DESC) FILTER (WHERE (climate.soil_moisture_south_1 IS NOT NULL)))[1] AS last_s1,
            (array_agg(climate.soil_moisture_south_1 ORDER BY climate.ts) FILTER (WHERE (climate.soil_moisture_south_1 IS NOT NULL)))[1] AS first_s1,
            (array_agg(climate.soil_moisture_south_2 ORDER BY climate.ts DESC) FILTER (WHERE (climate.soil_moisture_south_2 IS NOT NULL)))[1] AS last_s2,
            (array_agg(climate.soil_moisture_south_2 ORDER BY climate.ts) FILTER (WHERE (climate.soil_moisture_south_2 IS NOT NULL)))[1] AS first_s2,
            (array_agg(climate.soil_moisture_west ORDER BY climate.ts DESC) FILTER (WHERE (climate.soil_moisture_west IS NOT NULL)))[1] AS last_w,
            (array_agg(climate.soil_moisture_west ORDER BY climate.ts) FILTER (WHERE (climate.soil_moisture_west IS NOT NULL)))[1] AS first_w
           FROM public.climate
          WHERE ((climate.ts > (now() - '06:00:00'::interval)) AND ((climate.soil_moisture_south_1 IS NOT NULL) OR (climate.soil_moisture_west IS NOT NULL)))
        ), unpivoted AS (
         SELECT 'south_1'::text AS zone,
            l.soil_moisture_south_1 AS moisture,
            l.soil_temp_south_1 AS temp,
            l.soil_ec_south_1 AS ec,
            (EXTRACT(epoch FROM (now() - l.ts)))::integer AS age_s,
                CASE
                    WHEN ((t_1.last_s1 - t_1.first_s1) > (2)::double precision) THEN 'rising'::text
                    WHEN ((t_1.first_s1 - t_1.last_s1) > (2)::double precision) THEN 'falling'::text
                    ELSE 'stable'::text
                END AS trend
           FROM latest l,
            trend t_1
        UNION ALL
         SELECT 'south_2'::text,
            l.soil_moisture_south_2,
            l.soil_temp_south_2,
            NULL::double precision AS float8,
            (EXTRACT(epoch FROM (now() - l.ts)))::integer AS "extract",
                CASE
                    WHEN ((t_1.last_s2 - t_1.first_s2) > (2)::double precision) THEN 'rising'::text
                    WHEN ((t_1.first_s2 - t_1.last_s2) > (2)::double precision) THEN 'falling'::text
                    ELSE 'stable'::text
                END AS "case"
           FROM latest l,
            trend t_1
        UNION ALL
         SELECT 'west'::text,
            l.soil_moisture_west,
            l.soil_temp_west,
            NULL::double precision AS float8,
            (EXTRACT(epoch FROM (now() - l.ts)))::integer AS "extract",
                CASE
                    WHEN ((t_1.last_w - t_1.first_w) > (2)::double precision) THEN 'rising'::text
                    WHEN ((t_1.first_w - t_1.last_w) > (2)::double precision) THEN 'falling'::text
                    ELSE 'stable'::text
                END AS "case"
           FROM latest l,
            trend t_1
        )
 SELECT u.zone,
    u.moisture,
    u.temp,
    u.ec,
    u.age_s,
    u.trend,
    t.min_pct,
    t.max_pct,
    t.crop,
        CASE
            WHEN (u.moisture IS NULL) THEN 'offline'::text
            WHEN (u.moisture < (t.wilt_pct)::double precision) THEN 'critical_dry'::text
            WHEN (u.moisture < (t.min_pct)::double precision) THEN 'dry'::text
            WHEN (u.moisture > (t.saturation_pct)::double precision) THEN 'saturated'::text
            WHEN (u.moisture > (t.max_pct)::double precision) THEN 'wet'::text
            ELSE 'ok'::text
        END AS status
   FROM (unpivoted u
     LEFT JOIN public.soil_moisture_targets t ON ((u.zone = t.zone)));


ALTER VIEW public.v_soil_status OWNER TO verdify;

--
-- Name: VIEW v_soil_status; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_soil_status IS 'Latest soil readings with target comparison and true 6-hour moisture trend.';


--
-- Name: v_state_durations; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_state_durations AS
 WITH transitions AS (
         SELECT system_state.ts,
            system_state.value AS state,
            lead(system_state.ts) OVER (ORDER BY system_state.ts) AS next_ts
           FROM public.system_state
          WHERE ((system_state.entity = 'greenhouse_state'::text) AND (system_state.ts > (now() - '30 days'::interval)))
        )
 SELECT (ts)::date AS date,
    state,
    round(sum((EXTRACT(epoch FROM (COALESCE(next_ts, now()) - ts)) / (3600)::numeric)), 2) AS hours,
    count(*) AS transitions
   FROM transitions
  GROUP BY ((ts)::date), state
  ORDER BY ((ts)::date) DESC, (round(sum((EXTRACT(epoch FROM (COALESCE(next_ts, now()) - ts)) / (3600)::numeric)), 2)) DESC;


ALTER VIEW public.v_state_durations OWNER TO verdify;

--
-- Name: VIEW v_state_durations; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_state_durations IS 'Hours spent in each state per day. Feeds plan accuracy: predicted vs actual time in COOL/HEAT/HUMID states.';


--
-- Name: v_state_transition_rate; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_state_transition_rate AS
 SELECT date_trunc('hour'::text, ts) AS hour,
    count(*) AS transitions,
    count(DISTINCT value) AS unique_states
   FROM public.system_state
  WHERE ((entity = 'greenhouse_state'::text) AND (ts > (now() - '30 days'::interval)))
  GROUP BY (date_trunc('hour'::text, ts));


ALTER VIEW public.v_state_transition_rate OWNER TO verdify;

--
-- Name: v_stress_hours_today; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_stress_hours_today AS
 WITH bounds AS (
         SELECT (date_trunc('day'::text, (now() AT TIME ZONE 'America/Denver'::text)) AT TIME ZONE 'America/Denver'::text) AS start_ts,
            ((date_trunc('day'::text, (now() AT TIME ZONE 'America/Denver'::text)) + '1 day'::interval) AT TIME ZONE 'America/Denver'::text) AS end_ts
        ), g AS (
         SELECT gg.ts,
            gg.zone,
            gg.reading_temp,
            gg.reading_vpd,
            gg.g_temp,
            gg.g_vpd,
            gg.zone_score,
            gg.feasibility,
            gg.proxy_center,
            lead(gg.ts) OVER (ORDER BY gg.ts) AS next_ts
           FROM ( SELECT fn_zone_band_grade.ts,
                    fn_zone_band_grade.zone,
                    fn_zone_band_grade.reading_temp,
                    fn_zone_band_grade.reading_vpd,
                    fn_zone_band_grade.g_temp,
                    fn_zone_band_grade.g_vpd,
                    fn_zone_band_grade.zone_score,
                    fn_zone_band_grade.feasibility,
                    fn_zone_band_grade.proxy_center
                   FROM public.fn_zone_band_grade(( SELECT bounds.start_ts
                           FROM bounds), LEAST(now(), ( SELECT bounds.end_ts
                           FROM bounds))) fn_zone_band_grade(ts, zone, reading_temp, reading_vpd, g_temp, g_vpd, zone_score, feasibility, proxy_center)
                  WHERE (fn_zone_band_grade.zone = 'center'::text)) gg
        ), w AS (
         SELECT g.ts,
            g.zone,
            g.reading_temp,
            g.reading_vpd,
            g.g_temp,
            g.g_vpd,
            g.zone_score,
            g.feasibility,
            g.proxy_center,
            g.next_ts,
            LEAST(GREATEST((EXTRACT(epoch FROM (COALESCE(g.next_ts, LEAST(now(), (g.ts + '00:02:00'::interval))) - g.ts)) / 3600.0), (0)::numeric), (5.0 / 60.0)) AS sample_hours,
            ( SELECT b.temp_low
                   FROM public.fn_zone_band('center'::text, g.ts) b(zone, temp_low, temp_high, temp_stress_low, temp_stress_high, vpd_low, vpd_high, vpd_stress_low, vpd_stress_high, crop_basis, is_proxy)) AS t_lo,
            ( SELECT b.temp_high
                   FROM public.fn_zone_band('center'::text, g.ts) b(zone, temp_low, temp_high, temp_stress_low, temp_stress_high, vpd_low, vpd_high, vpd_stress_low, vpd_stress_high, crop_basis, is_proxy)) AS t_hi,
            ( SELECT b.vpd_low
                   FROM public.fn_zone_band('center'::text, g.ts) b(zone, temp_low, temp_high, temp_stress_low, temp_stress_high, vpd_low, vpd_high, vpd_stress_low, vpd_stress_high, crop_basis, is_proxy)) AS v_lo,
            ( SELECT b.vpd_high
                   FROM public.fn_zone_band('center'::text, g.ts) b(zone, temp_low, temp_high, temp_stress_low, temp_stress_high, vpd_low, vpd_high, vpd_stress_low, vpd_stress_high, crop_basis, is_proxy)) AS v_hi
           FROM g
        )
 SELECT ( SELECT bounds.start_ts
           FROM bounds) AS date,
    round(sum(
        CASE
            WHEN (reading_temp < t_lo) THEN (((1)::numeric - COALESCE(g_temp, (0)::numeric)) * sample_hours)
            ELSE (0)::numeric
        END), 2) AS cold_stress_hours,
    round(sum(
        CASE
            WHEN (reading_temp > t_hi) THEN (((1)::numeric - COALESCE(g_temp, (0)::numeric)) * sample_hours)
            ELSE (0)::numeric
        END), 2) AS heat_stress_hours,
    round(sum(
        CASE
            WHEN (reading_vpd > v_hi) THEN (((1)::numeric - COALESCE(g_vpd, (0)::numeric)) * sample_hours)
            ELSE (0)::numeric
        END), 2) AS vpd_stress_hours,
    round(sum(
        CASE
            WHEN (reading_vpd < v_lo) THEN (((1)::numeric - COALESCE(g_vpd, (0)::numeric)) * sample_hours)
            ELSE (0)::numeric
        END), 2) AS vpd_low_hours
   FROM w;


ALTER VIEW public.v_stress_hours_today OWNER TO verdify;

--
-- Name: VIEW v_stress_hours_today; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_stress_hours_today IS 'Graded-deficit stress-hours for the CENTER (priority) zone today: sum (1-g)*sample_hours over each deficit side. Re-points the 3rd binary stress path to the graded model (band-compliance design §6.5). Column names preserved for alert-monitor.py / tasks.py / Grafana. Values are severity-weighted minutes out of band (<= the old binary count).';


--
-- Name: v_succession_gaps; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_succession_gaps AS
 WITH current_crops AS (
         SELECT crops.id,
            crops.name,
            crops.zone,
            crops."position",
            crops.expected_harvest,
            crops.is_active
           FROM public.crops
          WHERE (crops.is_active = true)
        ), next_planned AS (
         SELECT DISTINCT ON (succession_plan.zone, succession_plan."position") succession_plan.zone,
            succession_plan."position",
            succession_plan.crop AS next_crop,
            succession_plan.planned_sow
           FROM public.succession_plan
          WHERE ((succession_plan.is_active = true) AND (succession_plan.planned_sow >= CURRENT_DATE))
          ORDER BY succession_plan.zone, succession_plan."position", succession_plan.planned_sow
        )
 SELECT COALESCE(c.zone, n.zone) AS zone,
    COALESCE(c."position", n."position") AS "position",
    c.name AS current_crop,
    c.expected_harvest AS current_harvest_date,
    n.next_crop AS next_planned_crop,
    n.planned_sow AS next_sow_date,
        CASE
            WHEN ((c.expected_harvest IS NOT NULL) AND (n.planned_sow IS NOT NULL)) THEN (n.planned_sow - c.expected_harvest)
            ELSE NULL::integer
        END AS gap_days,
        CASE
            WHEN (c.expected_harvest IS NULL) THEN true
            WHEN (n.planned_sow IS NULL) THEN true
            WHEN ((n.planned_sow - c.expected_harvest) > 7) THEN true
            ELSE false
        END AS gap_flag
   FROM (current_crops c
     FULL JOIN next_planned n ON (((c.zone = n.zone) AND (c."position" = n."position"))));


ALTER VIEW public.v_succession_gaps OWNER TO verdify;

--
-- Name: v_succession_plan_readiness; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_succession_plan_readiness AS
 SELECT p.greenhouse_id,
    z.slug AS zone,
    p.id AS position_id,
    p.label AS "position",
    c.id AS active_crop_id,
    c.name AS active_crop_name,
    c.expected_harvest,
    sp.id AS succession_plan_id,
    sp.crop AS next_crop,
    sp.planned_sow,
    sp.planned_harvest,
        CASE
            WHEN ((c.id IS NULL) AND (sp.id IS NULL)) THEN 'empty_unplanned'::text
            WHEN ((c.id IS NOT NULL) AND (c.expected_harvest IS NULL)) THEN 'active_crop_missing_harvest'::text
            WHEN ((c.id IS NOT NULL) AND (sp.id IS NULL)) THEN 'active_no_successor'::text
            ELSE 'planned'::text
        END AS readiness_status
   FROM ((((public.positions p
     JOIN public.shelves sh ON ((sh.id = p.shelf_id)))
     JOIN public.zones z ON ((z.id = sh.zone_id)))
     LEFT JOIN public.crops c ON (((c.position_id = p.id) AND (c.is_active = true))))
     LEFT JOIN public.succession_plan sp ON (((sp."position" = p.label) AND (sp.zone = z.slug) AND (sp.is_active = true))))
  WHERE (p.is_active = true);


ALTER VIEW public.v_succession_plan_readiness OWNER TO verdify;

--
-- Name: VIEW v_succession_plan_readiness; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_succession_plan_readiness IS 'Every active position with current crop and next planned crop readiness.';


--
-- Name: v_succession_timeline; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_succession_timeline AS
 SELECT 'current'::text AS entry_type,
    c.zone,
    c."position",
    c.name AS crop,
    c.variety,
    c.planted_date AS start_date,
    c.expected_harvest AS end_date,
    c.stage,
    NULL::text AS rotation_group,
    NULL::text AS season
   FROM public.crops c
  WHERE (c.is_active = true)
UNION ALL
 SELECT 'planned'::text AS entry_type,
    s.zone,
    s."position",
    s.crop,
    s.variety,
    s.planned_sow AS start_date,
    s.planned_harvest AS end_date,
    'planned'::text AS stage,
    s.rotation_group,
    s.season
   FROM public.succession_plan s
  WHERE (s.is_active = true)
  ORDER BY 2, 3, 6;


ALTER VIEW public.v_succession_timeline OWNER TO verdify;

--
-- Name: v_target_curve; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_target_curve AS
 SELECT gs AS ts,
    (public.fn_band_setpoints(gs)).temp_low AS target_temp_min,
    (public.fn_band_setpoints(gs)).temp_high AS target_temp_max,
    (public.fn_zone_band('center'::text, gs)).temp_stress_low AS stress_temp_low,
    (public.fn_zone_band('center'::text, gs)).temp_stress_high AS stress_temp_high,
    (public.fn_band_setpoints(gs)).vpd_low AS target_vpd_min,
    (public.fn_band_setpoints(gs)).vpd_high AS target_vpd_max,
    (public.fn_zone_band('center'::text, gs)).vpd_stress_low AS stress_vpd_low,
    (public.fn_zone_band('center'::text, gs)).vpd_stress_high AS stress_vpd_high,
    (12.0)::double precision AS target_dli
   FROM generate_series((date_trunc('day'::text, (now() AT TIME ZONE 'America/Denver'::text)) AT TIME ZONE 'America/Denver'::text), ((date_trunc('day'::text, (now() AT TIME ZONE 'America/Denver'::text)) AT TIME ZONE 'America/Denver'::text) + '24:00:00'::interval), '00:05:00'::interval) gs(gs);


ALTER VIEW public.v_target_curve OWNER TO verdify;

--
-- Name: VIEW v_target_curve; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_target_curve IS 'Served center diurnal target curve (temp/vpd) + center-zone stress edges, 5-min cadence over today. Repointed off the deprecated fn_target_band_smooth onto fn_band_setpoints + fn_zone_band (migration 145).';


--
-- Name: v_topology_tree; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_topology_tree AS
 SELECT id AS greenhouse_id,
    name AS greenhouse_name,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('zone_id', z.id, 'slug', z.slug, 'name', z.name, 'status', z.status, 'shelves', COALESCE(( SELECT jsonb_agg(jsonb_build_object('shelf_id', sh.id, 'slug', sh.slug, 'name', sh.name, 'kind', sh.kind, 'positions', COALESCE(( SELECT jsonb_agg(jsonb_build_object('position_id', p.id, 'label', p.label, 'mount_type', p.mount_type, 'is_active', p.is_active) ORDER BY p.label) AS jsonb_agg
                           FROM public.positions p
                          WHERE (p.shelf_id = sh.id)), '[]'::jsonb)) ORDER BY sh.slug) AS jsonb_agg
                   FROM public.shelves sh
                  WHERE (sh.zone_id = z.id)), '[]'::jsonb)) ORDER BY z.slug) AS jsonb_agg
           FROM public.zones z
          WHERE (z.greenhouse_id = g.id)), '[]'::jsonb) AS zones
   FROM public.greenhouses g;


ALTER VIEW public.v_topology_tree OWNER TO verdify;

--
-- Name: VIEW v_topology_tree; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_topology_tree IS 'Sprint 22: greenhouse → zone → shelf → position recursive tree as a single JSONB blob. Drives website nav + /api/v1/topology.';


--
-- Name: v_vent_mist_assist_7d; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_vent_mist_assist_7d AS
 WITH bounds AS (
         SELECT (now() - '7 days'::interval) AS start_ts,
            now() AS end_ts
        ), diag AS (
         SELECT d.greenhouse_id,
            d.ts,
            d.vent_mist_assist_active,
            lead(d.ts) OVER (PARTITION BY d.greenhouse_id ORDER BY d.ts) AS next_ts
           FROM (public.diagnostics d
             CROSS JOIN bounds b)
          WHERE ((d.ts > (b.start_ts - '00:10:00'::interval)) AND (d.ts <= b.end_ts))
        ), assist AS (
         SELECT d.greenhouse_id,
            GREATEST(d.ts, b.start_ts) AS ts,
            LEAST(COALESCE(d.next_ts, b.end_ts), b.end_ts) AS next_ts
           FROM (diag d
             CROSS JOIN bounds b)
          WHERE ((d.vent_mist_assist_active = 1) AND (d.ts < b.end_ts) AND (COALESCE(d.next_ts, b.end_ts) > b.start_ts))
        ), enriched AS (
         SELECT a.greenhouse_id,
            a.ts,
            (EXTRACT(epoch FROM (a.next_ts - a.ts)) / 60.0) AS minutes,
            COALESCE(state.value, 'unknown'::text) AS greenhouse_state,
            COALESCE(reason.value, 'vent_mist_assist_active'::text) AS mode_reason,
            public.fn_equip_at('vent'::text, a.ts) AS vent_on,
            public.fn_equip_at('fog'::text, a.ts) AS fog_on,
            (public.fn_equip_at('mister_south'::text, a.ts) OR public.fn_equip_at('mister_west'::text, a.ts) OR public.fn_equip_at('mister_center'::text, a.ts)) AS any_mister_on,
            c.temp_avg,
            c.vpd_avg,
            c.outdoor_temp_f,
            c.outdoor_rh_pct
           FROM (((assist a
             LEFT JOIN LATERAL ( SELECT ss.value
                   FROM public.system_state ss
                  WHERE ((ss.greenhouse_id = a.greenhouse_id) AND (ss.entity = 'greenhouse_state'::text) AND (ss.ts <= a.ts))
                  ORDER BY ss.ts DESC
                 LIMIT 1) state ON (true))
             LEFT JOIN LATERAL ( SELECT ss.value
                   FROM public.system_state ss
                  WHERE ((ss.greenhouse_id = a.greenhouse_id) AND (ss.entity = 'mode_reason'::text) AND (ss.ts <= a.ts))
                  ORDER BY ss.ts DESC
                 LIMIT 1) reason ON (true))
             LEFT JOIN LATERAL ( SELECT c_1.temp_avg,
                    c_1.vpd_avg,
                    c_1.outdoor_temp_f,
                    c_1.outdoor_rh_pct
                   FROM public.climate c_1
                  WHERE ((c_1.greenhouse_id = a.greenhouse_id) AND (c_1.ts <= a.ts))
                  ORDER BY c_1.ts DESC
                 LIMIT 1) c ON (true))
          WHERE (a.next_ts > a.ts)
        )
 SELECT greenhouse_id,
    greenhouse_state,
    mode_reason,
    count(*) AS samples,
    round(sum(minutes), 1) AS assist_minutes,
    round(sum(minutes) FILTER (WHERE vent_on), 1) AS vent_open_minutes,
    round(sum(minutes) FILTER (WHERE fog_on), 1) AS fog_minutes,
    round(sum(minutes) FILTER (WHERE any_mister_on), 1) AS mister_minutes,
    round((avg(temp_avg))::numeric, 1) AS avg_temp_f,
    round((avg(vpd_avg))::numeric, 2) AS avg_vpd_kpa,
    round((avg(outdoor_temp_f))::numeric, 1) AS avg_outdoor_temp_f,
    round((avg(outdoor_rh_pct))::numeric, 1) AS avg_outdoor_rh_pct
   FROM enriched
  GROUP BY greenhouse_id, greenhouse_state, mode_reason
  ORDER BY (round(sum(minutes), 1)) DESC;


ALTER VIEW public.v_vent_mist_assist_7d OWNER TO verdify;

--
-- Name: VIEW v_vent_mist_assist_7d; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_vent_mist_assist_7d IS 'Rolling seven-day open-vent moisture assist runtime by controller state/reason, using diagnostics.vent_mist_assist_active and equipment_state.';


--
-- Name: water_meter_events; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.water_meter_events (
    id bigint NOT NULL,
    ts timestamp with time zone NOT NULL,
    greenhouse_id text DEFAULT 'vallery'::text,
    source text DEFAULT 'climate.water_total_gal'::text NOT NULL,
    meter_id text DEFAULT 'main_pulse'::text NOT NULL,
    event_type text NOT NULL,
    prior_total_gal double precision,
    total_gal double precision,
    delta_gal double precision DEFAULT 0 NOT NULL,
    quality_flag text DEFAULT 'ok'::text NOT NULL,
    raw jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT water_meter_events_event_type_check CHECK ((event_type = ANY (ARRAY['initial'::text, 'delta'::text, 'reset'::text, 'phantom_zero'::text])))
);


ALTER TABLE public.water_meter_events OWNER TO verdify;

--
-- Name: TABLE water_meter_events; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.water_meter_events IS 'Event ledger derived from cumulative water meter snapshots. Holds deltas, resets, and phantom-zero samples so daily totals are auditable.';


--
-- Name: v_water_meter_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_water_meter_daily AS
 SELECT ((((ts AT TIME ZONE 'America/Denver'::text))::date)::timestamp without time zone AT TIME ZONE 'America/Denver'::text) AS day,
    greenhouse_id,
    meter_id,
    (round((COALESCE(sum(delta_gal) FILTER (WHERE ((event_type = 'delta'::text) AND (quality_flag = 'ok'::text))), (0)::double precision))::numeric, 3))::double precision AS used_gal,
    count(*) FILTER (WHERE ((event_type = 'delta'::text) AND (quality_flag = 'ok'::text))) AS delta_events,
    count(*) FILTER (WHERE (event_type = 'reset'::text)) AS reset_events,
    count(*) FILTER (WHERE (event_type = 'phantom_zero'::text)) AS phantom_zero_events,
    count(*) FILTER (WHERE (quality_flag <> 'ok'::text)) AS quality_events
   FROM public.water_meter_events
  WHERE (event_type = ANY (ARRAY['delta'::text, 'reset'::text, 'phantom_zero'::text]))
  GROUP BY (((((ts AT TIME ZONE 'America/Denver'::text))::date)::timestamp without time zone AT TIME ZONE 'America/Denver'::text)), greenhouse_id, meter_id
  ORDER BY (((((ts AT TIME ZONE 'America/Denver'::text))::date)::timestamp without time zone AT TIME ZONE 'America/Denver'::text)) DESC;


ALTER VIEW public.v_water_meter_daily OWNER TO verdify;

--
-- Name: VIEW v_water_meter_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_water_meter_daily IS 'Daily local-day water totals from water_meter_events. used_gal includes only quality_flag=ok deltas; quality_events counts rejected counter resets, phantom zeros, and high deltas for auditability.';


--
-- Name: v_water_daily; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_water_daily AS
 SELECT day,
    (round((sum(used_gal))::numeric, 3))::double precision AS used_gal
   FROM public.v_water_meter_daily
  GROUP BY day
  ORDER BY day DESC;


ALTER VIEW public.v_water_daily OWNER TO verdify;

--
-- Name: VIEW v_water_daily; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_water_daily IS 'Canonical America/Denver daily water usage from quality-filtered water_meter_events positive deltas.';


--
-- Name: v_water_efficiency; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_water_efficiency AS
 SELECT date,
    water_used_gal,
    dli_final,
        CASE
            WHEN (dli_final > (0)::double precision) THEN round(((water_used_gal / dli_final))::numeric, 3)
            ELSE NULL::numeric
        END AS gal_per_mol_dli
   FROM public.daily_summary ds
  WHERE (water_used_gal IS NOT NULL)
  ORDER BY date;


ALTER VIEW public.v_water_efficiency OWNER TO verdify;

--
-- Name: v_weekly_summary; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_weekly_summary AS
 SELECT (date_trunc('week'::text, (date)::timestamp with time zone))::date AS week_start,
    ((date_trunc('week'::text, (date)::timestamp with time zone) + '6 days'::interval))::date AS week_end,
    count(*) AS days,
    round((avg(temp_avg))::numeric, 1) AS temp_avg,
    round((min(temp_min))::numeric, 1) AS temp_min,
    round((max(temp_max))::numeric, 1) AS temp_max,
    round((avg(rh_avg))::numeric, 1) AS rh_avg,
    round((min(rh_min))::numeric, 1) AS rh_min,
    round((max(rh_max))::numeric, 1) AS rh_max,
    round((avg(vpd_avg))::numeric, 2) AS vpd_avg,
    round((min(vpd_min))::numeric, 2) AS vpd_min,
    round((max(vpd_max))::numeric, 2) AS vpd_max,
    round((avg(dli_final))::numeric, 1) AS dli_avg,
    round((avg(co2_avg))::numeric, 0) AS co2_avg,
    round((min(outdoor_temp_min))::numeric, 1) AS outdoor_temp_min,
    round((max(outdoor_temp_max))::numeric, 1) AS outdoor_temp_max,
    round((sum(COALESCE(stress_hours_heat, (0)::double precision)))::numeric, 1) AS stress_hours_heat,
    round((sum(COALESCE(stress_hours_cold, (0)::double precision)))::numeric, 1) AS stress_hours_cold,
    round((sum(COALESCE(stress_hours_vpd_high, (0)::double precision)))::numeric, 1) AS stress_hours_vpd_high,
    round((sum(COALESCE(stress_hours_vpd_low, (0)::double precision)))::numeric, 1) AS stress_hours_vpd_low,
    round((sum(COALESCE(water_used_gal, (0)::double precision)))::numeric, 0) AS total_water_gal,
    round((sum(COALESCE(mister_water_gal, (0)::double precision)))::numeric, 0) AS mister_water_gal,
    round((sum(COALESCE(kwh_total, kwh_estimated, (0)::double precision)))::numeric, 1) AS kwh_total,
    round((sum(COALESCE(therms_estimated, (0)::double precision)))::numeric, 2) AS therms_total,
    round((max(COALESCE(peak_kw, (0)::double precision)))::numeric, 2) AS peak_kw,
    round((sum(COALESCE(cost_electric, (0)::double precision)))::numeric, 2) AS cost_electric,
    round((sum(COALESCE(cost_gas, (0)::double precision)))::numeric, 2) AS cost_gas,
    round((sum(COALESCE(cost_water, (0)::double precision)))::numeric, 2) AS cost_water,
    round((sum(COALESCE(cost_total, (0)::double precision)))::numeric, 2) AS total_cost,
    round(((sum(COALESCE(runtime_heat1_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_heat1_h,
    round(((sum(COALESCE(runtime_heat2_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_heat2_h,
    round(((sum(COALESCE((runtime_fan1_min + runtime_fan2_min), (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_fans_h,
    round(((sum(COALESCE(runtime_fog_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_fog_h,
    round(((sum(COALESCE(runtime_vent_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_vent_h,
    round(((sum(COALESCE(runtime_grow_light_min, (0)::double precision)))::numeric / (60)::numeric), 1) AS runtime_grow_light_h,
    round((sum(COALESCE(((runtime_mister_south_h + runtime_mister_west_h) + runtime_mister_center_h), (0)::double precision)))::numeric, 1) AS runtime_misters_h,
    sum((COALESCE(cycles_heat1, 0) + COALESCE(cycles_heat2, 0))) AS cycles_heat,
    sum((COALESCE(cycles_fan1, 0) + COALESCE(cycles_fan2, 0))) AS cycles_fans,
    sum(COALESCE(cycles_fog, 0)) AS cycles_fog,
    sum(COALESCE(cycles_vent, 0)) AS cycles_vent
   FROM public.daily_summary
  WHERE (temp_avg IS NOT NULL)
  GROUP BY (date_trunc('week'::text, (date)::timestamp with time zone))
  ORDER BY ((date_trunc('week'::text, (date)::timestamp with time zone))::date);


ALTER VIEW public.v_weekly_summary OWNER TO verdify;

--
-- Name: VIEW v_weekly_summary; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_weekly_summary IS 'ISO week aggregation of daily_summary. Climate averages, stress/water/energy/cost sums, equipment runtime totals.';


--
-- Name: v_zone_band; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_zone_band AS
 SELECT b.zone,
    b.temp_low,
    b.temp_high,
    b.temp_stress_low,
    b.temp_stress_high,
    b.vpd_low,
    b.vpd_high,
    b.vpd_stress_low,
    b.vpd_stress_high,
    b.crop_basis,
    b.is_proxy
   FROM (( VALUES ('center'::text), ('east'::text), ('north'::text), ('south'::text), ('west'::text)) z(zone)
     CROSS JOIN LATERAL public.fn_zone_band(z.zone, now()) b(zone, temp_low, temp_high, temp_stress_low, temp_stress_high, vpd_low, vpd_high, vpd_stress_low, vpd_stress_high, crop_basis, is_proxy));


ALTER VIEW public.v_zone_band OWNER TO verdify;

--
-- Name: VIEW v_zone_band; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_zone_band IS 'Per-zone live grading band (ideal + stress) at now() for all 5 zones. center->orchid; east->intersection(ideal)/union(stress); empty zones->_default. Replaces fn_target_band_smooth as the dashboard band surface (v_target_curve repointed here).';


--
-- Name: v_zone_disease_risk; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_zone_disease_risk AS
 WITH per_zone AS (
         SELECT c.ts,
            'center'::text AS zone,
            c.temp_avg AS temp_f,
            c.rh_avg AS rh_pct,
            c.vpd_avg AS vpd_kpa,
            true AS proxy_flag
           FROM public.climate c
          WHERE ((c.ts >= (now() - '24:00:00'::interval)) AND (c.temp_avg IS NOT NULL) AND (c.rh_avg IS NOT NULL))
        UNION ALL
         SELECT c.ts,
            'east'::text,
            c.temp_east,
            c.rh_east,
            c.vpd_east,
            false
           FROM public.climate c
          WHERE ((c.ts >= (now() - '24:00:00'::interval)) AND (c.temp_east IS NOT NULL) AND (c.rh_east IS NOT NULL))
        UNION ALL
         SELECT c.ts,
            'north'::text,
            c.temp_north,
            c.rh_north,
            c.vpd_north,
            false
           FROM public.climate c
          WHERE ((c.ts >= (now() - '24:00:00'::interval)) AND (c.temp_north IS NOT NULL) AND (c.rh_north IS NOT NULL))
        UNION ALL
         SELECT c.ts,
            'south'::text,
            c.temp_south,
            c.rh_south,
            c.vpd_south,
            false
           FROM public.climate c
          WHERE ((c.ts >= (now() - '24:00:00'::interval)) AND (c.temp_south IS NOT NULL) AND (c.rh_south IS NOT NULL))
        UNION ALL
         SELECT c.ts,
            'west'::text,
            c.temp_west,
            c.rh_west,
            c.vpd_west,
            false
           FROM public.climate c
          WHERE ((c.ts >= (now() - '24:00:00'::interval)) AND (c.temp_west IS NOT NULL) AND (c.rh_west IS NOT NULL))
        ), flagged AS (
         SELECT pz.ts,
            pz.zone,
            pz.proxy_flag,
                CASE
                    WHEN ((pz.rh_pct > (85)::double precision) AND ((pz.temp_f >= (60)::double precision) AND (pz.temp_f <= (80)::double precision))) THEN 1
                    ELSE 0
                END AS botrytis_flag,
                CASE
                    WHEN (pz.vpd_kpa < (0.4)::double precision) THEN 1
                    ELSE 0
                END AS condensation_flag,
                CASE
                    WHEN (pz.temp_f > (85)::double precision) THEN 1
                    ELSE 0
                END AS heat_flag
           FROM per_zone pz
        )
 SELECT date_trunc('hour'::text, ts) AS hour,
    zone,
    bool_or(proxy_flag) AS proxy_flag,
    round((avg(botrytis_flag) * (100)::numeric), 1) AS botrytis_risk_pct,
    round((avg(condensation_flag) * (100)::numeric), 1) AS condensation_risk_pct,
    round((avg(heat_flag) * (100)::numeric), 1) AS heat_risk_pct,
    round((((sum(botrytis_flag))::numeric * 2.0) / 60.0), 2) AS botrytis_hours,
    round((((sum(condensation_flag))::numeric * 2.0) / 60.0), 2) AS condensation_hours,
    round((((sum(heat_flag))::numeric * 2.0) / 60.0), 2) AS heat_hours
   FROM flagged
  GROUP BY (date_trunc('hour'::text, ts)), zone
  ORDER BY (date_trunc('hour'::text, ts)) DESC, zone;


ALTER VIEW public.v_zone_disease_risk OWNER TO verdify;

--
-- Name: VIEW v_zone_disease_risk; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_zone_disease_risk IS 'Per-zone botrytis / condensation / heat KPIs (migration 149/M12). Replaces the *_avg-only v_disease_risk signal with per-zone {center(proxy),east,north,south,west} rollups from climate per-zone columns. Botrytis: rh>85%% & 60-80F. Condensation: vpd<0.4. Heat: temp>85F. center is a temp_avg/rh_avg proxy (proxy_flag=true; no dedicated center probe until HW-1/NB1).';


--
-- Name: v_zone_full; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_zone_full AS
 SELECT id AS zone_id,
    greenhouse_id,
    slug AS zone_slug,
    name AS zone_name,
    orientation,
    sensor_modbus_addr,
    peak_temp_f,
    status AS zone_status,
    notes AS zone_notes,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', sh.id, 'slug', sh.slug, 'name', sh.name, 'kind', sh.kind, 'tier', sh.tier, 'position_scheme', sh.position_scheme) ORDER BY sh.tier, sh.slug) AS jsonb_agg
           FROM public.shelves sh
          WHERE (sh.zone_id = z.id)), '[]'::jsonb) AS shelves,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', s.id, 'slug', s.slug, 'kind', s.kind, 'protocol', s.protocol, 'model', s.model, 'modbus_addr', s.modbus_addr, 'source_table', s.source_table, 'source_column', s.source_column, 'unit', s.unit, 'is_active', s.is_active) ORDER BY s.slug) AS jsonb_agg
           FROM public.sensors s
          WHERE (s.zone_id = z.id)), '[]'::jsonb) AS sensors,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', e.id, 'slug', e.slug, 'kind', e.kind, 'name', e.name, 'model', e.model, 'watts', e.watts, 'cost_per_hour_usd', e.cost_per_hour_usd, 'is_active', e.is_active) ORDER BY e.kind, e.slug) AS jsonb_agg
           FROM public.equipment e
          WHERE (e.zone_id = z.id)), '[]'::jsonb) AS equipment,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', w.id, 'slug', w.slug, 'kind', w.kind, 'name', w.name, 'nozzle_count', w.nozzle_count, 'head_count', w.head_count, 'mount', w.mount, 'pressure_group_id', w.pressure_group_id, 'is_fert_path', w.is_fert_path) ORDER BY w.kind, w.slug) AS jsonb_agg
           FROM public.water_systems w
          WHERE (w.zone_id = z.id)), '[]'::jsonb) AS water_systems,
    ( SELECT (count(*))::integer AS count
           FROM public.crops c
          WHERE ((c.zone_id = z.id) AND c.is_active)) AS active_crops_fk_count
   FROM public.zones z;


ALTER VIEW public.v_zone_full OWNER TO verdify;

--
-- Name: VIEW v_zone_full; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON VIEW public.v_zone_full IS 'Sprint 22: per-zone rollup of shelves, sensors, equipment, water_systems as JSONB arrays. Drives the website zone pages + /api/v1/zones/{slug}.';


--
-- Name: v_zone_temp_delta; Type: VIEW; Schema: public; Owner: verdify
--

CREATE VIEW public.v_zone_temp_delta AS
 SELECT ts,
    (temp_north - temp_south) AS zone_temp_delta
   FROM public.climate
  WHERE ((temp_north IS NOT NULL) AND (temp_south IS NOT NULL));


ALTER VIEW public.v_zone_temp_delta OWNER TO verdify;

--
-- Name: verdify_embeddings; Type: TABLE; Schema: public; Owner: verdify
--

CREATE TABLE public.verdify_embeddings (
    id bigint NOT NULL,
    source_type text NOT NULL,
    source_id text NOT NULL,
    chunk_idx integer DEFAULT 0 NOT NULL,
    content text NOT NULL,
    content_hash text NOT NULL,
    embedding public.vector(3072) NOT NULL,
    metadata jsonb,
    embedded_at timestamp with time zone DEFAULT now(),
    CONSTRAINT verdify_embeddings_source_type_check CHECK ((source_type = ANY (ARRAY['lesson'::text, 'plan'::text, 'site_doc'::text, 'playbook'::text, 'observation'::text])))
);


ALTER TABLE public.verdify_embeddings OWNER TO verdify;

--
-- Name: TABLE verdify_embeddings; Type: COMMENT; Schema: public; Owner: verdify
--

COMMENT ON TABLE public.verdify_embeddings IS 'Unified embedding store for lessons, plans, site docs, and the planner playbook. Embedded with OpenAI text-embedding-3-large (3072-dim). Populated by scripts/embed-corpora.py.';


